__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_Voice = readonly({
  Voice_100335_AwakerVoiceContent = {
    Text = "Hüter, darf ich fragen, wann ich den Friedhof der Akademie besuchen kann? Die dort begrabenen großen Seelen werden mir sicherlich außergewöhnliche Inspiration bringen! Seien Sie versichert, ich verspreche, die Leichname nicht mehr auszugraben, um sie aus der Nähe zu betrachten..."
  },
  Voice_100335_AwakerVoiceTitle = {
    Text = "Plauderei: Über Modelle"
  },
  Voice_100336_AwakerVoiceContent = {
    Text = "Warte! Mir ist eine neue Ausdrucksweise eingefallen, die die gesamte Malerei-Szene erschüttern wird!"
  },
  Voice_100336_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_100337_AwakerVoiceContent = {
    Text = "Ich bin Licht und Schatten, ich bin Farbe, ich... bin die Malerei selbst!"
  },
  Voice_100337_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_100338_AwakerVoiceContent = {
    Text = "Hiss... Eine Farbe, die ich noch nie gesehen habe, leuchtet in deiner geistigen Welt... Was könnte das nur sein..."
  },
  Voice_100338_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_100338_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_100339_AwakerVoiceContent = {
    Text = "Was für eine großartige schwarze Farbe! Ich habe einst viele Auflösungsflüssigkeiten gesammelt, um zu malen, doch am Ende sind all diese Werke verschwunden. Farben aus dem ursprünglichen Universum, all diese Bilder wurden verschlungen und werden von niemandem erinnert... Ist das nicht noch großartiger?!"
  },
  Voice_100339_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_100340_AwakerVoiceContent = {
    Text = "Lass mich ein bisschen näher kommen... Lass mich noch mehr sehen! Diese Lichter und Schatten, diese Farben, diese Posen... im Vergleich dazu sind die Dinge, die ich früher gemalt habe, nur ein Haufen Papier..."
  },
  Voice_100340_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_100340_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_100341_AwakerVoiceContent = {
    Text = "Durschein erzählt mir ständig, wie künstlerisch sein Kochen ist, und bittet mich zu sehen, dass Essen und Kunst überhaupt nichts miteinander zu tun haben! Man muss nicht nur wertvolle kreative Zeit mit der aufwendigen Verarbeitung von Leichenteilen verschwenden, sondern auch, nachdem man endlich ein Gericht kreiert hat, das sowohl im Aussehen als auch im Geschmack überzeugt, es abbeißen und hinunterschlucken! Das ist einfach ein Verbrechen an der Kunst!"
  },
  Voice_100341_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_100342_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100342_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_100343_AwakerVoiceContent = {
    Text = "Schlechtes Modell..."
  },
  Voice_100343_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_100344_AwakerVoiceContent = {
    Text = "Nein, nein, schon wieder ein schreckliches Gemälde... Wo kann ich nur Inspiration finden? Auf dem Friedhof? Oder am Ort der Hinrichtung..."
  },
  Voice_100344_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_100345_AwakerVoiceContent = {
    Text = "Obwohl ich denke, dass die Kunstform der Bildhauerei etwas zu steif und veraltet ist, hat die Bildhauerin namens Shan ein Schnitzmesser, das eine Ausdruckskraft besitzt, die über das hinausgeht, was diese Kunstform tragen kann... sie ist wirklich ein seltenes Genie!"
  },
  Voice_100345_AwakerVoiceTitle = {
    Text = "Plauderei: Über Shan"
  },
  Voice_100345_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Shan“"
  },
  Voice_100346_AwakerVoiceContent = {
    Text = "Hast du dieses Bild gesehen, Geheimnisträger? Das ist das Porträt, das ich für dich gemalt habe. Sieh dir an, wie charmant du beim Verzehren von Leichenteilen aussiehst! Ich weiß, dass nicht jeder meine Kunst verstehen kann, aber die verrückte Schönheit, die in diesem Bild vermittelt wird, hast du sicher berührt, oder?! Für mich ist das bereits genug, vollkommen genug..."
  },
  Voice_100346_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_100346_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_100347_AwakerVoiceContent = {
    Text = "Sie haben gerade gesagt, dass Sie dieses Bild kaufen möchten... Ist das wahr?! Danke, Hüter! Es gibt sehr wenige Menschen, die das zu schätzen wissen..."
  },
  Voice_100347_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_100347_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_100348_AwakerVoiceContent = {
    Text = "Geheimnisträger, hast du in letzter Zeit Zeit, um wieder mein Model zu sein? Im Vergleich zu dem, was ich beim letzten Mal an dir gesehen habe, sind die anderen Modelle einfach eine Zeitverschwendung für mich..."
  },
  Voice_100348_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_100349_AwakerVoiceContent = {
    Text = "Zeuge der Neugeburt in diesem Gemälde!"
  },
  Voice_100349_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_100350_AwakerVoiceContent = {
    Text = "Schau dir diese lebendigen Linien an!"
  },
  Voice_100350_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_100351_AwakerVoiceContent = {
    Text = "Ich habe ein Gefühl, dass das, was dieser Pinsel erschafft, alle in Staunen versetzen wird!"
  },
  Voice_100351_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_100352_AwakerVoiceContent = {
    Text = "Ah! Eine neuartige Farbe... Ich werde sie an der passendsten Stelle auftragen!"
  },
  Voice_100352_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_100353_AwakerVoiceContent = {
    Text = "Das ist wirklich ein inspirierender Ort! Ich habe wieder einige neue Kreationen, Hüter des Geheimnisses, hast du in letzter Zeit Zeit, mein Atelier zu besuchen? Komm, komm!"
  },
  Voice_100353_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_100353_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_100354_AwakerVoiceContent = {
    Text = "Genau, genau! Der durch Blut genährte Sieg! Welch wunderbare Komposition!"
  },
  Voice_100354_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_100355_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_100355_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_100356_AwakerVoiceContent = {
    Text = "Ah! Setz dich, Hüter des Geheimnisses. Es ist eine mühsame Aufgabe, mein Modell zu sein. Sei versichert, ich werde ein erstaunliches Gemälde für dich schaffen."
  },
  Voice_100356_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_100356_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_100357_AwakerVoiceContent = {
    Text = "Ein Künstler sollte nur die Werke selbst im Blick haben und sich nicht um die Blicke anderer kümmern, doch ich kann das nicht... Seit dem Tag, an dem ich zum ersten Mal den Pinsel in die Hand nahm, wollte ich die wahre Schönheit allen Menschen bringen."
  },
  Voice_100357_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_100357_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_100358_AwakerVoiceContent = {
    Text = "Hier erinnert mich an die Zeiten an der Kunstakademie. Obwohl die Professoren und Kommilitonen meistens völlig unbescholtene Leute waren, gab es immer ein oder zwei Kenner, die die Schönheit erkannten, die ich in meinen Gemälden sah."
  },
  Voice_100358_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_100359_AwakerVoiceContent = {
    Text = "Was für eine verrückte Kunst wird diese barbarische Aufführung hervorbringen?!"
  },
  Voice_100359_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_100360_AwakerVoiceContent = {
    Text = "Meine Farbpalette!"
  },
  Voice_100360_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_100361_AwakerVoiceContent = {
    Text = "Schmerz ist auch Kunst..."
  },
  Voice_100361_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_100362_AwakerVoiceContent = {
    Text = "Ah! Ich habe es gesehen... das blinde Auge, das unter dem Abgrund verborgen ist, das ultimative Bild des Universums... Bitte warte noch einen Moment, Geheimnisträger, wir sind fast fertig damit!"
  },
  Voice_100362_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_100362_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_100363_AwakerVoiceContent = {
    Text = "Mein Pinsel, aus meinen Schambeinen gefertigt. Die Farbpalette, diese Farben habe ich auf den Friedhöfen von zwanzig Städten gesammelt... und meine kostbare, lederne Leinwand! Geheimnisträger, bitte nehmen Sie dies und malen Sie mir ein Porträt! Nein, nein, nein, dafür brauchen Sie keine künstlerischen Fähigkeiten... Ich glaube, wenn diese seelische Resonanz auf der Leinwand erscheint, wird es ein Bild von unvergleichlicher Schönheit sein, die ich mir nie vorgestellt habe...!"
  },
  Voice_100363_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_100363_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_100364_AwakerVoiceContent = {
    Text = "Ich bin Licht und Schatten, ich bin Farbe, ich... bin die Malerei selbst!"
  },
  Voice_100364_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_100365_AwakerVoiceContent = {
    Text = "Probier diese Farbe!"
  },
  Voice_100365_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_100366_AwakerVoiceContent = {
    Text = "Die Essenz der Kunst ist Wahnsinn...!"
  },
  Voice_100366_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_100367_AwakerVoiceContent = {
    Text = "Meinen Sie, dass ich beim nächsten Mal versuchen kann, diesen Bereich in meinem Gemälde groß zu zeigen? Hm... ich habe nie daran gedacht! Das ist wirklich eine geniale Idee!"
  },
  Voice_100367_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_100368_AwakerVoiceContent = {Text = "Vorsicht!"},
  Voice_100368_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_100369_AwakerVoiceContent = {
    Text = "Die Essenz der Kunst ist Wahnsinn...!"
  },
  Voice_100369_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_100370_AwakerVoiceContent = {
    Text = "Meine Farbpalette!"
  },
  Voice_100370_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_100371_AwakerVoiceContent = {
    Text = "Oh! Diese geschmeidigen Kiefer, die leuchtenden Augen, die perfekte Gestalt und, und diese unermessliche geistige Welt wie der Sternenhimmel... Ich bin der Maler Pickman, darf ich Sie bitten, mein Modell zu werden?"
  },
  Voice_100371_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_100372_AwakerVoiceContent = {
    Text = "Die Kunstauffassung, der ich folge, ist verrückt und unruhig, die Musik von Hameln ist ganz anders, so streng wie die tristen Grabsteine auf einem Friedhof. Doch aus irgendeinem Grund kann ich in diesen ordentlichen Noten das intensivste Chaos tief im Universum erkennen..."
  },
  Voice_100372_AwakerVoiceTitle = {
    Text = "Plauderei: Über Hameln"
  },
  Voice_100372_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Hameln“ wird freigeschaltet"
  },
  Voice_100373_AwakerVoiceContent = {
    Text = "Sieh mal, Geheimnisträger! Das ewige, wahnsinnige Bild auf der Leinwand, wie faszinierend und verzweifelt es ist! Nur das, was in diesem ultimativen Wahnsinn und Schmerz erblüht, ist die Kunst..."
  },
  Voice_100373_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_100373_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_100374_AwakerVoiceContent = {
    Text = "Ah! Entschuldigung, Geheimnisträger... ich habe in dir eine nie dagewesene Vision gesehen... furchterregender als der Abgrund, faszinierender als der Abgrund..."
  },
  Voice_100374_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_100374_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_100375_AwakerVoiceContent = {
    Text = "Ich verstehe einfach nicht, warum Menschen, wenn sie die Gelegenheit haben, nicht zu Ghulen werden. Diese blutige, verrückte Ästhetik ist doch viel interessanter, als in einem großen Haus ein leidenschaftsloser Mensch zu sein?!"
  },
  Voice_100375_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_100376_AwakerVoiceContent = {Text = "Ha!"},
  Voice_100376_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_116964_AwakerVoiceContent = {
    Text = "Bestrafe die Sünden!"
  },
  Voice_116964_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_116965_AwakerVoiceContent = {
    Text = "Bestrafung der Sünden!"
  },
  Voice_116965_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_117791_AwakerVoiceContent = {
    Text = "Ich gebe zu, dass sie ein gewisses Talent fürs Stehlen hat, aber eine Dame braucht solche niederträchtigen Tricks nicht. Was ich will, können mir die Leute doch einfach “freiwillig“ geben, oder?"
  },
  Voice_117791_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_117791_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_117792_AwakerVoiceContent = {
    Text = "Haha, meine, meine, all die Süßigkeiten von Misaq gehören jetzt mir! Worauf wartest du noch? Folge dieser Hexe, lass uns sofort die Süßigkeitenläden von Lentiniën erobern!"
  },
  Voice_117792_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_117792_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_117793_AwakerVoiceContent = {
    Text = "Nicht geben? Dann wird die Hexe ernst machen!"
  },
  Voice_117793_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_117794_AwakerVoiceContent = {
    Text = "Du fragst dich, wie die Füllung in diese Süßigkeiten gelangt ist, es gibt absolut keine Spalte oder Nadelstich zu finden. Ich wünschte, die Erfinder dieser Süßigkeiten könnten auch in der Mensa von Misaq arbeiten und täglich ein neues Dessert für mich kreieren!"
  },
  Voice_117794_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_117795_AwakerVoiceContent = {
    Text = "Du hast die Hexe verärgert!"
  },
  Voice_117795_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_117796_AwakerVoiceContent = {
    Text = "Früher dachte ich, dass Süßigkeiten im Vergleich zu Kuchen zu schlicht und nicht elegant genug sind. Jetzt sehe ich, dass ich die kleinen Dinge in diesem bunten Plastikpapier unterschätzt habe. Besonders im Vergleich zu Kuchen haben diese Süßigkeiten eine viel längere Haltbarkeit. Ich könnte so viele aufbewahren, wie ich will, ohne Angst, dass sie verderben. Ich möchte am liebsten das ganze Zimmer damit füllen!"
  },
  Voice_117796_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_117797_AwakerVoiceContent = {
    Text = "Hast du eine neue Süßigkeit gefunden? Lass mal sehen... Was ist das? Diese Ring-Süßigkeit sieht ja lustig aus, wo gibt es denn einen Diamantring so groß wie ein Ei! Warte mal, was meinst du damit, mir einen Ring zu schenken? Erklär es mir klar!"
  },
  Voice_117797_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_117797_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_117798_AwakerVoiceContent = {
    Text = "Es heißt, dass eine mysteriöse schwarze Katze normalerweise die Hexe begleitet. Es wäre wirklich zu peinlich, das streunende Tier aus dem Campus auszuwählen. Also habe ich beschlossen, du sollst ein Katzenohren-Stirnband tragen und meine kleine schwarze Katze spielen."
  },
  Voice_117798_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_117798_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_117799_AwakerVoiceContent = {
    Text = "Widerstand ist sinnlos."
  },
  Voice_117799_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_117800_AwakerVoiceContent = {Text = "Hmpf!"},
  Voice_117800_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_117801_AwakerVoiceContent = {
    Text = "Gibt es wirklich Hexen auf der Welt? Sie leben allein in einem Wald, in dem es nicht einmal Schatten gibt. Wer kocht für sie, wäscht ihre Wäsche und bereitet Desserts vor? Wenn sie nicht einmal nachmittags Tee bekommen, was hat so ein Leben dann noch für einen Sinn? Ich kann das nur schwer ertragen, wenn ich darüber nachdenke."
  },
  Voice_117801_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_117801_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_117802_AwakerVoiceContent = {
    Text = "Die Hexe ist gekommen!"
  },
  Voice_117802_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_117803_AwakerVoiceContent = {
    Text = "Hast du noch Schokolade in der Hand? Gut, gib sie mir alles. Was ist los? Deine Sachen sind meine Sachen, ist das nicht selbstverständlich?"
  },
  Voice_117803_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_117803_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_117804_AwakerVoiceContent = {
    Text = "Du fragst mich, welche Süßigkeit ich am liebsten mag? Lass mich nachdenken, der Nachgeschmack von Haselnuss-Karamell ist sehr aromatisch, Karamellschokolade schmeckt auch sehr gut, die gefüllten Erdbeer- und Traubenzucker haben eine interessante Konsistenz, und es gibt auch eine Art von Malzzucker, die man ganz lang ziehen kann, die Farbe sieht aus wie Honig... Nein, ich kann mich nicht entscheiden, jede Süßigkeit hat ihr eigenes besonderes Merkmal, schließlich gibt es im Kürbiskorb genug, ich will sie alle!"
  },
  Voice_117804_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_117804_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_117805_AwakerVoiceContent = {
    Text = "Mein Lebensziel ist es jetzt, alle Süßigkeiten der Welt zu probieren. Schon der Gedanke, dass es so viele unzählige Süßigkeiten gibt, die auf mich warten, gibt mir jeden Morgen die Motivation aufzustehen. Du sagst Kuchen? Kuchen ist ein weiteres Lebensziel von mir."
  },
  Voice_117805_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_117805_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_117806_AwakerVoiceContent = {
    Text = "Lass dich nicht von seinem kindlichen Aussehen täuschen, er ist tatsächlich schon so alt, dass er längst im Boden liegen könnte. Er interessiert sich nicht für Süßigkeiten oder irgendetwas anderes, was lebende Menschen mögen. Also, was du ihm schenken wolltest, kannst du mir lieber alles geben, ich bin diejenige, die sie am meisten zu schätzen weiß."
  },
  Voice_117806_AwakerVoiceTitle = {
    Text = "Plauderei · Über Tulu"
  },
  Voice_117806_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_117807_AwakerVoiceContent = {
    Text = "Wenn ich eine Hexe wäre, dann wäre ich eine Hexe, die in einem luxuriösen Palast wohnt, wo es lebhaft zugeht, und ich würde zehn der besten Köche anstellen, die mir jeden Tag verschiedene Kuchen und Süßigkeiten machen... Du sagst, das nennt man Prinzessin? Was ist dabei, ich kann doch eine Prinzessinnenhexe sein!"
  },
  Voice_117807_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_117807_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_117808_AwakerVoiceContent = {
    Text = "Hey, bereite mir schnell mehrere Zahnpasten vor. Nein, ich habe nicht viel Süßes gegessen, ich habe keine Karies, nur ein bisschen Schmerz, wenn ich abends schlafe..."
  },
  Voice_117808_AwakerVoiceTitle = {
    Text = "Plauderei·Über Bonbons"
  },
  Voice_117809_AwakerVoiceContent = {
    Text = "Obwohl die Regeln im Restaurant von Misaq oft unangenehm sind, ist ihre Fähigkeit, Desserts zuzubereiten, nun ja... zumindest akzeptabel."
  },
  Voice_117809_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_117810_AwakerVoiceContent = {
    Text = "In dieser Welt gibt es so viele dunkle und ekelhafte Orte. Anstatt sich um die Zerstörung der Welt zu sorgen, iss lieber vorher noch ein paar Süßigkeiten."
  },
  Voice_117810_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_117811_AwakerVoiceContent = {Text = "Aua!"},
  Voice_117811_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_117812_AwakerVoiceContent = {
    Text = "Obwohl es jetzt keine Lammfellteppiche, keine schwarzen Perlenketten aus Übersee und keine Seidenpyjamas mehr gibt, ist es vielleicht das wahre Glück, jeden Tag in einem mit Süßigkeiten gefüllten Raum aufzuwachen und einen prall gefüllten Kürbiskorb zu berühren. Hey, lach nicht so selbstgefällig, du musst weiterhin immer für meine Hoheit dienen, du musst weiter hart arbeiten!"
  },
  Voice_117812_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_117812_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_117813_AwakerVoiceContent = {
    Text = "Verdammtes Misaq, wagst du es, mich daran zu hindern, Süßigkeiten zu nehmen? Na, sieh mal an, ich habe sie trotzdem gegessen?"
  },
  Voice_117813_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_117814_AwakerVoiceContent = {
    Text = "Was willst du? Willst du mein Süßigkeiten essen? Hmpf, ich könnte dir auch gnädig etwas schenken, komm, ruf einmal laut nach der Hexenmeisterin!"
  },
  Voice_117814_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_117815_AwakerVoiceContent = {
    Text = "Wie kann man das einen Raub nennen? Ich übe nur das edle Recht einer Dame aus."
  },
  Voice_117815_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_117816_AwakerVoiceContent = {
    Text = "Die zuckersüße Hexe der Gerechtigkeit ist gekommen, alle verlorenen Süßigkeiten sollten an ihren rechtmäßigen Platz zurückkehren!"
  },
  Voice_117816_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_117817_AwakerVoiceContent = {
    Text = "Verdammter Geizkragen, die Hexe wird sich an dich erinnern..."
  },
  Voice_117817_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_117818_AwakerVoiceContent = {
    Text = "Warum darf die kleine Maus so stolz Süßigkeiten einsammeln, ich aber nicht? Das ist eine Diskriminierung gegen Damen! Unverschämt!"
  },
  Voice_117818_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_117819_AwakerVoiceContent = {
    Text = "Nicht geben? Dann wird die Hexe ernst machen!"
  },
  Voice_117819_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_117820_AwakerVoiceContent = {
    Text = "Ich lade dich ein, Süßigkeiten zu essen!"
  },
  Voice_117820_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_117821_AwakerVoiceContent = {
    Text = "Im Vergleich zu den Kellnern in den Restaurants bist du wirklich der verständnisvollste, der weiß, dass er mir extra einen Zucker vorbereiten muss. Mach weiter so, mein persönlicher Diener."
  },
  Voice_117821_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_117821_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_117822_AwakerVoiceContent = {
    Text = "Läuft, läuft, läuft!"
  },
  Voice_117822_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_117823_AwakerVoiceContent = {
    Text = "Übertrieben!"
  },
  Voice_117823_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_117824_AwakerVoiceContent = {
    Text = "Was hältst du mich auf? Als treuer Diener dieses Fräuleins solltest du mir doch aktiv dabei helfen, alle Süßigkeiten zu rauben... oder sie zu holen?"
  },
  Voice_117824_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_117825_AwakerVoiceContent = {
    Text = "Halt, Raub! Ich rate dir, besser zu kooperieren und alle Süßigkeiten herauszugeben, sonst, hmhm..."
  },
  Voice_117825_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_117826_AwakerVoiceContent = {
    Text = "Weiche, harte, knusprige, mürbe, milchige, fruchtige, nussige, schokoladige... Ah, wie kann es so viele Sorten Süßigkeiten geben, die ich noch nie probiert habe? Ich habe beschlossen, Misaq vorzuschlagen, dass wir einmal pro Woche ein Allerheiligensfest feiern!"
  },
  Voice_117826_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_117827_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_117827_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_117828_AwakerVoiceContent = {
    Text = "Die große Hexe wird siegen! Der Gott der Süßigkeiten beschützt mich, und ich beschütze alle Süßigkeiten! Ahahaha!"
  },
  Voice_117828_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_117829_AwakerVoiceContent = {
    Text = "Widerstand ist zwecklos."
  },
  Voice_117829_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_117830_AwakerVoiceContent = {
    Text = "Alle Süßigkeiten werden mir gehören!"
  },
  Voice_117830_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_117831_AwakerVoiceContent = {
    Text = "Dieses Kind ist so gehorsam, dass es ein bisschen beängstigend ist. Wenn du sie nach Süßigkeiten fragst, wird sie dir welche geben und sogar selbst keine übrig lassen, was einem ein wenig unangenehm ist... Hüsteln, ich meine, da sie so verständnisvoll ist, wird die gütige Hexe ihr natürlich etwas als Belohnung lassen."
  },
  Voice_117831_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Lily"
  },
  Voice_117831_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Lily“"
  },
  Voice_117832_AwakerVoiceContent = {
    Text = "Du hast die Hexe verärgert!"
  },
  Voice_117832_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_117833_AwakerVoiceContent = {
    Text = "Ich bin wütend!"
  },
  Voice_117833_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_117834_AwakerVoiceContent = {
    Text = "Alle Süßigkeiten werden mir gehören!"
  },
  Voice_117834_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_117835_AwakerVoiceContent = {
    Text = "Was sagst du, kann man diese Zuckerwatte auch rösten? Hmm, ist es wirklich lecker, wenn sie warm und klebrig ist? Lass mich mal probieren? Na gut, dann probiere ich widerwillig einen Bissen. Wenn du mich veräppelst... Hmm?! Diese knusprige, weiche Konsistenz, das schmeckt wirklich gut!"
  },
  Voice_117835_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_117835_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_122115_AwakerVoiceContent = {
    Text = "Illusion, Inversion, alles ist Schicksal!"
  },
  Voice_122115_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_122117_AwakerVoiceContent = {
    Text = "Illusion, Inversion, alles ist Schicksal!"
  },
  Voice_122117_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_123312_AwakerVoiceContent = {
    Text = "Weil du dem wahren Schrecken begegnet bist, wirst du vor dem echten Ich keine Angst haben? Hmph, das ist eine ziemlich kluge Antwort, aber es macht mich auch... immer neugieriger auf dich."
  },
  Voice_123312_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_123312_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_123313_AwakerVoiceContent = {
    Text = "Wie sieht die Welt in deinen Augen aus? Wo sind diese erschreckenden Extreme? Nein, ich will nicht hören, wie du es beschreibst; ich will es mit dir erleben – den Wahnsinn, den Tod, das Grauen. Ich habe meinen Entschluss gefasst! Ich werde dich nicht verlassen, bis meine Neugierde gestillt ist."
  },
  Voice_123313_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_123313_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_123314_AwakerVoiceContent = {
    Text = "Ein unkontrollierbarer Wahnsinniger? Du hast recht. Das ist nicht meine Welt; hier gibt es keine langweiligen Gesetze oder Regeln... Hier kann ich tun, was ich will, also Hüter, pass besser auf - lass dich nicht von einem außer Kontrolle geratenen Wahnsinnigen beißen."
  },
  Voice_123314_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_123314_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_123315_AwakerVoiceContent = {
    Text = "Für mein geistiges und körperliches Wohlbefinden, möchtest du ein tiefes Gespräch führen? Gut, lass uns schnell anfangen – je früher wir mit dieser langweiligen Sache beginnen, desto schneller ist es vorbei."
  },
  Voice_123315_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_123315_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_123316_AwakerVoiceContent = {
    Text = "Ich habe nur vorgetäuscht, eine normale Person zu sein, um deine Frage zu beantworten? Ah, du hast mich enttarnt – bist du bereit, meine wahre Gestalt zu sehen?"
  },
  Voice_123316_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_123316_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_123770_AwakerVoiceContent = {
    Text = "Hau dir den Kopf ab."
  },
  Voice_123770_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_123771_AwakerVoiceContent = {
    Text = "Jeder, jung und alt, liebt es! Shining☆Tornado—!!"
  },
  Voice_123771_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_123772_AwakerVoiceContent = {
    Text = "Es sollte nicht ich sein, der fällt..."
  },
  Voice_123772_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_123773_AwakerVoiceContent = {
    Text = "Sturmwirkung!"
  },
  Voice_123773_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_123774_AwakerVoiceContent = {
    Text = "Du willst diese verdrehte und erschreckende Welt retten? Was für eine verrückte und interessante Art zu sterben – lass uns sehen, wie weit du kommen kannst."
  },
  Voice_123774_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_123775_AwakerVoiceContent = {
    Text = "Hey, kleine Freunde, wollt ihr meine Axt ausprobieren? Keine Sorge, sie kommt gleich..."
  },
  Voice_123775_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_123776_AwakerVoiceContent = {
    Text = "Hüter, es scheint, als hätte ich das Licht gesehen. Könnte es sein, dass diesmal... Ich frage mich, wie es meinen Kollegen vom Ermittlerteam geht? Bitte lass mir nicht einen Haufen Arbeit zurück; ich möchte wirklich keine Überstunden machen."
  },
  Voice_123776_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_123776_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_123777_AwakerVoiceContent = {
    Text = "Kann ich durch dieses Ritual nach Hause gehen? Bist du dir sicher? Wie oft wurde es schon gemacht... Nun, schaden kann es auf jeden Fall nicht, es zu versuchen."
  },
  Voice_123777_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_123777_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_123778_AwakerVoiceContent = {
    Text = "Haha, es stellt sich heraus, dass dieses adrenaline-pumpende Leben mir viel besser passt als die langweilige Alltagsroutine!"
  },
  Voice_123778_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_123779_AwakerVoiceContent = {Text = "Ha!"},
  Voice_123779_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_123780_AwakerVoiceContent = {
    Text = "Es sollte nicht ich sein, der fällt..."
  },
  Voice_123780_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_123781_AwakerVoiceContent = {
    Text = "Shining☆Supernova—Strahl!"
  },
  Voice_123781_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_123782_AwakerVoiceContent = {
    Text = "Jeder, jung und alt, liebt es! Shining☆Tornado—!!"
  },
  Voice_123782_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_123783_AwakerVoiceContent = {
    Text = "Gerade fühlt es sich an... als würde ich in den Nebel treten. Apropos Nebel, es erinnert mich an diese kleinen Kerle im Dunst. Es ist schade, dass ich meine Gefühle nicht an ihnen auslassen kann, wenn ich schlecht gelaunt bin."
  },
  Voice_123783_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_123783_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_123784_AwakerVoiceContent = {
    Text = "Hass? Das würde ich nicht sagen. Ich hoffe einfach aufrichtig, dass all diese langweiligen Besprechungen, gesellschaftlichen Zusammenkünfte und universellen Werte verschwinden."
  },
  Voice_123784_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_123785_AwakerVoiceContent = {
    Text = "Das ist es... Ich spüre, dass ich meinem \"wahren Ich\" näher komme"
  },
  Voice_123785_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_123786_AwakerVoiceContent = {
    Text = "Ah, ein Misserfolg, der zu erwarten war. Das Leben hat seine Höhen und Tiefen, daran gewöhnt man sich... Aber trotzdem, danke, dass du es dieses Mal versucht hast."
  },
  Voice_123786_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_123786_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_123787_AwakerVoiceContent = {
    Text = "So wie die Nebelkatastrophe weiß ich nichts über die Auflösung. Das macht es so faszinierend, nicht wahr?"
  },
  Voice_123787_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_123788_AwakerVoiceContent = {
    Text = "Mouchette, das Ermittlungsteam... oh nein, ich bin nicht mehr die Vorhut des Ermittlungsteams. Also, lass mich mich neu vorstellen – mein Name ist Mouchette, einfach ein liebes Mädchen~"
  },
  Voice_123788_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_123789_AwakerVoiceContent = {Text = "Geh weg!"},
  Voice_123789_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_123790_AwakerVoiceContent = {
    Text = "Es ist hier zu nah an menschlichen Siedlungen, mit langweiligen Erwachsenen überall... Hast du jemals darüber nachgedacht, die Schule in einen abgelegenen, unbewohnten Wald zu verlegen?"
  },
  Voice_123790_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_123791_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_123791_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_123792_AwakerVoiceContent = {
    Text = "Ich bin dabei, mich in dieses Gefühl des Driftens in einer anderen Welt zu verlieben, die mächtigen Erwacher, die erschreckende Erosion und die unbekannten Gottheiten! Ah, alles ist eine Erleichterung weg von der gewöhnlichen Gesellschaft!"
  },
  Voice_123792_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_123793_AwakerVoiceContent = {
    Text = "Gibt es noch mehr? Ich habe einen Riesenspaß – beeilt euch, jemand lasst mich eine weitere Axt hacken."
  },
  Voice_123793_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_123794_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_123794_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_123795_AwakerVoiceContent = {
    Text = "Ein Fehlschlag bedeutet nichts... nur ein Scherz. Ihr solltet euch besser die Hälse reinigen und auf mich warten!"
  },
  Voice_123795_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_123796_AwakerVoiceContent = {
    Text = "Hast du eine Aufgabe? Nächstes Mal musst du nicht grüßen, wir sind bereits gut genug vertraut, um die \"sozialen Begrüßungsrituale\" nicht durchzuführen"
  },
  Voice_123796_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_123797_AwakerVoiceContent = {
    Text = "Sich für andere zu opfern, ist wirklich eine törichte und ärgerliche Idee. Niemand hat das Recht, von anderen so etwas zu verlangen, nicht einmal die Götter."
  },
  Voice_123797_AwakerVoiceTitle = {
    Text = "Small Talk: Über El Salvador"
  },
  Voice_123797_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Salvador“"
  },
  Voice_123798_AwakerVoiceContent = {
    Text = "Überhaupt nicht schlecht—"
  },
  Voice_123798_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_123799_AwakerVoiceContent = {
    Text = "Endlich kein Pretending mehr... Jetzt lass uns Spaß haben."
  },
  Voice_123799_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_123800_AwakerVoiceContent = {
    Text = "Ist das Ritual noch nicht vorbei? Ich möchte wirklich schnell zurück, um etwas Ravenloft-Eintopf und eine dampfende Tasse Haselnuss-Kava-Tee zu haben. Natürlich sind auch der Ceylon-Schwarztee und die andalusischen Gebäckstücke hier ganz angenehm."
  },
  Voice_123800_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_123800_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_123801_AwakerVoiceContent = {
    Text = "Immer meine Fähigkeiten verbessernd, hast du nicht Angst, dass ich eines Tages die Kontrolle verlieren könnte...? Haha, nur ein Scherz."
  },
  Voice_123801_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_123802_AwakerVoiceContent = {
    Text = "Eigentlich ist es gar nicht so schlimm, eine Weile in dieser Welt zu bleiben. Ich werde alles, was hier passiert, im Gedächtnis behalten und aufschreiben, damit ich es allen zu Hause erzählen kann, wenn ich zurückkehre. Hmm, nennen wir es \"Mouchettes Abenteuer in einer anderen Welt.\" Klingt toll, oder?"
  },
  Voice_123802_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_123802_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_123803_AwakerVoiceContent = {
    Text = "Ich gebe zu, dass sie sehr süß ist... Ja, das stimmt, es ist wirklich sehr niedlich, sie zu beobachten, wie sie mit den streunenden Katzen, die auf dem Campus herumlaufen, jagt und kämpft."
  },
  Voice_123803_AwakerVoiceTitle = {
    Text = "Plauderei · Über Murphy"
  },
  Voice_123803_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_123804_AwakerVoiceContent = {
    Text = "Obwohl diese Macht mir nicht erlaubt, in meine Welt zurückzukehren, ist es immer gut, stärker zu werden."
  },
  Voice_123804_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_123805_AwakerVoiceContent = {
    Text = "Mädchen, ich habe es auch gemacht; lass uns einen Zeitpunkt finden, an dem sie meine Methode des Kämpfens mit einem Staubsauger sieht!"
  },
  Voice_123805_AwakerVoiceTitle = {
    Text = "Chat: Über Karen"
  },
  Voice_123805_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Karen“ wird freigeschaltet"
  },
  Voice_123806_AwakerVoiceContent = {
    Text = "Haha, es stellt sich heraus, dass dieses adrenaline-pumpende Leben mir viel besser passt als die langweilige Alltagsroutine!"
  },
  Voice_123806_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_124737_AwakerVoiceContent = {
    Text = "Ein Schlag, ein Kill."
  },
  Voice_124737_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_124738_AwakerVoiceContent = {
    Text = "Reihe dich eins nach dem anderen auf."
  },
  Voice_124738_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_124769_AwakerVoiceContent = {
    Text = "Verschwinde!"
  },
  Voice_124769_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_126946_AwakerVoiceContent = {
    Text = "Denke nicht nach oder stören, höre blind zu und gehorche, denn die weltliche Welt ist nichts als eine Last!"
  },
  Voice_126946_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_126947_AwakerVoiceContent = {
    Text = "Denke nicht nach oder stören, höre blind zu und gehorche, denn die weltliche Welt ist nichts als eine Last!"
  },
  Voice_126947_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_126948_AwakerVoiceContent = {
    Text = "Du fragst sie, warum ihre Köpfe leer sind? Nun, vielleicht wurden sie so geboren."
  },
  Voice_126948_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_126949_AwakerVoiceContent = {
    Text = "Beruhige deinen Zorn und deinen Groll, denn alles wird zu nichts werden."
  },
  Voice_126949_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_126950_AwakerVoiceContent = {
    Text = "So viel Aufmerksamkeit lässt mich nicht widerstehen, dich noch mehr zu necken."
  },
  Voice_126950_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_126951_AwakerVoiceContent = {Text = "Oops!"},
  Voice_126951_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_126952_AwakerVoiceContent = {
    Text = "Erwartest du, dass ich schöner oder furchterregender bin?"
  },
  Voice_126952_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_126953_AwakerVoiceContent = {
    Text = "Die aus Freude geborene Prinzessin, ihr Kleid mit goldenen Fäden bestickt, ihre Haut gleicht Elfenbein, umgeben von dem Duft von Agarholz, fesselt alle mit ihrem bezaubernden Blick."
  },
  Voice_126953_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_126953_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_126954_AwakerVoiceContent = {
    Text = "Bald wurde sie müde von diesem Vergnügen, da ihre Gläubigen einfach die gleichen Routinen wiederholten, sich der Liebe hinzugeben, die aus Verlangen geboren wurde, oder dem Verlangen, das aus Liebe geboren wurde. Der Schmerz des Verlustes und des Verrats ließ sie den Tod herbeiwünschen, und ihre Dummheit langweilte sie, während ihre Tränen sie ebenfalls erschöpften."
  },
  Voice_126954_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_126954_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_126955_AwakerVoiceContent = {
    Text = "Deine mickrigen Blicke machen mich wirklich angewidert."
  },
  Voice_126955_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_126956_AwakerVoiceContent = {
    Text = "Die Dame in Rot hat mir mehrere Einladungen zu ihrem Salon geschickt. \n Der Geschmack der exotischen Gebäckstücke ist recht gut, aber... \n Sie hätte mir früher sagen sollen, dass Snacks und Dienstmädchen in ihrem Haus nicht dasselbe bedeuten."
  },
  Voice_126956_AwakerVoiceTitle = {
    Text = "Chat: Über Sorel"
  },
  Voice_126956_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Sorel“"
  },
  Voice_126958_AwakerVoiceContent = {
    Text = "Ist es nicht Liebe? Warum dann die Angst, wenn man umgeben ist? Ist es nicht Verachtung? Warum dann die Tränen, wenn es für immer unerreichbar ist? \nAh, hast du jetzt Angst vor meinem Schatten? Ist der Duft der weißen Magnolie für dich zu einem süßlichen, unerklärlichen Moschus geworden?"
  },
  Voice_126958_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_126958_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_126959_AwakerVoiceContent = {Text = "...Okay!"},
  Voice_126959_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_126960_AwakerVoiceContent = {
    Text = "Hä? Fragst du mich, warum sie diese Muster unter den Achseln haben? Denkst du nicht, dass es wirklich lustig ist?"
  },
  Voice_126960_AwakerVoiceTitle = {
    Text = "Chat: Der Orden der Schwellungs-Gnade"
  },
  Voice_126961_AwakerVoiceContent = {Text = "Oops!"},
  Voice_126961_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_126963_AwakerVoiceContent = {
    Text = "Im Vergleich zu den Angeboten der Gläubigen gefallen mir diese besser."
  },
  Voice_126963_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_126964_AwakerVoiceContent = {
    Text = "Zuerst das Auftreten, dann die Gestalt, bis sie ebenfalls ein Paar besaßen... oder vielmehr, was in Erinnerung blieb, war ein Paar schöner, seelenbewegender Augen—genau wie meine."
  },
  Voice_126964_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_126964_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_126965_AwakerVoiceContent = {
    Text = "Ich langweile mich heute wirklich. Hast du keine Wünsche, die erfüllt werden müssen?\nEs ist so schade, dass viele Menschen bereit sind, ihre Sensen zu schwingen und Blut und Fleisch für mich anzubieten, alles aus langweiligen Gründen.\nAber wenn du es wärst..."
  },
  Voice_126965_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_126965_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_126966_AwakerVoiceContent = {
    Text = "Warum die Füllige Menschenmenge mir folgt, und wie sie entstand? Eine amüsante Frage. Habt auch Ihr die unerreichbare Person gekannt, oder das Bedauern eines gescheiterten Kampfes?\nHmm, anscheinend nicht. Wie schade. Dieser Ausdruck verzweifelten Ringens — es wäre so überaus amüsant, ihn auf Eurem Gesicht zu erblicken."
  },
  Voice_126966_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_126966_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_126967_AwakerVoiceContent = {
    Text = "...Wenn du weiterhin so anmaßend bist, könnte es sein, dass ich dir nicht mit dieser Haltung begegne."
  },
  Voice_126967_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_126968_AwakerVoiceContent = {
    Text = "Ihre Geschichte, die ich fast völlig vergessen habe, ist jedoch eine Geschichte von Freude, eine Geschichte von Grausamkeit, eine Geschichte, die mit Verlassenheit und Vergeltung beginnt und später zu einer von Opfer und Gehorsam wird."
  },
  Voice_126968_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_126968_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_126969_AwakerVoiceContent = {
    Text = "Bitte mich und lass den Schmerz und die Angst dich dazu treiben, euch gegenseitig zu töten~"
  },
  Voice_126969_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_126970_AwakerVoiceContent = {
    Text = "...Das hat mein Interesse tatsächlich ein wenig geweckt."
  },
  Voice_126970_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_126971_AwakerVoiceContent = {
    Text = "Jeder wird das Gesicht seines Geliebten unter meinem Fächer sehen. Ich leihe diese Macht den Schwachen und werde zu einer Klinge zum Vergnügen. \n Aber vielleicht sage ich nur, vielleicht. \n Wenn du bereit bist, dich davon fesseln zu lassen, werde ich wahre, höchste Ekstase empfinden."
  },
  Voice_126971_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_126971_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_126972_AwakerVoiceContent = {
    Text = "Keine Sorge, du bist anders als diese Niemanden. \n Pssst, schau nicht hinter mich, kümmere dich nicht um die unsichtbaren Berührungen—schau einfach in meine Augen."
  },
  Voice_126972_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_126972_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_126973_AwakerVoiceContent = {
    Text = "*Lacht. Traust du dich, mein wahres Wesen zu betrachten?"
  },
  Voice_126973_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_126975_AwakerVoiceContent = {Text = "Lärmend."},
  Voice_126975_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_126976_AwakerVoiceContent = {
    Text = "Was? Starrst du wieder fasziniert auf meinen Fächer? \n Hehe, ganz gleich, wessen Gesicht du hinter dem Fächer sehen möchtest, ich werde dich zufriedenstellen... Komm, komm ein wenig näher— \n Oh, willst du nicht? Solche kalten Worte, und doch ist dein Ausdruck ziemlich niedlich..."
  },
  Voice_126976_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_126976_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_126977_AwakerVoiceContent = {
    Text = "Du bist ins Traumlose Land gekommen, wonach suchst du?"
  },
  Voice_126977_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_126978_AwakerVoiceContent = {
    Text = "Beruhige deinen Zorn und deinen Groll, denn alles wird zu nichts werden."
  },
  Voice_126978_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_126979_AwakerVoiceContent = {
    Text = "Sei nicht unhöflich."
  },
  Voice_126979_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_126980_AwakerVoiceContent = {Text = "...Okay!"},
  Voice_126980_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_126981_AwakerVoiceContent = {
    Text = "Ich hatte einmal ein schönes, schüchternes kleines Mädchen wie das. \n Eine auffällige Blütenknospe muss natürlich einige Dornen haben; sie kann nicht einfach in eine Vase gesteckt werden."
  },
  Voice_126981_AwakerVoiceTitle = {
    Text = "Chat: Über Lily"
  },
  Voice_126981_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Lily“"
  },
  Voice_126982_AwakerVoiceContent = {
    Text = "Die Akademie hat meinen Antrag auf eine Tätigkeit im Beratungsraum entschieden abgelehnt. Es ist wirklich seltsam, was könnte da nur falsch sein?"
  },
  Voice_126982_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_126983_AwakerVoiceContent = {
    Text = "Alles wird schließlich in die Vergänglichkeit zurückkehren, also warum nicht etwas Spaß mit mir suchen? \n Sei unbesorgt, wenn der Tag kommt, an dem du nicht widerstehen kannst, werde ich nicht zulassen, dass Er dich zuerst nimmt."
  },
  Voice_126983_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_126984_AwakerVoiceContent = {
    Text = "Langweilig."
  },
  Voice_126984_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_126985_AwakerVoiceContent = {
    Text = "Du bist eine wirklich bemerkenswerte Person, die mit so vielen äußeren Angelegenheiten in einer Welt beschäftigt ist, die dem Untergang geweiht ist. \n Das weckt sogar mein eigenes Interesse."
  },
  Voice_126985_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_126985_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_126986_AwakerVoiceContent = {
    Text = "Komm nicht zu nah!"
  },
  Voice_126986_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_126988_AwakerVoiceContent = {
    Text = "Ich bin Xu, die Dame des Traumlosen Landes. Wenn es jemanden in deinem Herzen gibt, den du sehen möchtest, aber nicht kannst, bin ich bereit, die Flammen zu schüren und dir einen Blick zu gewähren."
  },
  Voice_126988_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_127088_AwakerVoiceContent = {
    Text = "Alle Nachkommen lebender Wesen können ziemlich lästig sein. \n Klein, weich und laut, bringen sie unabsichtlich alles um sich herum durcheinander. Ich mag eine lebhafte Atmosphäre, aber ich mag diesen Lärm wirklich nicht, also bitte haltet sie auf Abstand."
  },
  Voice_127088_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_127089_AwakerVoiceContent = {
    Text = "Meine kleine Jasminblüte, mein brav Baby, ich bin süß wie Honig in diesem Spielhaus~\n Ach, es sind nur einige fröhliche Schwärmereien, die Sie nicht beachten müssen."
  },
  Voice_127089_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_127090_AwakerVoiceContent = {
    Text = "In den Legenden des Panlong-Reichs ist der Pfau ein schönes und prunkvolles Tier. \n Schön, aber bösartig, sorgt es für Herzklopfen; wäre es hässlich, aber freundlich, wäre es eher langweilig."
  },
  Voice_127090_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_129651_AwakerVoiceContent = {
    Text = "Auffressen! Mjam mjam!"
  },
  Voice_129651_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_129652_AwakerVoiceContent = {
    Text = "Gluck gluck~"
  },
  Voice_129652_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_129653_AwakerVoiceContent = {
    Text = "Kohleball, ich, essen, zusammen? Zusammen!"
  },
  Voice_129653_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_129653_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_129654_AwakerVoiceContent = {
    Text = "Mosk! Sehr stark!"
  },
  Voice_129654_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_129655_AwakerVoiceContent = {
    Text = "Abgrund! Spirale! Zerstörung! Alles——verwandelt sich in den Wirbel!"
  },
  Voice_129655_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_129656_AwakerVoiceContent = {Text = "Aua!"},
  Voice_129656_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_129657_AwakerVoiceContent = {
    Text = "Fass mich nicht an! Fass mich an, und es wird kaputtgehen!"
  },
  Voice_129657_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_129657_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_129658_AwakerVoiceContent = {
    Text = "Schale, strahlend! Strahlend, schön, hier hast du es!"
  },
  Voice_129658_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_129658_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_129659_AwakerVoiceContent = {
    Text = "Kalt, beängstigend, Mosk, versteck dich!"
  },
  Voice_129659_AwakerVoiceTitle = {
    Text = "Plauderei: Über Puppe"
  },
  Voice_129659_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Puppe“ wird freigeschaltet"
  },
  Voice_129660_AwakerVoiceContent = {Text = "Ja hu!"},
  Voice_129660_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_129661_AwakerVoiceContent = {
    Text = "Jagd, verdammt! Zerschlagt sie! Mosk, verprügelt sie, zerschlagt sie!"
  },
  Voice_129661_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_129662_AwakerVoiceContent = {
    Text = "So viel Spaß! Beim nächsten Mal! Ich will mehr!"
  },
  Voice_129662_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_129662_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_129663_AwakerVoiceContent = {
    Text = "Streichle, gut! Mosk, du, streichle!"
  },
  Voice_129663_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_129664_AwakerVoiceContent = {
    Text = "Nein, tu das nicht! Kohleball, Mosk, schütze!"
  },
  Voice_129664_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_129665_AwakerVoiceContent = {
    Text = "Noch einmal? Noch einmal!"
  },
  Voice_129665_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_129666_AwakerVoiceContent = {
    Text = "Hehe, Mosk, lass uns spielen!"
  },
  Voice_129666_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_129667_AwakerVoiceContent = {
    Text = "Die große Welle kommt!"
  },
  Voice_129667_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_129668_AwakerVoiceContent = {Text = "Werf!"},
  Voice_129668_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_129669_AwakerVoiceContent = {Text = "Aua!"},
  Voice_129669_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_129670_AwakerVoiceContent = {Text = "Oh!"},
  Voice_129670_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_129671_AwakerVoiceContent = {
    Text = "Ritual?! Nimm mich mit!"
  },
  Voice_129671_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_129671_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_129672_AwakerVoiceContent = {
    Text = "Wirbel! Stärke! Stock!"
  },
  Voice_129672_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_129672_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_129673_AwakerVoiceContent = {Text = "Peng!"},
  Voice_129673_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_129674_AwakerVoiceContent = {Text = "Juhu!"},
  Voice_129674_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_129675_AwakerVoiceContent = {
    Text = "Hui la hui la~"
  },
  Voice_129675_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_129676_AwakerVoiceContent = {
    Text = "Schlägerei!"
  },
  Voice_129676_AwakerVoiceTitle = {
    Text = "Small Talk: Über Goliath"
  },
  Voice_129676_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Goliath“ wird freigeschaltet"
  },
  Voice_129677_AwakerVoiceContent = {
    Text = "Viel gefunden, strahlend hell!"
  },
  Voice_129677_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_129677_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_129678_AwakerVoiceContent = {
    Text = "Abgrund! Wirbel! Zerstörung! Alles — verwandle dich in einen Wirbel!"
  },
  Voice_129678_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_129679_AwakerVoiceContent = {Text = "Uwaa!!"},
  Voice_129679_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_129680_AwakerVoiceContent = {Text = "Ih!"},
  Voice_129680_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_129681_AwakerVoiceContent = {
    Text = "Mosk! Sehr stark!"
  },
  Voice_129681_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_129682_AwakerVoiceContent = {
    Text = "Auffressen! Mjam mjam!"
  },
  Voice_129682_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_129683_AwakerVoiceContent = {
    Text = "Der Nautilus, Nautila, Kohleball! Glänzend!"
  },
  Voice_129683_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_129684_AwakerVoiceContent = {
    Text = "Mosk, lade die Munition!"
  },
  Voice_129684_AwakerVoiceTitle = {
    Text = "Fähigkeit·II·Laden Eins"
  },
  Voice_129685_AwakerVoiceContent = {
    Text = "Mosk, lauf weg!"
  },
  Voice_129685_AwakerVoiceTitle = {
    Text = "Fähigkeit·II·Nachladen·II"
  },
  Voice_129686_AwakerVoiceContent = {
    Text = "Umarmung! Mosk! Gefällt mir!"
  },
  Voice_129686_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_129686_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_129687_AwakerVoiceContent = {
    Text = "Kohleball, Freund! Mosk, für immer!"
  },
  Voice_129687_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_129688_AwakerVoiceContent = {
    Text = "Schnell, schnell!"
  },
  Voice_129688_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_129688_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_129689_AwakerVoiceContent = {
    Text = "Mosk! Kohleball! Zusammen, immer? Für immer!"
  },
  Voice_129689_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_129689_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_129690_AwakerVoiceContent = {
    Text = "Juhu, lass die großen Wellen steigen!"
  },
  Voice_129690_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_129690_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_129691_AwakerVoiceContent = {
    Text = "Freund! So viele! Ich mag es!"
  },
  Voice_129691_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_129692_AwakerVoiceContent = {
    Text = "Mosk! Beeindruckend!"
  },
  Voice_129692_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_129693_AwakerVoiceContent = {
    Text = "Nautila, willst du sehen. Eh, Nautila, Mosk, Mosk!"
  },
  Voice_129693_AwakerVoiceTitle = {
    Text = "Small Talk: Über Nautila"
  },
  Voice_129693_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Nautila“ wird freigeschaltet"
  },
  Voice_129694_AwakerVoiceContent = {
    Text = "Ich bin stärker geworden!"
  },
  Voice_129694_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_129695_AwakerVoiceContent = {
    Text = "Ich! Mosk! Hallo!"
  },
  Voice_129695_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_130511_AwakerVoiceContent = {Text = "Puh—"},
  Voice_130511_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Zwei·Laden Drei"
  },
  Voice_133720_AwakerVoiceContent = {
    Text = "Der Fehler muss korrigiert werden."
  },
  Voice_133720_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_133721_AwakerVoiceContent = {
    Text = "Die Tragödie vor Euch ist nur ein Blick unter zahllosen Möglichkeiten.\n\nJenseits des Vorhangs des Schicksals liegt eine in Dunkelheit versunkene Bühne —\nLichter erloschen, Darsteller fort, alles kehrt in die Tiefe zurück.\n\nDoch dort endet es nicht.\nIch trage die Entschlossenheit, diese undankbare Arbeit zu ertragen, bis zu dem Tag, an dem die Lichter zurückkehren."
  },
  Voice_133721_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_133722_AwakerVoiceContent = {
    Text = "Das Schicksal jeder Seele wird von Fäden getragen... doch Eures ist ein Drehbuch, das ich nicht entziffern kann. Ich ertappe mich dabei, mich auf jede Improvisation zu freuen, die Ihr in diese Welt bringen werdet."
  },
  Voice_133722_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_133723_AwakerVoiceContent = {
    Text = "Die Bühne war schon immer Eure. Tretet vor, liebe Marionette."
  },
  Voice_133723_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_133724_AwakerVoiceContent = {Text = "Hm?"},
  Voice_133724_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_133725_AwakerVoiceContent = {
    Text = "Alles ist ein vergangener Epilog. Alles ist ein neuer Prolog. Das neue Kapitel zwischen uns wartet darauf, von Euch geschrieben zu werden, Schutzherr."
  },
  Voice_133725_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_133725_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_133726_AwakerVoiceContent = {
    Text = "Wenn Euch die Komödie zusagt, wäre <Italic:Ein Sommernachtstraum> eine gute Wahl. Ich bin besonders angetan von Pucks schelmischem Geplapper — verborgen im Lachen eines Kobolds lässt das Schicksal stets etwas durchsickern."
  },
  Voice_133726_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_133726_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_133727_AwakerVoiceContent = {
    Text = "Fügt Euch."
  },
  Voice_133727_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_133728_AwakerVoiceContent = {
    Text = "Die Spindel des Schicksals dreht sich nun."
  },
  Voice_133728_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_133729_AwakerVoiceContent = {
    Text = "Gefangener des Schicksals, erbärmlich wie eh und je... was geschrieben steht, lässt sich nicht verweigern."
  },
  Voice_133729_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_133730_AwakerVoiceContent = {
    Text = "Selbst jemand, der alle Dinge beobachtet, bleibt ein unbeholfener Darsteller im eigenen Drehbuch. Das Netz des Schicksals zu halten und doch von seinen Fäden gebunden zu sein — wir gehen verschiedene Wege in dieser vorbestimmten Lage, doch keiner von uns hat je wirklich seine undankbaren Bestrebungen aufgegeben. Töricht, vielleicht. Verblendet, vielleicht. So ist es mit mir, und so ist es mit ihr."
  },
  Voice_133730_AwakerVoiceTitle = {
    Text = "Small Talk: Über Tawil"
  },
  Voice_133730_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Tawil“ wird freigeschaltet"
  },
  Voice_133731_AwakerVoiceContent = {
    Text = "Eine unerwartete Wendung?"
  },
  Voice_133731_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_133732_AwakerVoiceContent = {
    Text = "Ich danke Euch, dass Ihr mich durch so viele sich hebende und senkende Vorhänge begleitet habt. Ich werde Euch nicht enttäuschen — es gibt noch weitere Abende, die Euch auf Weisen bewegen werden, die Ihr nicht erwartet habt."
  },
  Voice_133732_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_133732_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_133733_AwakerVoiceContent = {
    Text = "Was für eine begnadete Sängerin. Eine von Gnade geschenkte Stimme, klar und brennend zugleich, als erhöbe sie sich aus dem Schicksal selbst. Wenn sie in meinem Theater aufträte, würde sie, so stelle ich mir vor, selbst das anspruchsvollste Publikum überrumpeln."
  },
  Voice_133733_AwakerVoiceTitle = {
    Text = "Small Talk: Über Tinct"
  },
  Voice_133733_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Tinktur“ wird freigeschaltet"
  },
  Voice_133734_AwakerVoiceContent = {
    Text = "Die unsichtbaren Fäden, die Euch und mir gehören, haben sich längst fest umeinander gewunden und weben zugleich einen Käfig und einen Weg.\nIch kann nicht sehen, wo der Käfig endet, noch wohin der Weg führt.\nGenau das macht diese Geschichte so fesselnd."
  },
  Voice_133734_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_133734_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_133735_AwakerVoiceContent = {
    Text = "Die Fäden des Schicksals hängen still."
  },
  Voice_133735_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_133736_AwakerVoiceContent = {
    Text = "Sie besucht mein Theater oft... doch ich weiß, sie kommt nicht wegen der Stücke. Sie scheint diese Bühne zu nutzen, um ihrem eigenen Bild eine gewisse Verfeinerung zu verleihen. Solch bemerkenswerte Begabung allerdings — sie nur als Zuschauerin einzusetzen, scheint eine Verschwendung. Diese Dame ist nicht die Art, die im Dunkel des Publikums erblüht. Sie gehört ins Rampenlicht."
  },
  Voice_133736_AwakerVoiceTitle = {
    Text = "Chat: Über Sorel"
  },
  Voice_133736_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Sorel“"
  },
  Voice_133737_AwakerVoiceContent = {
    Text = "Ich habe ihn einmal spielen hören. Diese Musik ließ die Seele erzittern... Vielleicht sollte ich ihn einladen, eine Schicksalssymphonie für meine nächste Inszenierung zu komponieren."
  },
  Voice_133737_AwakerVoiceTitle = {
    Text = "Plauderei: Über Hameln"
  },
  Voice_133737_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Hameln“ wird freigeschaltet"
  },
  Voice_133738_AwakerVoiceContent = {
    Text = "Eine weitere Geschichte, wunderschön vollendet, neigt sich ihrem Ende zu."
  },
  Voice_133738_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_133739_AwakerVoiceContent = {
    Text = "Ich habe es endlich in seiner Gänze gesehen. Das endlose Netz des Schicksals."
  },
  Voice_133739_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_133740_AwakerVoiceContent = {
    Text = "Wenn Ihr es erlaubt... Ich möchte ein Stück weben, das nur Euch und mir gehört.\nKein Publikum, keine Probe. Ich möchte einfach sehen, wie der Faden, den selbst ich nicht lesen kann, sich zu regen beginnt... wenn Ihr ins Licht tretet."
  },
  Voice_133740_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_133740_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_133741_AwakerVoiceContent = {
    Text = "Was für eine vom Schicksal geplagte Tänzerin. Ich habe ihre Schritte beobachtet. Ihre Schönheit bewegt sich auf den Untergang zu — jede Drehung entzündet grüne Flammen, als versuchte sie, die Fäden des Schicksals wegzubrennen, obwohl diese Fäden am Ende nur etwas schmerzlich Lebendiges aus ihr herausschneiden werden. Wenn sich die Gelegenheit ergibt, würde ich gerne ein Ballett nur für sie schreiben."
  },
  Voice_133741_AwakerVoiceTitle = {
    Text = "Small Talk: Über Liz"
  },
  Voice_133741_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Liz“"
  },
  Voice_133742_AwakerVoiceContent = {
    Text = "Hier wird es gewoben. Hier wird es gewogen. Hier wird es durchtrennt."
  },
  Voice_133742_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_133743_AwakerVoiceContent = {
    Text = "Seid still..."
  },
  Voice_133743_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_133744_AwakerVoiceContent = {
    Text = "Ein weiterer Faden wird sichtbar."
  },
  Voice_133744_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_133745_AwakerVoiceContent = {
    Text = "Der Vorhang ist für Euch geöffnet, und das Drehbuch des Schicksals wartet darauf zu beginnen. Sagt mir: Welchen vorbestimmten Pfad würdet Ihr lieber beschreiten? Ein trauriges Ende oder einen freudigen Anfang?"
  },
  Voice_133745_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_133745_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_133746_AwakerVoiceContent = {
    Text = "Ich habe dieses Weben Tag für Tag recht liebgewonnen... Im stillen, wiederholten Ziehen eines jeden Fadens sehe ich die Anfänge und Enden aller Geschichten. Wenn ich jeden Vorhang fallen sehe, fühle ich mich zuweilen, als hätte ich mich über das Schicksal selbst erhoben. Und doch kann man dem Netz des Schicksals nicht entkommen, und nur zuzuschauen hinterlässt am Ende ein hohles Gefühl.\nIn solchen Momenten gehe ich ins Theater. Um die Leiden und Freuden aufzuführen, die ich mit eigenen Händen gesponnen, aber niemals selbst erlebt habe."
  },
  Voice_133746_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_133747_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_133747_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_133748_AwakerVoiceContent = {Text = "Heh..."},
  Voice_133748_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_133749_AwakerVoiceContent = {
    Text = "Hier wird es gewoben. Hier wird es gewogen. Hier wird es durchtrennt."
  },
  Voice_133749_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_133750_AwakerVoiceContent = {
    Text = "Das Schicksal regt sich. Sein Flüstern naht."
  },
  Voice_133750_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_133751_AwakerVoiceContent = {
    Text = "Das Theater hat eine neue romantische Komödie auf die Bühne gebracht, und ich habe Euch einen Platz im Publikum des Schicksals reserviert. Durch jede lange Nacht, in der sich Schicksale verflechten, werde ich still auf den Moment warten, in dem sich unsere Sterne begegnen."
  },
  Voice_133751_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_133751_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_133752_AwakerVoiceContent = {
    Text = "So beharrlich an den Fäden des Schicksals zu ziehen...\n\nIhr scheint recht begierig darauf zu sein, Eure eigene Geschichte zu lesen, nicht wahr?"
  },
  Voice_133752_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_133753_AwakerVoiceContent = {
    Text = "Was geschrieben steht, naht heran."
  },
  Voice_133753_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_133754_AwakerVoiceContent = {
    Text = "Wenn Ihr die Hallen der Tragödie betreten wollt, erlaubt mir, Euch <Italic:Antigone> zu präsentieren. Gefangen zwischen göttlichem Gesetz und sterblichem Erlass, fällt jeder ihrer Schritte auf Fäden, die das Schicksal bereits gesponnen hat, bis sie schließlich in den tiefen Schatten des steinernen Grabes tritt. Gerade weil diese Ketten nicht gebrochen werden können, lodert der Wille in ihrem zierlichen Körper so leuchtend gegen die lange Nacht."
  },
  Voice_133754_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_133754_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_133755_AwakerVoiceContent = {
    Text = "Kein Ende ist jemals wirklich gewiss, und doch entkommt keines dem Netz von Ursache und Wirkung..."
  },
  Voice_133755_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_133756_AwakerVoiceContent = {
    Text = "Auf den Fäden sehe ich Farben, die durch jeden Ton des Regenbogens wechseln.\nSie erstrecken sich über ein endloses Netz, spinnen grenzenlose Welten und unendliche Möglichkeiten, bis sie ein Muster weben, schöner als jedes, das je gesehen wurde.\n\nAm Ende — ob Gott oder Sterblicher, Held oder Schurke — wird jeder von diesen zarten Fäden geleitet, kopfüber seinem bestimmten Ende entgegeneilend unter dem unverwandten Blick des Schicksals."
  },
  Voice_133756_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_133757_AwakerVoiceContent = {
    Text = "Ich dachte, nichts auf dieser Welt könnte mich noch überraschen... Euer Theatergeschmack hat Eindruck hinterlassen."
  },
  Voice_133757_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_133757_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_133758_AwakerVoiceContent = {
    Text = "Die Fäden des Schicksals verbinden sich stets im Verborgenen... Ihr habt einen solchen Faden berührt und mich damit aufgeschreckt."
  },
  Voice_133758_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_133758_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_133759_AwakerVoiceContent = {
    Text = "Ich hatte nie etwas für Aufführungen übrig, die sich einfach nur wiederholen. Der eigentliche Grund, ein Theater zu betreten, ist, eine lebendige Bühne zu erleben — eine, die nicht nachgebildet werden kann.\nWenn sie sich nur wie ein Uhrwerk dreht, wird die Bühne zu einem prunkvollen Käfig, und das Zuschauen wird zu nichts weiter als einer mühseligen Pilgerreise zu einem Ende, das man bereits kennt.\nEine seelenlose Maskerade, egal wie prächtig die Inszenierung ist. Was meint Ihr?"
  },
  Voice_133759_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_133760_AwakerVoiceContent = {
    Text = "Einst flossen diese Fäden in vollkommener Ordnung durch meine Hände... bis Ihr erschient und Wellen durch ihren Lauf sandtet, die ich niemals vorhergesehen hatte."
  },
  Voice_133760_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_133760_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_133761_AwakerVoiceContent = {
    Text = "Gefangener des Schicksals, erbärmlich wie eh und je... was geschrieben steht, lässt sich nicht verweigern."
  },
  Voice_133761_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_133762_AwakerVoiceContent = {
    Text = "Aus endlosen Fäden spinne ich den einzigen Pfad."
  },
  Voice_133762_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_133763_AwakerVoiceContent = {
    Text = "Auf der großen Bühne des Schicksals warten alle Seelen im Netz von Ursache und Wirkung auf ihren Einsatz, ihre Freuden und Leiden nehmen leise Gestalt an, während die Zahnräder sich drehen...\nDer Vorhang ist gefallen, Schutzherr. Hier beginnt Eure Geschichte und die meine."
  },
  Voice_133763_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_133764_AwakerVoiceContent = {
    Text = "Der Konflikt ist da. Wollt Ihr den Helden spielen, der das Netz zerreißt, oder den Spieler, der sich nur bewegt, wie die Fäden es erlauben?"
  },
  Voice_133764_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_133765_AwakerVoiceContent = {
    Text = "Sinnloser Widerstand."
  },
  Voice_133765_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_139865_AwakerVoiceContent = {
    Text = "Danke. Ich werde dieses Geschenk sorgfältig schätzen."
  },
  Voice_139865_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_139866_AwakerVoiceContent = {
    Text = "Ich habe die Struktur Erweckter Körper ziemlich ausgiebig studiert, also würde ich mich mittlerweile als Experten bezeichnen. Aber die „Spiritualität\" in den Silberkernen... diesen Teil verstehe ich noch nicht ganz."
  },
  Voice_139866_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_139866_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_139867_AwakerVoiceContent = {
    Text = "Das ist... wo eine neue Welt beginnt."
  },
  Voice_139867_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_139868_AwakerVoiceContent = {
    Text = "Ich kann so was, weißt du. Zum Beispiel die Körper anderer Kreaturen umstrukturieren oder anpassen..."
  },
  Voice_139868_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_139868_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_139869_AwakerVoiceContent = {
    Text = "Jedes Lebewesen ist anders, also muss man sie wirklich sorgfältig studieren, bevor man anfängt, etwas zu verändern."
  },
  Voice_139869_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_139869_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_139870_AwakerVoiceContent = {
    Text = "Bin ich nicht beängstigend? Hey, das ist ein bisschen langweilig..."
  },
  Voice_139870_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_139871_AwakerVoiceContent = {
    Text = "Ich lasse niemanden uns in die Quere kommen."
  },
  Voice_139871_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_139872_AwakerVoiceContent = {
    Text = "Ich bin bereit, jederzeit."
  },
  Voice_139872_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_139873_AwakerVoiceContent = {
    Text = "Lebewesen sind wirklich voller Vielfalt. Ich will noch so viel mehr lernen!"
  },
  Voice_139873_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_139875_AwakerVoiceContent = {
    Text = "Willst du mit Shaye spielen?"
  },
  Voice_139875_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_139876_AwakerVoiceContent = {Text = "Autsch!!"},
  Voice_139876_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_139877_AwakerVoiceContent = {
    Text = "Das ist... wo eine neue Welt beginnt."
  },
  Voice_139877_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_139878_AwakerVoiceContent = {
    Text = "Ich bin satt, danke für die Bewirtung"
  },
  Voice_139878_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_139880_AwakerVoiceContent = {
    Text = "Hüter des Geheimnisses, hast du jemals jemanden geliebt oder an jemanden gedacht?"
  },
  Voice_139880_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_139880_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_139881_AwakerVoiceContent = {Text = "Ngh!"},
  Voice_139881_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_139882_AwakerVoiceContent = {
    Text = "Ist es hier?"
  },
  Voice_139882_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_139883_AwakerVoiceContent = {
    Text = "Gute Arbeit! Was Gutes gefunden?"
  },
  Voice_139883_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_139884_AwakerVoiceContent = {
    Text = "Nach verschiedenen Überprüfungen habe ich es im Großen und Ganzen verstanden. Jede Art von Erwecker hat eine völlig andere „Weisheit\". Und die Weisheit in meinem Silberkern scheint „Liebe\" zu sein."
  },
  Voice_139884_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_139884_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_139885_AwakerVoiceContent = {
    Text = "Wie, hast du dich erschreckt?"
  },
  Voice_139885_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_139886_AwakerVoiceContent = {
    Text = "Das ist mein letztes Geschenk... an dich."
  },
  Voice_139886_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_139887_AwakerVoiceContent = {
    Text = "„Auf einem dieser Sterne blüht meine Blume...\" so hast du gesagt. \n Es scheint, als hättest du so etwas auch gesagt."
  },
  Voice_139887_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_139887_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_139888_AwakerVoiceContent = {
    Text = "Es scheint, als wären „Silberkerne\" jeweils mit einem Willen aus weiter Ferne verbunden. Wie geheimnisvoll..."
  },
  Voice_139888_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_139888_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_139889_AwakerVoiceContent = {
    Text = "Das ist mein letztes Geschenk... an dich."
  },
  Voice_139889_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_139891_AwakerVoiceContent = {Text = "Ja!"},
  Voice_139891_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_139892_AwakerVoiceContent = {
    Text = "Der kleine Prinz sagte, es sei seine Pflege der Rose, die sie besonders macht... Denkst du das auch?"
  },
  Voice_139892_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_139892_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_139893_AwakerVoiceContent = {
    Text = "Gestern habe ich in Lilys Bücherregal ein Buch mit dem Titel „Der kleine Prinz“ gesehen. Ich habe es mir ausgeliehen. Möchtest du mit mir zusammen lesen?"
  },
  Voice_139893_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_139893_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_139895_AwakerVoiceContent = {
    Text = "Ja, ich habe die Struktur von Silberkernen studiert und beginne zu verstehen, wie Erweckte Körper funktionieren."
  },
  Voice_139895_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_139895_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_139896_AwakerVoiceContent = {Text = "Ja!"},
  Voice_139896_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_139897_AwakerVoiceContent = {Text = "Heyo!"},
  Voice_139897_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_139899_AwakerVoiceContent = {
    Text = "Bitte um Nachsicht!"
  },
  Voice_139899_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_139900_AwakerVoiceContent = {
    Text = "Hallo! … Ist das so richtig? \n Ich bin Shaye. Hmm … Ich freue mich auf die Zusammenarbeit—"
  },
  Voice_139900_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_139901_AwakerVoiceContent = {
    Text = "Es gibt eine Blume namens Pusteblume, die ihre Samen mit dem Wind treiben lässt. Die flauschigen Samen werden vom Wind mitgenommen, weit weg von ihrer Heimat, vielleicht landen sie in einer Wüste ohne ein einziges Gras oder Baum. In solchen Momenten, was könnte dieser kleine Samen wohl denken…"
  },
  Voice_139901_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_139901_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_139902_AwakerVoiceContent = {
    Text = "Egal wie oft man es macht, es macht immer Spaß!"
  },
  Voice_139902_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_139903_AwakerVoiceContent = {Text = "Heja!"},
  Voice_139903_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_139906_AwakerVoiceContent = {Text = "Pass auf!"},
  Voice_139906_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_140533_AwakerVoiceContent = {
    Text = "Ich liebe köstliches Essen! Ich mag auch Menschen, die sanft zu Shaye sind. Wenn ich sanft behandelt werde, bin ich wirklich sehr glücklich—"
  },
  Voice_140533_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_140534_AwakerVoiceContent = {
    Text = "Sie ist diejenige, die mich erweckt hat? Sie sieht wirklich... blendend aus. Und, hast du ihr geholfen, ihre Schwester zu finden?"
  },
  Voice_140534_AwakerVoiceTitle = {
    Text = "Small Talk: Über Tinct"
  },
  Voice_140534_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Tinktur“ wird freigeschaltet"
  },
  Voice_140535_AwakerVoiceContent = {
    Text = "Immer wenn Shaye den Schutzherrn für sich alleine haben möchte, kommen viele seltsame Leute herbei. Sie mag es immer noch mehr, wenn sie im Geheimgang ist—"
  },
  Voice_140535_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_140536_AwakerVoiceContent = {
    Text = "Verstehe. Ich kümmere mich darum!"
  },
  Voice_140536_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_140537_AwakerVoiceContent = {
    Text = "Schutzherr, Link, Erwecker, das sind die Beziehungen, die du mir erzählt hast, oder? Ich kann fühlen, dass die Seelen von zwei Personen miteinander verbunden sind... durch silberne Fäden? Irgendwie, hm—es scheint alles so kompliziert zu sein..."
  },
  Voice_140537_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_140538_AwakerVoiceContent = {
    Text = "Samen durch Fleisch und Blut verbreiten? Hmm... interessant. Ich bin eigentlich neugierig auf ihre Schafe."
  },
  Voice_140538_AwakerVoiceTitle = {
    Text = "Plauderei: Über Thais"
  },
  Voice_140538_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Thais“ wird freigeschaltet"
  },
  Voice_140539_AwakerVoiceContent = {
    Text = "Eine Art Krise, die diese Welt bedroht, wird die Dunkelheit des Aussterbens herbeiführen, nicht wahr? Das weiß ich. Ich habe viel von Professor Doll gehört."
  },
  Voice_140539_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_140540_AwakerVoiceContent = {
    Text = "Ich mag keine groben Menschen. Das macht ein unangenehmes Gefühl…"
  },
  Voice_140540_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_140541_AwakerVoiceContent = {
    Text = "Oh? Ihre Art vermehrt sich also auf neuen Planeten, indem sie andere Spezies jagt. Huh, verstehe..."
  },
  Voice_140541_AwakerVoiceTitle = {
    Text = "Plaudern: Über Winkle"
  },
  Voice_140541_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Zwinkern“ wird freigeschaltet"
  },
  Voice_141963_AwakerVoiceContent = {
    Text = "Braves Kind."
  },
  Voice_141963_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_141964_AwakerVoiceContent = {Text = "Hey!"},
  Voice_141964_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Drei"
  },
  Voice_141965_AwakerVoiceContent = {Text = "...Okay!"},
  Voice_141965_AwakerVoiceTitle = {
    Text = "Treffer · Fünf"
  },
  Voice_143501_AwakerVoiceContent = {
    Text = "Wie schade. Wenn du deine Meinung änderst, weißt du, wo du mich findest."
  },
  Voice_143501_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_143501_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_143502_AwakerVoiceContent = {
    Text = "Verdammt..."
  },
  Voice_143502_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_143503_AwakerVoiceContent = {
    Text = "Haut, Muskeln, Nerven, Knochen – sie alle werden neu aufgebaut, wieder gesund und heil, wieder voller Lebendigkeit."
  },
  Voice_143503_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_143503_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_143504_AwakerVoiceContent = {
    Text = "Vor dem Ozean gibt es keinen unbesiegbaren Feind!"
  },
  Voice_143504_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_143505_AwakerVoiceContent = {
    Text = "Festmahl, Verfolgung, Zuflucht?\nBete zu mir, das älteste Meerwasser wird dir meinen Namen verraten.\nIch bin der Herr des Abgrunds, Pontos."
  },
  Voice_143505_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_143506_AwakerVoiceContent = {
    Text = "Hehe, sehnst du dich nach der Zeit in Ebwynnos? ...\nEs ist in diesem Körper, und es heißt dich jederzeit willkommen, zurückzukehren."
  },
  Voice_143506_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_143507_AwakerVoiceContent = {
    Text = "Obwohl ich das nicht getan habe – solltest du eines Tages das Rauschen von Meerwasser und das Flattern von Flügeln in deinen Ohren hören, mach dir keine Sorgen, das ist völlig normal."
  },
  Voice_143507_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_143508_AwakerVoiceContent = {
    Text = "Opfere deine Sinne und bereue für immer im Abgrund!"
  },
  Voice_143508_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_143509_AwakerVoiceContent = {
    Text = "Ich mag lebhafte junge Menschen. Leider ist Misaqs Kontrolle über das Feiern viel zu streng – es gibt nicht einmal ein anständiges Jagdrevier.\nUnd dazu noch dieses schmutzige Ding dort drin, das es wagt, offen herumzustolzieren und sogar den Titel eines Professors zu tragen."
  },
  Voice_143509_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_143510_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_143510_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_143511_AwakerVoiceContent = {
    Text = "Nach allem, was ich getan habe, willst du mich nicht einmal mehr Onkel nennen. Das macht mir wirklich Kopfschmerzen."
  },
  Voice_143511_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_143513_AwakerVoiceContent = {
    Text = "Nur keine Eile – die Dunkelheit aus den tiefsten Tiefen des Ozeans wird euch verschlingen."
  },
  Voice_143513_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_143514_AwakerVoiceContent = {
    Text = "Knie nieder und werde zur Nahrung für Ebwynnos."
  },
  Voice_143514_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Drei"
  },
  Voice_143515_AwakerVoiceContent = {
    Text = "Was das Wesen betrifft, das mich auserwählt hat... man kann nur sagen, es ist sowohl freundlich als auch grausam.\nWo man landet, hängt ganz von seiner Laune ab – es wird dich gewiss aus der Gefahr retten, ob der neue Ort jedoch eine weitere Gefahr ist, das ist etwas, worüber man sich auf dieser „Reise \" keine Gedanken machen muss.\nWie interessant, wie unvorhersehbar – ich erwäge, diese Tradition fortzuführen."
  },
  Voice_143515_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_143515_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_143516_AwakerVoiceContent = {
    Text = "Ebwynnos und ich haben eine ganz besondere Verbindung. Besser gesagt: Ich bin Ebwynnos, Ebwynnos hängt von mir ab und existiert durch meinen Körper."
  },
  Voice_143516_AwakerVoiceTitle = {
    Text = "Small Talk: Über Ebwynnos"
  },
  Voice_143517_AwakerVoiceContent = {
    Text = "Heb den Kopf und entblöße deine Kehle."
  },
  Voice_143517_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_143518_AwakerVoiceContent = {
    Text = "Erinnerungen auslöschen, Existenz tilgen. Irgendwie vertraut ... du weißt, was ich meine. Auch wenn die Quelle eine andere ist, scheinen sie immer aus lichtlosen Tiefen zu entstehen."
  },
  Voice_143518_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_143519_AwakerVoiceContent = {
    Text = "Ihr wart dumm genug, meine Würde zu missachten."
  },
  Voice_143519_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_143520_AwakerVoiceContent = {
    Text = "Zu schwach."
  },
  Voice_143520_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_143521_AwakerVoiceContent = {
    Text = "In Ebwynnos hört das Fest niemals auf, und die Feinde von Ebwynnos werden niemals Ruhe finden."
  },
  Voice_143521_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_143521_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_143522_AwakerVoiceContent = {
    Text = "Ah, ich empfinde dein Zittern mit dir, aber das ist völlig unnötig, mein junger Freund.\nNimm deine Angst vor Mittelmäßigkeit und dem Aufgerieben-Werden an, schau mich an – du weißt, dass du immer eine andere Wahl hast."
  },
  Voice_143522_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_143522_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_143523_AwakerVoiceContent = {
    Text = "Ja, ich weiß, dass diese Katastrophe nicht direkt von ihm angeordnet wurde – nur ein zufälliges Ereignis während seines Zeitvertreibs. Aber das macht mich offensichtlich nur noch mehr dazu bringen, ihn zu töten.\nDieser schwarze Nebel sollte besser nicht allein sein und mir nicht in die Hände fallen."
  },
  Voice_143523_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_143524_AwakerVoiceContent = {
    Text = "Diese schleimigen Fischmenschen sind nicht meine Freunde, sondern meine Feinde. Überraschend? Der Ozean hat ihnen nie gehört."
  },
  Voice_143524_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_143524_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_143525_AwakerVoiceContent = {
    Text = "Für alle Ewigkeit – verweile hier!"
  },
  Voice_143525_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_143526_AwakerVoiceContent = {
    Text = "Seid ihr bereit, meine Beute!"
  },
  Voice_143526_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_143527_AwakerVoiceContent = {
    Text = "Die Spiritualität bringt neue Körper hervor, die Körper werden mit bedeutungslosem Wissen gefüllt, und dann werden jene schönen, lebhaften Wesen für immer an einem Ort versammelt sein.\nErinnerst du dich noch, was ich sagte? Die tiefsten Tiefen des Ozeans fassen alles ... und behalten alles."
  },
  Voice_143527_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_143527_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_143528_AwakerVoiceContent = {
    Text = "Albtraum, halte Sie auf."
  },
  Voice_143528_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_143529_AwakerVoiceContent = {
    Text = "Ich hoffe, diese kleinen Dinger fressen dich nicht arm. Du weißt ja, eine ganze Familie zu ernähren ist wirklich keine leichte Sache."
  },
  Voice_143529_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_143530_AwakerVoiceContent = {
    Text = "Vor langer, langer Zeit, bevor das Land aus dem Ozean auftauchte, erwachten auf diesem Planeten ganz besondere Geister. Mächtig, erhaben, nicht zu spionieren.\nSie lassen sich weder als feindlich noch als freundlich einordnen. Die Menschen sind für sie, wie unzählige Lebewesen zuvor, bedeutungslos – sie werden wie Staub abgewischt oder zusammen mit ihrem Territorium beschützt."
  },
  Voice_143530_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_143530_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_143531_AwakerVoiceContent = {
    Text = "Nur das Altern ist das Abenteuer, dem du dich allein stellen musst, dein bester Freund und dein hartnäckigster Feind. Das Licht von Ebwynnos wird es vollständig vertreiben ... Gerade ein paar bedeutungslose Erinnerungen, du musst dich nicht von ihnen verankern lassen."
  },
  Voice_143531_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_143531_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_143532_AwakerVoiceContent = {
    Text = "Gebt die Illusion der Flucht auf."
  },
  Voice_143532_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_143533_AwakerVoiceContent = {
    Text = "Du wirst zu grauweißem Staub zerfallen."
  },
  Voice_143533_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_143534_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_143534_AwakerVoiceTitle = {Text = "Schlag"},
  Voice_143535_AwakerVoiceContent = {
    Text = "Sehr klug, Kleines. Die Gläubiger fremder Monster sind immer dumm genug, Leichen ins Meer zu werfen – das gilt nicht als Geschenk, oder?"
  },
  Voice_143535_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_143536_AwakerVoiceContent = {
    Text = "Du bist bereits ins Visier genommen worden."
  },
  Voice_143536_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_143537_AwakerVoiceContent = {
    Text = "Auch wenn ich es nur ungern zugebe, gibt es sehr, sehr seltene Momente, in denen ich das Gefühl habe, dass das Altern nicht das Einzige ist, was die Zeit bringt, sondern nur ein Symbol.\nAlso erlaube ich ihm, in mir zu existieren. Natürlich – nur äußerlich."
  },
  Voice_143537_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_143539_AwakerVoiceContent = {
    Text = "Gebet ist wirksam. Stell dir vor: Selbst wenn Würmer vor dir Reo-Schriftzeichen formen, würdest du einen Moment darüber nachdenken, auf das Anliegen der Würmer einzugehen."
  },
  Voice_143539_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_143539_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_143540_AwakerVoiceContent = {
    Text = "Hahaha, nun gut, mach nicht dieses Emoji, mein kleiner Freund.\nDas ist nur eine Tradition, der sogenannte „alte Götter\" folgen müssen. Was dich betrifft – du brauchst keinen Preis und keine Bedingungen zu erfüllen. Ich werde immer auf deiner Seite stehen."
  },
  Voice_143540_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_143540_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_143554_AwakerVoiceContent = {
    Text = "Hmph, ein kleines Monster, das mit fremden Monstern gemeinsame Sache macht.\nIrgendein Dummkopf hat mich tatsächlich mit ihm auf denselben Altar gestellt – das ist eine glatte Beleidigung!"
  },
  Voice_143554_AwakerVoiceTitle = {
    Text = "Small Talk: Über Tulu"
  },
  Voice_143554_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_143555_AwakerVoiceContent = {
    Text = "Der Feind meines Feindes ist mein Freund. Wenn sich die Gelegenheit ergibt, hätte ich nichts dagegen, das Lieblингsspielzeug meines Erzfeindes zu stehlen – ein gutes Geschäft."
  },
  Voice_143555_AwakerVoiceTitle = {
    Text = "Small Talk: Über Ryker"
  },
  Voice_143555_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Ryker“ wird freigeschaltet"
  },
  Voice_146158_AwakerVoiceContent = {
    Text = "Oh? Du willst hier gegen mich kämpfen? Mir recht."
  },
  Voice_146158_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_146159_AwakerVoiceContent = {
    Text = "Mehr – gib mir mehr Stärke!"
  },
  Voice_146159_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_146160_AwakerVoiceContent = {
    Text = "Ich mag jene nicht, die ein gespaltenes Herz haben, da solche Spaltung meist Schwäche bedeutet. Aber du bist eine Ausnahme. Ich glaubte einst, dass jene, die zu viel tragen, niemals weit kommen können. Doch der Weg, den du gewählt hast, überrascht mich… Vielleicht ist ein Gegner, der einen anderen Weg geht, würdiger, geschliffen und herausgefordert zu werden. Würdest du nicht zustimmen, „Gegner\"?"
  },
  Voice_146160_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_146161_AwakerVoiceContent = {
    Text = "Cetus des Astralen Meeres – verschlinge sie alle!"
  },
  Voice_146161_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_146162_AwakerVoiceContent = {
    Text = "Sei geehrt, mir gegenüberzustehen!"
  },
  Voice_146162_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_146163_AwakerVoiceContent = {
    Text = "Lasst die Sterne Zeuge der Vernichtung sein!"
  },
  Voice_146163_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_146164_AwakerVoiceContent = {
    Text = "Nicht genug. Bei Weitem nicht genug…"
  },
  Voice_146164_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_146165_AwakerVoiceContent = {Text = "Heh."},
  Voice_146165_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_146166_AwakerVoiceContent = {Text = "Hmph."},
  Voice_146166_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_146167_AwakerVoiceContent = {
    Text = "Das Verblassen dieser Welt kümmert mich wenig – aber ich werde nicht zulassen, dass es mein Streben nach Stärke behindert."
  },
  Voice_146167_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_146168_AwakerVoiceContent = {
    Text = "Den Wert der Existenz zu bezweifeln, nur weil das Vergessen wartet… Solche kindischen Debatten interessieren mich nicht. Symptom: Zerstörung bedeutet nichts, Erinnerung ebenso wenig. Stärke selbst ist der Sinn."
  },
  Voice_146168_AwakerVoiceTitle = {
    Text = "Small Talk: Über Doll: Inferno"
  },
  Voice_146168_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Schmelzen·Puppe“ wird freigeschaltet"
  },
  Voice_146169_AwakerVoiceContent = {
    Text = "Ich sehe einen fremden Willen in deinen Augen. Unrein, aber zäh genug. Komm, zeig mir, welche Stärke oder Sehnsucht dich vor mich geführt hat."
  },
  Voice_146169_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_146170_AwakerVoiceContent = {Text = "Ha!"},
  Voice_146170_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_146171_AwakerVoiceContent = {
    Text = "Sei geehrt, mir gegenüberzustehen!"
  },
  Voice_146171_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_146172_AwakerVoiceContent = {
    Text = "Der Duft des Chaos – wie nostalgisch… Seit dem Moment, in dem ich aus dieser Leere geboren wurde, hat sich mein Streben nie verändert."
  },
  Voice_146172_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_146172_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_146173_AwakerVoiceContent = {
    Text = "Du willst mich herausfordern? Ich bewundere deinen Mut, und ich werde dir die Ehre gewähren, besiegt zu werden. Betrachte dies als meinen Respekt vor dem „Schutzherr des Misaq\"."
  },
  Voice_146173_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_146173_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_146174_AwakerVoiceContent = {
    Text = "Eine falsche Utopie, vollgepackt mit Schwächlingen, Feiglingen und selbstbetrügerischen Narren. Aber egal. Dieser Ort bringt mir die aufregendsten Gegner – und das reicht."
  },
  Voice_146174_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_146175_AwakerVoiceContent = {
    Text = "Immense Stärke verschwenden, sein Talent aus Angst, Schuld und Erschöpfung in einem langen Traum gefangen halten. Wie schade."
  },
  Voice_146175_AwakerVoiceTitle = {
    Text = "Small Talk: Über Tulu"
  },
  Voice_146175_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_146176_AwakerVoiceContent = {
    Text = "Kaum der Mühe wert."
  },
  Voice_146176_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_146177_AwakerVoiceContent = {
    Text = "Das Siegel lockert sich ein wenig… Die Stärke aus den Tiefen des Universums strömt empor. Das habe ich seit einer Ewigkeit nicht mehr gespürt…"
  },
  Voice_146177_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_146177_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_146178_AwakerVoiceContent = {
    Text = "Cetus des Astralen Meeres – verschlinge sie alle!"
  },
  Voice_146178_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_146179_AwakerVoiceContent = {
    Text = "…Berauschend."
  },
  Voice_146179_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_146180_AwakerVoiceContent = {
    Text = "Ich habe durch den weiten Kosmos gewandert seit Ewigkeiten; ich habe all jene „Mächtigen\" in den Abgrund geworfen. Du bist einzigartig, doch um an meiner Seite zu stehen, lerne zuerst, den Kopf hochzuhalten. Für Feiglinge habe ich keine Verwendung."
  },
  Voice_146180_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_146180_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_146181_AwakerVoiceContent = {
    Text = "Mutig oder feige, stark oder schwach… Heh – nein, es ist mir egal, was für ein Mensch mein Gegner ist. Jeder würdige Gegner bereitet mir echte Begeisterung."
  },
  Voice_146181_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_146182_AwakerVoiceContent = {
    Text = "Schwäche. Von all den abscheulichen Dingen auf der Welt ist Schwäche die erbärmlichste Sünde. Jeder wird mit einem Schwert in der Hand geboren; niemand hat das Recht, vor dem Ende nachzugeben, noch das vorherbestimmte Schlachtfeld bereits in Niederlage ergeben zu betreten. Das beleidigt sowohl deinen Gegner als auch dich selbst."
  },
  Voice_146182_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_146183_AwakerVoiceContent = {
    Text = "Korrumpiertes Astrales Kadaver – erwache!"
  },
  Voice_146183_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_146184_AwakerVoiceContent = {
    Text = "Heh… Das war aufregend. Beim nächsten Mal werde ich mich nicht zurückhalten."
  },
  Voice_146184_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_146185_AwakerVoiceContent = {
    Text = "Meine Knochen zittern vor Freude… Ich habe deine Mühe bezeugt. Und das beweist, dass du es wert bist, an meiner Seite zu stehen, Schutzherr."
  },
  Voice_146185_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_146185_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_146186_AwakerVoiceContent = {
    Text = "Heh… Du siehst es klar, Schutzherr. Die Fesseln der Stärke sind dazu bestimmt, zerschmettert zu werden!"
  },
  Voice_146186_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_146186_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_146187_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146187_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_146188_AwakerVoiceContent = {Text = "Hm?"},
  Voice_146188_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_146189_AwakerVoiceContent = {
    Text = "Direkt davor… der Gipfel der Stärke, den ich mein ganzes Leben lang verfolgt habe… Du bist diesen Weg mit mir gegangen und hast mich zu dieser Schwelle geführt. Ich bin gespannt, diesen ultimativen Tag gemeinsam mit dir zu erleben!"
  },
  Voice_146189_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_146189_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_146190_AwakerVoiceContent = {
    Text = "Vielleicht habe ich dich zu voreilig beurteilt… Dein Wachstum und deine verborgene Stärke haben mich überrascht. Ich habe unzählige Leben im Laufe der Zeit verblassen sehen, aber du… bist wirklich anders. Ich bin sehr neugierig auf den wahren Ursprung deiner Stärke."
  },
  Voice_146190_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_146190_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_146192_AwakerVoiceContent = {
    Text = "Schlund der Hölle, öffne dich weit für mich!"
  },
  Voice_146192_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_146193_AwakerVoiceContent = {
    Text = "Ah, ich verstehe… es gab nie ein Ende der Stärke. Die wahre Herausforderung hat gerade erst begonnen! Du warst es, der mich hierher gebracht und mir die Realität gezeigt hat. Bald werde ich dir einen noch vollkommeneren Krieger präsentieren. Sorge dafür, dass du noch stärker zurückkehrst, mein „Gegner\"."
  },
  Voice_146193_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_146193_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_146194_AwakerVoiceContent = {
    Text = "Armseliger Trick."
  },
  Voice_146194_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_146195_AwakerVoiceContent = {
    Text = "Stärke kocht in meinem Mark!"
  },
  Voice_146195_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_146196_AwakerVoiceContent = {
    Text = "Verschlingen – alles davon!"
  },
  Voice_146196_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_146197_AwakerVoiceContent = {
    Text = "Mitleid, Schwäche, Verwirrung… deine Augen sind von Unreinheiten getrübt. Wer schwankt, kann niemals verstehen, was Stärke ist."
  },
  Voice_146197_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_146197_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_146198_AwakerVoiceContent = {
    Text = "Wahre Stärke hat nie etwas mit Rache oder mit dem Wächter zu tun. Stärke ist gerade Stärke – das andere Ich hat diese Wahrheit nie „wirklich“ verstanden. Das ist der Ursprung ihrer mangelnden Stärke."
  },
  Voice_146198_AwakerVoiceTitle = {
    Text = "Small Talk: Über Lotan"
  },
  Voice_146198_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Lotan“ wird freigeschaltet"
  },
  Voice_146199_AwakerVoiceContent = {
    Text = "Hör gut zu, ich sage dies nur einmal:\nIch, Lotan, betrachte dich als einen Gegner, der meiner Geduld würdig ist.\nBis du deinen Höhepunkt erreichst, werde ich deine zuverlässigste Klinge sein. Dieses Versprechen hat nichts mit Gefühlen oder Loyalität zu tun. Du bist mein aufregendster Rivale, und ich werde niemals zulassen, dass du unterwegs fällst."
  },
  Voice_146199_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_146199_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_146200_AwakerVoiceContent = {
    Text = "Komm – töte mich, oder stirb."
  },
  Voice_146200_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_146201_AwakerVoiceContent = {
    Text = "Schlund der Hölle, öffne dich weit für mich!"
  },
  Voice_146201_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_146521_AwakerVoiceContent = {
    Text = "Wo die Knochenklinge zeigt, zerfällt alles!"
  },
  Voice_146521_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_147047_AwakerVoiceContent = {
    Text = "Stärke… kennt kein Ende!"
  },
  Voice_147047_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_147493_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_147493_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_147494_AwakerVoiceContent = {
    Text = "(Eine heisere, ruhige Melodie)"
  },
  Voice_147494_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_147495_AwakerVoiceContent = {
    Text = "Zuschauer, wir brauchen mehr Zuschauer"
  },
  Voice_147495_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_147496_AwakerVoiceContent = {
    Text = "Sand... weiße Wüste... Hier ist es gefährlich, komm schnell mit mir"
  },
  Voice_147496_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_147496_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_147497_AwakerVoiceContent = {
    Text = "Ich erinnere mich an die Karte des neuen Zuhauses, sie war bunt und sehr schön. Das ist der Ort, an den wir gehen sollten. Wir können singen, wir können glücklich sein"
  },
  Voice_147497_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_147498_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147498_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_147499_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_147499_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_147500_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_147500_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_147501_AwakerVoiceContent = {
    Text = "Das ist... die Stimme des Sternenhimmels"
  },
  Voice_147501_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_147502_AwakerVoiceContent = {
    Text = "Du bist wieder da. Setz dich wie früher neben mich und warte mit mir. Worauf warten... ? Warten, einfach warten"
  },
  Voice_147502_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_147503_AwakerVoiceContent = {
    Text = "Perfekte Generalprobe, ich bin bereit für die Bühne"
  },
  Voice_147503_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_147503_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_147504_AwakerVoiceContent = {Text = "Fallen."},
  Voice_147504_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_147505_AwakerVoiceContent = {
    Text = "Der Verwüstung und dem Tod gewidmet."
  },
  Voice_147505_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_147506_AwakerVoiceContent = {
    Text = "Ich bin weder verrückt noch traurig. Glaubt nicht an absurde Gerüchte"
  },
  Voice_147506_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_147507_AwakerVoiceContent = {
    Text = "Seltsam, sie scheinen Angst vor meinem Gesang zu haben"
  },
  Voice_147507_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_147508_AwakerVoiceContent = {Text = "Pssst..."},
  Voice_147508_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_147509_AwakerVoiceContent = {
    Text = "Schönes Kostüm, glitzernd, glitzernd"
  },
  Voice_147509_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_147509_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_147510_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_147511_AwakerVoiceContent = {
    Text = "Die Farben der Sterne, die bis heute überdauert haben"
  },
  Voice_147511_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_147512_AwakerVoiceContent = {Text = "Singe."},
  Voice_147512_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_147513_AwakerVoiceContent = {
    Text = "Richtiges Stimmtraining...? Aber ich bin mit meiner Stimme zufrieden"
  },
  Voice_147513_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_147513_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_147514_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_147515_AwakerVoiceContent = {
    Text = "Die Stimme scheint sich verändert zu haben"
  },
  Voice_147515_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_147515_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_147516_AwakerVoiceContent = {
    Text = "Wie ist es, gefällt dir mein Gesang?"
  },
  Voice_147516_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_147517_AwakerVoiceContent = {Text = "Schlaf gut"},
  Voice_147517_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_147518_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_147519_AwakerVoiceContent = {Text = "Okay"},
  Voice_147519_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_147520_AwakerVoiceContent = {Text = "Ah!"},
  Voice_147520_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_147521_AwakerVoiceContent = {
    Text = "Danke... Sollte ich danke sagen?"
  },
  Voice_147521_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_147522_AwakerVoiceContent = {Text = "*seufz*..."},
  Voice_147522_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_147523_AwakerVoiceContent = {Text = "Strahle"},
  Voice_147523_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_147524_AwakerVoiceContent = {
    Text = "Das lang vermisste Gefühl... endlich zurück auf der Bühne. Danke, Geheimnishüter"
  },
  Voice_147524_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_147524_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_147525_AwakerVoiceContent = {
    Text = "Entschuldigung für die Störung... Kannst du mich vom Baum herunterholen? Ich erinnere mich nicht, warum ich hinaufgeklettert bin, vielleicht wegen der Wolken, die mich an etwas erinnern"
  },
  Voice_147525_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_147526_AwakerVoiceContent = {
    Text = "Mein Volk hat mich nie verlassen, sie sind nur sehr weit weg"
  },
  Voice_147526_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über die Clanmitglieder"
  },
  Voice_147527_AwakerVoiceContent = {
    Text = "Hast du es gehört?"
  },
  Voice_147527_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_147528_AwakerVoiceContent = {Text = "Oh."},
  Voice_147528_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_147529_AwakerVoiceContent = {
    Text = "Du scheinst immer in meiner Nähe zu sein... Ich weiß, du musst mein Fan sein"
  },
  Voice_147529_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_147529_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_147530_AwakerVoiceContent = {
    Text = "La la la~ Was? Hier gibt es einen weltuntergangsbringenden Clades? Ah... Ich muss mir die Haare kämmen und meine Schwester finden..."
  },
  Voice_147530_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_147531_AwakerVoiceContent = {
    Text = "Pssst... Sei still, da kommen Bösewichte. Sie wollen meine Schwester und mich fangen und uns nicht aufs Schiff lassen"
  },
  Voice_147531_AwakerVoiceTitle = {
    Text = "Idle Talk · Über Sicherheit"
  },
  Voice_147532_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_147532_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_147533_AwakerVoiceContent = {
    Text = "Als ich aufwachte, zerstörte sich der Planet. Ich sah, wie der Nachthimmel abblätterte, die Welt wurde zu einer vom Wind durchdrungenen Leinwand, die sich zuerst verformte und dann zerriss und zerbrach"
  },
  Voice_147533_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_147533_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_147534_AwakerVoiceContent = {
    Text = "Das ist mein signiertes Poster, gezeichnet von Mr. Pikman. Ich präsentiere es dir."
  },
  Voice_147534_AwakerVoiceTitle = {
    Text = "Chat·Über Ohnmacht"
  },
  Voice_147534_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Ohnmacht“ wird freigeschaltet"
  },
  Voice_149667_AwakerVoiceContent = {
    Text = "Hmm? Neugierig, oder? Der Schatzgewölbe einer Patin ist nicht für fremde Augen bestimmt, weißt du. Wenn du unbedingt wissen willst, was da drin so vollgestopft ist... warum trittst du nicht gleich dem Heiligen Orden bei... Hehe."
  },
  Voice_149667_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_149668_AwakerVoiceContent = {
    Text = "Du glaubst mir nicht? Buh-huh... Ich schätze, man kann wirklich nicht jeden täuschen... Die Wahrheit ist, ich bin die uneheliche Tochter von Bohemond VI. von @1, lebe versteckt unter den Sterblichen, und ich behauptete nur, eine Fee zu sein, um der Jagd der Feinde zu entkommen... Ich habe dir jetzt mein kostbarstes Geheimnis verraten. Du würdest mir nicht... nicht glauben... oder?"
  },
  Voice_149668_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_149668_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_149669_AwakerVoiceContent = {Text = "Aua~"},
  Voice_149669_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_149670_AwakerVoiceContent = {
    Text = "Zu viele Süßigkeiten? Nein, nein, nein, das ist das Geheimnis einer Patin, ihr Lächeln zu bewahren, weißt du. Als ob ich wegen einer kleinen Sache wie einem Karies aufhören würde?"
  },
  Voice_149670_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_149671_AwakerVoiceContent = {
    Text = "Komm, stell dich hier neben deine Fee. Was? Alle teilen die Opfergaben und essen gemeinsam? ...Nun gut. Wenn das der Brauch in Misaq ist... dann habe ich... natürlich überhaupt nichts dagegen. Kommt alle her, lasst uns feiern!"
  },
  Voice_149671_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_149671_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_149672_AwakerVoiceContent = {
    Text = "Na, na, was für ein frommes kleines Lämmchen."
  },
  Voice_149672_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_149673_AwakerVoiceContent = {
    Text = "Noch ein kleines bisschen, und dann segnet dich die Fee, hmm?"
  },
  Voice_149673_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_149674_AwakerVoiceContent = {
    Text = "Ihr seid alle noch ein bisschen grün hinter den Ohren~"
  },
  Voice_149674_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_149676_AwakerVoiceContent = {
    Text = "Diese Verehrungszeremonie wird prächtiger sein als alle zuvor – und die Opfergaben müssen zahlreicher sein... Oh nein, wir hacken natürlich keine Gliedmaßen ab! Ich bin eine gütige Fee; ich würde niemandem etwas antun~"
  },
  Voice_149676_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_149676_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_149677_AwakerVoiceContent = {
    Text = "Schutzherr, bist du bereit für Caraboos aufrichtigstes Geständnis, von Herzen?\nWoher ich komme, spielt überhaupt keine Rolle. Was wirklich zählt, ist dies: Du bist ein Geschenk des Himmels an mich, und ich habe beschlossen, für immer und ewig an der Seite meines kostbaren Wohltäters zu bleiben.\nOb das wieder eine Lüge ist, um dich vom weiteren Nachforschen abzuhalten, fragst du? Hehe, was denkst du?\nAnyway... ich glaube, ich verdiene eine kleine Belohnung dafür, dass ich meine wahren Gefühle mit dir geteilt habe. Ein Apfel-Gummibärchen wäre schön, bitte?"
  },
  Voice_149677_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_149677_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_149678_AwakerVoiceContent = {Text = "Hehe~"},
  Voice_149678_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_149680_AwakerVoiceContent = {
    Text = "Macht nichts! Konzentrier dich beim nächsten Mal einfach darauf, deine Fee zu beschützen, dann wirst du nicht scheitern~"
  },
  Voice_149680_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_149682_AwakerVoiceContent = {
    Text = "Versuch gar nicht erst, mich zu täuschen!"
  },
  Voice_149682_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_149683_AwakerVoiceContent = {
    Text = "Wooow, so viele Tribute...! Ahem. Hehe, gut gemacht, du hast eine Belohnung verdient! Komm her, ich schenke dir den Kuss einer Fee! ...Was denkst du dir dabei? Auf die Stirn, natürlich!"
  },
  Voice_149683_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_149683_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_149684_AwakerVoiceContent = {
    Text = "Danke euch allen für eure Opfergaben, ihr Treuen! Eure allverständnisvolle Patin wird auch eine goldene Statue von euch im Tempel errichten lassen. Oh mein – um diese kühle, elegante Gestalt einzufangen, muss ich wohl noch einiges mehr sammeln~"
  },
  Voice_149684_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_149684_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_149685_AwakerVoiceContent = {
    Text = "Du? ...Du gehörst zu unserer Herde, noch nicht erleuchtet. Caraboo wird geduldig auf den Tag warten, an dem du die wahre Natur der Welt erkennst. Und wenn dieser Tag kommt – denk daran, deinen Körper, deine Treue und deine weltlichen Güter der Patin aller zu opfern. Hehe."
  },
  Voice_149685_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_149686_AwakerVoiceContent = {
    Text = "Alles auf der Liste... schon zusammengetragen? Misaqs Reichtum ist tiefer, als ich es mir vorstellen kann... Hätte ich das gewusst, hätte ich... Hmm? Was ich da vor mich hin murmle, fragst du? Ich danke nur LORD Dexter für seine Großzügigkeit, hehe~"
  },
  Voice_149686_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_149686_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_149687_AwakerVoiceContent = {
    Text = "Was ich am meisten hasse? Zauberer ohne Respekt vor einem Vertrag, natürlich. Ein kleines Geheimnis, nur zwischen uns: Jeder einzelne Zauberer ist ein dicker fetter Schwindler. All ihre sogenannten Prophezeiungen und Flüche? Nur Tricks, um dich in den Ruin zu treiben! Und wie schützt du dich...? Ganz einfach! Lass einfach all dein Geld den Segen der Fee empfangen!"
  },
  Voice_149687_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_149688_AwakerVoiceContent = {
    Text = "Wie schön, dich kennenzulernen! Ich bin eine Bleiche Fee aus fernen Landen. Möchtest du mehr erfahren? Der Segen einer Fee fällt je nach Mitgliedsstufe unterschiedlich aus, hehe~"
  },
  Voice_149688_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_149689_AwakerVoiceContent = {
    Text = "Bei früheren Andachtszeremonien haben die Gläubigen mir neben dem siebenfachen Ritual und dem dreifachen Gelübde auch einen brandneuen Tempel gebaut und prächtige Tribute dargebracht. Hier ist die Liste!"
  },
  Voice_149689_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_149689_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_149690_AwakerVoiceContent = {
    Text = "Komm nun... begrabe alles, was du abwerfen möchtest, tief im Schnee..."
  },
  Voice_149690_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_149691_AwakerVoiceContent = {
    Text = "Ich höre, du hast gefragt, woher ich komme. Hehe, das ist ein kleines Geheimnis der Patin. Aaaaaber, wenn du unbedingt nachforschen musst – der Heilige Orden bewahrt eine Biografie auf, die ich selbst verfasst habe. Für dich zu lesen für lediglich hunderttausend Silberkern. Möchtest du es versuchen?"
  },
  Voice_149691_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_149691_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_149692_AwakerVoiceContent = {
    Text = "Oh, es ist wunderschön hier – so viele entzückende Kinder, und Sozialhilfe so großzügig, dass es schon obszön ist. Mit all dem werde ich bald genug Reisegeld für den Osten gespart haben..."
  },
  Voice_149692_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_149693_AwakerVoiceContent = {
    Text = "Vergiss nicht, deine Göttliche Mutter anzubeten, hehe."
  },
  Voice_149693_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_149694_AwakerVoiceContent = {
    Text = "Tut mir leid, aber das Reich der Fee ist heiliges Gebiet – wir empfangen hier keine fremden Werwölfe... Irgendetwas mit dem Geruch von Lügen in der Luft? Seine Nase muss wohl nicht richtig funktionieren."
  },
  Voice_149694_AwakerVoiceTitle = {
    Text = "Small Talk: Über Ryker"
  },
  Voice_149694_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Ryker“ wird freigeschaltet"
  },
  Voice_149695_AwakerVoiceContent = {
    Text = "Huh? Jemand sagt, ich sei eine falsche Fee... Nun, ich bin ertappt. Hehe. Aber ich weiß, dass es dir nichts ausmacht... oder?"
  },
  Voice_149695_AwakerVoiceTitle = {
    Text = "Gespräch: Über die Gerüchte"
  },
  Voice_149696_AwakerVoiceContent = {
    Text = "Mmm, köstlich~♪"
  },
  Voice_149696_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_149697_AwakerVoiceContent = {Text = "Na, na~"},
  Voice_149697_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_149698_AwakerVoiceContent = {
    Text = "Verirrte Lämmlein, eure Fee ist hier, um eure Sünden fortzuwaschen, hehe~"
  },
  Voice_149698_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_149699_AwakerVoiceContent = {
    Text = "Noch nicht aufgegeben? Na gut, na gut – Caraboo wird es dir selbst sagen. Siehst du, Caraboo ist die Tochter von Umapati, Göttin eines gewissen wolkendurchbohrenden Schneegipfels im Osten... Hmm? Diese Göttin hatte zwei Söhne und keine Tochter? Nun, Aufzeichnungen über das Göttliche sind immer ein wenig... lückenhaft, verstehst du."
  },
  Voice_149699_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_149699_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_149700_AwakerVoiceContent = {
    Text = "Tadaa~ der Glanz der Fee erstrahlt nun auf dir. Auf geht's!"
  },
  Voice_149700_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_149701_AwakerVoiceContent = {
    Text = "Schon gut, schon gut, hör auf zu graben, ja? Sei ein braver {Male=boy,Female=girl} und lass diese unhöfliche kleine Untersuchung fallen, und ich teile heimlich die Hälfte meiner kostbarsten Süßigkeiten mit dir. Weißt du, auf den Schlachtfeldern der Kreuzzüge waren süße Bonbons ein seltener Schatz."
  },
  Voice_149701_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_149701_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_149702_AwakerVoiceContent = {
    Text = "Caraboos Segen kann jede Krankheit der Welt heilen – einschließlich dieser schwarzen Pest, natürlich... Natürlich ist das wahr! Du musst nur fromm genug sein, Caraboo genug vertrauen, hehe."
  },
  Voice_149702_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_149703_AwakerVoiceContent = {Text = "Aua~"},
  Voice_149703_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_149704_AwakerVoiceContent = {
    Text = "Schau her, der Glanz der Fee!"
  },
  Voice_149704_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_149705_AwakerVoiceContent = {
    Text = "Das siebenfache Ritual, das dreifache Gelübde – bring sie dar und erkaufe dir die Absolution der Fee!"
  },
  Voice_149705_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_150079_AwakerVoiceContent = {Text = "Spür es!"},
  Voice_150079_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_150104_AwakerVoiceContent = {
    Text = "Huh, wie hat Ogier dich reingelassen? Er hat versprochen, alle fernzuhalten. Du bist sein Lehnsherr...? Ugh, unzuverlässige kleine Kinder sind so ein Kopfschmerz. Ich habe viel Arbeit in die Vorbereitung dieser Versammlung gesteckt, weißt du. Sagen wir... fünfzig-fünfzig bei den eingenommenen Opfergaben, und du schaust für mich weg?"
  },
  Voice_150104_AwakerVoiceTitle = {
    Text = "Gespräch: Über Ogier"
  },
  Voice_150104_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Ogier“"
  },
  Voice_22276_AwakerVoiceContent = {
    Text = "Beeile dich und mach fertig. Bleib nicht auf der Straße hängen."
  },
  Voice_22276_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_36679_AwakerVoiceContent = {
    Text = "Er trat der Sekte bei, während ich schlief, daher habe ich keine Verbindung zu ihm.\nIch habe jedoch gehört, dass er aus eigenem Antrieb gekommen ist, um seine menschliche Gestalt aufzugeben und ein vollwertiger \"Seefahrer\" zu werden... Hmph, ein weiterer Narr, der von Macht geblendet ist."
  },
  Voice_36679_AwakerVoiceTitle = {
    Text = "Chat·Über Caecus"
  },
  Voice_36679_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36680_AwakerVoiceContent = {
    Text = "Goliath war nie ein treuer Welpe. Ich kann nicht verstehen, warum Miryam so viel Wert auf ihn legt... Ohne Kette wäre er der Erste, der weglaufen würde."
  },
  Voice_36680_AwakerVoiceTitle = {
    Text = "Chat·Über Goliath"
  },
  Voice_36680_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36681_AwakerVoiceContent = {
    Text = "Seefahrer werden nicht so geboren. Um sich einzugewöhnen, verbringen sie die erste Hälfte ihres Lebens wie Menschen...\nDu solltest aufpassen – der Besitzer deiner Lieblingskonditorei könnte einer von ihnen sein!"
  },
  Voice_36681_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über den Seefahrer"
  },
  Voice_36681_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36682_AwakerVoiceContent = {
    Text = "Celestes schräger Seemannslied, der geräucherte Fisch-Eintopf des Kapitäns, Decken, die durch die Meeresbrise fischig und steif geworden sind... Auch wenn es gefährlich und angespannt war, werde ich die Monate, die wir im Exil auf See verbrachten, niemals vergessen."
  },
  Voice_36682_AwakerVoiceTitle = {
    Text = "Plaudern · Über \"Geisterschiff\""
  },
  Voice_36682_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36683_AwakerVoiceContent = {
    Text = "Obwohl alle in der Schule sehr beschäftigt zu sein scheinen...\nHier gibt es einen Frieden, den ich noch nie zuvor erlebt habe.\nDas Gefühl, fürs gleiche Ziel zusammenzukommen und gemeinsam zu kämpfen... Hmph, es ist nicht schlecht."
  },
  Voice_36683_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität·II"
  },
  Voice_36683_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36684_AwakerVoiceContent = {
    Text = "Das Bett ist zu hart, das Wetter zu kalt, und der Nachmittagstee schmeckt immer wie Gras gespültes Wasser... Ich habe tausend Gründe, diesen Ort nicht zu mögen.\nDoch nur weil \"du hier bist\", könnte ich widerwillig bleiben."
  },
  Voice_36684_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über den Hüter III"
  },
  Voice_36684_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36685_AwakerVoiceContent = {
    Text = "Danke... Huh? Warum danke ich dir? Ist es nicht offensichtlich! Es ist für alles, was du für mich auf See getan hast...\nWarte mal, warum lachst du? Du willst doch nur sehen, dass ich mich schäme, oder?"
  },
  Voice_36685_AwakerVoiceTitle = {
    Text = "Idle-Gespräch · Über den Hüter · II"
  },
  Voice_36685_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36686_AwakerVoiceContent = {
    Text = "Ich dachte einmal, dass zwischen uns ein familiäres Band bestand...\nAber nach allem, was passiert ist, stellte ich fest, dass diese flüchtigen Momente der Wärme nichts anderes als mein Wunschdenken waren.\nWas du mit ihr machst, ist deine Angelegenheit, lass sie nur nicht in meine Nähe kommen."
  },
  Voice_36686_AwakerVoiceTitle = {
    Text = "Chat·Über Miryam·II"
  },
  Voice_36686_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_36687_AwakerVoiceContent = {
    Text = "Wie seltsam... Dieses Gefühl ist wirklich seltsam.\nMein Herz hat aufgehört zu schlagen, aber mein Körper ist immer noch warm... Hey, komm rüber und berühre meine Hand. Sag mir, dass das keine Illusion ist."
  },
  Voice_36687_AwakerVoiceTitle = {
    Text = "Ungezwungene Gespräche · Über \"Erwecker\""
  },
  Voice_36687_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 6 der \"Ermittlungsoperation\""
  },
  Voice_45153_AwakerVoiceContent = {
    Text = "Ich bin vielleicht nicht im Königreich Leo geboren, aber die Große Kirche ist der Ort, an dem ich mein zweites Leben erhalten habe. Warum kann ich diesen Ort also nicht mein Zuhause nennen?"
  },
  Voice_45153_AwakerVoiceTitle = {
    Text = "Idle-Gespräch · Über Zuhause"
  },
  Voice_45154_AwakerVoiceContent = {
    Text = "Nach Jahren einer unsichtbaren Plage hörte Gott Vater schließlich meine Gebete und schenkte mir den \"Segen\", der das Leiden entgegenwirken kann.\nEr gewährt tatsächlich Leben, verlangt aber auch einen Preis.\nAls Vollstrecker sollte ich natürlich die Last im Namen der Gesegneten tragen."
  },
  Voice_45154_AwakerVoiceTitle = {
    Text = "Ungezwungene Gespräche · Über \"Der Segen\""
  },
  Voice_45155_AwakerVoiceContent = {
    Text = "Für mich ist der Zustand, ein Erwachter zu sein, ein Geschenk des Vaters an die Seele in Seinen Armen. Es ist ein zweites Leben, eine Gelegenheit, vergangene Reue zu heilen.\nIch werde die Arbeit des Vaters fortsetzen, meine Pflichten als Sein Stellvertreter erfüllen und mehr Leiden lindern."
  },
  Voice_45155_AwakerVoiceTitle = {
    Text = "Ungezwungene Gespräche · Über \"Erwecker\""
  },
  Voice_45156_AwakerVoiceContent = {
    Text = "Lass mich erneut meine Dankbarkeit ausdrücken, Hüter, dafür, dass du meinen Wünschen Respekt zollst und mein Geheimnis vor dem Ausschuss bewahrst. Wenn sie intervenieren sollten, fürchte ich, würden sie nicht zulassen, dass ich weiterhin der Kirche diene."
  },
  Voice_45156_AwakerVoiceTitle = {
    Text = "Idle-Gespräch · Über den Hüter · II"
  },
  Voice_45156_UnlockDesc = {
    Text = "Wird nach Abschluss der Spezialmission „Primärfarbe des Bluts\" freigeschaltet"
  },
  Voice_45157_AwakerVoiceContent = {
    Text = "Dieses Kind ist aufrichtig, standhaft und freundlich, mit einer seltenen, strahlenden Seele. Das letzte Mal, dass ich jemandem wie diesem begegnete, war im ersten Kapitel meines Lebens."
  },
  Voice_45157_AwakerVoiceTitle = {
    Text = "Alltägliches Gespräch · Über Ogier"
  },
  Voice_45157_UnlockDesc = {
    Text = "Wird nach Abschluss der Spezialmission „Primärfarbe des Bluts\" freigeschaltet"
  },
  Voice_45158_AwakerVoiceContent = {
    Text = "Mein Sehvermögen zu verlieren bedeutet nicht, dass ich blind geworden bin. Während der Vater mir Dunkelheit brachte, erlaubte er mir auch, das schwache Licht der Seelen zu sehen."
  },
  Voice_45158_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über Vision"
  },
  Voice_45159_AwakerVoiceContent = {
    Text = "\nDamals, obwohl ich \"Der Segen\" erhalten hatte, war ich nur eine gewöhnliche Person. Es gab zu viele, die litten, und zu viele, die \"Der Segen\" benötigten. Ich wollte sie alle retten, aber ich scheiterte.\nDas ist mein größtes Bedauern und meine ewige Schuld."
  },
  Voice_45159_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über das erste Leben"
  },
  Voice_45160_AwakerVoiceContent = {
    Text = "Viele in der Kirche glauben, dass die „weiße Flamme“, die in den „Heiligen Schriften“ erwähnt wird, sich auf Mondlicht bezieht: Ein blasser Bote wird daraus erscheinen, um uns aus dem Leiden zu führen.\nAber ich weiß, dass die wahre Flamme die Seele ist, die in dir und mir brennt"
  },
  Voice_45160_AwakerVoiceTitle = {
    Text = "Ungezwungene Gespräche · Über \"Das Blasse Feuer\""
  },
  Voice_45161_AwakerVoiceContent = {
    Text = "Tatsächlich wurde mir vom Erzbischof aufgetragen, meine wahre Identität zu verbergen. Er ging nicht ins Detail, warnte mich aber: Selbst an den reinsten Orten können Schatten lauern, und man muss wachsam bleiben, selbst wenn man Gutes tut. Natürlich vertraue ich Euch voll und ganz."
  },
  Voice_45161_AwakerVoiceTitle = {
    Text = "Small Talk: Über Identitätsverbergung"
  },
  Voice_45161_UnlockDesc = {
    Text = "Wird nach Abschluss der Spezialmission „Primärfarbe des Bluts\" freigeschaltet"
  },
  Voice_4908_AwakerVoiceContent = {
    Text = "Hat mein Singen dir irgendwie geholfen?"
  },
  Voice_4908_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_4909_AwakerVoiceContent = {
    Text = "Verdammtes Miststück, er ist auch nur ein Kind! Warum respektiert ihr ihn alle so sehr? Zeigt mir den gleichen Respekt, verstanden!"
  },
  Voice_4909_AwakerVoiceTitle = {
    Text = "Plauderei · Über Tulu"
  },
  Voice_4909_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_4910_AwakerVoiceContent = {
    Text = "Hey, weißt du, was die anderen Wachenden normalerweise tun? Versteh mich nicht falsch, ich will keine Freunde, nur... ja, nur mal nachfragen!"
  },
  Voice_4910_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile: Über das tägliche Leben"
  },
  Voice_4911_AwakerVoiceContent = {
    Text = "Verdammtes Miststück, verdammtes Miststück, verdammtes Miststück! Das nächste Mal werfe ich ihre Leichen den Spinnen zum Fressen vor!"
  },
  Voice_4911_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_4912_AwakerVoiceContent = {Text = "Nachklang"},
  Voice_4912_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_4913_AwakerVoiceContent = {Text = "Rhythmus."},
  Voice_4913_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_4914_AwakerVoiceContent = {
    Text = "Ein kühner Versuch"
  },
  Voice_4914_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_4915_AwakerVoiceContent = {
    Text = "Kein Bedarf, so eilig zu sein... Gibt es etwas, was ich für dich tun kann?"
  },
  Voice_4915_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_4916_AwakerVoiceContent = {
    Text = "Wie wagst du es!"
  },
  Voice_4916_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_4917_AwakerVoiceContent = {
    Text = "(Fragen mit großem Interesse)"
  },
  Voice_4917_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_4918_AwakerVoiceContent = {
    Text = "Die Natur ist die Quelle meiner höchsten Ehre. Fühlt es sich nicht nach mir an?"
  },
  Voice_4918_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_4919_AwakerVoiceContent = {
    Text = "Was willst du tun?"
  },
  Voice_4919_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_4920_AwakerVoiceContent = {
    Text = "Nicht schlecht, oder? Jetzt die Belohnung. — Was? Es gibt nichts umsonst!"
  },
  Voice_4920_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_4921_AwakerVoiceContent = {Text = "Geh weg!"},
  Voice_4921_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_4922_AwakerVoiceContent = {Text = "Vorsicht!"},
  Voice_4922_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_4923_AwakerVoiceContent = {
    Text = "Was für ein glorreicher Sieg... Ich werde diesen Moment in die Ewigkeit eingravieren."
  },
  Voice_4923_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_4924_AwakerVoiceContent = {
    Text = "Fühlte die Quelle der Unreinheit... Einen Schritt näher zur wahren Form... Ahhh, lass mich diese Welt auseinanderreißen!"
  },
  Voice_4924_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_4924_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_4925_AwakerVoiceContent = {
    Text = "Wir sind...bereit. Bitte gib den Befehl, Hüter."
  },
  Voice_4925_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_4925_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_4926_AwakerVoiceContent = {
    Text = "Sir, Sie sind wirklich gütig. Leider habe ich nichts, womit ich Ihnen danken könnte, da ich nur eine wertlose Person bin..."
  },
  Voice_4926_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_4926_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_4927_AwakerVoiceContent = {
    Text = "......Nur ein kleines Stück weiter, und ich werde komplett von \"ihnen\" getrennt sein?"
  },
  Voice_4927_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_4927_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_4928_AwakerVoiceContent = {
    Text = "Huh, ich bin immer noch am Leben... Du wirst meine Organe wirklich nicht stehlen oder mich für Experimente benutzen?"
  },
  Voice_4928_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_4928_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_4929_AwakerVoiceContent = {
    Text = "Winkles einheimische Spezies kann in das biologische Gehirn eindringen, wodurch der äußere Wille fused mit mir sie fürchten lässt. Aber jetzt ist sie nur eine arme Seele, die in einer Hülle gefangen ist"
  },
  Voice_4929_AwakerVoiceTitle = {
    Text = "Chat·Über Zwinkern"
  },
  Voice_4929_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Zwinkern“ wird freigeschaltet"
  },
  Voice_4930_AwakerVoiceContent = {
    Text = "Alles, Aigis genießt es sehr. Egal, ob alle um den Tisch versammelt sind für eine Mahlzeit und Gebet, oder die Vorfreude, wenn der Hüter auf einer Mission ist und auf deine triumphale Rückkehr wartet... Die Luft ist immer voller Glück... Verdiene ich wirklich solch Freude?"
  },
  Voice_4930_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_4931_AwakerVoiceContent = {Text = "Sink."},
  Voice_4931_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_4932_AwakerVoiceContent = {Text = "Blühen."},
  Voice_4932_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_4933_AwakerVoiceContent = {
    Text = "\"Vertrauen,\" \"Gehorsam,\" \"Sklave,\" \"Zuneigung,\" \"Respekt\"... Rekonstruktion und Lernen des Sprachmoduls. Bitte, Hüter, führe mich."
  },
  Voice_4933_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_4933_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_4934_AwakerVoiceContent = {
    Text = "Erica befindet sich derzeit im Standby-Modus. Der Körper wird in 1 Stunde und 15 Minuten abkühlen. <Del:Um zu beginnen, tauschen Sie Ihr Herz> Notfallstart? ... Berechtigungsüberprüfung läuft... Höchste Autorität des Hüters verifiziert. Hallo, Hüter."
  },
  Voice_4934_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_4934_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_4935_AwakerVoiceContent = {
    Text = "Der durchschnittliche Risikoindex für Untersuchungsaufgaben liegt bei 7, mit einem durchschnittlichen Verbrauch von 8 Flaschen Alchemie-Nahrungsergänzungen und durchschnittlich 10 Stunden für die Leichenschau.\nFazit: Die Arbeit der Hüter ist äußerst gefährlich. Bitte bleiben Sie während der Einsätze sicher."
  },
  Voice_4935_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_4935_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_4936_AwakerVoiceContent = {
    Text = "Suche nach Lehrerdokumenten: Erica Layfield, Dozentin für Silbermechatronik und Automatisierung, verstorben—Ist das nicht, wonach du suchst? Okay, neu Suche nach dem Schlüsselwort \"Erica\"."
  },
  Voice_4936_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_4936_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_4937_AwakerVoiceContent = {
    Text = "Wenn du Informationen nachschlagen möchtest, gib bitte den vollständigen Namen der Datei an. Die unscharfe Suchfunktion ist derzeit nicht verfügbar."
  },
  Voice_4937_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_4937_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_4938_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_4938_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_4939_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4939_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_4940_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_4940_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_4941_AwakerVoiceContent = {Text = "Ah!"},
  Voice_4941_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_4942_AwakerVoiceContent = {
    Text = "Aufladung abgeschlossen, bereit zur Detonation."
  },
  Voice_4942_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_4943_AwakerVoiceContent = {
    Text = "Aufladung abgeschlossen, bereit zur Detonation."
  },
  Voice_4943_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_4944_AwakerVoiceContent = {
    Text = "Störe in Zukunft den Schlaf der Prinzessin nicht mit solchen trivialen Angelegenheiten."
  },
  Voice_4944_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_4945_AwakerVoiceContent = {
    Text = "Ich werde dich beschützen, so wie ich Tinct beschütze."
  },
  Voice_4945_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_4946_AwakerVoiceContent = {
    Text = "Ich bin keine wichtige Person, nur ein demütiger Anhänger unter vielen... Solange ich diesem großartigen Wesen dienen und seine Aufmerksamkeit auf mich ziehen kann, bin ich bereit, alles zu geben."
  },
  Voice_4946_AwakerVoiceTitle = {
    Text = "Idle Talk·Über die Vergangenheit"
  },
  Voice_4946_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_4947_AwakerVoiceContent = {
    Text = "Schau mich an!"
  },
  Voice_4947_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_4948_AwakerVoiceContent = {
    Text = "Schau mich an!"
  },
  Voice_4948_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_4949_AwakerVoiceContent = {
    Text = "...Es ist in Ordnung, solange sie mich mit ihrem fanatischen Glauben nicht belästigen. In einem Raum mit ihnen zu sein, wäre nicht ausgeschlossen."
  },
  Voice_4949_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über den Seefahrer"
  },
  Voice_4949_UnlockDesc = {
    Text = "Nach dem Erwerb eines der Erwachenden „Miryam“, „Goliath“, „Caecus“, „Sanga“ oder „Faros“ freischalten."
  },
  Voice_4950_AwakerVoiceContent = {
    Text = "Ich hasse dieses dunkle Gefühl, als wäre mein Herz ausgehöhlt. Das unerfüllte Gefühl bringt meinen ganzen Körper zum Jucken..."
  },
  Voice_4950_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_4951_AwakerVoiceContent = {
    Text = "Tu das nicht, tu das nicht, tu das nicht, tu das nicht, erwähne es nicht..."
  },
  Voice_4951_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_4953_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4953_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_4954_AwakerVoiceContent = {Text = "...Okay!"},
  Voice_4954_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_4955_AwakerVoiceContent = {
    Text = "Die Historiker, die laut das Aussterben des göttlichen Reiches verkünden, sind nervig... Aber das spielt keine Rolle; ihre Worte können das Wiedererwachen des Ruhms des göttlichen Reiches nicht aufhalten."
  },
  Voice_4955_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_4956_AwakerVoiceContent = {
    Text = "Eigentlich... lass mich dir ein Geheimnis erzählen. Ich bin mit meinem aktuellen Motorrad nicht ganz zufrieden - es ist nicht so, dass ich es nicht mag! Es ist nur so, dass ich das Gefühl habe, dass etwas fehlt..."
  },
  Voice_4956_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_4957_AwakerVoiceContent = {Text = "Ha!"},
  Voice_4957_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_4958_AwakerVoiceContent = {Text = "Hau rein!"},
  Voice_4958_AwakerVoiceTitle = {
    Text = "Fähigkeit·II·Manie"
  },
  Voice_4959_AwakerVoiceContent = {
    Text = "Entschuldigung... Ich wollte nicht, dass das passiert..."
  },
  Voice_4959_AwakerVoiceTitle = {
    Text = "Fähigkeit·II·Depression"
  },
  Voice_4960_AwakerVoiceContent = {
    Text = "(Neugieriges Flüstern)"
  },
  Voice_4960_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_4961_AwakerVoiceContent = {
    Text = "Im Jahr @1@2 gründeten Mr. Ward Phillips, Krelarkesh und Tawil zusammen das Mythag College. Nach einer langen Entwicklung brachte es letztendlich <Del:diesen verdammten Gefängnis> die Mythag Universität hervor."
  },
  Voice_4961_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_4962_AwakerVoiceContent = {
    Text = "Gerechtigkeit, Loyalität, Widerstandsfähigkeit, Disziplin. Diese sind schon lange in mein Herz eingraviert."
  },
  Voice_4962_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_4963_AwakerVoiceContent = {
    Text = "Ich werde die Aufgabe, die du mir zugewiesen hast, ordnungsgemäß abschließen."
  },
  Voice_4963_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_4964_AwakerVoiceContent = {
    Text = "Welche Art von verantwortungslosen Eltern würden ihre Tochter Banshees Schild nennen? Du sagst, das Kind hat keine Eltern? Hmm... lass uns dieses Gespräch unter uns halten"
  },
  Voice_4964_AwakerVoiceTitle = {
    Text = "Chat·Über Aigis"
  },
  Voice_4964_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Aigis“"
  },
  Voice_4965_AwakerVoiceContent = {
    Text = "Wenn dir langweilig ist, warum nicht \"halte mir Gesellschaft\" im Labyrinth? Schließlich ist dein hoffnungsloses Leben nicht anders als dieses endlose Labyrinth!"
  },
  Voice_4965_AwakerVoiceTitle = {
    Text = "Chat · Über das Labyrinth"
  },
  Voice_4966_AwakerVoiceContent = {
    Text = "Wenn die Puppe in der Nähe ist, steigt die Effizienz der Ermittler um 78,312 %, aber mehr Menschen geraten auch in emotionale Tiefs. Wie sie es ausdrückte: \"Wenn einige Menschen ihren Mund halten könnten, würde die Welt reibungsloser laufen.\""
  },
  Voice_4966_AwakerVoiceTitle = {
    Text = "Chat·Über Puppe"
  },
  Voice_4966_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Puppe“ wird freigeschaltet"
  },
  Voice_4967_AwakerVoiceContent = {Text = "Ankunft!"},
  Voice_4967_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_4968_AwakerVoiceContent = {
    Text = "Wie sieht es aus?"
  },
  Voice_4968_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_4969_AwakerVoiceContent = {
    Text = "Wer würde kein Abenteuer lieben? In unerforschte geheimnisvolle Bereiche eintauchen, das Unbekannte entdecken und deine eigene Geschichte weben... Wie spannend!"
  },
  Voice_4969_AwakerVoiceTitle = {
    Text = "Small Talk · Über Abenteuer"
  },
  Voice_4970_AwakerVoiceContent = {
    Text = "Grüße, ich bin Nymphaea von Febvre. Du hast mir diesen Körper gegeben, der frei atmet... Was kann ich tun, um dir zu danken?"
  },
  Voice_4970_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_4971_AwakerVoiceContent = {
    Text = "Ich glaube, ich habe gerade die gehört, die behaupten, meine Herren zu sein, wieder weinen — wie erfreulich."
  },
  Voice_4971_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_4971_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_4972_AwakerVoiceContent = {
    Text = "Kann ich die Gemüse überspringen? Obwohl Tinktur gesagt hat, ich solle nicht wählerisch sein, mag ich ihre Farben nicht..."
  },
  Voice_4972_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_4973_AwakerVoiceContent = {
    Text = "Relikt Gottes Worte: Leiden ist nicht meine Schöpfung. Ertrage und löse es auf, mein Stellvertreter, und baue ein Land ohne Leiden. Dafür biete ich alles, sogar das Leben."
  },
  Voice_4973_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_4973_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_4974_AwakerVoiceContent = {
    Text = "Im Angesicht des alles verzehrenden Schmelzfluchs verblassen andere Leiden im Vergleich. Selbst wenn ich den Fluch für andere nicht ertragen kann, werde ich mein Bestes tun, um ihren Schmerz zu lindern."
  },
  Voice_4974_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_4974_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_4975_AwakerVoiceContent = {
    Text = "Bin ich jetzt in der Lage, ihren Schmerz zu lindern und ihre Seelen zu trösten?"
  },
  Voice_4975_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_4975_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_4976_AwakerVoiceContent = {
    Text = "So werde ich all das Leiden tragen und den Weg für alle Wesen in ein schmerzfreies Land ebnen."
  },
  Voice_4976_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_4976_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_4977_AwakerVoiceContent = {
    Text = "Diese Wärme tief in meiner Seele... Danke für dieses Geschenk, das Blasse Feuer. Mit dieser Macht kann ich vielleicht endlich meine Pflicht als Stellvertreter erfüllen und mehr Menschen retten."
  },
  Voice_4977_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_4977_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_4978_AwakerVoiceContent = {
    Text = "Kann ich wirklich so viel essen?"
  },
  Voice_4978_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_4978_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_4979_AwakerVoiceContent = {
    Text = "Hmm... Das ist nicht der Tod; es ist nur deine Zukunft, meine Zukunft und die Zukunft dieser Welt."
  },
  Voice_4979_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_4980_AwakerVoiceContent = {
    Text = "Tinktur... Ihr klagender Gesang lässt dich tanzen wollen..."
  },
  Voice_4980_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über Tinktur"
  },
  Voice_4980_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Tinktur“ wird freigeschaltet"
  },
  Voice_4981_AwakerVoiceContent = {
    Text = "Kann gewöhnliches Training auch das Potenzial der eigenen Blutlinie erwecken? Das übersteigt wirklich meine Erwartungen."
  },
  Voice_4981_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_4982_AwakerVoiceContent = {
    Text = "Die Waffe fühlt sich handlicher an."
  },
  Voice_4982_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_4983_AwakerVoiceContent = {
    Text = "Nimm nicht an, dass ich dafür dankbar sein werde; mein Volk erlaubt das nicht."
  },
  Voice_4983_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_4984_AwakerVoiceContent = {Text = "Ah, äh!"},
  Voice_4984_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_4985_AwakerVoiceContent = {
    Text = "Dieser Mann... Hey, warte einen Moment, unsere Wette ist noch nicht vorbei, oder?"
  },
  Voice_4985_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über andere"
  },
  Voice_4986_AwakerVoiceContent = {
    Text = "Ich mag den Rekorder der Akademie wirklich. Wenn ich nur eine tragbare Version erstellen könnte, die mich in Echtzeit an das erinnert, was ich vergessen habe..."
  },
  Voice_4986_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_4987_AwakerVoiceContent = {
    Text = "Überall Krümel... Nein, nicht einmal Krümel, nur Überreste, die Nahrung für sein Kommen bieten."
  },
  Voice_4987_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_4988_AwakerVoiceContent = {
    Text = "Die Vorräte sind hier."
  },
  Voice_4988_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_4989_AwakerVoiceContent = {
    Text = "Die Vorräte sind hier."
  },
  Voice_4989_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_4990_AwakerVoiceContent = {
    Text = "Hmm... Härter, härter. Ja, genau so..."
  },
  Voice_4990_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_4991_AwakerVoiceContent = {
    Text = "Noch nicht vollständig Erwacht, kam der Sieg jedoch mühelos."
  },
  Voice_4991_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_4992_AwakerVoiceContent = {
    Text = "Oh nein, mein Hut ist schief... Hmm, ist das besser? Perfekt!"
  },
  Voice_4992_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_4992_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_4993_AwakerVoiceContent = {
    Text = "\"Mit solch einer Fähigkeit, bin ich wirklich noch menschlich?\" Seit ich mit dem Kampfausbildung begonnen habe, frage ich mich das jeden Tag. Ich liebe diese Welt, trotz ihrer Dunkelheit, Dreck und Monotonie, aber deine Präsenz lässt sie wie Diamanten im Staub erstrahlen.\nIch fürchtete einst, dass sich meine menschliche Stellung ändern würde, während meine Macht wuchs... Jetzt bin ich dankbar, dich an meiner Seite zu haben. Unser Band verankert mich fest in der menschlichen Welt. Bitte achte weiterhin auf mich, Hüter."
  },
  Voice_4993_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_4993_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_4994_AwakerVoiceContent = {
    Text = "Ah... Es ist nur natürlich, dass du Bedenken hast. Ich habe nicht gründlich nachgedacht. Als dein Partner hätte ich das von Anfang an erklären sollen. Wie du siehst, habe ich einige ungewöhnliche Eigenschaften, die wahrscheinlich mit meinem Hintergrund verbunden sind. Es ist unmöglich, nicht neugierig zu sein, oder? Aber einen Ort wie die Akademie zu haben, ist ein Segen für mich, also wähle ich, den Schleier des Schicksals nicht zu lüften."
  },
  Voice_4994_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_4994_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_4995_AwakerVoiceContent = {
    Text = "Du hast diese Frau getroffen, oder? Die Erwacherin im weißen Schleier—sie ist eine der Gründerinnen der Universität...\nAber ehrlich gesagt, mag ich sie nicht. Diese distanzierte Haltung, als ob sie sich überhaupt nicht um die Welt schert, geht mir wirklich auf die Nerven... Oh, du denkst, sie sieht mir ähnlich? Lass uns deine Augen in der Campusklinik überprüfen."
  },
  Voice_4995_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_4995_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_4996_AwakerVoiceContent = {
    Text = "Bist du neugierig auf meine Beziehung zu dem Professor? Es ist kein Geheimnis, also sag ich's dir. Professor Dexter ist mein Pflegevater. Was meine Pflege-mutter betrifft... Ich bin in der Schule aufgewachsen und wurde von allen Lehrern betreut. Allerdings bin ich unter ihnen Doll am nächsten."
  },
  Voice_4996_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_4996_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_4997_AwakerVoiceContent = {
    Text = "Ob es die Abläufe im Erwecker-Amt oder das Datum für indisches Essen in der Kantine ist, ich kann jede Frage zu den Angelegenheiten der Akademie beantworten—mach dir keine Sorgen, mich zu belästigen. Sehe ich so unnahbar aus?"
  },
  Voice_4997_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_4997_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_4998_AwakerVoiceContent = {
    Text = "Spiegel, Spiegel, wer ist der größte Magier der Welt? Ich? Richtig!"
  },
  Voice_4998_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_4998_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_4999_AwakerVoiceContent = {
    Text = "Überhaupt nicht schlecht."
  },
  Voice_4999_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5000_AwakerVoiceContent = {
    Text = "Sehr schön~"
  },
  Voice_5000_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5001_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5001_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5002_AwakerVoiceContent = {
    Text = "Hat es ... funktioniert? Konnte ich dir helfen?"
  },
  Voice_5002_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5003_AwakerVoiceContent = {Text = "Nutzlos!"},
  Voice_5003_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5004_AwakerVoiceContent = {Text = "(Erdulden)"},
  Voice_5004_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5005_AwakerVoiceContent = {
    Text = "Sieh hierher!"
  },
  Voice_5005_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_5006_AwakerVoiceContent = {
    Text = "Lass diesen Ort zu einem Meer der Aufregung für alle werden!"
  },
  Voice_5006_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5007_AwakerVoiceContent = {
    Text = "Brauchen Sie einen Wächter, der Sie begleitet? Wenn Ihr Streben gerecht ist, werde ich Ihnen helfen."
  },
  Voice_5007_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5008_AwakerVoiceContent = {
    Text = "Kann nicht vollständig verbrannt werden."
  },
  Voice_5008_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5009_AwakerVoiceContent = {
    Text = "Kann nicht vollständig verbrannt werden."
  },
  Voice_5009_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5010_AwakerVoiceContent = {
    Text = "Willst du eine Umarmung?"
  },
  Voice_5010_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5011_AwakerVoiceContent = {
    Text = "Sieh dir diese Fesseln an – sie sind keine Dekorationen, sondern Erinnerungen. Erinnerungen an Verrat und Demütigung."
  },
  Voice_5011_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5012_AwakerVoiceContent = {
    Text = "Wenn du mehr über die Vergangenheit der Akademie erfahren möchtest, empfehle ich dir, die Archive zu durchstöbern.\nKomm schon, inklusive seines Vorgängers, ist das eine Geschichte, die 300 Jahre umfasst! Erwartest du wirklich, dass ich sie Jahr für Jahr erzähle?"
  },
  Voice_5012_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5013_AwakerVoiceContent = {
    Text = "Ist das eine Provokation? Ich bin jederzeit bereit!"
  },
  Voice_5013_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5014_AwakerVoiceContent = {
    Text = "Aequor gewährt dir ewige Rast."
  },
  Voice_5014_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5015_AwakerVoiceContent = {
    Text = "Aequor gewährt dir ewige Rast."
  },
  Voice_5015_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5016_AwakerVoiceContent = {
    Text = "Sink and burn! Tanz zur Zerstörung!"
  },
  Voice_5016_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5017_AwakerVoiceContent = {
    Text = "Hier präsentiere ich den Tanz zur Zerstörung der Ewigen Grünen Flamme!"
  },
  Voice_5017_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5018_AwakerVoiceContent = {
    Text = "Diese Dame, wie ein Leuchtturm... Hätte ich ihr strahlendes Licht während der ewigen Nachtfahrt sehen können, vielleicht hätte ich mich nicht verloren..."
  },
  Voice_5018_AwakerVoiceTitle = {
    Text = "Chat·Über Faros"
  },
  Voice_5018_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Faros“ wird freigeschaltet"
  },
  Voice_5019_AwakerVoiceContent = {
    Text = "Du solltest dich besser als würdig erweisen, mich aus dem Labor zu lassen, neuer Hüter."
  },
  Voice_5019_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5020_AwakerVoiceContent = {
    Text = "Ich bin der Meister, und du bist der Diener. Was ich wünsche, muss sofort geliefert werden. Was ist los? Erwarten Sie eine Belohnung? Sehr gut, sehr gut, nimm sie!"
  },
  Voice_5020_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5021_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5021_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5022_AwakerVoiceContent = {
    Text = "Schande, lass diesen Zug dich reinigen!"
  },
  Voice_5022_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5023_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5023_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5024_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5024_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5025_AwakerVoiceContent = {
    Text = "Geben heißt empfangen."
  },
  Voice_5025_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5026_AwakerVoiceContent = {
    Text = "Geben heißt empfangen."
  },
  Voice_5026_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5027_AwakerVoiceContent = {
    Text = "Du wirst verletzt werden!"
  },
  Voice_5027_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5028_AwakerVoiceContent = {
    Text = "Komm nicht näher!"
  },
  Voice_5028_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5029_AwakerVoiceContent = {
    Text = "Ich liebe das goldene Mondlicht bei Vollmond. Es ist mysteriös und sanft. Wenn der Wind weht, funkelt das Meer mit goldenem Phosphoreszenz, wie eine traumhafte Romanze."
  },
  Voice_5029_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5030_AwakerVoiceContent = {
    Text = "Wenn unser Zuhause nicht unter Auflösung gelitten hätte, wären Tinct und ich nicht getrennt... Ich hasse die Auflösung mehr, als ich Gemüse hasse."
  },
  Voice_5030_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5031_AwakerVoiceContent = {
    Text = "Ob das, was vor uns liegt, ein Schatz oder ein Hafen ist, macht für mich keinen Unterschied. Meine Mission ist es, deine sichere Rückkehr zu gewährleisten."
  },
  Voice_5031_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5031_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5032_AwakerVoiceContent = {
    Text = "Folge der Spur des Paradiesvogels; das Ziel liegt vor dir im azurblauen."
  },
  Voice_5032_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5032_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5033_AwakerVoiceContent = {
    Text = "Ich blicke oft zum Horizont und stelle mir die Szenen dahinter vor – ein fernes Land, dem ich näher komme, das ich aber nie erreichen kann. Wenn dieser Tag jemals kommt, bitte gehe mit mir, um es zu sehen."
  },
  Voice_5033_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5033_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5034_AwakerVoiceContent = {
    Text = "Danke für Ihre Freundlichkeit. Jetzt kann mich selbst das tobende Meer nicht davon abhalten, Ihnen meine unerschütterlichen Segenswünsche zu überbringen."
  },
  Voice_5034_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5034_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5035_AwakerVoiceContent = {
    Text = "Es fühlt sich an, als ob ich die Lieder der Ruderer höre, den vertrauten Geschmack von Zuhause."
  },
  Voice_5035_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5035_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5036_AwakerVoiceContent = {
    Text = "Bist du hier, um mich zu retten? Aus der zerfallenden Welt, aus dem Hass, der meine Augen befleckt, aus den ewigen grünen Flammen..."
  },
  Voice_5036_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5037_AwakerVoiceContent = {
    Text = "Freche Schurke!"
  },
  Voice_5037_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5038_AwakerVoiceContent = {
    Text = "Ich betrachte dies als meinen Treueschwur dir gegenüber."
  },
  Voice_5038_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5038_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5039_AwakerVoiceContent = {
    Text = "Lerne deine Lektion!"
  },
  Voice_5039_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5040_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5040_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5041_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5041_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5042_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5042_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5043_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5044_AwakerVoiceContent = {
    Text = "Fühlen Sie die Kraft der Ratte!"
  },
  Voice_5044_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5045_AwakerVoiceContent = {
    Text = "Fühlen Sie die Kraft der Ratte!"
  },
  Voice_5045_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5046_AwakerVoiceContent = {
    Text = "Der Würfel ist gefallen. Lassen Sie uns das schnell beenden!"
  },
  Voice_5046_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5047_AwakerVoiceContent = {
    Text = "Ich werde deinen Namen in meine Danksagungen aufnehmen. Du hast es ermöglicht, dass diese Füße, die von dunklem Blut getränkt sind, erneut in die wunderbare Welt des Balletts treten. Von nun an, bitte beobachte mich beim Tanzen, Hüter."
  },
  Voice_5047_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5047_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5048_AwakerVoiceContent = {
    Text = "Egal wie sehr du kämpfst, du kannst dem Schicksal nicht trotzen. Aber dieser flüchtige Moment des Glanzes wird in die Ewigkeit eingefroren."
  },
  Voice_5048_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5048_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5049_AwakerVoiceContent = {
    Text = "Was sollen wir mit diesen Besiegten tun?"
  },
  Voice_5049_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5050_AwakerVoiceContent = {
    Text = "Auch wenn mein Herz keine Sehnsucht mehr hat, werde ich dennoch die Rolle des Schwans spielen."
  },
  Voice_5050_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5050_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5051_AwakerVoiceContent = {
    Text = "Schließe deine Augen und sag mir, was siehst du? Makelloses Mondlicht, ein ruhiger See..."
  },
  Voice_5051_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5051_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5052_AwakerVoiceContent = {
    Text = "Warum umschlingen mich und meine Schwester die Katastrophen der Zerstörung und des Unglücks?"
  },
  Voice_5052_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5053_AwakerVoiceContent = {
    Text = "Akzeptiere meine Zuneigung."
  },
  Voice_5053_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5054_AwakerVoiceContent = {
    Text = "Akzeptiere meine Zuneigung."
  },
  Voice_5054_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5055_AwakerVoiceContent = {
    Text = "Ich fühle mich jetzt viel besser, danke."
  },
  Voice_5055_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5056_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5056_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5057_AwakerVoiceContent = {
    Text = "Wenn möglich, möchte ich dir eine blasslila Wasserrose als Zeichen meines Dankes überreichen."
  },
  Voice_5057_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5058_AwakerVoiceContent = {
    Text = "Kann ich auch stärker werden?"
  },
  Voice_5058_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5059_AwakerVoiceContent = {
    Text = "Hier geht es...!"
  },
  Voice_5059_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5060_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5060_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5061_AwakerVoiceContent = {
    Text = "Dieses verletzte Bein? Ich bin überrascht, dass du es bemerkt hast. Es stammt vom Schlachtfeld, bevor ich ein Erwachter wurde.\nMach dir keine Sorgen, es stört mich nicht mehr im Kampf.\nSchmerz? Nein, darüber habe ich nicht nachgedacht."
  },
  Voice_5061_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5061_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5062_AwakerVoiceContent = {
    Text = "Sylvia fragte nach meinem psychischen Zustand, hast du sie geschickt? Ich gebe zu, dass Phantomschmerzen gelegentlich auftreten. Aber mach dir keine Sorgen um meine Gefühle. Ich bin dein Schwert, deine Klinge, solange ich für die Gerechtigkeit kämpfen kann, wird ein bisschen Schmerz keinen Einfluss haben"
  },
  Voice_5062_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5062_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5063_AwakerVoiceContent = {
    Text = "Teeparty, Teeparty, lass uns eine Teeparty veranstalten! Ich habe viele Teeblätter und Süßigkeiten von Sylvia bekommen! Ja, ich habe sie gegen einen Fortwoken-Tanz eingetauscht!"
  },
  Voice_5063_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5064_AwakerVoiceContent = {
    Text = "Mein selbsternannter Titel? Interessierst du dich wirklich so sehr für meine persönlichen Angelegenheiten? Nur plaudern wollen... in Ordnung.\nIn der Armee unterscheiden wir nicht zwischen Kameraden basierend auf Geschlecht, einschließlich Stärke und Geschwindigkeit, und natürlich auch nicht bei Frisuren und Titeln. Mit der Zeit habe ich mich an diese Ausdrucksweise gewöhnt."
  },
  Voice_5064_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5064_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5065_AwakerVoiceContent = {
    Text = "Interessant... Hast du keine Angst, dass ich dich in Stücke reißen und den Fischen zum Fressen geben werde, sobald ich Macht erlange?"
  },
  Voice_5065_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5066_AwakerVoiceContent = {
    Text = "Um es wert zu sein, mein Hüter zu sein, hast du sicherlich hart gearbeitet!"
  },
  Voice_5066_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5067_AwakerVoiceContent = {
    Text = "Zeit, um die Kehlen einiger Schwächlinge zu zerreißen und es zu versuchen."
  },
  Voice_5067_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5068_AwakerVoiceContent = {
    Text = "Tanzen ist rein. Worte können zu Missverständnissen führen, aber Tanzschritte niemals."
  },
  Voice_5068_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Tanz"
  },
  Voice_5069_AwakerVoiceContent = {
    Text = "Ich hasse das Meer, und das aus gutem Grund. Der Ozean verschlang alles, was ich liebte..."
  },
  Voice_5069_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5070_AwakerVoiceContent = {
    Text = "Ob es Vergesslichkeit oder Verlust ist, dieses Mal werden wir auf jeden Fall zurückkehren!"
  },
  Voice_5070_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5071_AwakerVoiceContent = {
    Text = "Ob es Vergesslichkeit oder Verlust ist, dieses Mal werden wir auf jeden Fall zurückkehren!"
  },
  Voice_5071_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5072_AwakerVoiceContent = {
    Text = "Bitte, bitte komm nicht näher. Es ist gefährlich."
  },
  Voice_5072_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5073_AwakerVoiceContent = {
    Text = "Fühlen Sie sich frei zu berühren... Das sind Narben aus der Arena, ein Zeichen des Mannes!"
  },
  Voice_5073_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5074_AwakerVoiceContent = {
    Text = "(Schrei des Schmerzes)"
  },
  Voice_5074_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5075_AwakerVoiceContent = {
    Text = "Aua, aua, aua!"
  },
  Voice_5075_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5076_AwakerVoiceContent = {
    Text = "(Schmerzgrunzen)"
  },
  Voice_5076_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5077_AwakerVoiceContent = {
    Text = "(Unbeeindrucktes Grunzen)"
  },
  Voice_5077_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5078_AwakerVoiceContent = {
    Text = "Es fühlt sich an, als ob etwas im Körper brodelt. Ist das das Gefühl, das man beim Erleuchten hat?"
  },
  Voice_5078_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5078_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5079_AwakerVoiceContent = {
    Text = "Ist das eine Art neue Technologie? Mein Prothesenmitglied fühlt sich viel leichter an."
  },
  Voice_5079_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5079_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5080_AwakerVoiceContent = {
    Text = "Die salzige Meeresbrise sagt mir, dass meine Heimat nicht weit entfernt ist."
  },
  Voice_5080_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5080_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5081_AwakerVoiceContent = {
    Text = "Können die verstorbenen Kameraden ihren Weg zurück finden, indem sie diesem Licht folgen?"
  },
  Voice_5081_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5081_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5082_AwakerVoiceContent = {
    Text = "Ich habe zehntausende von Jahren gesucht; ein flüchtiges Jahrhundert ist nichts. Bis ich dein Ufer erreiche, werde ich dir weiterhin helfen."
  },
  Voice_5082_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5082_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5083_AwakerVoiceContent = {
    Text = "Ich werde nur für mein Heimatland strahlen. Du..."
  },
  Voice_5083_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5083_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5084_AwakerVoiceContent = {
    Text = "Ich fühlte die Brise, die feinen Sand über meine Füße trug."
  },
  Voice_5084_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5084_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5085_AwakerVoiceContent = {
    Text = "Das Ausmaß meines Beitrags zu deiner Macht endet hier. Zu gierig zu sein, ist kein gutes Zeichen, weißt du?"
  },
  Voice_5085_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5085_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5086_AwakerVoiceContent = {
    Text = "Was erwartest du, dass ich zurückgebe? Nur einen Kampf?"
  },
  Voice_5086_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5086_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5087_AwakerVoiceContent = {
    Text = "Schädel der Liebe, Schädel des Grolls, Schädel des Hasses, Schädel des Verlangens... Oh, du bist zurückgekehrt?"
  },
  Voice_5087_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5087_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5088_AwakerVoiceContent = {
    Text = "Da es ein Geschäft ist, kann ich dein Geschenk nicht einfach annehmen. Möchtest du etwas aus dem Laden auswählen?"
  },
  Voice_5088_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5088_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_50898_AwakerVoiceContent = {
    Text = "Ich werde dir Freude, Spaß und das Gefühl des Gipfels beibringen... Im Gegenzug musst du ehrlich deine Verlangen offenbaren, okay?"
  },
  Voice_50898_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über den Hüter 2"
  },
  Voice_50899_AwakerVoiceContent = {
    Text = "Ich bin der Mutterbaum, und der Mutterbaum bin ich. Der Saft fließt in meinen Adern und der Wille des Baumes verweilt in meinem Geist..."
  },
  Voice_50899_AwakerVoiceTitle = {
    Text = "Idle-Gespräch·Über den Mutterbaum"
  },
  Voice_50899_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 7 der \"Ermittlungsoperation\""
  },
  Voice_5089_AwakerVoiceContent = {
    Text = "Den Preis für deinen Verrat bezahlen!"
  },
  Voice_5089_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_50900_AwakerVoiceContent = {
    Text = "Ich glaube, ich habe deinen Grabstein gesehen, während ich nach einem versteckten Ort im Schlüsselgrab suchte... Wird meine Mumie auch hier beerdigt? Nein? Was für ein Bedauern."
  },
  Voice_50900_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über den Schlüssel-Hügel"
  },
  Voice_50900_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 7 der \"Ermittlungsoperation\""
  },
  Voice_50901_AwakerVoiceContent = {
    Text = "Der Wolfsmann... Er hat eine ambiguöse Beziehung zu diesem N..."
  },
  Voice_50901_AwakerVoiceTitle = {
    Text = "Chat·Über Ryker"
  },
  Voice_50901_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Ryker“ wird freigeschaltet"
  },
  Voice_50902_AwakerVoiceContent = {
    Text = "Komm näher, umarme mich, koste mich... vergiss mich nicht."
  },
  Voice_50902_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über den Hüter 3"
  },
  Voice_50902_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 7 der \"Ermittlungsoperation\""
  },
  Voice_50903_AwakerVoiceContent = {
    Text = "Sie war ein übermäßig fleißiges und vorsichtiges Kind. Natürlich würde ich ihr keinen Vorwurf machen~ Ohne sie wäre der freiheitsliebende Stamm längst inmitten der Veränderungen zerstört worden, oder nicht?"
  },
  Voice_50903_AwakerVoiceTitle = {
    Text = "Plauderei: Über Alva"
  },
  Voice_50903_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Alva“ wird freigeschaltet"
  },
  Voice_50904_AwakerVoiceContent = {
    Text = "Aus den gelben Sanden geboren, und zu den gelben Sanden wirst du zurückkehren. Auf dieser kurzen Reise solltest du nicht etwas hinterlassen und einige Samen säen?"
  },
  Voice_50904_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über die Wüste"
  },
  Voice_50905_AwakerVoiceContent = {
    Text = "Alle Verlangen stammen aus der Liebe; Liebe ist der Anfangs-Samen, bevor der aufragende Baum entsteht."
  },
  Voice_50905_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Desire"
  },
  Voice_50906_AwakerVoiceContent = {
    Text = "Oh mein Gott, eine süße kleine Maus ist gerade vorbeigelaufen... Ich habe gehört, dass Mäuse gerne herumschleichen, aber leider ist diese hier noch zu jung, praktisch ein Neugeborenes."
  },
  Voice_50906_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_50906_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_50907_AwakerVoiceContent = {
    Text = "Sie trugen mein Blut und mein Erbe weiter und verwandelten sich in die blühenden Gewässer von Lemwahi... Von diesem Tag an liegt es an dir, sicherzustellen, dass mein Erbe weiterbesteht."
  },
  Voice_50907_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Alan"
  },
  Voice_50907_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 7 der \"Ermittlungsoperation\""
  },
  Voice_50908_AwakerVoiceContent = {
    Text = "Spinnen... Spinnen. Hmm~ Ich liebe Spinnen. Sie werden mit der Fähigkeit geboren, zu laufen, und ihre Fortpflanzungs- und Überlebensfähigkeiten sind wirklich beneidenswert..."
  },
  Voice_50908_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Agrippa"
  },
  Voice_50908_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Agrippa“"
  },
  Voice_50909_AwakerVoiceContent = {
    Text = "Alle Wesen mit dem Blut des fließenden Baumes sind meine Kinder. Dazu gehört auch ihr, die ihr die Baumsamen geschluckt habt, oder?"
  },
  Voice_50909_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Nachkommen"
  },
  Voice_50909_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 7 der \"Ermittlungsoperation\""
  },
  Voice_5090_AwakerVoiceContent = {
    Text = "Meine Waren? Du könntest sagen, ich habe alles, um all deine Wünsche zu erfüllen... für einen Preis."
  },
  Voice_5090_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5090_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_50910_AwakerVoiceContent = {
    Text = "Oh mein Gott, ich muss zugeben, dass ich diesmal gegen sie verloren habe... Aber glücklicherweise, da sie dich gewählt hat, wirst du den Saft des Baumes trinken und mein Blut und meine Saat in eine neue Welt tragen, oder?"
  },
  Voice_50910_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Tawil"
  },
  Voice_50910_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Ramona“"
  },
  Voice_50911_AwakerVoiceContent = {
    Text = "Als einer der drei großen Essenzen ist dieser Typ ein unberechenbares Monster. Lass dich nicht leicht von seinen süßen Worten beeinflussen, sonst werde ich gebrochen sein..."
  },
  Voice_50911_AwakerVoiceTitle = {
    Text = "Plauderei · Über N"
  },
  Voice_50912_AwakerVoiceContent = {
    Text = "Solange es Bewusstsein gibt, gibt es auch Wünsche. Selbst mechanische Wesen sind da keine Ausnahme, oder?"
  },
  Voice_50912_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Erica"
  },
  Voice_50912_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Erica“ wird freigeschaltet"
  },
  Voice_5091_AwakerVoiceContent = {
    Text = "Den Preis für deinen Verrat bezahlen!"
  },
  Voice_5091_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5092_AwakerVoiceContent = {
    Text = "Willkommen im unglaublichen Reich!"
  },
  Voice_5092_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5093_AwakerVoiceContent = {
    Text = "(Niedriges Nummer)"
  },
  Voice_5093_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5094_AwakerVoiceContent = {
    Text = "Ich kenne den Schmerz des Schnitzens und das Brennen der Verwandlung gut. Doch all dies verblasst ins Unbedeutende im Vergleich zur ewigen Schönheit."
  },
  Voice_5094_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5094_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5095_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5096_AwakerVoiceContent = {
    Text = "Die ungesagten Worte werden dir durch mein Werk übermittelt."
  },
  Voice_5096_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5096_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5097_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5097_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5098_AwakerVoiceContent = {
    Text = "Der schlafende Herrscher murmelt mir ins Ohr, die Ruinen des tiefen Meeres rekonstruieren sich ständig vor meinen Augen... Haben die unzähligen Traumszenen endlich Wirklichkeit geworden?"
  },
  Voice_5098_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5098_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5099_AwakerVoiceContent = {
    Text = "Danke, dass ihr das Studio für mich vorbereitet habt. Alles hier ist im Sonnenlicht gebadet. Es scheint, dass jedes Werk, jedes Schnitzmesser, in goldenem Licht erstrahlt. Oh, der Frühling ist golden."
  },
  Voice_5099_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5099_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5100_AwakerVoiceContent = {
    Text = "Obwohl unsere Temperamente unterschiedlich sind, bewundere ich dieses Kind wirklich. Sie besitzt einen Mut, der alle Schwierigkeiten und Beschränkungen überwindet. Wenn ich so mutig und widerstandsfähig gewesen wäre wie sie, hätte ich vielleicht nicht gewählt, mein Leben im Meer zu beenden..."
  },
  Voice_5100_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Murphy"
  },
  Voice_5100_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_5101_AwakerVoiceContent = {
    Text = "Die Rote Dame ist anders als jeder Lord, dem ich jemals gedient habe... Nein, es ist nicht so, dass ich sie nicht mag; es ist nur... nur ein bisschen schwierig zu handhaben..."
  },
  Voice_5101_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Sorel"
  },
  Voice_5101_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Sorel“"
  },
  Voice_5102_AwakerVoiceContent = {
    Text = "Umarmung des Wahnsinns!"
  },
  Voice_5102_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5103_AwakerVoiceContent = {
    Text = "Kaum durchhältend."
  },
  Voice_5103_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5104_AwakerVoiceContent = {Text = "Ausrotten!"},
  Voice_5104_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5105_AwakerVoiceContent = {
    Text = "Du musst nicht..."
  },
  Voice_5105_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5106_AwakerVoiceContent = {
    Text = "Das Herz ist ein bodenloser Abgrund, der niemals gefüllt werden kann."
  },
  Voice_5106_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5107_AwakerVoiceContent = {
    Text = "Kein Schmerz, kein Jucken, aber... trotzdem extrem dankbar."
  },
  Voice_5107_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5108_AwakerVoiceContent = {
    Text = "Ah... Sprichst du mit mir? Entschuldigung, ich erinnerte mich gerade an die Aussicht vom Mast. Könntest du deine Frage wiederholen?"
  },
  Voice_5108_AwakerVoiceTitle = {
    Text = "Idle Talk·Über die Vergangenheit"
  },
  Voice_5109_AwakerVoiceContent = {
    Text = "Sowohl ein Meister als auch eine Mutter."
  },
  Voice_5109_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5110_AwakerVoiceContent = {
    Text = "Eine Eröffnung!"
  },
  Voice_5110_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5111_AwakerVoiceContent = {
    Text = "Eine Eröffnung!"
  },
  Voice_5111_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5112_AwakerVoiceContent = {Text = "Bereit—"},
  Voice_5112_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5113_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5113_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5114_AwakerVoiceContent = {
    Text = "Drücke ein wenig fester~"
  },
  Voice_5114_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5115_AwakerVoiceContent = {
    Text = "Brennende Liebe!"
  },
  Voice_5115_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5116_AwakerVoiceContent = {
    Text = "D-Phänomen... Ich kann nicht viel verraten. Doch sein Auftreten ist viel früher als du denkst."
  },
  Voice_5116_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5118_AwakerVoiceContent = {Text = "Hmm—"},
  Voice_5118_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5119_AwakerVoiceContent = {Text = "Gut."},
  Voice_5119_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5120_AwakerVoiceContent = {
    Text = "Lass uns aufbrechen."
  },
  Voice_5120_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5121_AwakerVoiceContent = {
    Text = "Heh, unsere Puppenprinzessin weint wieder. Passt die Flasche nicht oder ist das Wiegenlied aus der Tonlage?"
  },
  Voice_5121_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Murphy"
  },
  Voice_5121_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_5122_AwakerVoiceContent = {
    Text = "Waaah... Ich möchte mich diesen Dingen nicht stellen..."
  },
  Voice_5122_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5123_AwakerVoiceContent = {
    Text = "Jetzt ist es meine Aufgabe, dir etwas zurückzugeben."
  },
  Voice_5123_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5124_AwakerVoiceContent = {
    Text = "Der Anstieg der Kraft fühlt sich an wie sengende Flammen, die bis in die Knochen brennen."
  },
  Voice_5124_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5125_AwakerVoiceContent = {
    Text = "Ah... Entschuldigung, bitte beweg dich nicht!"
  },
  Voice_5125_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5126_AwakerVoiceContent = {
    Text = "Die Wärme ist in Reichweite..."
  },
  Voice_5126_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5127_AwakerVoiceContent = {
    Text = "Die Rosen im Innenhof blühen in voller Pracht."
  },
  Voice_5127_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5128_AwakerVoiceContent = {
    Text = "Gute Arbeit! Haben Sie noch die Energie, weiterzumachen?"
  },
  Voice_5128_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5129_AwakerVoiceContent = {
    Text = "Der Ritter ist eine immaterielle Entität, geformt durch Loyalität, Tapferkeit und Tugend. Meine Waffe ist die gleiche, geformt aus dem Willen zu schützen: eine Lanze und ein Schild."
  },
  Voice_5129_AwakerVoiceTitle = {
    Text = "Plauderei: Über Ritter"
  },
  Voice_5130_AwakerVoiceContent = {
    Text = "Jenkin, Diana, Mike, Tyug, Braun... Wow! Entschuldigung, ich habe nur mit mir selbst gesprochen! Du fragst, warum ich diese Namen aufsage? Weil Aigis nicht will, dass wir alle vergessen werden..."
  },
  Voice_5130_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Freunde"
  },
  Voice_5131_AwakerVoiceContent = {
    Text = "Komm nicht in meine Nähe!"
  },
  Voice_5131_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5132_AwakerVoiceContent = {
    Text = "Ich kann es nicht ertragen!"
  },
  Voice_5132_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5133_AwakerVoiceContent = {Text = "Ah~ Hey!"},
  Voice_5133_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5134_AwakerVoiceContent = {Text = "Ah~ Hey!"},
  Voice_5134_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5135_AwakerVoiceContent = {
    Text = "Danke für Ihre Einladung. Wenn es eine Gelegenheit gibt, bei der meine Stimme benötigt wird, bitte informieren Sie mich im Voraus."
  },
  Voice_5135_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5137_AwakerVoiceContent = {
    Text = "Das... ist die schwarze, viskose Flüssigkeit, die durch die Adern strömt, die ultimative Kraft, die alle Stöhnungen zum Schweigen bringt! \"Ich\" wurde daraus geboren, geboren, um zu zerstören! Hahaha!"
  },
  Voice_5137_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5138_AwakerVoiceContent = {
    Text = "Ruf mich heraus, möchtest du spielen? ...Was, eine Untersuchung? Auf keinen Fall, das ist eine Verschwendung von Glück..."
  },
  Voice_5138_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5139_AwakerVoiceContent = {
    Text = "Der Theorieunterricht ist ziemlich langweilig. Ich lese heimlich Ermittlungsunterlagen hinten im Klassenzimmer. Nur damit du es weißt, sag es der Puppe nicht."
  },
  Voice_5139_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5140_AwakerVoiceContent = {
    Text = "Koste die bitteren Konsequenzen!"
  },
  Voice_5140_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5141_AwakerVoiceContent = {
    Text = "Koste die bitteren Konsequenzen!"
  },
  Voice_5141_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5142_AwakerVoiceContent = {
    Text = "Ich habe Juliette nie beschuldigt; sie war lediglich ein Opfer des schwarzen Leidens. Aber... sie scheint das von mir nicht hören zu wollen. Könntest du mir das für sie übermitteln, Bote?"
  },
  Voice_5142_AwakerVoiceTitle = {
    Text = "Klatsch · Über Juliette"
  },
  Voice_5142_UnlockDesc = {
    Text = "Stimme noch nicht implementiert"
  },
  Voice_5143_AwakerVoiceContent = {
    Text = "Langsame dich runter."
  },
  Voice_5143_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5144_AwakerVoiceContent = {Text = "Gut."},
  Voice_5144_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5145_AwakerVoiceContent = {
    Text = "Hey! Hör auf, Dinge anzufassen, du machst ein Chaos! ...Nun, ich lasse es dir dieses Mal durchgehen, da ich großzügig bin."
  },
  Voice_5145_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5146_AwakerVoiceContent = {
    Text = "Keine Notwendigkeit!"
  },
  Voice_5146_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5147_AwakerVoiceContent = {Text = "Tsk!"},
  Voice_5147_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5148_AwakerVoiceContent = {
    Text = "Seit dem Tag, an dem du mich aus der Dunkelheit erweckt hast, bin ich mir sicher, dass du alle aus der Verzweiflung, bekannt als Auflösung, retten und sie ins Reine Land führen kannst. Ich warte auf diesen Tag."
  },
  Voice_5148_AwakerVoiceTitle = {
    Text = "Idle-Gespräch · Über den Hüter · Ich"
  },
  Voice_5149_AwakerVoiceContent = {
    Text = "Ich rieche... den Geruch von Blut."
  },
  Voice_5149_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5150_AwakerVoiceContent = {
    Text = "Wo ist das Ziel? Als Dankeschön dafür, dass du mich erweckt hast, werde ich mich um sie kümmern."
  },
  Voice_5150_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5151_AwakerVoiceContent = {
    Text = "Mein Hut kann nicht länger warten!"
  },
  Voice_5151_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5152_AwakerVoiceContent = {
    Text = "Diese Muschel sollte sich für niemanden außer Ihm rühren... Doch deine Wärme..."
  },
  Voice_5152_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5153_AwakerVoiceContent = {
    Text = "Wie wäre es mit einem Kampf?"
  },
  Voice_5153_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5154_AwakerVoiceContent = {
    Text = "Schänder..."
  },
  Voice_5154_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5155_AwakerVoiceContent = {
    Text = "Unverzeihlich."
  },
  Voice_5155_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5156_AwakerVoiceContent = {
    Text = "Erica funktioniert normal und ist gut mit den elektrischen Geräten der Mythag Universität verbunden. Brauchen Sie, dass ich die Wohnheimlichter einschalte?"
  },
  Voice_5156_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Erica"
  },
  Voice_5157_AwakerVoiceContent = {
    Text = "Als nächstes, ist es Zeit für eine Mahlzeit, hehe..."
  },
  Voice_5157_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5159_AwakerVoiceContent = {
    Text = "Lass die Frau mit dem breiten lila Hut in der Nähe der Bühne nicht! Keine Fragen – halte sie einfach fern, wenn du nicht willst, dass sticky graue Substanz aus ihrem Hut herausläuft!"
  },
  Voice_5159_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Narzisse"
  },
  Voice_5159_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Daffodil“"
  },
  Voice_5160_AwakerVoiceContent = {
    Text = "Bist du immer so? Vertraust jedem und drehst ihnen den Rücken zu? Zu naiv."
  },
  Voice_5160_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5161_AwakerVoiceContent = {
    Text = "Hass kann gemildert, aber niemals ausgelöscht werden."
  },
  Voice_5161_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5162_AwakerVoiceContent = {
    Text = "Erwachender? Hmm... Ja, 7 Uhr ist die beste Zeit zum Aufwachen! Lass uns morgen früh um 7 am Strand Muscheln sammeln!"
  },
  Voice_5162_AwakerVoiceTitle = {
    Text = "Chat · Über Erwacher"
  },
  Voice_5163_AwakerVoiceContent = {
    Text = "Gewähre dir ewiges Leben!"
  },
  Voice_5163_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5164_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5164_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5165_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5165_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5166_AwakerVoiceContent = {
    Text = "Es tut mir leid, wenn Aigis dir irgendwelche Probleme bereitet, werde ich sofort gehen!"
  },
  Voice_5166_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5166_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5167_AwakerVoiceContent = {
    Text = "Du hast mir einen Ort zum Verweilen gegeben, und ich bin dir dankbar. Aber vergib mir, ich verdiene es nicht mehr, wieder auf der Bühne zu stehen."
  },
  Voice_5167_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5168_AwakerVoiceContent = {
    Text = "Danke, dass ihr mir erlaubt habt, hier zu bleiben. Wenn ich mich irgendwie revanchieren kann, lasst es bitte Aigis wissen. Möchtet ihr etwas Tee?"
  },
  Voice_5168_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5168_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5169_AwakerVoiceContent = {
    Text = "Es ist so warm, dass ich nicht gehen möchte. Wenn ich allein bin, ist es wirklich dunkel, kalt und beängstigend..."
  },
  Voice_5169_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5169_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5170_AwakerVoiceContent = {
    Text = "Aigis... Kann ich wirklich zurück zur Menge? Ich bin noch nicht bereit, aber du hast mich bereits akzeptiert... In diesem Fall bitte ich dich, weiterhin auf mich zu achten... Hüter."
  },
  Voice_5170_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5170_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5171_AwakerVoiceContent = {
    Text = "Ich erinnere mich, ich erinnere mich...! Das dreckige Blut der Menschen hat mich gefangen... Ich konnte mich nicht verwandeln! Wie, wie... wo sind meine Kiemen? Warum bewegen sie sich nicht?! Warum!"
  },
  Voice_5171_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5172_AwakerVoiceContent = {
    Text = "Ich liebe gegrillten Oktopus, gekochten Oktopus, frittierten Oktopus... Einige sagen, ich begehe Blasphemie. Entschuldigung, aber Oktopus ist einfach so köstlich, ha ha ha!"
  },
  Voice_5172_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5173_AwakerVoiceContent = {
    Text = "Würmer. Sterne. Ich bin... Uvhash! Töten... lass mich töten!"
  },
  Voice_5173_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5173_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5174_AwakerVoiceContent = {
    Text = "Dunkler Körper, pulsierende Tentakel, ständig sich öffnende und schließende Mundteile... Großartig, großartig! Ich kann es nicht erwarten, jemandem die Kehle aufzureißen!"
  },
  Voice_5174_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5174_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5175_AwakerVoiceContent = {
    Text = "Hahaha, das ist das Gefühl! Gib mir mehr... doppelt, nein, zehnmal die Dosis!"
  },
  Voice_5175_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5175_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5176_AwakerVoiceContent = {
    Text = "Ich werde es ertragen."
  },
  Voice_5176_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5177_AwakerVoiceContent = {
    Text = "Dieses seltsame Gefühl... nicht schlecht. Besser als die Nachtschatten des levantinischen Magiers."
  },
  Voice_5177_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5177_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5178_AwakerVoiceContent = {
    Text = "Gefährten? Hmph... Ich brauche keine. Ich will nicht zweimal mit derselben Last belastet werden."
  },
  Voice_5178_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5178_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5179_AwakerVoiceContent = {
    Text = "Ich werde nur mit dir kooperieren, weil du genug Stärke gezeigt hast, um mit meiner gleichzuziehen. Vergiss nicht, dieser Vertrag endet, wenn deine Macht nachlässt, und ich werde nicht zögern, dir den Kopf abzutrennen."
  },
  Voice_5179_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5179_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5180_AwakerVoiceContent = {
    Text = "In deinen Augen... sehe ich einen Funken, das leidenschaftliche Feuer von Ehrgeiz und Verlangen. Sterblicher, erkenne dich selbst! Wir sind verwandte Geister!"
  },
  Voice_5180_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5180_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5181_AwakerVoiceContent = {
    Text = "Kennt Ihr den Albatros? Er trotzt mutig den Stürmen, doch einmal auf den Boden verbannt, umringt von Spott, werden seine riesigen, herabhängenden Schwingen ironischerweise zu einem erbärmlichen Hindernis. Wie auch immer, diese Geschichte bedeutet nichts... Sie kam mir nur in den Sinn, weil ich mich in Eurer Gegenwart sehr entspannt fühle — einfach nur Small Talk."
  },
  Voice_5181_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5181_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5182_AwakerVoiceContent = {
    Text = "Vielleicht haben sich die Zeiten wirklich geändert. Nun können selbst die zerbrechlichen die Riffe überwinden, die Wellen beherrschen und zum König der Lüfte werden.\nSterblicher, ich erwarte den Tag, an dem du die Geschichte neu schreibst. Es wird mir eine Ehre sein, die mächtige Klinge in deiner Hand zu werden!"
  },
  Voice_5182_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5182_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5183_AwakerVoiceContent = {
    Text = "Die Umwandlungsrate ist zu niedrig. Melden Sie sich morgen in meinem Büro zur erneuten Schulung."
  },
  Voice_5183_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5184_AwakerVoiceContent = {
    Text = "Hast du eine andere Puppe getroffen? Die sogenannte \"Wahrheit der Welt\" kann eine so ruhige und rationale Puppe in eine völlig andere Person verwandeln... Am Ende werden auch du und ich so werden?"
  },
  Voice_5184_AwakerVoiceTitle = {
    Text = "Idle Talk·Über @2"
  },
  Voice_5184_UnlockDesc = {
    Text = "Nach dem Erwerb des Erwachenden@2 freischalte"
  },
  Voice_5185_AwakerVoiceContent = {
    Text = "Meister... ich brauche Befehle. Bitte gib mir Befehle."
  },
  Voice_5185_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5186_AwakerVoiceContent = {
    Text = "Die Leistung des Mechs wurde verbessert."
  },
  Voice_5186_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5189_AwakerVoiceContent = {
    Text = "Hmm-hmm-hmm!"
  },
  Voice_5189_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5190_AwakerVoiceContent = {
    Text = "Mehr Verbündete!"
  },
  Voice_5190_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5191_AwakerVoiceContent = {
    Text = "Mehr Verbündete!"
  },
  Voice_5191_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5192_AwakerVoiceContent = {
    Text = "Es tut mir leid, ich kann die Wiege nicht verlassen... Es könnte die Sicht aller behindern, also bleibe ich lieber hinten im Klassenzimmer."
  },
  Voice_5192_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5193_AwakerVoiceContent = {
    Text = "Was! Nicht einmal ein Teppich aus Konstantinopel, Ceylon-Tee oder Andalucía-Churros...? Ugh... diese Frau bekommt diese Dinge immer so leicht. Ich dachte, sie wären alltäglich..."
  },
  Voice_5193_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5194_AwakerVoiceContent = {
    Text = "Ich bin noch weit von meiner ursprünglichen Form entfernt."
  },
  Voice_5194_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5194_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5195_AwakerVoiceContent = {
    Text = "So eifrig, es scheint etwas grob für jemanden deiner Kaliber zu sein."
  },
  Voice_5195_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5196_AwakerVoiceContent = {
    Text = "Egal wie sehr es sich verbessert, das Aussehen dieses Ungezügels wird sich nicht ändern. Schließlich ist es lediglich eine Manifestation meiner Macht."
  },
  Voice_5196_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5196_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5197_AwakerVoiceContent = {
    Text = "Es fühlt sich an, als wäre ich wieder im chaotischen Ozean, nicht schlecht"
  },
  Voice_5197_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5197_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5198_AwakerVoiceContent = {
    Text = "In Anbetracht deiner enormen Anstrengungen werde ich dich widerwillig als Gefährten akzeptieren."
  },
  Voice_5198_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5198_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5199_AwakerVoiceContent = {
    Text = "Durch die Barrieren der Macht brechen, gleich wie die Wände eines Labyrinths zertrümmern."
  },
  Voice_5199_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5199_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5200_AwakerVoiceContent = {
    Text = "Du kannst keine Lebensmittel zerreißen oder die Cafeteriabänke zerdrücken... Gut, Lily wird es das nächste Mal nicht tun."
  },
  Voice_5200_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5200_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5201_AwakerVoiceContent = {
    Text = "Kann ich dich Mutter nennen?"
  },
  Voice_5201_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5201_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5202_AwakerVoiceContent = {
    Text = "Gibt es einen Befehl, Meister? \n\"Bring sie nicht nach draußen, alle werden Angst haben?\"\nLily versteht und wird sie sofort verstecken."
  },
  Voice_5202_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5202_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5203_AwakerVoiceContent = {
    Text = "Also, so fühlt es sich an, ein Erwachter zu werden."
  },
  Voice_5203_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5203_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5204_AwakerVoiceContent = {
    Text = "Mutter, darf ich neben dir schlafen? Wenn ich allein bin, habe ich dunkle, gruselige Träume. Lilys Hände und Füße sind abgefallen... Es tut wirklich weh."
  },
  Voice_5204_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5204_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5205_AwakerVoiceContent = {
    Text = "Ah! Danke für deine Freundlichkeit, Karen ist nur eine demütige Dienstmagd..."
  },
  Voice_5205_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5205_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5206_AwakerVoiceContent = {Text = "Hmph~"},
  Voice_5206_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5207_AwakerVoiceContent = {
    Text = "Ich muss einige Schnitzmaterialien sammeln, vorzugsweise frische."
  },
  Voice_5207_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5208_AwakerVoiceContent = {
    Text = "Bitte sei ruhig."
  },
  Voice_5208_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5209_AwakerVoiceContent = {
    Text = "Diejenigen, die starrköpfig in ihrer Torheit bleiben, vollbringen vergebliche Taten."
  },
  Voice_5209_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5209_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5210_AwakerVoiceContent = {
    Text = "An diesem Punkt kann ich deine Absicht irgendwie verstehen. Ist okay, mach weiter."
  },
  Voice_5210_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5210_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5211_AwakerVoiceContent = {
    Text = "Ich sehe deinen Entschluss. Bevor ich wieder schlafe, werde ich dein Zeuge sein, der den Ungehorsam des Schicksals durch den Sohn der Menschen bezeugt. Aber für jetzt brauche ich etwas Ruhe."
  },
  Voice_5211_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5211_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5212_AwakerVoiceContent = {
    Text = "Ist es nicht gut, dem Willen des Himmels zu folgen? Warum dem Willen des Schicksals widerstehen?"
  },
  Voice_5212_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5212_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5213_AwakerVoiceContent = {
    Text = "Um Ihren Wunsch zu erfüllen, sind Sie bereit, so viel zu opfern..."
  },
  Voice_5213_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5213_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5214_AwakerVoiceContent = {
    Text = "Huh? Ist das nicht nervig? Hör auf, mich wegen diesem Typen zu belästigen! ...Gut, mach was du willst. Es dient ja nur zur Zeitvertreibung."
  },
  Voice_5214_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5215_AwakerVoiceContent = {
    Text = "Auflösung... Diese dreckigen schwarzen Flüssigkeiten dringen oft in meine Träume ein, wirklich unerträglich."
  },
  Voice_5215_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5216_AwakerVoiceContent = {
    Text = "Kraft ist ein zweischneidiges Schwert. Wie könnte ich das nicht verstehen? Es ist nur so, dass ich es viel zu spät begriffen habe, viel zu spät. Sobald ich loslasse, werden sie mich zerreißen... Hätte ich von Anfang an so klar gedacht wie du, hätte ich nicht so ein tragisches Ende gefunden. Eh, eh? Du sagst, in der Zukunft kann ich Salons in der Lounge veranstalten?! Das ist... Wie könnte ich dir anders danken, als dir persönlich zu dienen..."
  },
  Voice_5216_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5216_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5217_AwakerVoiceContent = {
    Text = "Du bist ein sehr hartnäckiger Gast. Was muss ich tun, damit du das Privileg in deinen Händen aufgibst? Macht zieht nur Ärger an – so eine einfache Wahrheit, das verstehst du sicher, oder?"
  },
  Voice_5217_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5217_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5218_AwakerVoiceContent = {
    Text = "Bevor der Salon beginnt, möchtest du eine Geschichte hören? Eine Erzählung davon, wie ein Dorfmädchen die Krone der Macht beanspruchte... Wo sollen wir anfangen? Von ihren Eltern, die sie zwangen, einen alten Mann zu heiraten, oder vielleicht möchtest du den Teil, in dem sie im edlen Garten erblüht, lieber hören?"
  },
  Voice_5218_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5218_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5219_AwakerVoiceContent = {
    Text = "Früher nannten mich die Gäste \"Rote Dame\". Natürlich kannst du mich auch \"Sorel\" nennen, schließlich bist du mein ganz besonderer Gast..."
  },
  Voice_5219_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5219_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5220_AwakerVoiceContent = {
    Text = "Als die Gastgeberin des Salons ist es meine Pflicht sicherzustellen, dass jeder Gast zufrieden ist."
  },
  Voice_5220_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5220_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5221_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5221_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5222_AwakerVoiceContent = {
    Text = "Master? Ist etwas mit meiner Haltung nicht in Ordnung?"
  },
  Voice_5222_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5223_AwakerVoiceContent = {Text = "Oops!"},
  Voice_5223_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5224_AwakerVoiceContent = {
    Text = "Schlechtes Glück~"
  },
  Voice_5224_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5225_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5225_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5226_AwakerVoiceContent = {
    Text = "Ich erinnere mich an dieses Gefühl... Der glorreiche Moment naht."
  },
  Voice_5226_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5226_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5227_AwakerVoiceContent = {
    Text = "Obwohl die Kiemenmarkierungen noch nicht aufgetreten sind, fühle ich mich darüber nicht mehr ängstlich. Dieser Membranflügel wird sich in ein Schild verwandeln, um Sie zu beschützen, Hüter."
  },
  Voice_5227_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5227_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5228_AwakerVoiceContent = {
    Text = "Du... bist tatsächlich geduldiger als andere Menschen... Du hast so viele Ressourcen in mich investiert. Hasst du mich wirklich... nicht?"
  },
  Voice_5228_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5228_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5229_AwakerVoiceContent = {
    Text = "Hä? Das Ritual ist vorbei, aber ich habe immer noch keine Kiemen gewachsen? Hat dieTransformation wieder versagt?! Verdammt! Verdammt! Verdammt!"
  },
  Voice_5229_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5229_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5230_AwakerVoiceContent = {
    Text = "Diese Stimme ruft mich wieder... das ätherische Geräusch aus dem tiefen Aequor!"
  },
  Voice_5230_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5230_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5231_AwakerVoiceContent = {
    Text = "Rate—falsch—wieder—"
  },
  Voice_5231_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5232_AwakerVoiceContent = {
    Text = "Sanga, die Bildhauerin aus Cité, bietet dir ihren Meißel an. Du magst fehlerhaft sein, aber du bist dennoch wert, gemeißelt zu werden."
  },
  Voice_5232_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5238_AwakerVoiceContent = {
    Text = "Kinder, die nicht hören, versammelt euch~"
  },
  Voice_5238_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5239_AwakerVoiceContent = {
    Text = "Wahre Kunst braucht keine Erklärung."
  },
  Voice_5239_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5240_AwakerVoiceContent = {
    Text = "Wahre Kunst braucht keine Erklärung."
  },
  Voice_5240_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5241_AwakerVoiceContent = {
    Text = "Aurita, kannst du helfen?"
  },
  Voice_5241_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5242_AwakerVoiceContent = {
    Text = "Blas das Horn!"
  },
  Voice_5242_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5243_AwakerVoiceContent = {
    Text = "Um jeden Preis!"
  },
  Voice_5243_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5244_AwakerVoiceContent = {
    Text = "Das Gefühl, in Sonnenlicht gebadet zu werden... so sanft, dass es dir die Tränen in die Augen treibt."
  },
  Voice_5244_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5244_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5245_AwakerVoiceContent = {
    Text = "Um meine Dankbarkeit auszudrücken... werde ich einen verborgenen Altar für Sie in den Tiefen meines Leidens errichten."
  },
  Voice_5245_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5245_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5246_AwakerVoiceContent = {
    Text = "Bruder's Caro und mein Körper verschmelzen immer perfekter und enger..."
  },
  Voice_5246_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5246_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5247_AwakerVoiceContent = {
    Text = "Ich bin widerstandsfähiger, als du denkst. Also, wenn du mich benutzt, kannst du mehr Kraft anwenden. Halte dich nicht zurück."
  },
  Voice_5247_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5247_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5248_AwakerVoiceContent = {
    Text = "Ist es nur meine Einbildung? Das Verlangen nach Blut scheint etwas nachgelassen zu haben."
  },
  Voice_5248_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5248_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5249_AwakerVoiceContent = {
    Text = "Selbst bevor wir offiziell angefangen haben, habe ich bereits deiner Ankunft entgegengesehnt. Es scheint, als würden wir ganz gut zusammenarbeiten, oder? Partner."
  },
  Voice_5249_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5250_AwakerVoiceContent = {
    Text = "Das ist beschämend."
  },
  Voice_5250_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5251_AwakerVoiceContent = {Text = "Aah!"},
  Voice_5251_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5252_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5252_AwakerVoiceTitle = {
    Text = "Schlag·Manie"
  },
  Voice_5253_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5253_AwakerVoiceTitle = {
    Text = "Schlag·Depression"
  },
  Voice_5254_AwakerVoiceContent = {
    Text = "Verletze mich, so viel du willst!"
  },
  Voice_5254_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5255_AwakerVoiceContent = {
    Text = "Aigis hat wirklich Angst. Nein, nicht vor euch allen, sondern davor, dass sie euch erneut Angst und Trauer bringt."
  },
  Voice_5255_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5256_AwakerVoiceContent = {
    Text = "Die Märchenbücher dieser Ära sind viel interessanter als die, die ich damals gelesen habe! Ah, ah! Mein Herr, bitte missverstehen Sie nicht! Ich bin aus dem Alter für Gute-Nacht-Geschichten heraus!"
  },
  Voice_5256_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5257_AwakerVoiceContent = {
    Text = "Verletze mich, so viel du willst!"
  },
  Voice_5257_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5258_AwakerVoiceContent = {
    Text = "Puh... Hat Aigis allen Schwierigkeiten bereitet?"
  },
  Voice_5258_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5259_AwakerVoiceContent = {
    Text = "Du hast immer an diesem amüsanten Vertrauen festgehalten und bist an meiner Seite geblieben... Gut, vielleicht ist es keine schlechte Idee, dich nützlich zu machen. Aber denk daran: Ich kann keinen Verrat tolerieren, besonders nicht von dir."
  },
  Voice_5259_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5259_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5260_AwakerVoiceContent = {
    Text = "Ich bedaure nur, ihre Leichname nicht auf Pfähle zu spießen und sie an die Wände zu hängen! Ich werde niemanden verschonen, der mich verraten, getreten oder beleidigt hat!"
  },
  Voice_5260_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5260_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5261_AwakerVoiceContent = {
    Text = "Ja, ich habe mich vor diesen Leuten gekrümmt; das lässt sich nicht leugnen. Sie haben meine Unwissenheit ausgenützt, und ich habe sie dafür bezahlen lassen."
  },
  Voice_5261_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5261_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5262_AwakerVoiceContent = {
    Text = "Glaubst du, dass ein paar schmeichelnde Worte und ein paar Tage falscher Freundlichkeit mich dazu bringen werden, wieder bereitwillig die Fesseln anzulegen und dein Spielzeug zu werden?"
  },
  Voice_5262_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5262_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5263_AwakerVoiceContent = {
    Text = "Alle, die versucht haben, mich zu kontrollieren oder zu nutzen, endeten durch meine eigenen Hände in der Unterwelt—ich habe nichts dagegen, dich auch dorthin zu schicken."
  },
  Voice_5263_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5263_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5264_AwakerVoiceContent = {
    Text = "Ah... Entschuldigung, bitte beweg dich nicht!"
  },
  Voice_5264_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5265_AwakerVoiceContent = {
    Text = "Berühre mich nicht!"
  },
  Voice_5265_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5266_AwakerVoiceContent = {
    Text = "Respektlosigkeit!"
  },
  Voice_5266_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5267_AwakerVoiceContent = {
    Text = "Gib auf... Willkommen im Reich der Vergnügen und Träume."
  },
  Voice_5267_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5268_AwakerVoiceContent = {
    Text = "Das ist die Stadt, in der unzählige verlorene Seelen umhergeistern und ihren Weg nach Hause nicht finden können."
  },
  Voice_5268_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5269_AwakerVoiceContent = {
    Text = "Aigis wird ihr Bestes tun!"
  },
  Voice_5269_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5270_AwakerVoiceContent = {
    Text = "Ähm... ich kann meine Fähigkeit, Lebensenergie zu absorbieren, nicht kontrollieren, also lege bitte deine Hand nicht in die Wiege, sonst wirst du krank."
  },
  Voice_5270_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5271_AwakerVoiceContent = {
    Text = "Ich hoffe, sie funktioniert während unseres Gesprächs nicht falsch. Meine liebenswerte, aber auch ärgerliche Assistentin, es gibt keine weiteren Ersatzlabore mehr, die sie in die Luft sprengen kann."
  },
  Voice_5271_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Erica"
  },
  Voice_5271_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Erica“ wird freigeschaltet"
  },
  Voice_5272_AwakerVoiceContent = {
    Text = "Hände, diese lästigen Hände! Sie greifen immer in mein Haar. Ich kann meine eigenen Hände nicht einmal kontrollieren – was für ein nutzloser Kerl ich bin... Vielleicht sollte ich..."
  },
  Voice_5272_AwakerVoiceTitle = {
    Text = "Plauderei · Über mich selbst"
  },
  Voice_5274_AwakerVoiceContent = {
    Text = "Danke für Ihre Anleitung. Ich verstehe jetzt endlich Faints Entscheidung. Ich habe alles für selbstverständlich gehalten, ohne zu realisieren, welche mentale Last das für sie bedeutete. Von nun an werde ich versuchen, für mich selbst zu leben..."
  },
  Voice_5274_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5274_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5275_AwakerVoiceContent = {
    Text = "Durch die langen, endlosen Zeiten hatten Faint und ich nur einander... Aber jetzt habe ich neue wichtige Menschen... Hüter, bitte erlaub mir, meine vorherigen Worte zurückzunehmen. Du bist anders. Du interessierst dich nicht nur für meine Singstimme oder mein formelles Kleid; du siehst mich wirklich. Daher werde ich auch auf dich achtgeben."
  },
  Voice_5275_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5275_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5276_AwakerVoiceContent = {
    Text = "Die Sterne im Traum, auf dem Weg dorthin, wo sie hingehören, zeigen auf das Reich Gottes!"
  },
  Voice_5276_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5277_AwakerVoiceContent = {
    Text = "Warum bin ich immer in diesem Kleid gekleidet? Damit ich jederzeit für dich singen kann."
  },
  Voice_5277_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5277_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5278_AwakerVoiceContent = {
    Text = "Was will ich tun? ......Entschuldigung, ich verstehe nicht, was du meinst......Tatsächlich hat Faint mir diese Frage schon viele Male gestellt, aber alles, was ich will, ist, dass sie sich bald erholt......"
  },
  Voice_5278_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5278_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5279_AwakerVoiceContent = {
    Text = "Während unserer Zeit auf dem menschenleeren Planeten ermöglichten die Mitgefühl zeigenden einflussreichen Personen meiner Schwester und mir die Ressourcen zum Überleben. Am Ende gaben sie mir auch die Möglichkeit, den Planeten zu verlassen, obwohl sie auf eine Person beschränkt war. Sie sind alle meine Wohltäter, genau wie du, Hüter, der mir einen Platz zum Verweilen gegeben hat."
  },
  Voice_5279_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5279_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5280_AwakerVoiceContent = {
    Text = "Du bist die freundliche Person, die mir einen Platz zum Verweilen bietet. Aigis wird auf dich hören. Wenn Aigis doch nur ein wenig nützlicher sein könnte..."
  },
  Voice_5280_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5281_AwakerVoiceContent = {
    Text = "Vergiss nicht, den Veranstaltungsort vorzubereiten. Der, den du gebucht hast, ist nicht kleiner als der in Elworth, oder?"
  },
  Voice_5281_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5281_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5282_AwakerVoiceContent = {
    Text = "Gut, Karen ist jetzt motivierter und kann zwanzig Zimmer am Tag sauber machen!"
  },
  Voice_5282_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5282_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5283_AwakerVoiceContent = {
    Text = "Das ist die Musik, die so alt ist wie das Wasser des Sees und zu „uns“ gehört. Meister, lass uns zusammen tanzen! Bevor der Gesang von Karen von „Ihm“ genommen wird..."
  },
  Voice_5283_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5283_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5284_AwakerVoiceContent = {
    Text = "Meister! Karens Stimme... verblasst... Hilfe..."
  },
  Voice_5284_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5284_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5285_AwakerVoiceContent = {
    Text = "Karens Sehvermögen hat sich verbessert... Meister, hast du vergessen, dir wieder die Haare zu kämmen!"
  },
  Voice_5285_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5285_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5286_AwakerVoiceContent = {
    Text = "Auch wenn sie stärker wird, will Karen überhaupt keine Rache. Karen will einfach singen! Tanzen! Feiern!"
  },
  Voice_5286_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5286_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5287_AwakerVoiceContent = {
    Text = "Um nach totaler Zerstörung zu überleben, habe ich meinen Geist und mein Blut mit zu vielen Menschen geteilt. Meine gegenwärtige Macht ist weit entfernt von dem, was sie war, als ich diesen Willen zum ersten Mal akzeptierte."
  },
  Voice_5287_AwakerVoiceTitle = {
    Text = "Idle Talk·Über die Vergangenheit"
  },
  Voice_5288_AwakerVoiceContent = {
    Text = "Erwarte nicht, mich im Lehrgebäude zu finden. Es ist erfüllt vom Gestank verstaubter alter Gelehrter; ich kann es dort nicht einmal einen Tag aushalten."
  },
  Voice_5288_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5289_AwakerVoiceContent = {
    Text = "Lauf nicht."
  },
  Voice_5289_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5290_AwakerVoiceContent = {
    Text = "Meine Heimat verehrt die \"Götter\", und entsprechend ist der König, dem ich folge, natürlich ein \"göttlicher Kommunikator\"."
  },
  Voice_5290_AwakerVoiceTitle = {
    Text = "Idle Talk: Über das Ewige Königreich"
  },
  Voice_5291_AwakerVoiceContent = {
    Text = "Du hast hier eine bemerkenswerte Versammlung von Talenten, die eines großen Salons würdig sind... Sei versichert, die Einladung wird dir von meinem Diener überbracht."
  },
  Voice_5291_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5292_AwakerVoiceContent = {
    Text = "Komm schon!"
  },
  Voice_5292_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5293_AwakerVoiceContent = {
    Text = "Wenn es nur mehr Gefährten gäbe..."
  },
  Voice_5293_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5294_AwakerVoiceContent = {
    Text = "Ich bin nicht wie sie. Sie bringt nur feindliche Schauer und Angst, während ich dir intime, süße, brennende Schmerzen und Liebe gebe."
  },
  Voice_5294_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Wanda"
  },
  Voice_5294_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Wanda“"
  },
  Voice_5295_AwakerVoiceContent = {
    Text = "Denk nicht, das ist vorbei! Ich werde dafür sorgen, dass du für jeden Gramm dieser Demütigung bezahlst!"
  },
  Voice_5295_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5296_AwakerVoiceContent = {
    Text = "Deine Hände sind, wie deine Seele, warm. Das bleiche Feuer... Ich schätze deine Berührung."
  },
  Voice_5296_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5297_AwakerVoiceContent = {
    Text = "Was ist falsch daran, im Klassenraum Bridge zu spielen? Es gibt einen Tisch, Leute, und ich habe die Karten mitgebracht. Das bedeutet \"Spiel beginnt\"!"
  },
  Voice_5297_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5299_AwakerVoiceContent = {
    Text = "Tu das nicht..."
  },
  Voice_5299_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5300_AwakerVoiceContent = {
    Text = "Blick in den Abgrund!"
  },
  Voice_5300_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5301_AwakerVoiceContent = {
    Text = "Blick in den Abgrund!"
  },
  Voice_5301_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5302_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5302_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5303_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5303_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5304_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5304_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5305_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5305_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5306_AwakerVoiceContent = {
    Text = "Im göttlichen Licht baden!"
  },
  Voice_5306_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5307_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5307_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5308_AwakerVoiceContent = {
    Text = "Die schwachen Seelen versammeln sich, aber was nützt ihr Lärm? Seufz..."
  },
  Voice_5308_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5311_AwakerVoiceContent = {
    Text = "Krieg bringt immer Schmerz, und das Aushalten von Leid ist die Pflicht eines Kriegers. Selbst wenn ich meine Hände, meine Füße und alles andere verliere, werde ich dennoch für dich und für die Gerechtigkeit der Welt kämpfen."
  },
  Voice_5311_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5312_AwakerVoiceContent = {
    Text = "Ist das das Tribut, das du Ihm anbietest?"
  },
  Voice_5312_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5313_AwakerVoiceContent = {
    Text = "Glaubst du, dass dies die Zukunft verändern kann?"
  },
  Voice_5313_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5314_AwakerVoiceContent = {
    Text = "Seine Schwangerschaft... in meinem Bauch..."
  },
  Voice_5314_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5315_AwakerVoiceContent = {
    Text = "Heh, du bist schlauer als ich dachte."
  },
  Voice_5315_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5316_AwakerVoiceContent = {
    Text = "Es ist nur natürlich, dem Meister Tribut zu zollen."
  },
  Voice_5316_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5317_AwakerVoiceContent = {
    Text = "Du siehst ziemlich niedlich aus, wenn du versuchst, mir zu gefallen."
  },
  Voice_5317_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5318_AwakerVoiceContent = {
    Text = "Brownie, Karamellpudding, Sachertorte, Schokoladenmousse, Kekse... Jeder Tisch muss sie haben!"
  },
  Voice_5318_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5318_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5319_AwakerVoiceContent = {
    Text = "Überprüfe meinen Rock für mich, wirst du? Keine Falten, keine Lockerheit... Was ist los? Bist du unzufrieden?"
  },
  Voice_5319_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5319_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5320_AwakerVoiceContent = {
    Text = "Willkommen zu meiner letzten Erleuchtungszeremonie! All dies wurde von mir sorgfältig entworfen. Natürlich hat der Hüter nur ein wenig beigetragen..."
  },
  Voice_5320_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5320_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5321_AwakerVoiceContent = {
    Text = "Die Tische und Stühle sollten mit Spitze verziert sein, die meiner Temperament entspricht, und die Blumentöpfe müssen rote Spinnenpflanzen enthalten... Mach dich schnell bereit!"
  },
  Voice_5321_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5321_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5322_AwakerVoiceContent = {
    Text = "Geh und mach die Reservierung für den Gast! Wie konntest du so eine einfache Aufgabe vermasseln?"
  },
  Voice_5322_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5322_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5323_AwakerVoiceContent = {
    Text = "Keine Flucht!"
  },
  Voice_5323_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5324_AwakerVoiceContent = {
    Text = "Keine Flucht!"
  },
  Voice_5324_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5325_AwakerVoiceContent = {
    Text = "Ich werde mein Bestes tun! Um den Erwartungen meines Herrn gerecht zu werden."
  },
  Voice_5325_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5325_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5326_AwakerVoiceContent = {
    Text = "Ich mag diese Frau wirklich. Wir haben... das... richtig, eine gemeinsame Sprache!"
  },
  Voice_5326_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Wanda"
  },
  Voice_5326_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Wanda“"
  },
  Voice_5327_AwakerVoiceContent = {
    Text = "Du unverschämter Narr!"
  },
  Voice_5327_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5328_AwakerVoiceContent = {
    Text = "Du unverschämter Narr!"
  },
  Voice_5328_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5329_AwakerVoiceContent = {
    Text = "In Trümmer verwandelt."
  },
  Voice_5329_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5330_AwakerVoiceContent = {
    Text = "Zersplittere."
  },
  Voice_5330_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5331_AwakerVoiceContent = {
    Text = "Durch die Barrieren der Realität brechen!"
  },
  Voice_5331_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5332_AwakerVoiceContent = {
    Text = "Planst du, bald zu segeln? Könntest du meiner bescheidenen Bitte nachkommen und mich mitnehmen? Lass mich nur das Meer erreichen..."
  },
  Voice_5332_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5332_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5333_AwakerVoiceContent = {
    Text = "Wenn du mir immer noch vertraust, lass mich bitte das Leitlicht auf dieser Reise sein. Doch selbst bei so einer einfachen Aufgabe habe ich schon versagt..."
  },
  Voice_5333_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5333_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5334_AwakerVoiceContent = {
    Text = "Hast du kein Verlangen, aufs Meer hinauszusegeln? Lass mich die aktuelle Karte überprüfen... 47°9' S, 126°43' W, genau hier."
  },
  Voice_5334_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5334_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5335_AwakerVoiceContent = {
    Text = "Ich habe in der Vergangenheit viele Katastrophen verursacht und beinahe die Zerstörung gewisser Zivilisationen herbeigeführt... Wenn ich sage, es war nicht absichtlich, ist es dann schon zu spät?"
  },
  Voice_5335_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5335_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5336_AwakerVoiceContent = {
    Text = "Ich bin der Wächter des Eingangs zum Ewigen Königreich, der die Heimkehrer führt. Wie ironisch, dass jemand mit einer solchen Pflicht den Weg nach Hause vergessen hat...\nWirst du... mein Licht sein?"
  },
  Voice_5336_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5336_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5337_AwakerVoiceContent = {
    Text = "Sternencluster."
  },
  Voice_5337_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5338_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5338_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5339_AwakerVoiceContent = {
    Text = "Dichter Nebel."
  },
  Voice_5339_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5340_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5340_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5341_AwakerVoiceContent = {
    Text = "Für die meisten Menschen macht es keinen Unterschied, ein Wächter zu sein, aber diese Frau ist eine Ausnahme. Wenn möglich, bitte arrangiere einen anderen Weg für mich."
  },
  Voice_5341_AwakerVoiceTitle = {
    Text = "Chat·Über Miryam"
  },
  Voice_5341_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Miryam“ wird freigeschaltet"
  },
  Voice_5342_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5342_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5343_AwakerVoiceContent = {
    Text = "Es spielt keine Rolle."
  },
  Voice_5343_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5344_AwakerVoiceContent = {
    Text = "Lass deine Hände davon."
  },
  Voice_5344_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5345_AwakerVoiceContent = {
    Text = "Bevor ich zum Aequor-Palast zurückkehre, werde ich dir, einem einfachen Menschen, einmalig etwas von der Macht von Aequor leihen."
  },
  Voice_5345_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5346_AwakerVoiceContent = {Text = "Los!"},
  Voice_5346_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5347_AwakerVoiceContent = {
    Text = "Gefällt es dir? Ich liebe den Schmerz—das Gefühl von geschwollenem, brennendem Fleisch, die Stöhnen, die Freude und Leiden verschmelzen. Schmerz ist das ursprünglichste und wahrhaftigste Verlangen, nicht wahr?"
  },
  Voice_5347_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5348_AwakerVoiceContent = {
    Text = "Tritt Aurita bei!"
  },
  Voice_5348_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5349_AwakerVoiceContent = {
    Text = "Tritt Aurita bei!"
  },
  Voice_5349_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5350_AwakerVoiceContent = {
    Text = "Diese große Schwester starrt mich immer heftig an. Aber aus irgendeinem Grund fühle ich eine Vertrautheit. Erinnern wir uns an meine Mutter?"
  },
  Voice_5350_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Helot"
  },
  Voice_5350_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Helot“ wird freigeschaltet"
  },
  Voice_5351_AwakerVoiceContent = {
    Text = "Mein Geist fühlt sich schärfer an, nicht schlecht."
  },
  Voice_5351_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5351_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5352_AwakerVoiceContent = {
    Text = "Ich ziehe Laborarbeit dem Außendienst vor—hast du gedacht, diese Hilfswerkzeuge wurden aus dem Meer gefischt?"
  },
  Voice_5352_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5352_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5353_AwakerVoiceContent = {
    Text = "Ob es Schrauben oder Nägel sind, je mehr, desto besser!"
  },
  Voice_5353_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5354_AwakerVoiceContent = {
    Text = "Der Körper kann diese Macht kaum bewältigen, aber es ist noch nicht an der Zeit, die Puppen zu wechseln. Warum stehst du nur da? Hilf mir, dieses Bein zu halten; ich muss einige Anpassungen vornehmen."
  },
  Voice_5354_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5354_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5355_AwakerVoiceContent = {
    Text = "Die Last des leitenden Lichts kann selbst die reinsten Heiligen überwältigen. Wenn du erschöpft bist, meine blasse Flamme, zögere nicht, dich mir anzuvertrauen. Ich werde alles in meiner Macht Stehende tun, um deine Last zu erleichtern und das Gewicht dieser unzähligen Segnungen zu teilen."
  },
  Voice_5355_AwakerVoiceTitle = {
    Text = "Idle-Gespräch · Über Erschöpfung"
  },
  Voice_5356_AwakerVoiceContent = {
    Text = "Ihre Zustimmung ist der Grund für meine Existenz als Ritter."
  },
  Voice_5356_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5356_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5357_AwakerVoiceContent = {
    Text = "Getränkt im Schimmer der Götter, ist dies die göttliche Macht meines Herrn? So weit, so heilig"
  },
  Voice_5357_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5357_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5358_AwakerVoiceContent = {
    Text = "Die Tür zu dem Göttlichen ist in Reichweite."
  },
  Voice_5358_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5358_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5359_AwakerVoiceContent = {
    Text = "Heller und klarer..."
  },
  Voice_5359_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5359_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5360_AwakerVoiceContent = {
    Text = "Um meine vollständige menschliche Form als Erwachter wiederzuerlangen... habe ich bereits die heilige Melodie gehört, die für mich vom Göttlichen Reich gespielt wurde..."
  },
  Voice_5360_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5360_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5361_AwakerVoiceContent = {
    Text = "Es wird mich in die Kirche willkommen heißen und mir ruhigen Frieden gewähren..."
  },
  Voice_5361_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5361_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5362_AwakerVoiceContent = {
    Text = "Mach dir keine Sorgen, wir sind alle ziemlich nützlich. Ich kann nähen und putzen, ein anderer ich ist im Kämpfen gut, und die anderen..."
  },
  Voice_5362_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5363_AwakerVoiceContent = {
    Text = "Ich hasse helle, weiche Dinge. Sanftheit ist wie ein Spiegel, der all das Hässliche, die Gier und die Zerbrechlichkeit offenbart."
  },
  Voice_5363_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5364_AwakerVoiceContent = {
    Text = "Willst du Brown streicheln? Ich kann diese Entscheidung nicht für dich treffen. Du musst sie selbst fragen."
  },
  Voice_5364_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5365_AwakerVoiceContent = {
    Text = "Willst du mich erfreuen? Dann knie nieder, biete mir deinen Hals an und schweige, bis ich dich vollkommen ausgezehrt habe."
  },
  Voice_5365_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5366_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5366_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5367_AwakerVoiceContent = {
    Text = "Ich hatte letzte Nacht einen Traum; er markierte den Beginn meiner Reise durch die Sterne."
  },
  Voice_5367_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5367_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5368_AwakerVoiceContent = {
    Text = "Kann Aigis helfen?"
  },
  Voice_5368_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5368_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5369_AwakerVoiceContent = {
    Text = "Ich kann es fühlen~"
  },
  Voice_5369_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5370_AwakerVoiceContent = {Text = "Tippe!"},
  Voice_5370_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Drei"
  },
  Voice_5371_AwakerVoiceContent = {Text = "Vorsicht!"},
  Voice_5371_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5372_AwakerVoiceContent = {
    Text = "Rücktritt."
  },
  Voice_5372_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5373_AwakerVoiceContent = {
    Text = "Niemand wird verletzt... in dieser... Welt..."
  },
  Voice_5373_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5374_AwakerVoiceContent = {Text = "(kokett)"},
  Voice_5374_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5375_AwakerVoiceContent = {
    Text = "Bitte erlaube mir, einen Altar für meinen Herrn aufzustellen. Es ist eine Statue, die von ergebenen Anhängern geschnitzt wurde und wird dir keinen Fluch bringen."
  },
  Voice_5375_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5376_AwakerVoiceContent = {
    Text = "Nur ein kleines bisschen..."
  },
  Voice_5376_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5377_AwakerVoiceContent = {
    Text = "Mein Schraubenschlüssel ist noch nicht in Position!"
  },
  Voice_5377_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5378_AwakerVoiceContent = {
    Text = "Chemie, Physik, Silberanwendungen... Ist es in dieser Ära nicht mehr notwendig, die sieben Ritterfähigkeiten zu lernen? Ich verstehe. In diesem Fall bitte ich um die entsprechenden Kurse, mein Herr!"
  },
  Voice_5378_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5379_AwakerVoiceContent = {
    Text = "Aurita hat die Welt bereist! Nicht von den Wellen weggetragen, sondern mit einer Karawane gereist!"
  },
  Voice_5379_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5379_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5380_AwakerVoiceContent = {
    Text = "Leuchtturmqualle, Kronenqualle, Pfirsichblütenqualle – sie alle bewegen sich in Gruppen. Natürlich tut Aurita das auch! Aurita möchte bei allen sein!"
  },
  Voice_5380_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5380_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5381_AwakerVoiceContent = {
    Text = "Vergangene Ereignisse? Schwer zu erinnern... Aber Aurita erinnert sich, dass sie in einem Aquarium gearbeitet hat! Der Tageslohn betrug 2 Pensh!"
  },
  Voice_5381_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5381_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5382_AwakerVoiceContent = {
    Text = "Lasst mich euch ein Geheimnis verraten: Aurita ist tatsächlich ein Aram, Trans... ähm, im Grunde genommen ist Aurita eine Meeresbewohnerin! Wenn Aurita brav ist, Gemüse isst und Freunde findet, wird Atlanta sie willkommen heißen!"
  },
  Voice_5382_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5382_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5383_AwakerVoiceContent = {
    Text = "Auritas Zuhause, die Aquarienfreunde, ihre Lieblingsqualle – alle weg... Wirst du auch verschwinden? Kannst du nicht für immer bei Aurita bleiben?"
  },
  Voice_5383_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5383_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5384_AwakerVoiceContent = {
    Text = "Haben wir gewonnen? Das ist wunderbar..."
  },
  Voice_5384_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5387_AwakerVoiceContent = {
    Text = "Für Frieden."
  },
  Voice_5387_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5388_AwakerVoiceContent = {
    Text = "Für Gerechtigkeit."
  },
  Voice_5388_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5389_AwakerVoiceContent = {
    Text = "Ich weiß, dass du in mir bist!"
  },
  Voice_5389_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5390_AwakerVoiceContent = {
    Text = "Menschen, falsche Götter, Erwachende und sogar Auflösung... Alle werden als Grundlage für mein ewiges Land dienen."
  },
  Voice_5390_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5391_AwakerVoiceContent = {
    Text = "Erwecke, erwache! Ich weiß, du bist in mir!"
  },
  Voice_5391_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5392_AwakerVoiceContent = {
    Text = "Uvhash... er erinnert mich an meinen Bruder und bringt Erinnerungen an dunkle, kalte und schlaflose Tage zurück."
  },
  Voice_5392_AwakerVoiceTitle = {
    Text = "Chat·Über Uvhash"
  },
  Voice_5392_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Uvhash“ wird freigeschaltet"
  },
  Voice_5393_AwakerVoiceContent = {
    Text = "Unsere Beziehung ist wie die von Sherlock Holmes und Dr. Watson, oder? Hast du die neuesten beliebten Magazine verfolgt?"
  },
  Voice_5393_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5394_AwakerVoiceContent = {
    Text = "Verbeuge dich vor der Schönheit."
  },
  Voice_5394_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5395_AwakerVoiceContent = {
    Text = "Verbeuge dich vor der Schönheit."
  },
  Voice_5395_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5396_AwakerVoiceContent = {
    Text = "Aversion, ein beschreibendes Verb, bedeutet, eine Abneigung gegen etwas zu entwickeln. Abneigung, ein Verb, bezieht sich auf das Gefühl der Aversion, wenn etwas nicht gemocht und vermieden wird. Aversion, ein Substantiv, das Gefühl der Abneigung, <Del:Abneigung unterdrückt zu werden, lässt mich zerstören lässt mich zerstören lässt mich> — Entschuldigung, aber ich fürchte, ich verstehe nicht, was \"Abneigung\" bedeutet."
  },
  Voice_5396_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5397_AwakerVoiceContent = {Text = "Am Ende..."},
  Voice_5397_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5398_AwakerVoiceContent = {
    Text = "Werde noch unterschiedlicher."
  },
  Voice_5398_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5399_AwakerVoiceContent = {
    Text = "Erinnere dich an meinen Namen, Goliath. Dieser Name ist dazu bestimmt, die unbedeutende Geschichte der Menschheit zu zertreten."
  },
  Voice_5399_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5400_AwakerVoiceContent = {
    Text = "Bitte hab keine Bedenken."
  },
  Voice_5400_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5401_AwakerVoiceContent = {
    Text = "Hoffe, dass du dein Potenzial und die Erwartungen der Menschheit, neuer Hüter, nicht enttäuschen wirst."
  },
  Voice_5401_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5402_AwakerVoiceContent = {
    Text = "Überlastung."
  },
  Voice_5402_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5403_AwakerVoiceContent = {
    Text = "Überfahren"
  },
  Voice_5403_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5404_AwakerVoiceContent = {
    Text = "Hmm, das Foto, das du in deinem Geldbeutel gefunden hast? Ah, das ist das alte Ich. Mein aktuelles Aussehen wurde von meinem Glücksspielfreund und Rivalen geprägt."
  },
  Voice_5404_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5404_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5405_AwakerVoiceContent = {
    Text = "Perfekt—möchtet ihr riskieren? Wenn ihr gewinnt, teile ich ein Geheimnis mit euch.\nAber seid vorsichtig, Alva könnte euch erwischen~"
  },
  Voice_5405_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5405_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5406_AwakerVoiceContent = {
    Text = "Kümmert dich dieses Fell? Willst du es berühren? Keine Sorge, ich bin sehr großzügig!"
  },
  Voice_5406_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5406_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5407_AwakerVoiceContent = {
    Text = "Natürlich gibt es Vorteile. Habe ich nicht meinen Watson getroffen? Im Vergleich dazu zählen Leben und Aussehen nicht, oder?"
  },
  Voice_5407_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5407_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5408_AwakerVoiceContent = {
    Text = "Bereue ich es? Überhaupt nicht. Das Leben wäre viel zu langweilig, wenn alles immer reibungslos laufen würde, nicht wahr?"
  },
  Voice_5408_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5408_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5409_AwakerVoiceContent = {
    Text = "In meiner Zeit waren Schulen Orte zur Ausbildung von Kriegern. Es scheint, dass dies auch jetzt noch der Fall ist."
  },
  Voice_5409_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5410_AwakerVoiceContent = {
    Text = "Mason... Nein, das ist in Ordnung. Zumindest können wir wieder zusammen sein, \"24\"."
  },
  Voice_5410_AwakerVoiceTitle = {
    Text = "Idle Talk · Über \"24\""
  },
  Voice_5410_UnlockDesc = {
    Text = "Nach dem Erwerb des Erwachenden „24“ freischalte"
  },
  Voice_5411_AwakerVoiceContent = {
    Text = "Nicht schlecht, oder? Jetzt die Belohnung. — Was? Es gibt nichts umsonst!"
  },
  Voice_5411_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5412_AwakerVoiceContent = {
    Text = "Ich komme aus der Cité. Dort will jeder Schauspieler werden; niemand ist damit zufrieden, nur zuzuschauen. In Wirklichkeit sind wir nur die erbärmlichen Fußnoten der Stadt."
  },
  Voice_5412_AwakerVoiceTitle = {
    Text = "Idle Talk·Über die Vergangenheit"
  },
  Voice_5413_AwakerVoiceContent = {
    Text = "Hast du antike Steinmetze gesehen? Mit den Bergen verschmolzen, die Zeit durch die Natur überdauernd, solch wunderbare Relikte... aber immer noch nicht genug..."
  },
  Voice_5413_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5414_AwakerVoiceContent = {
    Text = "Die Taube ist nicht zurückgekehrt..."
  },
  Voice_5414_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5415_AwakerVoiceContent = {
    Text = "Tretet zurück!"
  },
  Voice_5415_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5416_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5416_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5417_AwakerVoiceContent = {
    Text = "Führen Sie den Befehl aus!"
  },
  Voice_5417_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5418_AwakerVoiceContent = {Text = "Narr"},
  Voice_5418_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5419_AwakerVoiceContent = {
    Text = "...Hä? Rufst du mich? Ich habe nichts gehört, während ich das Motorrad repariert habe... Übrigens, netter Fremder, hast du meinen Schraubenschlüssel gesehen?"
  },
  Voice_5419_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5419_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5420_AwakerVoiceContent = {
    Text = "Meine Erinnerung ist immer verschwommen, und ich kann mich nur auf das konzentrieren, was direkt vor mir ist. Ich werde jedoch mein Bestes tun, um deinen Namen in mein Gedächtnis einzuprägen... Wie war er noch gleich?"
  },
  Voice_5420_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5420_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5421_AwakerVoiceContent = {
    Text = "Du kommst mir irgendwie vertraut vor, aber ich kann mich nicht an deinen Namen erinnern... Bist du meine Assistentin? Könntest du mir sieben Bolzen bringen?"
  },
  Voice_5421_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5421_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5422_AwakerVoiceContent = {
    Text = "Ich habe deinen Namen auf das Phantasma eingraviert. Wenn wir eines Tages Abenteuer erleben, werde ich nicht vergessen, wie ich dich ansprechen kann."
  },
  Voice_5422_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5422_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5423_AwakerVoiceContent = {
    Text = "So vertraut, so vertraut. Es muss etwas zwischen uns passiert sein, oder? Gib mir einen Moment, um mich zu erinnern... Ah, es bist du, der Hüter!"
  },
  Voice_5423_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5423_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5424_AwakerVoiceContent = {
    Text = "Du bist wirklich ein unaufrichtiger Kind. Zum Glück habe ich genug Zeit und Geduld, um auf dich zu warten..."
  },
  Voice_5424_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5425_AwakerVoiceContent = {
    Text = "„Jeder ist glücklich,“ richtig?"
  },
  Voice_5425_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5426_AwakerVoiceContent = {
    Text = "Ich habe einen anständigen Pokal bekommen... Auch wenn er sich nicht mit meiner besten Sammlung vergleichen kann, ist der Nervenkitzel, nach neuen Stückchen zu jagen, immer aufregend. Lade mich das nächste Mal auch ein."
  },
  Voice_5426_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5427_AwakerVoiceContent = {Text = "Hmm..."},
  Voice_5427_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5428_AwakerVoiceContent = {
    Text = "Eine professionelle Dienerin wird alles für ihren Meister aufräumen, einschließlich der Bösewichte~"
  },
  Voice_5428_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5429_AwakerVoiceContent = {
    Text = "Wir sind jetzt Komplizen, richtig? Wenn du jemals auf der Straße landest, werde ich dich nicht im Müll überleben lassen."
  },
  Voice_5429_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5430_AwakerVoiceContent = {
    Text = "Wachse und gedeihe, mein kleiner Setzling."
  },
  Voice_5430_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5431_AwakerVoiceContent = {
    Text = "Wachse und gedeihe, mein kleiner Setzling."
  },
  Voice_5431_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5432_AwakerVoiceContent = {
    Text = "Fühlt sich an, als hätte sich mein Würfelglück ein wenig verbessert!"
  },
  Voice_5432_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5433_AwakerVoiceContent = {
    Text = "Wow! Dein Glück brennt heiß!"
  },
  Voice_5433_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5434_AwakerVoiceContent = {
    Text = "Glücklich~"
  },
  Voice_5434_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5435_AwakerVoiceContent = {
    Text = "Komme mir nicht näher."
  },
  Voice_5435_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5436_AwakerVoiceContent = {
    Text = "Komme mir nicht näher."
  },
  Voice_5436_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5437_AwakerVoiceContent = {
    Text = "Ich muss dich anklagen, Hüter. Deine Freundlichkeit macht mir Unbehagen – nur körperlicher Schmerz ist für mich wirklich ewig."
  },
  Voice_5437_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5438_AwakerVoiceContent = {
    Text = "Sehr gut, gut gemacht."
  },
  Voice_5438_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5439_AwakerVoiceContent = {
    Text = "Diese Ebene ist bei weitem nicht ausreichend."
  },
  Voice_5439_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5440_AwakerVoiceContent = {
    Text = "Also, welche Belohnung wünschst du dir?"
  },
  Voice_5440_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5441_AwakerVoiceContent = {
    Text = "Ugh! Der Schmutz und die Unordnung überall... Ich kann nicht einmal einen sauberen Platz finden, um meine Füße abzusetzen. Sehr gut, biete mir deinen weichen Rücken an, Sterblicher."
  },
  Voice_5441_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5442_AwakerVoiceContent = {
    Text = "Endlich... habe ich es gefunden!"
  },
  Voice_5442_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5443_AwakerVoiceContent = {
    Text = "Selbst Browns Fell ist glatter geworden."
  },
  Voice_5443_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5443_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5444_AwakerVoiceContent = {
    Text = "Als Sicherheitsbeamter arbeiten mag etwas tough sein, aber du kannst alle Besorgungen und Lieferungen mir überlassen."
  },
  Voice_5444_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5444_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5445_AwakerVoiceContent = {
    Text = "Sieh dir dich an, wenn du Brown gegenüberstehst.\n...Hehe, Lord Brown wird heute Abend die Zehen eines Feiglings essen. Lass uns sehen, wer unglücklich genug sein wird."
  },
  Voice_5445_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5445_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5446_AwakerVoiceContent = {
    Text = "Ich frage mich, ob ich noch größer werden kann."
  },
  Voice_5446_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5446_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5447_AwakerVoiceContent = {
    Text = "Bereit zur Arbeit? Alles klar, Brown, lass uns aufdrehen!"
  },
  Voice_5447_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5447_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5448_AwakerVoiceContent = {
    Text = "Agrippa? Entschuldigung, ich habe selbst zu viele Menschen fortgeschickt. Die meisten von ihnen sind gesichtslos und nicht der Erinnerung wert."
  },
  Voice_5448_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Agrippa"
  },
  Voice_5448_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Agrippa“"
  },
  Voice_5449_AwakerVoiceContent = {
    Text = "Gefährliche Crewmitglieder... Nein, das ist nur aus der Perspektive der Navigationssicherheit..."
  },
  Voice_5449_AwakerVoiceTitle = {
    Text = "Chat·Über Faros"
  },
  Voice_5449_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Faros“ wird freigeschaltet"
  },
  Voice_5450_AwakerVoiceContent = {
    Text = "Komm nicht näher!"
  },
  Voice_5450_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5451_AwakerVoiceContent = {
    Text = "Sei vorsichtig!"
  },
  Voice_5451_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5452_AwakerVoiceContent = {
    Text = "Ich habe deine Anweisungen abgeschlossen... Ah, ich habe es wieder vermasselt, nicht wahr?"
  },
  Voice_5452_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5453_AwakerVoiceContent = {
    Text = "Ah, das ist genau der Teil, den ich gebraucht habe, danke! ...Hä? Ich habe Sie gebeten, es zu finden? Ich erinnere mich überhaupt nicht daran. Sind Sie sich sicher, dass Sie sich nicht irren?"
  },
  Voice_5453_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Teile"
  },
  Voice_5454_AwakerVoiceContent = {
    Text = "Inspiration, unendlich fließend"
  },
  Voice_5454_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5455_AwakerVoiceContent = {
    Text = "Guter Geschmack."
  },
  Voice_5455_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5456_AwakerVoiceContent = {
    Text = "Du hast das perfekte Schnitzmesser für mich gewählt."
  },
  Voice_5456_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5457_AwakerVoiceContent = {
    Text = "Ich hasse es, die Kontrolle zu verlieren. Dennoch hat deine Anwesenheit mir gezeigt, dass eine Prise subtilen Chaos eine einzigartige Art von Freude bringen kann."
  },
  Voice_5457_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5458_AwakerVoiceContent = {
    Text = "Bist du ein bisschen gewachsen?"
  },
  Voice_5458_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5459_AwakerVoiceContent = {
    Text = "Es tut mir leid, es ist schwer für mich, meinen Körper zu entwickeln..."
  },
  Voice_5459_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_54601_AwakerVoiceContent = {
