  },
  Voice_54614_AwakerVoiceContent = {
    Text = "Schwelge in diesem einzigartigen Schmerz!"
  },
  Voice_54614_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_54615_AwakerVoiceContent = {
    Text = "Schwelge in diesem einzigartigen Schmerz!"
  },
  Voice_54615_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_54616_AwakerVoiceContent = {
    Text = "\"Ja, Kind, du bist im strömenden Fluss umgekommen!\""
  },
  Voice_54616_AwakerVoiceTitle = {
