  },
  Voice_54622_AwakerVoiceContent = {
    Text = "Im Abgrund... wird es ein Licht der Gerechtigkeit geben."
  },
  Voice_54622_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_54623_AwakerVoiceContent = {
    Text = "Ich bin diejenige, die die Ketten zerreißt—Tokuli—Li!"
  },
  Voice_54623_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_54624_AwakerVoiceContent = {
    Text = "Ich bin diejenige, die die Ketten zerreißt—Tokuli—Li!"
  },
  Voice_54624_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_54625_AwakerVoiceContent = {
    Text = "Dieser Körper ist derjenige, der die Zukunft offenbart!"
  },
  Voice_54625_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_54626_AwakerVoiceContent = {
    Text = "Dieser Körper ist derjenige, der die Zukunft offenbart!"
  },
  Voice_54626_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_54627_AwakerVoiceContent = {
    Text = "Beuge dich und küsse die Spitzen meiner Füße!"
  },
  Voice_54627_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_54628_AwakerVoiceContent = {
    Text = "Alle Muscheln sind hier!"
  },
  Voice_54628_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_54629_AwakerVoiceContent = {
    Text = "Alle Muscheln sind hier!"
  },
  Voice_54629_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_5462_AwakerVoiceContent = {
    Text = "Die außergewöhnliche Kraft kann nur von einem Aequor ertragen werden. Du musst mich beneiden, haha. Es ist nicht deine Schuld, dass du ein schwacher Mensch bist; akzeptiere es einfach."
  },
  Voice_5462_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5462_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_54630_AwakerVoiceContent = {
    Text = "Beuge dich und küsse die Spitzen meiner Füße!"
  },
  Voice_54630_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_5463_AwakerVoiceContent = {
    Text = "Kann ich diese besiegten Personen zu meinen Sklaven machen?"
  },
  Voice_5463_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5464_AwakerVoiceContent = {Text = "Heh."},
  Voice_5464_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5465_AwakerVoiceContent = {
    Text = "So wie erwartet."
  },
  Voice_5465_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5466_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5466_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5467_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5467_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5468_AwakerVoiceContent = {
    Text = "Wenn ich früher gewusst hätte, dass diese Menschen von diesem alles verzehrenden Fluch gequält werden, hätte ich... Nein, es ist jetzt nicht zu spät. Ich muss ihn ausmerzen und alles Leid beseitigen, selbst wenn es mich erneut das Leben kostet."
  },
  Voice_5468_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5469_AwakerVoiceContent = {
    Text = "Verliere nicht den Mut. Das Meer umarmt jeden."
  },
  Voice_5469_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5470_AwakerVoiceContent = {
    Text = "Mit einem so zerbrechlichen Körper ist es zu viel verlangt, dich zu meinem Gefährten zu machen. Komm schon, lass uns dich zum Sportclub an der Akademie bringen, um deinen Horizont zu erweitern und strenges Training zu durchlaufen!"
  },
  Voice_5470_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5471_AwakerVoiceContent = {
    Text = "Die arme Seele, die meine Macht entliehen hat, wird von der Auflösung gequält... Was für ein Blick ist das? Denk gar nicht daran! Ich werde dir nicht sagen, wo sie ist!"
  },
  Voice_5471_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5472_AwakerVoiceContent = {
    Text = "Solange du genug Glück hast, kannst du unbesiegbar werden."
  },
  Voice_5472_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5473_AwakerVoiceContent = {
    Text = "Wird es zu hart sein?"
  },
  Voice_5473_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5474_AwakerVoiceContent = {
    Text = "Oh mein Gott, die meisten hier sind noch Kinder. Der Gentleman hat bereits weißes Haar, und der ernst blickende junge Mann fehlt ein Arm. Keiner von ihnen ist eine ideale Wahl... Das ist echt ein Dilemma."
  },
  Voice_5474_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5475_AwakerVoiceContent = {
    Text = "Wird es zu hart sein?"
  },
  Voice_5475_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5476_AwakerVoiceContent = {
    Text = "Sorgfältig gezeichnete Runen, fromm gemeißelte Statuen, wiederholt raffinierte Tabupotionen... nichts kann gespart werden."
  },
  Voice_5476_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5476_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5477_AwakerVoiceContent = {
    Text = "Der Thron sollte aus altem grünen Stein von Aequor gebaut werden, und der Altar sollte mit opferblut verschmiert sein... Solltest du nicht anfangen, vorzubereiten?"
  },
  Voice_5477_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5477_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5478_AwakerVoiceContent = {
    Text = "Beschwöre sie alle; sie sollten zittern und knieen in Erwartung Seiner Ankunft."
  },
  Voice_5478_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5478_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5479_AwakerVoiceContent = {
    Text = "Ich werde zu den Ruinen von Aequor gehen und in den Gewässern baden, wo Er geboren wurde..."
  },
  Voice_5479_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5479_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5480_AwakerVoiceContent = {
    Text = "Willkommen zu Seiner Geburtstagsfeier, um Sein Kommen zu zeugen... Was? Du sagst, Sein Untergang ist ebenfalls vorbestimmt? ... Nein, das ist unmöglich... Ich habe bereits einen so hohen Preis bezahlt..."
  },
  Voice_5480_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5480_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5481_AwakerVoiceContent = {
    Text = "Folge den göttlichen Geboten."
  },
  Voice_5481_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5482_AwakerVoiceContent = {
    Text = "Wird deine Seite der Ort sein, wo Ohnmacht und ich hingehören?"
  },
  Voice_5482_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5482_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5483_AwakerVoiceContent = {
