  },
  Voice_5484_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5485_AwakerVoiceContent = {
    Text = "Das weite Universum, der grenzenlose Tiefenraum und die endlose Reise ließen mich einst verloren fühlen..."
  },
  Voice_5485_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5485_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5486_AwakerVoiceContent = {
    Text = "Abkürzungsmethoden können dir einen Schub geben, aber vernachlässige nicht das Training deiner Fähigkeiten."
  },
  Voice_5486_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5487_AwakerVoiceContent = {
    Text = "So gilt diese Methode auch für mich..."
  },
  Voice_5487_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5488_AwakerVoiceContent = {
    Text = "Ein wunderbares Gefühl."
  },
  Voice_5488_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5492_AwakerVoiceContent = {
    Text = "Würde seine Ankunft nicht das Ende des Leidens bringen, das durch diesen schwarzen Tod verursacht wurde?"
  },
  Voice_5492_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5493_AwakerVoiceContent = {
    Text = "Guten Tag, mein Herr. Wenn Sie hinausgehen, um eine Ermittlung durchzuführen, erlauben Sie mir bitte, Sie als Ihre Wache zu begleiten."
  },
  Voice_5493_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5493_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5494_AwakerVoiceContent = {
    Text = "Was tun? Wenn dir langweilig ist, schreib einfach diesen Missionsbericht."
  },
  Voice_5494_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5495_AwakerVoiceContent = {
    Text = "Beginnt es endlich? Meine kleinen Haustiere haben schon sehr, sehr lange gehungert..."
  },
  Voice_5495_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5496_AwakerVoiceContent = {
    Text = "Die Kraft der Blutlinie steigt."
  },
  Voice_5496_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5497_AwakerVoiceContent = {
    Text = "...Warte mal, ich habe das schon mal gesehen. Sie haben mir Wasser mit dieser schwarzen Substanz gegeben. Könnte es damit verbunden sein, dass ich die Macht der Grünen Flamme erlangt habe? Ich schätze, es ist ein versteckter Segen."
  },
  Voice_5497_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5498_AwakerVoiceContent = {
    Text = "Ramona Dexter, nenn mich einfach Ramona. Ich freue mich darauf, mit dir zu arbeiten, Hüter."
  },
  Voice_5498_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5499_AwakerVoiceContent = {Text = "Ja."},
  Voice_5499_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5500_AwakerVoiceContent = {
    Text = "Befehl empfangen."
  },
  Voice_5500_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5501_AwakerVoiceContent = {
    Text = "Hmph, respektlose, lasst mich ein wenig Spaß mit euch haben."
  },
  Voice_5501_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5502_AwakerVoiceContent = {
    Text = "Missfallen? Ein Rohr, das gerade rechtzeitig leer wird, ein verpasstes Auto, Regen bei neuen Schuhen. Im Grunde ist alles Pech nervig."
  },
  Voice_5502_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5503_AwakerVoiceContent = {
    Text = "Schraubenschlüssel, verstellbarer Schlüssel, Ringschlüssel, Schlitzschraubendreher, Kreuzschlitzschraubendreher, Senkschraube, Flachkopfschraube... Wenn es kaputte Dinge reparieren kann, mag ich es."
  },
  Voice_5503_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5504_AwakerVoiceContent = {
    Text = "Oh nein~ Du hast mich erwischt~\nEs ist in Ordnung, Erwacher haben so viele geistige Kräfte. Ich muss mindestens 365 Mal stehlen, bevor sie zu willenlosen Puppen werden~ Kann ich das nicht? Gut, ich werde beim nächsten Mal vorsichtiger sein! Nur ein kleines bisschen \"Angst\" während des Sägens, okay?"
  },
  Voice_5504_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5504_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5505_AwakerVoiceContent = {
    Text = "Hey, du weißt schon die Geheimnisse von Casiah's Magie, oder? Hmm, um sicherzustellen, dass du nicht ausplauderst, musst du mir überallhin folgen, wohin ich gehe~ Haha, denkst du, ich sammele deine Emotionen? In der Tat, nichts entgeht dir!"
  },
  Voice_5505_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5505_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5506_AwakerVoiceContent = {
    Text = "Du, sei Casiahs magische Assistentin! Hab keine Angst~ Steig einfach für einen Moment in meine magische Kiste.\n\nVersteckst du dich gut? Ich werde gleich das Schwert einsetzen~ Oh, es gibt drinnen keine Fallen~"
  },
  Voice_5506_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5506_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5507_AwakerVoiceContent = {
    Text = "Hier, setze diesen Zylinderhut auf! Dann sag mir, welches Geschenk du dir am meisten wünschst. Verstanden, ich sehe! Jetzt, greif in den Hut—"
  },
  Voice_5507_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5507_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5508_AwakerVoiceContent = {
    Text = "Ein bisschen besorgniserregend. Diese Kinder kommen zu jeder Show, und meine Vorräte schwinden... Hmm, ein Zauberer kann nicht die gleichen Tricks für dasselbe Publikum vorführen. Neue Magie erschaffen? Tut mir leid, ich habe dieses Talent nicht; ich kann nur imitieren."
  },
  Voice_5508_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5508_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5509_AwakerVoiceContent = {
    Text = "Diese Akademie ist stark renovierungsbedürftig; nur die Lounge des Direktors ist einigermaßen ansprechend. Was denkst du?"
  },
  Voice_5509_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5509_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5510_AwakerVoiceContent = {
    Text = "Diese arroganten und abscheulichen Narren werden alle zu rachsüchtigen Geistern unter meinem Befehl."
  },
  Voice_5510_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5511_AwakerVoiceContent = {
    Text = "Die Klinge der Vergeltung wird immer schärfer."
  },
  Voice_5511_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5512_AwakerVoiceContent = {
    Text = "Mein Salon ist nicht so unschuldig wie ein Ball. Bist du bereit?"
  },
  Voice_5512_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5512_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5513_AwakerVoiceContent = {
    Text = "Mein Salon ist der Boden, der Garten, wo berauschende Schönheit und Macht gedeihen werden..."
  },
  Voice_5513_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5513_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5514_AwakerVoiceContent = {
    Text = "Seidenkissen, schwarzer Tee, Makronen... Ich brauche auch frische Rosen mit Morgentau, um mein Empfangszimmer zu schmücken."
  },
  Voice_5514_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5514_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5515_AwakerVoiceContent = {
    Text = "Können wir nicht eine Ausnahme machen und den Gästen draußen den Eintritt zur Akademie erlauben?"
  },
  Voice_5515_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5515_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5516_AwakerVoiceContent = {
    Text = "Laufzeitfehler, Fehler, Fehler, Fehler..."
  },
  Voice_5516_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5517_AwakerVoiceContent = {
    Text = "Ah! Wie spät ist es?! Entschuldige, Meister... Karen sollte nicht faul sein! Aber ich bin so erschöpft..."
  },
  Voice_5517_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5518_AwakerVoiceContent = {
    Text = "Ist meine einzige Option, auf den Tod zu warten? Kann mir jemand helfen? Kann ich ihren Einfluss widerstehen? Ich fragte mich jeden Tag diese Fragen, aber die Antwort war immer in meinem Kopf—ich hatte nur nicht den Mut, mich ihr zu stellen... Hättest du nicht den Mut gefunden, zurückzukämpfen.\nD-Danke—versteh mich nicht falsch, das ist kein Geständnis oder so!"
  },
  Voice_5518_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5518_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5519_AwakerVoiceContent = {
    Text = "Ich lebe in ihren falschen Träumen, mir wurde das Recht genommen, eine gewöhnliche Person zu sein, durch eine lächerliche Prophezeiung, ohne auch nur die Freiheit zu wählen... Ich werde alles tun, um diesem Leben zu entkommen."
  },
  Voice_5519_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5519_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5520_AwakerVoiceContent = {
    Text = "\"Niedrig hängende Wasserlilien seufzen überall,\nSie regt sich gelegentlich zwischen den schlafenden Erlen;\nEin Vogel raschelt, zittert in seinem Nest,\nEin mysteriöses Lied descendiert von goldenen Sternen.\"\nAh, hast du das gehört? Entschuldigung, es ist eines meiner Lieblingsstücke... Möchtest du es mit mir lesen?"
  },
  Voice_5520_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über Lesen"
  },
  Voice_5521_AwakerVoiceContent = {
    Text = "Stürze nicht ungebeten in das Zimmer einer Dame und mache keine Kommentare zu ihrem Verhalten. Geh jetzt, ich brauche Ruhe."
  },
  Voice_5521_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5521_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5522_AwakerVoiceContent = {
    Text = "Du solltest dich besser nicht über mich erheben. Kenne deinen Platz und öffne deine Augen, um zu sehen, wer der wahre Meister ist."
  },
  Voice_5522_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5522_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5523_AwakerVoiceContent = {
    Text = "Oh, muss ich die Gegenstände anzeigen?"
  },
  Voice_5523_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5524_AwakerVoiceContent = {
    Text = "Gut gemacht. Es ist Zeit, den Sieg mit einem Fass Rum zu feiern!"
  },
  Voice_5524_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5525_AwakerVoiceContent = {
    Text = "Verschwinden."
  },
  Voice_5525_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5526_AwakerVoiceContent = {
    Text = "Überlass es mir!"
  },
  Voice_5526_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5527_AwakerVoiceContent = {
    Text = "Das Gefühl, unter meinen Füßen zerdrückt zu werden, muss absolut wundervoll sein~"
  },
  Voice_5527_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5528_AwakerVoiceContent = {
    Text = "Halt durch!"
  },
  Voice_5528_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5529_AwakerVoiceContent = {
    Text = "Neugierig auf das, was sich unter dem Augenpflaster befindet? Ich werde es dir in einem geeigneteren Rahmen zeigen, also sei nicht zu ungeduldig."
  },
  Voice_5529_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5530_AwakerVoiceContent = {
    Text = "Ist es schon vorbei? ... Meine Aufregung hatte gerade erst begonnen."
  },
  Voice_5530_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5531_AwakerVoiceContent = {
    Text = "Hey, hör auf, mit mir zu spielen. Wahre Krieger verlassen sich niemals auf externe Hilfen."
  },
  Voice_5531_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5531_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5532_AwakerVoiceContent = {
    Text = "Aigis ist stärker geworden... Ich werde diese Augen benutzen, um den Feind zu lähmen!"
  },
  Voice_5532_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5533_AwakerVoiceContent = {
    Text = "Mythag Universität ist nicht anders als das Militär. Jeder von uns steht an der Frontlinie, poliert unsere Waffen und bereitet sich auf den Kampf vor."
  },
  Voice_5533_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5534_AwakerVoiceContent = {Text = "Perfekt!"},
  Voice_5534_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5535_AwakerVoiceContent = {Text = "Perfekt!"},
  Voice_5535_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5536_AwakerVoiceContent = {
    Text = "Ich kann in Ketten gelegt werden, ich kann an den Haaren gezogen und vor dir knien, dein Sklave sein. Das ist alles kein Problem—solange ich töten darf, Bildhauer, Laternenhalter, die asthmatische alte Frau, die vorbeigeht... egal wer, ich verspreche, ich werde ihnen die Kehle aufreißen und ihr Blut trinken"
  },
  Voice_5536_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5536_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5537_AwakerVoiceContent = {
    Text = "Aus den Wunden der Auflösung fließt nicht nur schwarzer Schleim, sondern auch endlose Inspiration. Ehrlich gesagt, würde ich mich über etwas mehr freuen"
  },
  Voice_5537_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5538_AwakerVoiceContent = {
    Text = "Angst? Hahaha, genau! Zum Teufel mit allem. Ich will nur deine Angst genießen."
  },
  Voice_5538_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5538_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5539_AwakerVoiceContent = {
    Text = "Interessant, dein Blut schmeckt... süß, wie Met."
  },
  Voice_5539_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5539_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5540_AwakerVoiceContent = {
    Text = "Damals jubelten mir zehntausende zu. Das Meer, genannt \"Uvhash\", ertränkte alles und feierte, dass ich das Genick eines kahlen Schwächlings brach. Es fühlte sich unglaublich an. Als mein Kamerad musst du das verstehen."
  },
  Voice_5540_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5540_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5541_AwakerVoiceContent = {
    Text = "Warte, warte!"
  },
  Voice_5541_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5542_AwakerVoiceContent = {Text = "Nein!"},
  Voice_5542_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5543_AwakerVoiceContent = {Text = "Aua!"},
  Voice_5543_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5544_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5544_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5545_AwakerVoiceContent = {
    Text = "Suche nach \"Auflösung\" im weiten Archiv... Nicht benötigt? Du möchtest meine Stellungnahme zur Auflösung wissen? Verstanden. Suche nach \"Auflösungswaffen\" im privaten Bereich des Erwachens... Ergebnis: \"0\"."
  },
  Voice_5545_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5546_AwakerVoiceContent = {
    Text = "Falsche Objekte, so zerbrechlich wie Staub, können durch eine bloße Brise weggeblasen werden..."
  },
  Voice_5546_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Murphy"
  },
  Voice_5546_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_5547_AwakerVoiceContent = {
    Text = "Ein bisschen laut, sind das Studenten?\nSie erinnern mich an Wanderalbatrosse. Kennst du diese Vögel? Endlose Energie, Reisen, die scheinbar nie enden..."
  },
  Voice_5547_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5548_AwakerVoiceContent = {Text = "Ha"},
  Voice_5548_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5549_AwakerVoiceContent = {Text = "Hmph"},
  Voice_5549_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5550_AwakerVoiceContent = {
    Text = "Ramona ist hier die Einzige, die interessant ist, talentiert im Schwertkampf. Der Rest ist alles starr... Bist du einer von ihnen? Findest du das Schreiben von Missionsberichten wirklich lustig?"
  },
  Voice_5550_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5551_AwakerVoiceContent = {
    Text = "Nicht der Rede wert."
  },
  Voice_5551_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5552_AwakerVoiceContent = {
    Text = "Mütter sind nicht alle gleich. Einige sind gut, und einige sind schlecht.\nDie Meisterin ist eine gute Mutter."
  },
  Voice_5552_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5552_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5553_AwakerVoiceContent = {
    Text = "Es tut mir leid, dass ich dich nicht beschützen konnte..."
  },
  Voice_5553_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5554_AwakerVoiceContent = {
    Text = "Hast du den Veranstaltungsort gebucht? Es muss ein Garten größer als 150 Quadratmeter sein!"
  },
  Voice_5554_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5554_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5555_AwakerVoiceContent = {
    Text = "Das Blut der Sterbenden ist eine glitschige Flüssigkeit. Mit nur einem leichten Schnitt am Hals fließt das Blut zwischen den Zähnen hindurch und verwandelt sich in warme Ströme, die langsam meinen Bauch füllen... Heh, köstlich."
  },
  Voice_5555_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Blut"
  },
  Voice_5556_AwakerVoiceContent = {Text = "Ah"},
  Voice_5556_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_5557_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5557_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_5558_AwakerVoiceContent = {Text = "Hey"},
  Voice_5558_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_5559_AwakerVoiceContent = {
    Text = "Danke für deine Freundlichkeit, mir Unterschlupf zu gewähren. Ich hoffe, ich bringe kein tragisches Schicksal über dich..."
  },
  Voice_5559_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5560_AwakerVoiceContent = {
    Text = "Ich komme von einem fernen fremden Planeten, einem Ort unbarmherziger Schneestürme und extremen Kälte. Aber es ist in Ordnung; in meinem Herrenhaus bieten über tausend Diener durch ihre Nähe beruhigende Wärme."
  },
  Voice_5560_AwakerVoiceTitle = {
    Text = "Idle Talk·Über die Vergangenheit"
  },
  Voice_5561_AwakerVoiceContent = {
    Text = "Ich kann hier nicht fallen, bevor du zurückkommst."
  },
  Voice_5561_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5562_AwakerVoiceContent = {
    Text = "Ich kann hier nicht fallen, bevor du zurückkommst."
  },
  Voice_5562_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5563_AwakerVoiceContent = {
    Text = "Oh, wie kann es einen so arroganten Gast auf der Welt geben, der \"die mächtigste Waffe der Welt\" verlangt? Ich habe ihm gesagt, dass es einen Kopf, der in Hass getränkt ist, kosten würde, um sie zu erhalten, und er ist schmollend weggegangen..."
  },
  Voice_5563_AwakerVoiceTitle = {
    Text = "Chat·Über Goliath"
  },
  Voice_5563_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Goliath“ wird freigeschaltet"
  },
  Voice_5564_AwakerVoiceContent = {
    Text = "Ihr selbstsicherer Blick, als ob Sie immer bereit wären, die \"Welt zu retten\", lässt meine Gelenke schon beim Hinschauen jucken."
  },
  Voice_5564_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5564_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5565_AwakerVoiceContent = {
    Text = "Gerade bevor das Forschungsverbot verhängt wurde, stand ich kurz davor, die Auslöschung dieses sogenannten Auflösungsheims zuzulassen... Was für eine Schande."
  },
  Voice_5565_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5565_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5566_AwakerVoiceContent = {
    Text = "Ja, ich habe unzählige Körper und Fluchten vor der Auflösung. Aber ich strebte nach Wahrheit, und ich bereue es nicht"
  },
  Voice_5566_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5566_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5567_AwakerVoiceContent = {
    Text = "Die Wahrheit der Welt, ihr Anfang und ihr Ende – alles bedeutungslos. Wenn du den Weg zur Wahrheit beschreiten möchtest, macht es mir nichts aus, dein Führer zu sein... genau wie zuvor."
  },
  Voice_5567_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5567_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5568_AwakerVoiceContent = {
    Text = "Möglicherweise kannst du mich aufhalten, aber das Ende ist unvermeidlich... Ich werde diese Schule — und dich — als Letztes retten. Gemeinsam werden wir im Zwielicht der Zeit oben auf dem Turm baden und den Untergang der Zivilisation miterleben... Was denkst du? So wird unser Band nicht vergeblich gewesen sein, oder?"
  },
  Voice_5568_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5568_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5569_AwakerVoiceContent = {Text = "Alright."},
  Voice_5569_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5570_AwakerVoiceContent = {
    Text = "Verschwinden."
  },
  Voice_5570_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5571_AwakerVoiceContent = {
    Text = "Möge mein Gebet die Morgenläute sein, die das Heimatland weckt..."
  },
  Voice_5571_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5572_AwakerVoiceContent = {
    Text = "Ich hätte nie gedacht, dass jemand außer Tinktur mich akzeptieren würde. Ich bin froh, dich getroffen zu haben, Hüter. Ich werde mein Bestes tun, um zu lernen, wie ich meine Kraft kontrolliere, damit ich, wenn ich dich umarme, nicht deine Lebensenergie entziehe... Eine Umarmung, oder? Der menschliche Weg, Dankbarkeit auszudrücken?"
  },
  Voice_5572_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5572_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5573_AwakerVoiceContent = {
    Text = "Wenn ich hier bleibe, muss ich dann nichts bezahlen? Ich kann dir helfen, hier Ansehen zu erlangen. Drohe einfach, deren Leben zu entziehen – es ist einfach, so wie ich es für Tinktur gemacht habe... Ah! Erzähl niemandem davon!"
  },
  Voice_5573_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5573_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5574_AwakerVoiceContent = {
    Text = "Entschuldigung, ich bin nicht wie die anderen... ich bin fehlerhaft."
  },
  Voice_5574_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5574_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5575_AwakerVoiceContent = {
    Text = "Eine geschickte Dienstmagd kann den Salon erheblich aufwerten, aber eine bläulich-grüne Dienstmagd... lass mich das überdenken..."
  },
  Voice_5575_AwakerVoiceTitle = {
    Text = "Chat·Über Karen"
  },
  Voice_5575_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Karen“ wird freigeschaltet"
  },
  Voice_5576_AwakerVoiceContent = {
    Text = "Tinktur ist meine Zwillingsschwester. Im Gegensatz zu mir strahlt sie immer hell...\nOhne meine Belastung hätte sie eine hellere Zukunft, ihr Gesang hallt durch die Galaxie..."
  },
  Voice_5576_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5576_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5577_AwakerVoiceContent = {
    Text = "Die Wiege ist eng, es gibt keinen Platz, um meinen Körper zu strecken... Aber Tinktur sagte, dass ich zu meinem eigenen Schutz in der Wiege bleiben sollte... Da dies ihr Wunsch ist, werde ich gehorchen."
  },
  Voice_5577_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5577_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5578_AwakerVoiceContent = {
    Text = "Ich fühle oft, als würde ich im Zwiespalt zwischen Leben und Tod existieren. Wo immer ich bin, breitet sich Melancholie wie eine Flut aus, und Tragödien entfalten sich eins nach dem anderen. Dennoch, würdest du immer noch wollen, dass ich dir ein Gedicht schreibe? Hmm... vielleicht verdienst du das süßeste..."
  },
  Voice_5578_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5578_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5579_AwakerVoiceContent = {
    Text = "\"Die Rosen sind noch nicht verblüht, aber die Dämmerung naht.\""
  },
  Voice_5579_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5579_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5580_AwakerVoiceContent = {
    Text = "Wonach sehnst du dich? Ist es die Schönheit eleganter Worte, der weit verbreitete Ruhm, oder die aufrichtige Herzlichkeit hinter diesen Worten?"
  },
  Voice_5580_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5580_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5581_AwakerVoiceContent = {
    Text = "Mit unsichtbarer Tinte skizziere die deformierten Knospen... Dieser geisterhafte und ätherische Rosenzweig kann tatsächlich poetische Inspiration wecken..."
  },
  Voice_5581_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5581_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_55825_AwakerVoiceContent = {
    Text = "Höre meines Herren."
  },
  Voice_55825_AwakerVoiceTitle = {
    Text = "Wecken · II"
  },
  Voice_55826_AwakerVoiceContent = {
    Text = "Opfer! Gestalte das Gottesreich neu—"
  },
  Voice_55826_AwakerVoiceTitle = {Text = "Wecken III"},
  Voice_5582_AwakerVoiceContent = {
    Text = "Wenn du darauf bestehst, werde ich wieder ins Sonnenlicht treten... das gleiche Sonnenlicht wie an dem Tag, an dem ich Cité verlassen habe..."
  },
  Voice_5582_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5582_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5583_AwakerVoiceContent = {
    Text = "Hehe, möchtest du das Universum im Untergang sehen? Eh, es ist zu spät, um jetzt zurückzuweichen!"
  },
  Voice_5583_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5583_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5584_AwakerVoiceContent = {
    Text = "Trink, den süßen Geschmack des Todes."
  },
  Voice_5584_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5585_AwakerVoiceContent = {
    Text = "Trink, den süßen Geschmack des Todes."
  },
  Voice_5585_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5586_AwakerVoiceContent = {
    Text = "Das ist genug!"
  },
  Voice_5586_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5587_AwakerVoiceContent = {Text = "Nein..."},
  Voice_5587_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5588_AwakerVoiceContent = {
    Text = "Sieh die Majestät von Yu."
  },
  Voice_5588_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5589_AwakerVoiceContent = {
    Text = "Die Luft auf dem Campus um 4 Uhr morgens ist erfrischend. Ich bin froh, dass du bereit bist, mit mir zu trainieren. Ich muss sagen, das Formen ist ein ziemlich gutes Workout."
  },
  Voice_5589_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über den Morgen"
  },
  Voice_5590_AwakerVoiceContent = {
    Text = "Diese Kraft fühlt sich ziemlich gut an, sie zu nutzen."
  },
  Voice_5590_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5590_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5591_AwakerVoiceContent = {
    Text = "Ich hasse Menschen, die nicht für das bezahlen, was sie kaufen. Wenn du lange genug einen Laden führst, wirst du mit dieser Art von Problemen konfrontiert werden. Ich habe keine Wahl, als es selbst zu regeln und die Rechnung wiederzubekommen~"
  },
  Voice_5591_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5592_AwakerVoiceContent = {
    Text = "Foltere langsam."
  },
  Voice_5592_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5593_AwakerVoiceContent = {
    Text = "Foltere langsam."
  },
  Voice_5593_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5594_AwakerVoiceContent = {Text = "Laden."},
  Voice_5594_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5595_AwakerVoiceContent = {Text = "Starten."},
  Voice_5595_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5596_AwakerVoiceContent = {
    Text = "Lass diesen Ort zu einem Meer der Aufregung für alle werden!"
  },
  Voice_5596_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5597_AwakerVoiceContent = {
    Text = "Was? Erwartest du, dass ich dir danke?"
  },
  Voice_5597_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5598_AwakerVoiceContent = {
    Text = "Als Tribut ist das weit davon entfernt, ausreichend zu sein... aber im Licht deiner Aufrichtigkeit werde ich es widerwillig akzeptieren."
  },
  Voice_5598_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5599_AwakerVoiceContent = {
    Text = "Hast du wirklich gedacht, das würde mich dazu bringen, dir zuzuhören?"
  },
  Voice_5599_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5600_AwakerVoiceContent = {Text = "Hah!"},
  Voice_5600_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5601_AwakerVoiceContent = {Text = "Gehe!"},
  Voice_5601_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5602_AwakerVoiceContent = {
    Text = "Undankbare Monster, Auftragsmörder und Mörder - haben sie einen Wert, den Sie anerkennen? Ungeheuer."
  },
  Voice_5602_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5602_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5603_AwakerVoiceContent = {
    Text = "Egal wie viele Kissen du stapelst, ein Lapislazuli-Thron kann nicht mit einem Federbett verglichen werden. In dieser Hinsicht gibt es etwas Lobenswertes an deinem Platz."
  },
  Voice_5603_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5604_AwakerVoiceContent = {
    Text = "Eine kleine Strafe."
  },
  Voice_5604_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5605_AwakerVoiceContent = {
    Text = "Ich hasse Einsamkeit, hasse es, mir in einer endlosen Dunkelheit Sorgen um die Gefühle anderer zu machen... Bitte verlasse mich also nicht, okay?"
  },
  Voice_5605_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5606_AwakerVoiceContent = {
    Text = "Wenn ich du wäre, würde ich alle Erwacher in Käfige sperren! Wenn verrückte Hunde einmal ausbrechen, beißen sie immer zuerst ihre Meister."
  },
  Voice_5606_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5606_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5607_AwakerVoiceContent = {
    Text = "Ich war eine Stunde zu spät zu diesem Treffen – schimpft auf diese Gutmenschen, die die Sklaverei abgeschafft haben! Jetzt gibt es niemanden mehr, der mir die Haare kämmen kann!"
  },
  Voice_5607_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5607_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5608_AwakerVoiceContent = {
    Text = "Unglaublich, mein Zuhause ist so zugrunde gegangen... Das war das große Rom! Davon musstest du gehört haben!"
  },
  Voice_5608_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5608_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5609_AwakerVoiceContent = {
    Text = "Komm schon, lass uns mit einem Sieg beginnen!"
  },
  Voice_5609_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5610_AwakerVoiceContent = {
    Text = "Das ist der Segen meines Herrn."
  },
  Voice_5610_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5611_AwakerVoiceContent = {
    Text = "Behalte dein Mitleid für dich. Ich mag es nicht und brauche niemandes Mitgefühl. Wenn du mich so weiter anblickst, kann ich mich vielleicht nicht zurückhalten, dich zu quälen... Du willst nicht, dass die Dinge außer Kontrolle geraten, oder? Also sei ein braver Junge/Mädchen, höre zu und werde gehorsam mein Gladiator."
  },
  Voice_5611_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5611_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5612_AwakerVoiceContent = {
    Text = "Sei nicht *still*, frag nicht wieder. Ich war unvorsichtig, ließ den Gladiator entkommen und ließ meine ganze Familie sterben! Genau wie das Römische Reich jetzt, zu Asche reduziert!"
  },
  Voice_5612_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5612_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5613_AwakerVoiceContent = {
    Text = "Im Vergleich zu anderen ist Nymphaea einfach eine gewöhnliche Person ohne Errungenschaften oder Wert.\nWas mich erweckte... könnten einige kleine, bescheidene Wünsche sein."
  },
  Voice_5613_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5614_AwakerVoiceContent = {
    Text = "Heute habe ich die Schulregeln wieder gebrochen, indem ich fünf Minuten zu spät zum Unterricht gekommen bin... Daher bitte ich aufrichtig um die härteste Strafe, vorzugsweise durchgeführt vom Hüter."
  },
  Voice_5614_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5615_AwakerVoiceContent = {
    Text = "Werkzeuge brauchen auch Wartung. Ein praktisches Set von Werkzeugen ist die Seele eines Mechanikers."
  },
  Voice_5615_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5615_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5616_AwakerVoiceContent = {
    Text = "(Verächtliche Ausdauer)"
  },
  Voice_5616_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5617_AwakerVoiceContent = {
    Text = "Wenn es wieder passiert, werde ich für dich eine disziplinarische Bewährung beantragen."
  },
  Voice_5617_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5618_AwakerVoiceContent = {
    Text = "Neben dem Kämpfen habe ich auch andere Aufgaben zu erledigen. Selbst im Archean Eon war ich nicht untätig... Hey, du denkst doch nicht wirklich, ich bin nur ein Grobian, der nur kämpfen kann, oder?"
  },
  Voice_5618_AwakerVoiceTitle = {
    Text = "Kleine Gespräche: Über die Arbeit"
  },
  Voice_5619_AwakerVoiceContent = {
    Text = "Wenn Menschen sich mir nähern, erinnern sie sich immer an ihre traurigsten Erinnerungen und können nicht anders, als Tränen zu vergießen. Kann jemand wie ich noch wachsen?"
  },
  Voice_5619_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5619_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5620_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5621_AwakerVoiceContent = {
    Text = "Ist das korrekt?"
  },
  Voice_5621_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5622_AwakerVoiceContent = {
    Text = "Dieser Ort ist viel besser als das schmutzige, stinkende Neue Tor Gefängnis! Egal, ob man auf dem Sofa liegt oder sich in eine Ecke quetscht, es ist alles ziemlich bequem, nicht wahr?"
  },
  Voice_5622_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5623_AwakerVoiceContent = {Text = "Brown...!"},
  Voice_5623_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5624_AwakerVoiceContent = {
    Text = "Schale, wo ist sie hin"
  },
  Voice_5624_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5625_AwakerVoiceContent = {Text = "Listig!"},
  Voice_5625_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5626_AwakerVoiceContent = {
    Text = "Wo ist die Spiralschale hin?!"
  },
  Voice_5626_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5627_AwakerVoiceContent = {
    Text = "Die fließende Milchstraße..."
  },
  Voice_5627_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5628_AwakerVoiceContent = {
    Text = "Aurita mag es nicht, dass Freunde plötzlich gehen... Aber wenn sie zurückkommen, wird Aurita ihnen vergeben!"
  },
  Voice_5628_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5629_AwakerVoiceContent = {
    Text = "Eine Frau, die alleine über das Meer segelt, ist entweder eine Göttin oder eine Wahnsinnige. Miryam für eine Göttin zu halten, war ein schwerer Fehler."
  },
  Voice_5629_AwakerVoiceTitle = {
    Text = "Chat·Über Miryam"
  },
  Voice_5629_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Miryam“ wird freigeschaltet"
  },
  Voice_5630_AwakerVoiceContent = {Text = "...Okay!"},
  Voice_5630_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_56313_AwakerVoiceContent = {
    Text = "Ich habe heimlich die Magie von Miss Casiah beobachtet. Ihre Darbietung brachte Freude zum Publikum, aber ich bringe immer Traurigkeit... Glauben Sie, dass Tränen und Lächeln gleich wertvoll sind? Vielleicht..."
  },
  Voice_56313_AwakerVoiceTitle = {
    Text = "Chat·Über Casiah"
  },
  Voice_56313_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Casiah“ wird freigeschaltet"
  },
  Voice_56314_AwakerVoiceContent = {
    Text = "Poesie, Flammen und Trauer sind ähnlich; sie verschlingen dich ohne Vorwarnung... Als du wieder zu dir kommst, bist du bereits in die Welt der Poesie eingetaucht..."
  },
  Voice_56314_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_56315_AwakerVoiceContent = {
    Text = "Lasst die Gedichte der Vergangenheit den verborgenen Garten in deinem Herzen erwecken."
  },
  Voice_56315_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_56316_AwakerVoiceContent = {
    Text = "Poesie und Blumen sind wahrscheinlich das Gleiche, oder nicht? Beides ist vergänglich und doch ewig. In dieser grenzenlosen Welt fangen sie die unvergesslichsten Momente in einem kleinen Raum ein... Ich denke, jeder ist für ein Gedicht still geworden, so wie man inne hält, um die Blüte einer Blume zu bewundern."
  },
  Voice_56316_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Poesie"
  },
  Voice_56317_AwakerVoiceContent = {
    Text = "Ich hätte es fast vergessen... Welche Art von Blumen blüht in dieser Saison in Cité?"
  },
  Voice_56317_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Cité"
  },
  Voice_56318_AwakerVoiceContent = {
    Text = "Deine Anwesenheit hat die Tinte in meinem Stift neu entfacht, sodass sie erneut wie ein sanfter Strom fließen kann. Ich werde weiterhin Gedichte für deine Geschichte schreiben."
  },
  Voice_56318_AwakerVoiceTitle = {
    Text = "Idle Talk: Über den Hüter 1"
  },
  Voice_56319_AwakerVoiceContent = {
    Text = "Die Schönheit der blühenden Blumen wird durch die Traurigkeit ihres Verblühens übertroffen. Egal wie oft ich Kummer empfinde, kann ich nicht anders, als innezuhalten und um sie zu trauern. Wenn ich sie aus Angst vor Schmerz ignorieren würde, wie traurig wären diese Blumen..."
  },
  Voice_56319_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über Leiden"
  },
  Voice_5631_AwakerVoiceContent = {
    Text = "Um die interne Struktur dieses Körpers zu erforschen, während Erica \"schläft\", bat Winkle darum, dass ich nachts in ihrem Büro ausruhe.\nSollte ich erwähnen, dass Erica einen Teil ihres Bewusstseins im Schlaf behält?"
  },
  Voice_5631_AwakerVoiceTitle = {
    Text = "Chat·Über Zwinkern"
  },
  Voice_5631_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Zwinkern“ wird freigeschaltet"
  },
  Voice_56320_AwakerVoiceContent = {
    Text = "Die Rote Dame ist wahrhaft schön. Ihre Stärke und ihr Selbstbewusstsein, ihr anmutiges Lächeln angesichts des Schicksals und ihre lebendige, aber entschlossene Lebensenergie machen mich neidisch"
  },
  Voice_56320_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Sorel"
  },
  Voice_56320_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Sorel“"
  },
  Voice_56321_AwakerVoiceContent = {
    Text = "Ich habe gestern ein neues Gedicht geschrieben, aber es noch niemandem gezeigt. Es ist nicht sehr gut, aber... Hüter, würdest du bereit sein, einen Blick darauf zu werfen?"
  },
  Voice_56321_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über den Hüter 2"
  },
  Voice_56322_AwakerVoiceContent = {
    Text = "Der Studentenpoesieclub möchte, dass ich ihr Berater werde... Ich kann nicht zustimmen. Ich möchte ihre Stimmung nicht dämpfen, aber ich würde ihnen nur Enttäuschung und Entmutigung bringen."
  },
  Voice_56322_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_56323_AwakerVoiceContent = {
    Text = "Es gibt in dieser Welt nichts zu hassen. Die goldenen Jahre verdienen Lob, während der Verfall des Alters Mitleid erfordert; der Glanz der Jugend ist bewundernswert, während zerfledderte Reste Reflexion hervorrufen."
  },
  Voice_56323_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_56324_AwakerVoiceContent = {
    Text = "Jedes Mal, wenn ich Fräulein Nymphaea sehe, denke ich an das Bild von Wasserlilien. Sie trägt die ruhige Bitterkeit und den Duft der Wasserlilien... Ich frage mich, wie ihre Welt aussieht?"
  },
  Voice_56324_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Nymphaea"
  },
  Voice_56324_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Nymphaea“ wird freigeschaltet"
  },
  Voice_56325_AwakerVoiceContent = {
    Text = "Ich habe immer die Präsenz von \"Geistern\" um mich herum gespürt, wie eine unerklärliche Besessenheit oder Verzauberung, die meine Hoffnung auf die Welt raubt. Aber wenn es ein Geist ist, wie erklärt man dann, dass Milch und Wasser in Luft verschwinden...?"
  },
  Voice_56325_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Geister"
  },
  Voice_56326_AwakerVoiceContent = {
    Text = "Mein Körper wurde nicht von Auflösung betroffen; diese schwarzen Flüssigkeiten sind nur Tinte. Aber ehrlich gesagt, selbst ohne Auflösung wird alles schließlich zur Illusion, nicht wahr?"
  },
  Voice_56326_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_56327_AwakerVoiceContent = {
    Text = "Auf dem Grabstein des Schlüsselgrabes sah ich den Namen des Hüters... Die Erinnerungen an das Leben waren schmerzhaft, aber ich hatte nie die Absicht, sie zu vergessen. Für den Hüter müssen diese verlorenen Erinnerungen ebenso kostbar sein, oder?"
  },
  Voice_56327_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Erinnerung"
  },
  Voice_56328_AwakerVoiceContent = {
    Text = "Wenn Poesie existiert, um Schönheit zu preisen, dann ist ihre Existenz wie Poesie selbst. Wenn sie zu singen beginnt, verstehe ich plötzlich, was die Ältesten als die Stimme einer Nachtigall beschrieben haben..."
  },
  Voice_56328_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über Tinktur"
  },
  Voice_56328_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Tinktur“ wird freigeschaltet"
  },
  Voice_56329_AwakerVoiceContent = {
    Text = "Die schöne Tänzerin... Ihre smaragdgrünen Flammen sind unwiderstehlich, selbst wenn sie einen zu Asche verbrennen..."
  },
  Voice_56329_AwakerVoiceTitle = {
    Text = "Kleine Gespräche: Über Liz"
  },
  Voice_56329_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Liz“"
  },
  Voice_5632_AwakerVoiceContent = {
    Text = "Ersetze die Absorption der uranfänglichen Essenz auf diese Weise?"
  },
  Voice_5632_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5633_AwakerVoiceContent = {
    Text = "Köstlich, absolut köstlich."
  },
  Voice_5633_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5634_AwakerVoiceContent = {
    Text = "Gast, welche Art von Belohnung möchtest du?"
  },
  Voice_5634_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5635_AwakerVoiceContent = {
    Text = "Beeile dich und mach fertig. Bleib nicht auf der Straße hängen."
  },
  Voice_5635_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5636_AwakerVoiceContent = {
    Text = "Unvermeidliches Opfer"
  },
  Voice_5636_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5637_AwakerVoiceContent = {
    Text = "(Ein unterdrücktes Stöhnen der Ausdauer)"
  },
  Voice_5637_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_56386_AwakerVoiceContent = {
    Text = "Aktuelle Eingabe vollständig. Aktuelle Ausstrahlung."
  },
  Voice_56386_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_56387_AwakerVoiceContent = {
    Text = "Unterschätze den besten Straßenräuber nicht!"
  },
  Voice_56387_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_56388_AwakerVoiceContent = {
    Text = "Hier kommt die Eröffnungs-Huldigung!"
  },
  Voice_56388_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_56389_AwakerVoiceContent = {
    Text = "Die tausend Illusionen erscheinen hier!"
  },
  Voice_56389_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_5638_AwakerVoiceContent = {
    Text = "Komm näher..."
  },
  Voice_5638_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5638_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_56390_AwakerVoiceContent = {
    Text = "Sink and burn! Tanz zur Zerstörung!"
  },
  Voice_56390_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_56391_AwakerVoiceContent = {
    Text = "Das ist die Stadt, in der unzählige verlorene Seelen umhergeistern und ihren Weg nach Hause nicht finden können."
  },
  Voice_56391_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_56392_AwakerVoiceContent = {
    Text = "Lass mich dir meine verbleibende Transferenergie geben...!"
  },
  Voice_56392_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_56393_AwakerVoiceContent = {
    Text = "Unterschätze den besten Straßenräuber nicht!"
  },
  Voice_56393_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_5639_AwakerVoiceContent = {
    Text = [[
Ist es ein Feind? Bitte gib mir den Angriffsbefehl.
Der schwarze Schleim ist ein Feind... Ist Lily auch ein Feind?]]
  },
  Voice_5639_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5640_AwakerVoiceContent = {
    Text = "Erica der Automat, Torso Nr. EA307881, Motor Nr. MF311028. Freut sich, zu Ihrer Verfügung zu stehen."
  },
  Voice_5640_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5641_AwakerVoiceContent = {
    Text = "Kämpfe mit all deiner Kraft, bis der Feind vollständig besiegt ist!"
  },
  Voice_5641_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5642_AwakerVoiceContent = {
    Text = "Hallo, ich bin... Kannst du mir meinen Namen sagen?"
  },
  Voice_5642_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5643_AwakerVoiceContent = {
    Text = "Nachdem ich zur Schule gekommen war, verstand ich die Krankheit namens Auflösung, die mich befallen hatte. Meine Eltern hielten mich immer vom Ozean fern, als ich lebte, und jetzt scheint es, dass diese Infektion möglicherweise tatsächlich mit meiner Nähe zum Meer verbunden ist..."
  },
  Voice_5643_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5644_AwakerVoiceContent = {
    Text = "In Ordnung, ich werde dich nicht \"enttäuschen.\""
  },
  Voice_5644_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5645_AwakerVoiceContent = {
    Text = "Dieser sengende Atem—"
  },
  Voice_5645_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5646_AwakerVoiceContent = {Text = "Gehe."},
  Voice_5646_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5647_AwakerVoiceContent = {
    Text = "Drehe dich."
  },
  Voice_5647_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5648_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5648_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5650_AwakerVoiceContent = {
    Text = "Der Tag ist endlich gekommen..."
  },
  Voice_5650_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5651_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5651_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5652_AwakerVoiceContent = {
    Text = "Ich bin noch nicht fertig... Wie wäre es, wenn du aufstehst, damit ich dich erneut töten kann?"
  },
  Voice_5652_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5654_AwakerVoiceContent = {
    Text = "Hüter, ich muss mit dir sprechen. Bevor wir den endgültigen Sieg erreichen, sollten manche Menschen nicht so extravagant sein. Denk daran, ich kämpfe nicht für das luxuriöse Leben solcher Menschen."
  },
  Voice_5654_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Sorel"
  },
  Voice_5654_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Sorel“"
  },
  Voice_5655_AwakerVoiceContent = {
    Text = "Wenn ich als Kriegsgefangener weggenommen werde, welches grausame Schicksal erwartet mich?"
  },
  Voice_5655_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5656_AwakerVoiceContent = {
    Text = "Beobachte das!"
  },
  Voice_5656_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5657_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5657_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5658_AwakerVoiceContent = {
    Text = "Puh—so schläfrig. Bevor wir uns ausruhen, hast du irgendwelche Erfrischungen zur Entspannung vorbereitet?"
  },
  Voice_5658_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5659_AwakerVoiceContent = {
    Text = "Mutter, möchtest du sie berühren? Sie sollen sehr weich sein."
  },
  Voice_5659_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5659_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5660_AwakerVoiceContent = {
    Text = "Hmm hmm hmm, la la la~ Reinigen, reinigen, ich liebe es zu reinigen, fühle mich großartig~"
  },
  Voice_5660_AwakerVoiceTitle = {
    Text = "Kleine Gespräche: Über die Arbeit"
  },
  Voice_5661_AwakerVoiceContent = {
    Text = "(Stöhnen vor Schmerz)"
  },
  Voice_5661_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5662_AwakerVoiceContent = {
    Text = "Hmm... Nicht schlecht."
  },
  Voice_5662_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5663_AwakerVoiceContent = {
    Text = "(Stöhnen vor Schmerz)"
  },
  Voice_5663_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5664_AwakerVoiceContent = {
    Text = "(Stöhnen vor Schmerz)"
  },
  Voice_5664_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5665_AwakerVoiceContent = {
    Text = "Brennende Wut!"
  },
  Voice_5665_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_5666_AwakerVoiceContent = {
    Text = "Ich habe viele gesehen, die durch die Auflösung verrückt wurden. Ehrlich gesagt, ich bin schon verrückt genug. Die Auflösung wird mich nicht beeinflussen."
  },
  Voice_5666_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5667_AwakerVoiceContent = {
    Text = "Heh~ Hahaha!"
  },
  Voice_5667_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5668_AwakerVoiceContent = {
    Text = "Gute Werkzeuge sind die halbe Miete!"
  },
  Voice_5668_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5669_AwakerVoiceContent = {
    Text = "Fühlt sich an, als würde man wieder zum Leben erwachen."
  },
  Voice_5669_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5670_AwakerVoiceContent = {
    Text = "Überhaupt nicht schlecht."
  },
  Voice_5670_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5671_AwakerVoiceContent = {
    Text = "Jetzt kann ich mit größerer Kraft schwingen."
  },
  Voice_5671_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5672_AwakerVoiceContent = {
    Text = "Die Teilnahme auszubalancieren, den Forschungsfortschritt aufrechtzuerhalten und Lehraufgaben abzuschließen. Es scheint, dass das Experiment zur Rückwärtszeitkompression priorisiert werden muss."
  },
  Voice_5672_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5672_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5673_AwakerVoiceContent = {
    Text = "Einen Schritt näher zum offiziellen Abenteuer."
  },
  Voice_5673_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5674_AwakerVoiceContent = {
    Text = "Lass niemanden in die Nähe des Wassers, sonst könnte die Flamme deiner Liebe erlöschen!"
  },
  Voice_5674_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5675_AwakerVoiceContent = {
    Text = "Kämpfen bis zum Ende!"
  },
  Voice_5675_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5676_AwakerVoiceContent = {
    Text = "Du hast wirklich bemerkenswerte Courage. Schau dir diese Tentakeln an – hast du keine Angst, vom Wahn verschlungen zu werden?"
  },
  Voice_5676_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5676_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5677_AwakerVoiceContent = {Text = "Aua!"},
  Voice_5677_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5678_AwakerVoiceContent = {Text = "Autsch..."},
  Voice_5678_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5679_AwakerVoiceContent = {
    Text = "Bitte stoppen Sie!"
  },
  Voice_5679_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5680_AwakerVoiceContent = {
    Text = "Möchtest du es berühren? Mein Herz schlägt wegen deiner Anwesenheit."
  },
  Voice_5680_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5680_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5681_AwakerVoiceContent = {
    Text = "Sie zwitschern fröhlich. Danke, Meister."
  },
  Voice_5681_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5681_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5682_AwakerVoiceContent = {
    Text = "Etwas erwacht in meiner Brust... warm und sanft. Lily, Lilys Tränen sind fast...\nMutter, lass uns gemeinsam feiern."
  },
  Voice_5682_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5682_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5683_AwakerVoiceContent = {
    Text = "Mit meiner Mutter zusammen zu sein, erfüllt mich mit einem Gefühl des Glücks."
  },
  Voice_5683_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5683_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5684_AwakerVoiceContent = {
    Text = "Ich bin voll... Mein Magen ist voll.\nWird Lily nach dem Ritual stärker werden?"
  },
  Voice_5684_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5684_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5685_AwakerVoiceContent = {
    Text = "Ich liebe das Meer. Ist das ironisch? Denn alles, was ich besaß, ist jetzt im Aequor versunken..."
  },
  Voice_5685_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5686_AwakerVoiceContent = {
    Text = "Sei vorsichtig!"
  },
  Voice_5686_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5687_AwakerVoiceContent = {
    Text = "Dinge, die ich hasse...? Keins. Würdest du einen Staubkorn oder ein Blatt hassen?"
  },
  Voice_5687_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5688_AwakerVoiceContent = {
    Text = "Ich habe die Einladungen zur Maidensitzung mehrere Male abgelehnt. Sie schien ein wenig niedergeschlagen... Aber im Vergleich zu Spaß ist die Sicherheit des Meisters weit wichtiger!"
  },
  Voice_5688_AwakerVoiceTitle = {
    Text = "Chat·Über Karen"
  },
  Voice_5688_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Karen“ wird freigeschaltet"
  },
  Voice_5689_AwakerVoiceContent = {
    Text = "Der Lord ist der Grund für die Existenz eines Ritters, also fühle dich frei, mir Befehle zu geben!"
  },
  Voice_5689_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5690_AwakerVoiceContent = {
    Text = "...Wir könnten dazu einen Drehmomentschlüssel brauchen... Hmm, Entschuldigung, hast du mich gerade gerufen?"
  },
  Voice_5690_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5691_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5692_AwakerVoiceContent = {
    Text = "Wie wagst du es!"
  },
  Voice_5692_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5693_AwakerVoiceContent = {
    Text = "(Elegantes Summen)"
  },
  Voice_5693_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5694_AwakerVoiceContent = {
    Text = "(Ein unterdrücktes Stöhnen der Ausdauer)"
  },
  Voice_5694_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5695_AwakerVoiceContent = {
    Text = "Das ist genug."
  },
  Voice_5695_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5696_AwakerVoiceContent = {Text = "Sei sanft."},
  Voice_5696_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5697_AwakerVoiceContent = {
    Text = "Es ist wirklich immer noch schwer, den Geist zu fokussieren..."
  },
  Voice_5697_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5698_AwakerVoiceContent = {
    Text = "Sie bleibt nachts oft in meiner Nähe. Liegt es einfach daran, dass mein Kopf zu auffällig ist?"
  },
  Voice_5698_AwakerVoiceTitle = {
    Text = "Chat·Über Zwinkern"
  },
  Voice_5698_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Zwinkern“ wird freigeschaltet"
  },
  Voice_5699_AwakerVoiceContent = {
    Text = "Ich habe immer auf das Kommen der Zerstörung gewartet und nie an \"Widerstand\" gedacht... Wirst du meiner oberflächlichen Seele helfen, den Abgrund zu überqueren? Selbst in einer Welt, in der ich knapp überlebt habe, schenkst du mir noch Rettung..."
  },
  Voice_5699_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5699_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5700_AwakerVoiceContent = {
    Text = "Da ich als dein Apostel erwacht bin, strebe ich nichts weiter als deinen Frieden und deine Freude an, das ist mein Wunsch... Ugh... Ah... Tatsächlich, Überleben, Überleben, Überleben, weiterleben"
  },
  Voice_5700_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5700_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5701_AwakerVoiceContent = {
    Text = "Warum sich nicht in meiner Liebe verlieren? Hast du mich nicht für die Wärme meiner Umarmung erweckt?"
  },
  Voice_5701_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5701_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5702_AwakerVoiceContent = {
    Text = "Wünschst du dir nicht, dich von Frauen unbekannter Herkunft zu distanzieren? Sehr gut, sehr gut. Der abgesetzte König von Nineveh, die Menschen von Schinar, die sich nach dem Himmel sehnen, das Mädchen, dessen Wille unter dem heiligen Baum des Euphrat genommen wurde... Wo möchtest du anfangen?"
  },
  Voice_5702_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5702_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5703_AwakerVoiceContent = {
    Text = "Warum meidest du mich immer? Bist du schüchtern? Wie süß, diese Abneigung, deinen Verlangen ins Gesicht zu sehen"
  },
  Voice_5703_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5703_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5704_AwakerVoiceContent = {
    Text = "Dieser Ort ist schrecklich, absolut schrecklich! Wie können sie es wagen, mich für den Nachmittagstee an einen Tisch zu setzen! ...Die selbstgemachten Plätzchen sind jedoch ganz gut. Schick einige nach meinem Schlafzimmer nach dem Abendessen."
  },
  Voice_5704_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5705_AwakerVoiceContent = {Text = "Heyo!"},
  Voice_5705_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5706_AwakerVoiceContent = {
    Text = "Beobachte das!"
  },
  Voice_5706_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5707_AwakerVoiceContent = {
    Text = "Auflösung... In der Akademie meines Heimatorts gibt es Aufzeichnungen, aber Karen hasst es zu lesen und hat alles vergessen!"
  },
  Voice_5707_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5708_AwakerVoiceContent = {
    Text = "Wünschst du mir, nochmals in See zu stechen? Wenn du meine vergangenen Misserfolge übersehen kannst, werde ich einen Versuch wagen."
  },
  Voice_5708_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5708_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5709_AwakerVoiceContent = {
    Text = "Unlikes? Viele—Chefs, die ihre Arbeiter lange bleiben lassen, selbstgerechte Nonnen, knurrende Mägen, Schwarzbrot mit Glassplittern..."
  },
  Voice_5709_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5710_AwakerVoiceContent = {
    Text = "Es ist ganz Aigis' Schuld... Alles ist meine Schuld..."
  },
  Voice_5710_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5711_AwakerVoiceContent = {
    Text = "Lass uns das beenden!"
  },
  Voice_5711_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5712_AwakerVoiceContent = {
    Text = "Dank der Freundlichkeit von Fräulein Hannah konnte ich am Chorproben teilnehmen. Hymnen sind ganz anders als Seemannslieder. Während meiner Zeit, in der ich das Schiff beschützte, hatte ich nie so markante Melodien gehört..."
  },
  Voice_5712_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5713_AwakerVoiceContent = {
    Text = "Wie wäre dieser Zug!"
  },
  Voice_5713_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5714_AwakerVoiceContent = {
    Text = "Wie wäre dieser Zug!"
  },
  Voice_5714_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5715_AwakerVoiceContent = {
    Text = "So gruselig~"
  },
  Voice_5715_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5716_AwakerVoiceContent = {Text = "Uhh"},
  Voice_5716_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5717_AwakerVoiceContent = {
    Text = "Hallo, mein neuer Meister! Das Menü für heute umfasst Schneckenpudding, Kröte-Eintopf und grünen Flammenwein. Wählen Sie gerne aus."
  },
  Voice_5717_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5718_AwakerVoiceContent = {
    Text = "Ist das die Form der Rückkehr zu Genesis...? Nein, es ist ein wenig anders, als ich es mir vorgestellt habe. Aber wenn ich so werden könnte, wäre das großartig."
  },
  Voice_5718_AwakerVoiceTitle = {
    Text = "Chat·Über die Aequor Blutlinie"
  },
  Voice_5718_UnlockDesc = {
    Text = "Nach dem Erwerb eines der Erwachenden: „Tulu“, „Murphy“, „Miryam“ oder „Goliath“ freischalten."
  },
  Voice_5719_AwakerVoiceContent = {
    Text = "Auf den richtigen Moment warten."
  },
  Voice_5719_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5720_AwakerVoiceContent = {
    Text = "Beobachte das!"
  },
  Voice_5720_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5721_AwakerVoiceContent = {
    Text = "Lämmer, die Barmherzigkeit Gottes wird euch erlösen."
  },
  Voice_5721_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5722_AwakerVoiceContent = {
    Text = "Lämmer, die Barmherzigkeit Gottes wird euch erlösen."
  },
  Voice_5722_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5723_AwakerVoiceContent = {Text = "Sterben!"},
  Voice_5723_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5724_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5724_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5725_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5725_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5726_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5726_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5727_AwakerVoiceContent = {
    Text = "Sie ist auch eine bedauernswerte Seele, dazu bestimmt, von dem Schicksal verwüstet zu werden. Denn wenn Er wirklich herabsteigt, wird es der Moment sein, in dem ich ihr den Tod bringe."
  },
  Voice_5727_AwakerVoiceTitle = {
    Text = "Chat·Über Miryam"
  },
  Voice_5727_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Miryam“ wird freigeschaltet"
  },
  Voice_5728_AwakerVoiceContent = {
    Text = "Lass dich mit Blut beflecken!"
  },
  Voice_5728_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5729_AwakerVoiceContent = {Text = "Rache...!"},
  Voice_5729_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5730_AwakerVoiceContent = {
    Text = "Es tut weh..."
  },
  Voice_5730_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5731_AwakerVoiceContent = {
    Text = "(Unterdrücktes Stöhnen des Schmerzes)"
  },
  Voice_5731_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5732_AwakerVoiceContent = {
    Text = "(Unterdrücktes Stöhnen des Schmerzes)"
  },
  Voice_5732_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5733_AwakerVoiceContent = {Text = "Autsch..."},
  Voice_5733_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5734_AwakerVoiceContent = {
    Text = "Möchtest du zusammen mit mir sinken?"
  },
  Voice_5734_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5735_AwakerVoiceContent = {Text = "Geh weg!"},
  Voice_5735_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5736_AwakerVoiceContent = {
    Text = "Dinge, die ich hasse... ein unordentlicher Schreibtisch, ein chaotischer Kleiderschrank, verstaubte Fensterbänke - ja, ich beschreibe dein Zimmer. Bis 7 Uhr morgens morgen möchte ich, dass es in den Zustand zurückversetzt wird, in dem es war, bevor du eingezogen bist."
  },
  Voice_5736_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5737_AwakerVoiceContent = {
    Text = "(Interesse heucheln)"
  },
  Voice_5737_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5738_AwakerVoiceContent = {
    Text = "Interessant!"
  },
  Voice_5738_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5739_AwakerVoiceContent = {
    Text = "(Schnippt verächtlich)"
  },
  Voice_5739_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5740_AwakerVoiceContent = {
    Text = "Wenn nötig, kann ich die Wiege verlassen..."
  },
  Voice_5740_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5741_AwakerVoiceContent = {
    Text = "Willst du es?"
  },
  Voice_5741_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5742_AwakerVoiceContent = {Text = "Achtung~!"},
  Voice_5742_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5743_AwakerVoiceContent = {
    Text = "Double, double, double!"
  },
  Voice_5743_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5744_AwakerVoiceContent = {
    Text = "Das erinnert mich an das erste Paar roter Tanzschuhe, das ich mit acht Jahren bekam. Ich liebe sie wirklich. Danke, Hüter."
  },
  Voice_5744_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5744_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5745_AwakerVoiceContent = {
    Text = "Freund... Meister? Oder Mutter?"
  },
  Voice_5745_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5746_AwakerVoiceContent = {
    Text = "Mein Schutz kann manchmal auch versagen..."
  },
  Voice_5746_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5747_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5747_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5748_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5748_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5749_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5749_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5750_AwakerVoiceContent = {
    Text = "Mögen? Jemand hat mich das einmal auf den Schlachtfeldern von Peloponnes gefragt... Es ist zu spät. Ich habe solche persönlichen Vorlieben längst aufgegeben."
  },
  Voice_5750_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5751_AwakerVoiceContent = {
    Text = "Pssst... Bitte lass \"sie\" nicht entdecken, dass ich stärker werde."
  },
  Voice_5751_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5752_AwakerVoiceContent = {
    Text = "\"Sie\" sagten... Sehr geschätzt."
  },
  Voice_5752_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5753_AwakerVoiceContent = {
    Text = "Uh... Was ist das?"
  },
  Voice_5753_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5754_AwakerVoiceContent = {
    Text = "Das wird mich nur näher an den Abgrund bringen."
  },
  Voice_5754_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5754_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5755_AwakerVoiceContent = {
    Text = "Du bist mein geliebter Diener. Ich weiß, dass du es Freund, Partner, Kamerad... nennst, wie auch immer es dich glücklich macht."
  },
  Voice_5755_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5756_AwakerVoiceContent = {
    Text = "Ich bekam die Antwort... Auch wenn es nicht das war, was ich erwartet hatte, erhielt ich dennoch die Antwort."
  },
  Voice_5756_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5756_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5757_AwakerVoiceContent = {
    Text = "Ist es \"Angst\"? Oder \"Trauer\"? Dein bedrückter Ausdruck ist wirklich fesselnd."
  },
  Voice_5757_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5757_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5758_AwakerVoiceContent = {
    Text = "Der Geruch von Tod und Vernichtung, so lebhaft."
  },
  Voice_5758_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5758_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5759_AwakerVoiceContent = {
    Text = "Leben hier? Ziemlich, ziemlich gut. Solange ich etwas mechanische Wissenschaft und spirituelle Forschung mit Fräulein Puppe teile, lässt sie mich die Lichter brennen."
  },
  Voice_5759_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5760_AwakerVoiceContent = {
    Text = "Ich hoffe, Jenkin und Braun genießen ihre Zeit an der Akademie. Im Vergleich zu ihrer Freiheit sind Vaters Manschettenknöpfe unbedeutend. Ich bin mir sicher, dass er eine ganze Schachtel mit Ersatz hat."
  },
  Voice_5760_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_5760_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_5761_AwakerVoiceContent = {
    Text = "Kann nicht verlassen..."
  },
  Voice_5761_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5762_AwakerVoiceContent = {
    Text = "Nachdem ich minderwertige Rassen überstiegen habe, fürchte ich solchen Einfluss nicht. Selbst wenn der Wirtskörper zerbrochen ist, wird die edle Blutlinie nicht vergehen."
  },
  Voice_5762_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5763_AwakerVoiceContent = {
    Text = "Ich verabscheue Menschen mit falschen Lächeln! Du kannst ihnen keine Emotionen stehlen!"
  },
  Voice_5763_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5764_AwakerVoiceContent = {
    Text = "Hmm? Warum sind alle still? Karen hasst die Stille. Lass mich dir eine Geschichte erzählen. Es war einmal ein Berg..."
  },
  Voice_5764_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5765_AwakerVoiceContent = {
    Text = "Lily wird die Zukunft ergreifen... Tokuli—Li!"
  },
  Voice_5765_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5766_AwakerVoiceContent = {
    Text = "Lily wird die Zukunft ergreifen... Tokuli—Li!"
  },
  Voice_5766_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5767_AwakerVoiceContent = {
    Text = "Wenn du versuchst, Seine Anwesenheit zu erkennen, werde ich deine Unhöflichkeit vorübergehend verzeihen."
  },
  Voice_5767_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5768_AwakerVoiceContent = {
    Text = "Ich möchte das nicht tun..."
  },
  Voice_5768_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5769_AwakerVoiceContent = {
    Text = "Bleib zurück!"
  },
  Voice_5769_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5770_AwakerVoiceContent = {
    Text = "Allmählich, allmählich synchronisiere ich mich mit deinem Befehlsrhythmus!"
  },
  Voice_5770_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5771_AwakerVoiceContent = {
    Text = "Kommen dem vollwertigen Ritter immer näher!"
  },
  Voice_5771_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5772_AwakerVoiceContent = {
    Text = "Danke für Ihre Beförderung, es ist mir eine Ehre"
  },
  Voice_5772_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5773_AwakerVoiceContent = {
    Text = "Das Badehaus ist ein großartiger Ort, um die Zeit zu verbringen. Das Essen ist köstlich, und sie bieten Dienstleistungen zur Muskelentspannung an. Tentiert? Baue gleich eines in der Schule!"
  },
  Voice_5773_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5774_AwakerVoiceContent = {
    Text = "Nein, geh nicht!"
  },
  Voice_5774_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5775_AwakerVoiceContent = {Text = "Bereit."},
  Voice_5775_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5776_AwakerVoiceContent = {
    Text = "(Schmerzgrunzen)"
  },
  Voice_5776_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5777_AwakerVoiceContent = {
    Text = "(Verächtliche Ausdauer)"
  },
  Voice_5777_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5778_AwakerVoiceContent = {
    Text = "(Verächtliche Ausdauer)"
  },
  Voice_5778_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5779_AwakerVoiceContent = {
    Text = "(Verächtliche Ausdauer)"
  },
  Voice_5779_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5780_AwakerVoiceContent = {
    Text = "Überlass es mir."
  },
  Voice_5780_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_57818_AwakerVoiceContent = {
    Text = "Alle, die mich beleidigen, werden den Preis zahlen!"
  },
  Voice_57818_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57819_AwakerVoiceContent = {
    Text = "Alle, die mich beleidigen, werden den Preis zahlen!"
  },
  Voice_57819_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_5781_AwakerVoiceContent = {
    Text = "Überlass es mir."
  },
  Voice_5781_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_57820_AwakerVoiceContent = {
    Text = "Niemand kann die Schritte auf dem Weg zur Heimkehr aufhalten!"
  },
  Voice_57820_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57821_AwakerVoiceContent = {
    Text = "Genieße dieses Fest des Gemetzels in vollen Zügen!"
  },
  Voice_57821_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57822_AwakerVoiceContent = {
    Text = "Niemand kann die Schritte auf dem Weg zur Heimkehr aufhalten!"
  },
  Voice_57822_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57823_AwakerVoiceContent = {
    Text = "Falsche Missionen, definierte Zukünfte... Ich werde bis zum Ende widerstehen!"
  },
  Voice_57823_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57824_AwakerVoiceContent = {
    Text = "Falsche Missionen, definierte Zukünfte... Ich werde bis zum Ende widerstehen!"
  },
  Voice_57824_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57825_AwakerVoiceContent = {
    Text = "Genieße dieses Fest des Gemetzels in vollen Zügen!"
  },
  Voice_57825_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57826_AwakerVoiceContent = {
    Text = "Beteilige dich an meinem Ritual und werde mein Samen!"
  },
  Voice_57826_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57827_AwakerVoiceContent = {
    Text = "Verräter, schmecke meine Verzweiflung und Wut!"
  },
  Voice_57827_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57828_AwakerVoiceContent = {
    Text = "Verräter, schmecke meine Verzweiflung und Wut!"
  },
  Voice_57828_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57829_AwakerVoiceContent = {
    Text = "Beteilige dich an meinem Ritual und werde mein Samen!"
  },
  Voice_57829_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_5782_AwakerVoiceContent = {
    Text = "Ich war zu schüchtern, um Aurita zu sagen, dass ich nicht so jung bin, wie sie denkt... Kannst du sie überzeugen, mich nicht mehr \"kleine Schwester\" zu nennen?"
  },
  Voice_5782_AwakerVoiceTitle = {
    Text = "Chat·Über Aurita"
  },
  Voice_5782_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Aurita“ wird freigeschaltet"
  },
  Voice_57830_AwakerVoiceContent = {
    Text = "Die lange verlorene Stadt Luoyan hat endlich ihren Schleier gelüftet."
  },
  Voice_57830_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57831_AwakerVoiceContent = {
    Text = "Die lange verlorene Stadt Luoyan hat endlich ihren Schleier gelüftet."
  },
  Voice_57831_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57832_AwakerVoiceContent = {
    Text = "Es ist Zeit, mein Versprechen zu erfüllen."
  },
  Voice_57832_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57833_AwakerVoiceContent = {
    Text = "Es ist Zeit, mein Versprechen zu erfüllen."
  },
  Voice_57833_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57834_AwakerVoiceContent = {
    Text = "Alles ist Teil Seines Plans."
  },
  Voice_57834_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57835_AwakerVoiceContent = {
    Text = "Alles ist Teil Seines Plans."
  },
  Voice_57835_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57836_AwakerVoiceContent = {
    Text = "Eine Einladung von dem Wesen der Sterne."
  },
  Voice_57836_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57837_AwakerVoiceContent = {
    Text = "Ich bin immer noch... die Farbe aus den Sternen!"
  },
  Voice_57837_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57838_AwakerVoiceContent = {
    Text = "Ich bin immer noch... die Farbe aus den Sternen!"
  },
  Voice_57838_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57839_AwakerVoiceContent = {
    Text = "Eine Einladung von dem Wesen der Sterne."
  },
  Voice_57839_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_5783_AwakerVoiceContent = {
    Text = "Tretet zurück!"
  },
  Voice_5783_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_57840_AwakerVoiceContent = {
    Text = "Alle, lasst uns gemeinsam angreifen!"
  },
  Voice_57840_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57841_AwakerVoiceContent = {
    Text = "Der Gott des unterirdischen Labyrinths spricht das Urteil über euch alle!"
  },
  Voice_57841_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57842_AwakerVoiceContent = {
    Text = "Der Gott des unterirdischen Labyrinths spricht das Urteil über euch alle!"
  },
  Voice_57842_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57843_AwakerVoiceContent = {
    Text = "Vogel, der im azurblauen Himmel schwebt, bitte höre mein Gebet."
  },
  Voice_57843_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57844_AwakerVoiceContent = {
    Text = "Vogel, der im azurblauen Himmel schwebt, bitte höre mein Gebet."
  },
  Voice_57844_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57845_AwakerVoiceContent = {
    Text = "Beweg dich nicht! Beweg dich nicht! Beweg dich nicht!"
  },
  Voice_57845_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57846_AwakerVoiceContent = {
    Text = "Zittere unter dem Helot... Verirre unter dem Helot!"
  },
  Voice_57846_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57847_AwakerVoiceContent = {
    Text = "Zittere unter dem Helot... Verirre unter dem Helot!"
  },
  Voice_57847_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57848_AwakerVoiceContent = {
    Text = "Alle, lasst uns gemeinsam angreifen!"
  },
  Voice_57848_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_57849_AwakerVoiceContent = {
    Text = "Beweg dich nicht! Beweg dich nicht! Beweg dich nicht!"
  },
  Voice_57849_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_5784_AwakerVoiceContent = {Text = "Heh heh."},
  Voice_5784_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_57850_AwakerVoiceContent = {
    Text = "Sieh! Das ist die Macht, auf die sich die Perishiten verlassen!"
  },
  Voice_57850_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_57851_AwakerVoiceContent = {
    Text = "Sieh! Das ist die Macht, auf die sich die Perishiten verlassen!"
  },
  Voice_57851_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_5785_AwakerVoiceContent = {
    Text = "Zu schwach."
  },
  Voice_5785_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5786_AwakerVoiceContent = {Text = "Ha!"},
  Voice_5786_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5787_AwakerVoiceContent = {
    Text = "Hmm... Meister scheint verärgert? Lass Karen dich mit einem lustigen Gesicht aufheitern, hehe!\nGeht es dir jetzt besser?"
  },
  Voice_5787_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5788_AwakerVoiceContent = {
    Text = "Entblöße das Wesen der Welt mit menschlicher Intelligenz...!"
  },
  Voice_5788_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5789_AwakerVoiceContent = {
    Text = "Ich traf einige beunruhigende Personen im Flur. Du musst aufgrund der Umstände vielleicht mit ihnen kooperieren, aber bleib wachsam. Das menschliche Herz ist grausamer als der Krieg, und die schlimmsten Verräte kommen oft von innen."
  },
  Voice_5789_AwakerVoiceTitle = {
    Text = "Idle Talk·Über @2"
  },
  Voice_5789_UnlockDesc = {
    Text = "Nach dem Erwerb des Erwachenden „Helot“ oder „Lily“ freischalte"
  },
  Voice_5790_AwakerVoiceContent = {
    Text = "Ihre Aufgabe ist erledigt, oder? Können Sie mit mir in die Stadt Londinium kommen... Hä? Ihre Mathe-Hausaufgaben sind noch nicht erledigt?!\nAh... Entschuldigung, ich hätte nicht erwartet, dass jemand nicht mit Analysis umgehen kann... Lassen Sie mich helfen."
  },
  Voice_5790_AwakerVoiceTitle = {
    Text = "Small Talk: Über Lernen"
  },
  Voice_5791_AwakerVoiceContent = {
    Text = "Ich schwöre dir, dass dieser Händler definitiv im Salon von Fontainebleau erschienen ist... Ich verstehe, sie ist seitdem so. Ich frage mich, wie viele Geheimnisse wir von ihr handeln können?"
  },
  Voice_5791_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Narzisse"
  },
  Voice_5791_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Daffodil“"
  },
  Voice_5792_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5792_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5793_AwakerVoiceContent = {
    Text = "Breche es nicht."
  },
  Voice_5793_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5794_AwakerVoiceContent = {
    Text = "Aurita liebt es, mit allen zu spielen! Wirst du mitmachen? Diese hier ist Jelly, jene ist Hela, und dort drüben ist Jelly... huh?"
  },
  Voice_5794_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5795_AwakerVoiceContent = {
    Text = "Schande, lass diesen Zug dich reinigen!"
  },
  Voice_5795_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5796_AwakerVoiceContent = {
    Text = "Daffodils Laden ist jetzt geöffnet. Kinder, die nicht vorbereitet sind, bitte nicht einfach hereinkommen."
  },
  Voice_5796_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5796_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5797_AwakerVoiceContent = {
    Text = "Bitte fasse meinen Hals nicht an... Nur weil du ihn nicht sehen kannst, bedeutet das nicht, dass er nicht existiert."
  },
  Voice_5797_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5798_AwakerVoiceContent = {
    Text = "Ich bewundere diejenigen mit Überzeugungen, seien es Tiere, Erwachende oder Menschen. Wenn sie geschickte Kämpfer sind, umso besser."
  },
  Voice_5798_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5799_AwakerVoiceContent = {Text = "Gehe."},
  Voice_5799_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5800_AwakerVoiceContent = {
    Text = "<Mach dir keine Sorgen!>"
  },
  Voice_5800_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5801_AwakerVoiceContent = {
    Text = "Ramona hasst es, zu verlieren... Entschuldigung, ich meine, ich mag Abschiede nicht; das ist zu traurig."
  },
  Voice_5801_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5802_AwakerVoiceContent = {
    Text = "Ich bin nicht gut im Umgang mit Klerikern. Sie sind langweilig und starr, und sie haben ihre Gürtel ihrem geliebten \"Gott\" übergeben. So schade, Mr. Salvador riecht so süß..."
  },
  Voice_5802_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Salvador"
  },
  Voice_5802_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Salvador“"
  },
  Voice_5803_AwakerVoiceContent = {
    Text = "Der Nervenkitzel des Kampfes übertrifft alles, einschließlich Sieg oder Niederlage"
  },
  Voice_5803_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5804_AwakerVoiceContent = {
    Text = "Wer liebt nicht ein weiches Bett und einen zugfreien Abfluss... Raum?"
  },
  Voice_5804_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5805_AwakerVoiceContent = {
    Text = "...Mach mich nicht dazu, mich an... die Tage in Elworth eingesperrt zu erinnern..."
  },
  Voice_5805_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5806_AwakerVoiceContent = {
    Text = "Brenne alles nieder!"
  },
  Voice_5806_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5807_AwakerVoiceContent = {
    Text = "Brenne alles nieder!"
  },
  Voice_5807_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5808_AwakerVoiceContent = {
    Text = "Ich folgte dem Geruch von Blut an diesen Ort. Darf ich fragen... bieten Sie hier frische Blutbeutel an?"
  },
  Voice_5808_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5809_AwakerVoiceContent = {
    Text = "Hmm... Agrippa hat viele Begleiter, aber sie scheinen alle Angst vor ihr zu haben. Könnte es sein, dass sie ihr Essen stiehlt?"
  },
  Voice_5809_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Agrippa"
  },
  Voice_5809_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Agrippa“"
  },
  Voice_5810_AwakerVoiceContent = {
    Text = "Mein Leben dreht sich um den Tanz. Anderes Wissen zu lernen, fällt mir schwer. Aber alle sind freundlich; sie werden mich nicht aus Eitelkeit oder Geld verraten—ich kann es spüren."
  },
  Voice_5810_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5811_AwakerVoiceContent = {
    Text = "Feigling! Du besitzt eine mächtige Kraft, die meiner ähnelt, und dennoch hältst du dich zurück. Wie unterscheidet sich das von einem freiwilligen Anlegen einer Halsbinde?"
  },
  Voice_5811_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Lily"
  },
  Voice_5811_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Lily“"
  },
  Voice_5812_AwakerVoiceContent = {
    Text = "Nicht genug... immer noch nicht genug Kraft..."
  },
  Voice_5812_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5813_AwakerVoiceContent = {Text = "Dreh um."},
  Voice_5813_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5814_AwakerVoiceContent = {Text = "Ja!"},
  Voice_5814_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5815_AwakerVoiceContent = {
    Text = "Zylinder, Bowler, Jagdhüte, Baskenmützen... Ich muss sagen, es ist ziemlich amüsant, wie ihr Herren der Oberschicht so große Anstrengungen unternehmt, um eure Glatzen zu verbergen."
  },
  Voice_5815_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Etikette"
  },
  Voice_5816_AwakerVoiceContent = {
    Text = "Ich bewundere diese Person tief, den maritimen Gott, so rein und elegant wie eine Lilie... Du sagst, selbst sie konnte ihr Schicksal nicht kontrollieren und sank letztendlich ins Meer? Es ist wirklich schwer vorstellbar..."
  },
  Voice_5816_AwakerVoiceTitle = {
    Text = "Chat·Über Celeste"
  },
  Voice_5816_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Celeste“ wird freigeschaltet"
  },
  Voice_5817_AwakerVoiceContent = {
    Text = "Es gibt nichts auf der Welt, was ein Riese nicht überwinden kann!"
  },
  Voice_5817_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5818_AwakerVoiceContent = {
    Text = "Es gibt nichts auf der Welt, was ein Riese nicht überwinden kann!"
  },
  Voice_5818_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5819_AwakerVoiceContent = {
    Text = "Verdammter, verdammter...! Macht hält mich nur in diesem Körper gefangen..."
  },
  Voice_5819_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5819_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5820_AwakerVoiceContent = {
    Text = "Ich wünsche mir, an einem Ort zu bleiben, der immer hell ist... Ja, an den Polen. Auf diesem Planeten gibt es nur die Pole."
  },
  Voice_5820_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5820_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5821_AwakerVoiceContent = {
    Text = "Ich... ich kann keine schweren Verantwortungen tragen. Ich kann nur dem Licht nachjagen. Also bitte, höre nicht auf zu strahlen..."
  },
  Voice_5821_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5821_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5822_AwakerVoiceContent = {
    Text = "Wenn ich migrieren könnte, möchte ich ein Stern werden..."
  },
  Voice_5822_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5822_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5823_AwakerVoiceContent = {
    Text = "Egal wie ich rechne, die Formel für den Bewusstseinsübergang bleibt unlösbar..."
  },
  Voice_5823_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5823_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5824_AwakerVoiceContent = {
    Text = "Willkommen! Lass uns zusammen Spaß haben!"
  },
  Voice_5824_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5825_AwakerVoiceContent = {
    Text = "Hier ist dein Essen!"
  },
  Voice_5825_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5826_AwakerVoiceContent = {
    Text = "Huch—Es ist Aurita! Eins, zwei, drei... Wow! Willkommen, willkommen! Ein neuer Partner ist dazugekommen! Hä? Ich bin der neue Partner? Naja, so könnte man sagen!"
  },
  Voice_5826_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5827_AwakerVoiceContent = {
    Text = "Du nennst dieses kleine Spielzeug eine Pistole? Nur Feiglinge verstecken sich im Schatten, um ihre Feinde zu überfallen."
  },
  Voice_5827_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5828_AwakerVoiceContent = {
    Text = "Es ist bedeutungslos. Das zu tun ist völlig sinnlos."
  },
  Voice_5828_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5829_AwakerVoiceContent = {
    Text = "Du weißt absolut nichts."
  },
  Voice_5829_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5830_AwakerVoiceContent = {
    Text = "Zählst du immer noch darauf, dass ich der \"Retter\"-Backup bin?"
  },
  Voice_5830_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5831_AwakerVoiceContent = {
    Text = "Es tut mir leid, hast du meine Schraube gesehen? Es ist komisch, aber wann immer dieses Kind mit den Mäuseohren in der Nähe ist, scheine ich zu vergessen, wo ich die Dinge hingelegt habe..."
  },
  Voice_5831_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_5831_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_5832_AwakerVoiceContent = {
    Text = "Ich werde nicht alles vergessen, was du für mein Wiedersehen mit meinem Meister geopfert hast..."
  },
  Voice_5832_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5833_AwakerVoiceContent = {
    Text = "Ein meisterhaftes Lied!"
  },
  Voice_5833_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5834_AwakerVoiceContent = {
    Text = "Hast du meinen Wunsch anerkannt?"
  },
  Voice_5834_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5835_AwakerVoiceContent = {
    Text = "Hoffe, dass dein Befehl nicht enttäuscht."
  },
  Voice_5835_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5836_AwakerVoiceContent = {
    Text = "Ist es dieser Körper oder mein Bewusstsein, das sich verbessert hat? Ein interessantes Thema."
  },
  Voice_5836_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5836_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5837_AwakerVoiceContent = {
    Text = "Rücktritt."
  },
  Voice_5837_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5838_AwakerVoiceContent = {
    Text = "Tretet zur Seite."
  },
  Voice_5838_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5839_AwakerVoiceContent = {
    Text = "Mein Blut durchströmt den Willen zu überleben, schreit und drängt mich dazu, Blut auf jeden Zoll dieses Planeten zu vergießen... Ah, ich habe zu lange geschwärmt; bitte verzeih mir. Ich bin Thais. Hast du mich beschworen? Bist du bereit, mit mir zu verschmelzen?"
  },
  Voice_5839_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5840_AwakerVoiceContent = {
    Text = "Wenn Aigis nur diese schwarze Flüssigkeit für alle ertragen könnte... Schließlich existierte Aigis nie, was vielleicht eine gute Sache für diese Welt ist, oder?"
  },
  Voice_5840_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5841_AwakerVoiceContent = {
    Text = "Hobbys umfassen die Riemannsche Hypothese - das ist das geflügelte Wort des Pfaus, nicht meins. Persönlich interessiere ich mich mehr für Atommasse-Standards."
  },
  Voice_5841_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5842_AwakerVoiceContent = {
    Text = "Der Geschmack, verbannt und auf dem Meer gestrandet zu sein... Einmal ist genug."
  },
  Voice_5842_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5844_AwakerVoiceContent = {
    Text = "Genau hinschauen!"
  },
  Voice_5844_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5845_AwakerVoiceContent = {
    Text = "Genau hinschauen!"
  },
  Voice_5845_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5846_AwakerVoiceContent = {
    Text = "Solange du diese Gerechtigkeit aufrechterhalten kannst, werde ich immer die Pflicht der Klinge übernehmen."
  },
  Voice_5846_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5847_AwakerVoiceContent = {
    Text = "Wusstest du von der Legende des \"Malers\" hier? Aus diesen expressionistischen Graffiti spüre ich eine vertraute Berührung..."
  },
  Voice_5847_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5848_AwakerVoiceContent = {
    Text = "So schmerzhaft, doch so aufregend—"
  },
  Voice_5848_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5849_AwakerVoiceContent = {
    Text = "Fühl meinen Zorn!"
  },
  Voice_5849_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5850_AwakerVoiceContent = {
    Text = "Lasst diesen Sieg in Poesie festgehalten werden."
  },
  Voice_5850_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5851_AwakerVoiceContent = {
    Text = "Wachse auf—"
  },
  Voice_5851_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5852_AwakerVoiceContent = {
    Text = "Beobachte das!"
  },
  Voice_5852_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5853_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5853_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5854_AwakerVoiceContent = {
    Text = "Vielleicht, wenn ich erwachsen bin, kann ich mich kontrollieren und anderen nicht ihr Leben entziehen... Ein kleines bisschen genügt mir zum Überleben."
  },
  Voice_5854_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5854_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5855_AwakerVoiceContent = {
    Text = "Es scheint, als ob ich schwerer geworden bin. Kann die Wiege mein Gewicht noch tragen?"
  },
  Voice_5855_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5855_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5856_AwakerVoiceContent = {
    Text = "Die Kraft steht kurz vor dem Überlaufen, und mein Rücken juckt. Werde ich erwachsen?"
  },
  Voice_5856_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_5856_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_5857_AwakerVoiceContent = {
    Text = "Obwohl ich immer noch wie ein Kind aussehe, habe ich jetzt... die Kraft, dich zu beschützen."
  },
  Voice_5857_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5857_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5858_AwakerVoiceContent = {
    Text = "Ich werde mein Bestes tun, um erwachsen zu werden."
  },
  Voice_5858_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_5858_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_5859_AwakerVoiceContent = {
    Text = "Du undankbares Ding, warum bist du so hartnäckig darin, mich zu wecken?"
  },
  Voice_5859_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5860_AwakerVoiceContent = {
    Text = "Ich werde die Mutter der Götter werden!"
  },
  Voice_5860_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5861_AwakerVoiceContent = {
    Text = "Wie oft wurde ich beschworen... Mensch, du solltest besser genug „Essen“ vorbereitet haben, sonst kann ich nichts garantieren."
  },
  Voice_5861_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5862_AwakerVoiceContent = {
    Text = "Jenseits der Tür!"
  },
  Voice_5862_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5863_AwakerVoiceContent = {Text = "Torheit."},
  Voice_5863_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5864_AwakerVoiceContent = {Text = "Haha"},
  Voice_5864_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5865_AwakerVoiceContent = {
    Text = "Hmph, nicht schlecht. Ich werde alles in unser nächstes Duell stecken."
  },
  Voice_5865_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5866_AwakerVoiceContent = {
    Text = "Du unverschämter Mensch!"
  },
  Voice_5866_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_5867_AwakerVoiceContent = {
    Text = "Manchmal liegt die Schönheit der Kunst in ihrer Vernichtung. Aber dein Versagen... fällt eindeutig nicht in diese Kategorie."
  },
  Voice_5867_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5868_AwakerVoiceContent = {
    Text = "Du bist mein wichtigster Zuhörer. Immer wenn du es brauchst, bin ich bereit zu singen und dir alles zu geben."
  },
  Voice_5868_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5869_AwakerVoiceContent = {
    Text = "Lieblingssachen? Algen, Fischschwärme, Kolonnaden, Labyrinthe... Natürlich habe ich sie gesehen! Sie sind alle im Buch von Onkel Ornn!"
  },
  Voice_5869_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5870_AwakerVoiceContent = {
    Text = "Bereitet ihr euch auf eine Ermittlungsmission vor? Ich verstehe."
  },
  Voice_5870_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5870_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5871_AwakerVoiceContent = {
    Text = "Mein Name ist Celeste. Solange du mich noch brauchst, werde ich hier sein."
  },
  Voice_5871_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5872_AwakerVoiceContent = {
    Text = "Lerne deine Lektion!"
  },
  Voice_5872_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5873_AwakerVoiceContent = {
    Text = "Zeig etwas Respekt, Junior. In der Armee wird die Dienstgradordnung respektiert, und Befehle müssen ohne Ausnahme befolgt werden. Solches unangemessenes Verhalten wird bestraft."
  },
  Voice_5873_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5874_AwakerVoiceContent = {
    Text = "Ich wäre bereit, einen After-Sales-Service für diese „kleinen Spielzeuge“ anzubieten, aber die Frage ist, wagst du es, meinen Service anzunehmen?"
  },
  Voice_5874_AwakerVoiceTitle = {
    Text = "Small Talk · Über Erfindungen"
  },
  Voice_5875_AwakerVoiceContent = {
    Text = "Du bist der Meister hier, aber auch ein Gast in meinem Salon. Ich werde die feinste Gastfreundschaft für deinen Besuch vorbereiten—bevorzugst du ein scharlachrotes Unterkleid oder einen weißroséfarbenen Nachthemd?"
  },
  Voice_5875_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5876_AwakerVoiceContent = {
    Text = "Es tut mir leid, das Sonnenlicht hier ist etwas grell... Eine Maus aus einer dunklen Höhle kann sich nicht schnell anpassen."
  },
  Voice_5876_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5877_AwakerVoiceContent = {
    Text = "Fähig, alles zu korrodieren und alles auszulöschen... Es war eine ziemlich mächtige Waffe. Hätte ich damals nur gewusst... Hah."
  },
  Voice_5877_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5878_AwakerVoiceContent = {
    Text = "Es heißt, dass Körper, die in den Flammen zucken, so erscheinen, als würden sie tanzen."
  },
  Voice_5878_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über Feuer"
  },
  Voice_5880_AwakerVoiceContent = {
    Text = "Gehe nachts nicht raus. Selbst mit einem 2000-Lumen-Licht ist es nicht ganz sicher... Sobald du in die Dunkelheit trittst, wird das Böse, das außerhalb deines Sichtfeldes lauert, dich verfolgen, dich verschlingen, dich verfolgen, dich verschlingen... bis nichts mehr übrig bleibt."
  },
  Voice_5880_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über die Nacht"
  },
  Voice_5881_AwakerVoiceContent = {Text = "Schrei."},
  Voice_5881_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5882_AwakerVoiceContent = {Text = "Erhalten."},
  Voice_5882_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5883_AwakerVoiceContent = {
    Text = "Es ist das Verlangen nach Leben, das den Schwan antreibt, um für seine Rückkehr in den fernen Himmel zu kämpfen."
  },
  Voice_5883_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5883_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5884_AwakerVoiceContent = {
    Text = "Es fängt an sich zu ändern!"
  },
  Voice_5884_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5885_AwakerVoiceContent = {Text = "Hilfe!"},
  Voice_5885_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5886_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5886_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_5887_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5887_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5888_AwakerVoiceContent = {Text = "Ah!"},
  Voice_5888_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5889_AwakerVoiceContent = {
    Text = "Ah, Braun ist weggelaufen! Ich... ich sollte mich wahrscheinlich ein bisschen zurückziehen...\nIch wollte ihr Freund sein, aber stattdessen wurde ich zu ihrem Albtraum... Sie möchte mich sowieso wahrscheinlich nicht sehen..."
  },
  Voice_5889_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_5889_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_5890_AwakerVoiceContent = {
    Text = "Kapelle? Danke, aber ich bin nicht so altmodisch. Solange ich die Lehren des Gottes der Güte in meinem Herzen bewahre und seinem Willen folge, wird meine Seele niemals von seiner Herrlichkeit abweichen."
  },
  Voice_5890_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Kapelle"
  },
  Voice_5891_AwakerVoiceContent = {
    Text = "Mein Name ist Ogier. Gemäß unserem Vertrag gelobe ich dir meine ritterliche Treue, beschütze dein Wohlbefinden und beseitige deine Feinde. Dieses Gelübde lege ich ab, um es niemals zu vergessen."
  },
  Voice_5891_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5892_AwakerVoiceContent = {
    Text = "Diese ausgemergelte Frau mit den doppelten Pupillen riecht genau wie ein Spartaner Käfer."
  },
  Voice_5892_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Agrippa"
  },
  Voice_5892_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Agrippa“"
  },
  Voice_5893_AwakerVoiceContent = {
    Text = "Mögen? Natürlich, gutes Glück. Ich suche immer nach einem guten Omen, bevor ich jeden Tag hinausgehe."
  },
  Voice_5893_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5894_AwakerVoiceContent = {
    Text = "B-Bitte sag Miss Hannah nicht, dass ich mich hier verstecke. Ich bin noch nicht bereit..."
  },
  Voice_5894_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Hannah"
  },
  Voice_5895_AwakerVoiceContent = {
    Text = "Wie wäre es damit?"
  },
  Voice_5895_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5896_AwakerVoiceContent = {
    Text = "Du bist mein geschätzter Gast. Denk daran, du bist der Einzige, der ein Guthaben führen darf. Schließlich ist es Jahre her, seit ich einen so perfekten Schädel gesehen habe..."
  },
  Voice_5896_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5897_AwakerVoiceContent = {Text = "Aua!"},
  Voice_5897_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5898_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_5898_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5899_AwakerVoiceContent = {Text = "Aua!"},
  Voice_5899_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5900_AwakerVoiceContent = {
    Text = "Mögen... Ein König sollte solche Vorlieben nicht zeigen, aber wenn ich den lästigen Gedenkfeiern und Gebeten entkommen könnte, würde ich sicherlich etwas Freizeit auf einer weichen Couch genießen."
  },
  Voice_5900_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5901_AwakerVoiceContent = {
    Text = "Ich werde deinen Mangel an Respekt als ein Flehen um ewigen Frieden ansehen."
  },
  Voice_5901_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5902_AwakerVoiceContent = {
    Text = "Hass du es? Ich hasse ein unausweichliches Schicksal und unvermeidliche Tragödie."
  },
  Voice_5902_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5903_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_5903_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5904_AwakerVoiceContent = {
    Text = "(Gedämpftes Summen)"
  },
  Voice_5904_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5905_AwakerVoiceContent = {
    Text = "Komm nicht näher!"
  },
  Voice_5905_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5906_AwakerVoiceContent = {
    Text = "Oh, neugierig auf mein Geheimnis? Dieser Name, dieser Körper, dieses Gesicht, diese Stimme—alles kommt von der Frau, die einen Kopf aus San Pedro hatte. Sie machte einen Deal mit mir... Nach ihrem Tod wurde ich sie. Was ihren Verbleib angeht... nun, das ist meine exquisiteste Sammlung, weißt du?"
  },
  Voice_5906_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5906_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5907_AwakerVoiceContent = {
    Text = "Du bist ein wunderbarer Gast; selbst ich bin von deinem einzigartigen Kopf fasziniert... Wenn du jemals darüber nachdenkst, dich davon zu trennen, komm unbedingt in meinen kleinen Laden. Haha... nur ein Scherz."
  },
  Voice_5907_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5907_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5908_AwakerVoiceContent = {
    Text = "Neugierig auf meine wahre Identität? Das ist immer noch zu früh dafür. Glaub nur dies: verlorene Kinder können ihren Weg in meinem Laden finden. Vielleicht gilt das auch für dich?"
  },
  Voice_5908_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5908_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5909_AwakerVoiceContent = {
    Text = "Niemand wird verletzt werden."
  },
  Voice_5909_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5910_AwakerVoiceContent = {
    Text = "Es ist noch nicht vorbei!"
  },
  Voice_5910_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5911_AwakerVoiceContent = {
    Text = "Als du siehst, wie hart du arbeitest, fühle ich mich fast schuldig, meine Belohnung so schnell zu kassieren. Also lasse ich deinen Kopf vorerst dort, wo er ist.\nAber vergiss nicht, dass er bereits als mein persönliches Eigentum reserviert ist, okay?"
  },
  Voice_5911_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5911_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5912_AwakerVoiceContent = {
    Text = "Ich war nicht immer so; sie gab mir ein neues Leben. In diesem Sinne hast du mir auch ein zweites Leben gegeben, also werde ich auch deinen Kopf schätzen."
  },
  Voice_5912_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5912_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5913_AwakerVoiceContent = {
    Text = "Vollständig aus der Dunkelheit entkommen."
  },
  Voice_5913_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5914_AwakerVoiceContent = {
    Text = "So abenteuerlich ist es so gefährlich..."
  },
  Voice_5914_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_5915_AwakerVoiceContent = {
    Text = "Warum rennt dieses dumme Mädchen immer weg, wenn sie mich sieht? Nächstes Mal trete ich auf ihr Garn und sehe, wohin sie gehen kann."
  },
  Voice_5915_AwakerVoiceTitle = {
    Text = "Chat·Über Aigis"
  },
  Voice_5915_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Aigis“"
  },
  Voice_5916_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_5916_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5917_AwakerVoiceContent = {
    Text = "Hmph~ Hahaha!"
  },
  Voice_5917_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5918_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_5918_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5919_AwakerVoiceContent = {
    Text = "Das Kind ist scharfsinnig; das Überleben auf der Straße erfordert so einen Verstand. Wenn ich noch draußen ermitteln würde, würde ich mich definitiv mit ihr anfreunden."
  },
  Voice_5919_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_5919_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_5920_AwakerVoiceContent = {
    Text = "Der Heilige Vater kann nicht jeden retten. Er kann vielleicht einer unglücklichen Seele helfen, aber er kann nicht jeden aus dem Morast ziehen... Ich erwarte mit Vorfreude seinen Fall, den Zusammenbruch seines Glaubens."
  },
  Voice_5920_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Salvador"
  },
  Voice_5920_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Salvador“"
  },
  Voice_5921_AwakerVoiceContent = {
    Text = "Du kannst alles in den Abwasserkanälen von Londinium finden: Lachs, Seife, halb getrunkener Whiskey... \nWas? Du fragst, warum ich das weiß? Ich habe einmal die Leiche meines Bruders durch fünf Meilen davon gezogen..."
  },
  Voice_5921_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über die Abwasserkanäle"
  },
  Voice_5922_AwakerVoiceContent = {
    Text = "Niederknien vor mir!"
  },
  Voice_5922_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5923_AwakerVoiceContent = {
    Text = "Knien Sie vor mir."
  },
  Voice_5923_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5924_AwakerVoiceContent = {
    Text = "Nachdem ich einen Blick in die reale Welt jenseits des Schlachtfeldes erhascht hatte, stellte ich einmal den Wert von „Helden“ in Frage. Aber zum Glück traf ich dich—ehrlich, mutig und rein. Unter deiner Führung werde ich unermüdlich für Frieden und Stabilität kämpfen. Dieses Mal werde ich meine Erlösung sicherlich vollenden."
  },
  Voice_5924_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5924_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5925_AwakerVoiceContent = {
    Text = "Aua! Oh nein..."
  },
  Voice_5925_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5926_AwakerVoiceContent = {
    Text = "Unrein, dreckig, chaotisch—das ist unsere Macht."
  },
  Voice_5926_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5927_AwakerVoiceContent = {
    Text = "Ich hasse deinen manieristischen Auftritt. Denkst du, ich bin verrückt und erbärmlich, oder? Für mich bist du wie Ikarus, vom Sonnenlicht geblendet. Ihr seid die wirklich erbärmlichen."
  },
  Voice_5927_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5928_AwakerVoiceContent = {
    Text = "Lass mich die Führung übernehmen!"
  },
  Voice_5928_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_5929_AwakerVoiceContent = {
    Text = "Diese Typen fühlen sich fremd an. Sie dürfen keine Lebensformen sein, die natürlich auf diesem Planeten geboren wurden."
  },
  Voice_5929_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über die Sternenfahrer"
  },
  Voice_5929_UnlockDesc = {
    Text = "Nach dem Erwerb eines der Erwachenden „Winkle“, „Tinktur“, „Ohnmacht“ oder „Wanda“ freischalten."
  },
  Voice_5931_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5931_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_5932_AwakerVoiceContent = {
    Text = "Verschwinde!"
  },
  Voice_5932_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_5933_AwakerVoiceContent = {
    Text = "Bitte nicht..."
  },
  Voice_5933_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5934_AwakerVoiceContent = {
    Text = "Ein Monster zu sein ist in Ordnung. Alles, was ich jemals gewollt habe, war die Macht zur Rache."
  },
  Voice_5934_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5934_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5935_AwakerVoiceContent = {
    Text = "Neben der Beseitigung deines Gegners, hast du noch andere Wünsche? Im Gegenzug werde ich deinen Wunsch erfüllen... innerhalb meiner Möglichkeiten, natürlich."
  },
  Voice_5935_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_5935_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_5936_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5936_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_5937_AwakerVoiceContent = {
    Text = "Ein Gefährte? ... Ich werde darüber nachdenken. Stirb nicht, bevor ich meine Entscheidung treffe."
  },
  Voice_5937_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_5937_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_5938_AwakerVoiceContent = {
    Text = "Seit es zum ersten Mal klar dokumentiert wurde, hat das D-Phänomen das Leben von mehr als einer Million Menschen beeinflusst. Unsere Handlungen sind entscheidend für das Überleben der gesamten Menschheit."
  },
  Voice_5938_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5939_AwakerVoiceContent = {Text = "Vollgas!"},
  Voice_5939_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5940_AwakerVoiceContent = {
    Text = "Hüte dich vor der Wut des Meeres"
  },
  Voice_5940_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5941_AwakerVoiceContent = {
    Text = "Hüte dich vor der Wut des Meeres"
  },
  Voice_5941_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5942_AwakerVoiceContent = {Text = "Hey!"},
  Voice_5942_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5943_AwakerVoiceContent = {
    Text = "Ich bin seine Prinzessin und seine Mutter. Was dich betrifft, du bist nur eine unbedeutende Ameise vor ihm."
  },
  Voice_5943_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5944_AwakerVoiceContent = {
    Text = "Alles ist gut, lasst uns die triumphalen Segel setzen."
  },
  Voice_5944_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_5945_AwakerVoiceContent = {
    Text = "Halt dich von mir fern! Möchtest du das Spielzeug der Prinzessin oder ein Opfer für die göttliche Geburt werden?"
  },
  Voice_5945_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5945_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_59463_AwakerVoiceContent = {
    Text = "Ein einfacher Sieg, ein voller Triumph!"
  },
  Voice_59463_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_59464_AwakerVoiceContent = {
    Text = "Ein einfacher Sieg, ein voller Triumph!"
  },
  Voice_59464_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_5946_AwakerVoiceContent = {
    Text = "Ich erlaube dir, Zeuge zu werden, diesen strahlenden Moment zu sehen, der die Ethik herausfordert."
  },
  Voice_5946_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5946_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5947_AwakerVoiceContent = {
    Text = "Hohl? Hohlräume entstehen oft während der Telekinese. Haben die Hohlräume, die von Casiah geschaffen wurden, eine Verbindung zu einer anderen Dimension, wie die in der Auflösung?"
  },
  Voice_5947_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_5948_AwakerVoiceContent = {
    Text = "Hüter, durch die Macht der Muttergöttin habe ich einen Platz für dich neben dem Thron von Aequor reserviert. Du wirst die Ära der Wiedergeburt nach der Zerstörung erleben. Freue dich, denn dies ist das Versprechen der Muttergöttin!"
  },
  Voice_5948_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5948_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5949_AwakerVoiceContent = {
    Text = "In Anerkennung deiner respektvollen Haltung werde ich dir eine Antwort geben. Am Anfang gab es tatsächlich Kämpfe. Aber jetzt verstehe ich: mein Leben in Luxus stammt von Ihm. Der Tod ist nicht das Ende; Er wird mich neu beleben und mir durch diesen verdrehten Zyklus das ewige Leben gewähren..."
  },
  Voice_5949_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5949_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5950_AwakerVoiceContent = {
    Text = "Der Wunsch dieser Frau ist lächerlich. Nichts kann die Vernichtung überleben, nicht einmal ein \"Gott\"."
  },
  Voice_5950_AwakerVoiceTitle = {
    Text = "Plaudern: Über Thais"
  },
  Voice_5950_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Thais“ wird freigeschaltet"
  },
  Voice_5951_AwakerVoiceContent = {
    Text = "Ich bin ein Praktizierender des Spiritismus, kein allmächtiges Wesen, und daher bin ich anfällig für Fehler. Die Taten dieser Frau, die alle ins Verderben gestürzt haben, waren meine unbeabsichtigten Fehler... Daher brauche ich deine Hilfe. Um sicherzustellen, dass du jederzeit auf meinen Ruf reagieren kannst, darfst du ein Bett in meinem Zimmer aufstellen."
  },
  Voice_5951_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5951_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5952_AwakerVoiceContent = {
    Text = "Du trägst die Last, dich den Clades zu stellen, ein schweres Gewicht für jemanden in deinem Alter... Hättest du von Anfang an gewusst, dass du die Zukunft nicht ändern kannst, hättest du dann deine Mission trotzdem treu erfüllt? Eile nicht mit der Antwort; denke darüber nach, während ich mich ausruhe. Ich bin neugierig auf deine Antwort."
  },
  Voice_5952_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5952_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5953_AwakerVoiceContent = {
    Text = "Es ist einige Zeit vergangen, seit ich erwacht bin. Hast du nichts, das du mich fragen möchtest? Die Offenbarungen des Gottes, die absolut wahre Prophezeiung, sogar der Schatz des versunkenen Landes – bist du nicht neugierig? \nHm... seltsamer."
  },
  Voice_5953_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5953_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5954_AwakerVoiceContent = {
    Text = "Ich habe nie von jemandem Verehrung gefordert. Der Unsinn anderer erschöpft mich nur weiter... Gib auf, es ist Zeit zu ruhen."
  },
  Voice_5954_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5954_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5955_AwakerVoiceContent = {
    Text = "Ich sehe in Ihnen keine der Eigenschaften meiner Untergebenen... Vielleicht ist das besser so. Der Gedanke an diese Frau erschöpft mich."
  },
  Voice_5955_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5955_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5956_AwakerVoiceContent = {
    Text = "Gott behandelt alle gleich."
  },
  Voice_5956_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5957_AwakerVoiceContent = {
    Text = "Ich weiß, du bist ein besonderes Publikum. Ich kann dich nicht einfach in eine andere Dimension beamen; das würde große Probleme verursachen. Hey, hast du das jemals jemand anderem angetan? Frag nicht, es ist mein Geheimnis!"
  },
  Voice_5957_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_5958_AwakerVoiceContent = {
    Text = "Eek, interessiert dich dieses Aussehen? Es scheint immer einen Preis zu geben. Das muss eines meiner Glücksgefühle sein, Rykers Glück!"
  },
  Voice_5958_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_5959_AwakerVoiceContent = {
    Text = "Mythag ist der Ort, an dem ich die meisten Erinnerungen habe, und auch... mein wärmstes Zuhause."
  },
  Voice_5959_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_5960_AwakerVoiceContent = {
    Text = "Überlass es mir."
  },
  Voice_5960_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5961_AwakerVoiceContent = {Text = "Wie naiv!"},
  Voice_5961_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5962_AwakerVoiceContent = {
    Text = "Aequor's Hymne!"
  },
  Voice_5962_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5963_AwakerVoiceContent = {
    Text = "Das, was mir gewährt wurde—"
  },
  Voice_5963_AwakerVoiceTitle = {
    Text = "Fähigkeit·eins·Ruhiges Meer"
  },
  Voice_5964_AwakerVoiceContent = {
    Text = "Wenn du bereit bist anzuerkennen, dass ich immer noch \"Ramona\" bin, nenn mich bitte weiterhin so."
  },
  Voice_5964_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5965_AwakerVoiceContent = {
    Text = "Was? Willst du auch meinen Zorn ausnutzen?"
  },
  Voice_5965_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_5965_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_5966_AwakerVoiceContent = {
    Text = "Die Wahrheit... wird hier offenbart."
  },
  Voice_5966_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_5967_AwakerVoiceContent = {
    Text = "Laut den Regeln der Straße muss das Essen sofort gegessen werden."
  },
  Voice_5967_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_5968_AwakerVoiceContent = {
    Text = "Fühlt sich an, als wäre man satt."
  },
  Voice_5968_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_5969_AwakerVoiceContent = {
    Text = "Hmm... Es juckt. Braun, kratz mir den Rücken."
  },
  Voice_5969_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_5970_AwakerVoiceContent = {
    Text = "New mechanical parts will greatly help my system operate—doesn't that count as liking something? Sorry, I'm afraid I don't understand your question. Preferences hold no meaning for mechanical dolls."
  },
  Voice_5970_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_5971_AwakerVoiceContent = {
    Text = "Schau dir das an."
  },
  Voice_5971_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5972_AwakerVoiceContent = {
    Text = "Beobachte das!"
  },
  Voice_5972_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5974_AwakerVoiceContent = {
    Text = "Denke es durch."
  },
  Voice_5974_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_5975_AwakerVoiceContent = {
    Text = "Bleib ruhig und denke nach."
  },
  Voice_5975_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_5976_AwakerVoiceContent = {
    Text = "Miss Winkle ist, wie ich, nicht von diesem Planeten... Es gibt nichts, was mich mit meinem Heimatland verbindet, außer der Tinktur. Ich frage mich, wie Miss Winkle über ihre Heimat denkt?"
  },
  Voice_5976_AwakerVoiceTitle = {
    Text = "Chat·Über Zwinkern"
  },
  Voice_5976_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Zwinkern“ wird freigeschaltet"
  },
  Voice_5977_AwakerVoiceContent = {
    Text = "Komm nicht von hinten näher, es sei denn, du willst dir den Hals brechen."
  },
  Voice_5977_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_5977_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_5978_AwakerVoiceContent = {
    Text = "Hah – Wie könntest du es erlauben, dass Streunerkatzen über den Campus laufen?! Was ist, wenn dieses unhöfliche Wesen jemanden kratzt?!"
  },
  Voice_5978_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5979_AwakerVoiceContent = {
    Text = "Macht mein Blick dich unwohl? Gut, das ist die Wildheit, die mich in der Vorhölle überlebt hat."
  },
  Voice_5979_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_5979_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_5980_AwakerVoiceContent = {
    Text = "Verschone mich mit den hochtrabenden Reden. Was willst du von mir? Es muss einen Grund geben, warum mein Verstand intakt bleibt."
  },
  Voice_5980_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_5980_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_5981_AwakerVoiceContent = {
    Text = "Meine Rache richtete sich immer gegen die Spartaner, aber jetzt existiert selbst dieser Stadtstaat nicht mehr... Gut, dein Schwert zu werden ist nicht unmöglich. Ich akzeptiere dich widerwillig als meinen Partner, aber wenn du es wagst, mich zu verraten, werde ich dir dein Herz herausreißen."
  },
  Voice_5981_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_5981_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_5982_AwakerVoiceContent = {
    Text = "Meine Hände sind mit Blut beschmiert. Meine schwachen Verwandten verstehen meinen Racheakt nicht; sie flüstern über meine Grausamkeit, meine Undankbarkeit und meinen Verrat... Rache war immer nur für mich allein, und für niemanden sonst."
  },
  Voice_5982_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_5982_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_5983_AwakerVoiceContent = {
    Text = "Es ist Zeit, mehr Stahl einzusetzen."
  },
  Voice_5983_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5984_AwakerVoiceContent = {
    Text = "Es ist Zeit, mehr Stahl einzusetzen."
  },
  Voice_5984_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5985_AwakerVoiceContent = {Text = "Sterben."},
  Voice_5985_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_5986_AwakerVoiceContent = {
    Text = "Ich bin... nenn mich einfach Winkle, so nennen mich alle. Ja, nenn mich so, genau wie sie es tun."
  },
  Voice_5986_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5987_AwakerVoiceContent = {
    Text = "Dieser Körper soll der Schild meines Herrn sein!"
  },
  Voice_5987_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5988_AwakerVoiceContent = {
    Text = "Dieser Körper soll der Schild meines Herrn sein!"
  },
  Voice_5988_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_5989_AwakerVoiceContent = {
    Text = "„Der Nussknacker“ soll ein romantisches Märchen für Mädchen sein, aber diese abscheulichen Personen sehen nur die anmutigen Gliedmaßen in Bewegung und vulgäre Wünsche... Ekelhaft."
  },
  Voice_5989_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_5990_AwakerVoiceContent = {
    Text = "Muss... eliminieren...!"
  },
  Voice_5990_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_5991_AwakerVoiceContent = {
    Text = "Pandia... Nennen sie das Training? Haha... Lass mich einen Moment lachen. Menschen sind immer noch zu weichherzig; alles, was sie tun, scheint ein Kinderspiel zu sein."
  },
  Voice_5991_AwakerVoiceTitle = {
    Text = "Chat·Über Pandia"
  },
  Voice_5991_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Pandia“"
  },
  Voice_5992_AwakerVoiceContent = {
    Text = "Komm nicht näher!"
  },
  Voice_5992_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5993_AwakerVoiceContent = {
    Text = "Muss ich mich wieder vorstellen? Du bist wirklich ein Fall für dich. Ich bin Jenkin, und dieses Kind ist Braun. \"Quieeek!\"\nVergiss nicht! Wenn du unsere Namen falsch machst, knall ich deinen *zensiert* mit meiner Laterne! \"Quieeek quieeek?!\""
  },
  Voice_5993_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_5994_AwakerVoiceContent = {
    Text = "Spring, spring!"
  },
  Voice_5994_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_5995_AwakerVoiceContent = {
    Text = "Spring, spring!"
  },
  Voice_5995_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_5996_AwakerVoiceContent = {
    Text = "Hier kommt die Eröffnungs-Huldigung!"
  },
  Voice_5996_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_5997_AwakerVoiceContent = {Text = "Hmph."},
  Voice_5997_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_5998_AwakerVoiceContent = {
    Text = "Nur ein bisschen Stein, zwei Meißel und drei zur Sonne gerichtete Iris... Ich kann alles für dich erschaffen."
  },
  Voice_5998_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_5998_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_5999_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_5999_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6000_AwakerVoiceContent = {
    Text = "Ist das alles?"
  },
  Voice_6000_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6001_AwakerVoiceContent = {Text = "Gut."},
  Voice_6001_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6002_AwakerVoiceContent = {
    Text = "Dieser sinnlose Kampf..."
  },
  Voice_6002_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6003_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6003_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6004_AwakerVoiceContent = {
    Text = "Nachdem Tiberius gestorben war, erfüllten die Menschen in Rom endlich ihren lang gehegten Wunsch - ihn in den Tiber zu werfen, um die Fische zu füttern. Natürlich zahlten sie dafür einen kleinen Preis: von Caligula in die Arena geworfen zu werden, zu meinem Vergnügen."
  },
  Voice_6004_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6005_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6005_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6006_AwakerVoiceContent = {
    Text = "Ich kann spüren, dass das kleine Mädchen ähnliche Kräfte wie ich hat. Sie hat die volle Ausmaße ihrer Stärke noch nicht erfasst. Für deinetwillen werde ich sie angemessen trainieren."
  },
  Voice_6006_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Lily"
  },
  Voice_6006_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Lily“"
  },
  Voice_6007_AwakerVoiceContent = {
    Text = "Verdammtes Ding, siehst du immer noch auf mich herab?!"
  },
  Voice_6007_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6008_AwakerVoiceContent = {
    Text = "Nachweis der Existenz"
  },
  Voice_6008_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6009_AwakerVoiceContent = {
    Text = "Nachweis der Existenz"
  },
  Voice_6009_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6010_AwakerVoiceContent = {
    Text = "Ich glaube, alles geschieht aus einem Grund, aber... die sinnlose Gewalt, die Vorurteile, die Geschwister dazu bringen, gegeneinander zu kämpfen, betrübt mich wirklich. Wenn es etwas gibt, was ich verabscheue, dann ist es wahrscheinlich das."
  },
  Voice_6010_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6011_AwakerVoiceContent = {
    Text = "Ich möchte diese Macht wirklich nicht nutzen."
  },
  Voice_6011_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6012_AwakerVoiceContent = {
    Text = "Lass deine Wachsamkeit nicht nachlassen."
  },
  Voice_6012_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6013_AwakerVoiceContent = {Text = "Hmph"},
  Voice_6013_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6014_AwakerVoiceContent = {Text = "Hör auf!"},
  Voice_6014_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6015_AwakerVoiceContent = {Text = "Hör auf!"},
  Voice_6015_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6016_AwakerVoiceContent = {
    Text = "Casiah ist unglaublich! Sie kann in einem Augenblick einen Hasen erscheinen lassen!"
  },
  Voice_6016_AwakerVoiceTitle = {
    Text = "Chat·Über Casiah"
  },
  Voice_6016_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Casiah“ wird freigeschaltet"
  },
  Voice_6017_AwakerVoiceContent = {
    Text = "Magie, bereit!"
  },
  Voice_6017_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6018_AwakerVoiceContent = {
    Text = "Auflösung... Ich muss zugeben, es gibt Dinge in dieser Welt, die der Macht entzogen sind."
  },
  Voice_6018_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6019_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6019_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6020_AwakerVoiceContent = {
    Text = "Tanze im smaragdgrünen Flammen."
  },
  Voice_6020_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6021_AwakerVoiceContent = {
    Text = "Mach dir keine Sorgen; Narben sind das Abzeichen eines Kriegers."
  },
  Voice_6021_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6022_AwakerVoiceContent = {
    Text = "Zittere vor diesen Muskeln... immer bereit, dir den Kopf abzuschlagen."
  },
  Voice_6022_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6024_AwakerVoiceContent = {
    Text = "Essenszeit? Oder Aktivitätszeit?"
  },
  Voice_6024_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6024_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6025_AwakerVoiceContent = {
    Text = "Hmm! So werden Auritas Gefährten nicht verschwinden!"
  },
  Voice_6025_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6025_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6026_AwakerVoiceContent = {
    Text = "Lehrerin Sylvia sagte, man soll Danke sagen, wenn man etwas bekommt... Danke, danke, danke!"
  },
  Voice_6026_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6026_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6027_AwakerVoiceContent = {
    Text = "Diesmal ist Auritas die Geisterrunde! Du hast nur 5 Sekunden, um dich zu verstecken! 5, 4—"
  },
  Voice_6027_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6027_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6028_AwakerVoiceContent = {
    Text = "Jeder verschwand, nachdem das Versteckspiel begann. Diesmal ist Aurita entschlossen, alle zu finden!"
  },
  Voice_6028_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6028_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6029_AwakerVoiceContent = {
    Text = "Weil sie meine Knochen unter Wasser gefunden haben, denken sie, ich liebe Wasser und möchte einen Pool vor meinen Quartieren bauen? \nHaha... Macht, was ihr wollt. Kommt mir nicht wieder mit solchen Nebensächlichkeiten."
  },
  Voice_6029_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6030_AwakerVoiceContent = {
    Text = "Ein kleiner Tropfen im Ozean, ein unsterblicher, aber flacher Gläubiger, Miryam... begrüßt dich."
  },
  Voice_6030_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6031_AwakerVoiceContent = {
    Text = "Ich bin an der Reihe zu handeln."
  },
  Voice_6031_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6032_AwakerVoiceContent = {Text = "Ho!"},
  Voice_6032_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6033_AwakerVoiceContent = {
    Text = "Absolut erstaunlich... Dein beiläufiger Kommentar hat ein kreatives Problem gelöst, das mich seit Monaten plagt."
  },
  Voice_6033_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6033_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6034_AwakerVoiceContent = {
    Text = "Im Vergleich zu diesen edlen Damen beim Weinfest ist Murphys Temperament einfach bezaubernd."
  },
  Voice_6034_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Murphy"
  },
  Voice_6034_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_6035_AwakerVoiceContent = {
    Text = "Mentale Heilung Meister? Diese Kinder übertreiben die Lobpreisung. Ich tue einfach mein Bestes, um zuzuhören und ihnen zu helfen, ihre innere Not zu lindern - so wie ich es immer getan habe."
  },
  Voice_6035_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6036_AwakerVoiceContent = {
    Text = "Unterschätze mich nicht!"
  },
  Voice_6036_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6037_AwakerVoiceContent = {
    Text = "Unterschätze mich nicht!"
  },
  Voice_6037_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6038_AwakerVoiceContent = {
    Text = "Fühlen Sie sich durstig? Sauberes Wasser ist im Gefängnis ein seltener Luxus."
  },
  Voice_6038_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6038_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6039_AwakerVoiceContent = {
    Text = "Gute Kinder, gehorsame Kinder~ Ihr dürft nicht auf halbem Weg aufgeben~"
  },
  Voice_6039_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6039_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6040_AwakerVoiceContent = {
    Text = "Du musst in meine süße Falle gefallen sein, oder?"
  },
  Voice_6040_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6040_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6041_AwakerVoiceContent = {
    Text = "Mach weiter, nur noch ein bisschen~ Du bist fast am Höhepunkt des Ekstase~"
  },
  Voice_6041_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6041_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6042_AwakerVoiceContent = {
    Text = "Ich trat der Schule im Alter von 14 Jahren bei. Hätte ich reibungslos abgeschlossen, würdest du mich jetzt \"Direktor\" nennen."
  },
  Voice_6042_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6043_AwakerVoiceContent = {
    Text = "Dein schwacher Verstand scheint unfähig zu sein, Lektionen zu behalten."
  },
  Voice_6043_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6044_AwakerVoiceContent = {
    Text = "Du fragst, was mein Wunsch ist? Sichere Reisen und Frieden – zählt das nicht?\nWas andere Wünsche betrifft, habe ich darüber nicht viel nachgedacht... Aber ich werde es sorgfältig überlegen und dir später Bescheid geben."
  },
  Voice_6044_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6044_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6045_AwakerVoiceContent = {
    Text = "\"Was ich suche, sind die Geheimnisse des Universums. Ich möchte verstehen, welche Macht mich beeinflusst.\" Obwohl ich mit der Handlung dieses Romans unzufrieden bin und seine fiktive Wissenschaft lachhaft naiv finde, solltest du mich nach dem Lesen verstehen... Warte, hast du dieses Buch nicht gelesen?"
  },
  Voice_6045_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6045_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6046_AwakerVoiceContent = {
    Text = "Mission und Schicksal sind ähnlich. Sie können nicht leicht aufgegeben werden, noch ist es nötig, dies zu tun."
  },
  Voice_6046_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6046_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6047_AwakerVoiceContent = {
    Text = "Scheine ich immer beschäftigt? Ja, Assistenten können gelegentlich helfen, aber in einigen Forschungen bin ich unersetzlich. Willst du helfen? Dann schau gelegentlich vorbei, um zu sehen, ob ich noch lebe."
  },
  Voice_6047_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6047_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6048_AwakerVoiceContent = {
    Text = "Du denkst, ich bin wütend? Weißt du, wie viele Muskeln es braucht, um zu lächeln? Ich habe das einmal im Unterricht erklärt, was offensichtlich von deinem glatten Gehirn abgerutscht ist. Die Antwort sind mindestens siebzehn, und ich habe keinen Grund, wütend auf dich zu sein."
  },
  Voice_6048_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6048_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6049_AwakerVoiceContent = {
    Text = "Miss Ramona sagte: „Ich muss nicht jeden unterbringen. Verstehst du, was das bedeutet? ...Bedeutet es, dass ich ihren Schutz nicht mehr brauche?“"
  },
  Voice_6049_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6049_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6050_AwakerVoiceContent = {
    Text = "Dreizehn Berichte benötigen dringende Genehmigung, sechs beschädigte Kommunikatoren warten auf Reparatur, und ich muss auch die Ergebnisse von fünf verschiedenen Silber-Extraktionsexperimenten überwachen... Anstatt also meine begrenzte Zeit mit Störungen zu verschwenden, warum versuchst du nicht, dein schwaches Gehirn etwas anzustrengen?"
  },
  Voice_6050_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6050_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6051_AwakerVoiceContent = {
    Text = "Hoffe, dass mein Heimatland beim nächsten Mal auf meinen Ruf antwortet."
  },
  Voice_6051_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6052_AwakerVoiceContent = {
    Text = "Schloss freigegeben."
  },
  Voice_6052_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6054_AwakerVoiceContent = {
    Text = "Ich bin so glücklich... Du bist so voreingenommen und bevorzugst mich so sehr."
  },
  Voice_6054_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6054_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6055_AwakerVoiceContent = {
    Text = "Andere könnten verärgert sein, wenn sie denken, dass du Vorlieben zeigst."
  },
  Voice_6055_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6055_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6056_AwakerVoiceContent = {
    Text = "Sehnst du dich auch nach mir?"
  },
  Voice_6056_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6056_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6057_AwakerVoiceContent = {
    Text = "Schließlich ist es vorbei. Kein weiteres Sehen dieser schwarzen, schleimigen..."
  },
  Voice_6057_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6058_AwakerVoiceContent = {
    Text = "Für all das, was du mir gegeben hast, ist deine Liebe bereits eins geworden mit meiner..."
  },
  Voice_6058_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6058_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6059_AwakerVoiceContent = {Text = "Hey!"},
  Voice_6059_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6060_AwakerVoiceContent = {
    Text = "So gefährlich."
  },
  Voice_6060_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6061_AwakerVoiceContent = {
    Text = "Du hast so hart gearbeitet; es ist Zeit, die Früchte deiner Arbeit zu genießen, oder? Komm näher, ich werde dich nicht enttäuschen~"
  },
  Voice_6061_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6061_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6062_AwakerVoiceContent = {
    Text = "Ich... Ich verstehe deine Absicht. Auch wenn ich noch ungeschickt bin, wird Aigis für dich mit all ihrer Kraft kämpfen!"
  },
  Voice_6062_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6062_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6063_AwakerVoiceContent = {
    Text = "Dein Blick brennt mich an... Hat Aigis dir Probleme bereitet?"
  },
  Voice_6063_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6063_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6064_AwakerVoiceContent = {
    Text = "Aigis ist sehr ängstlich... unsicher, ob sie deinen Erwartungen gerecht werden kann..."
  },
  Voice_6064_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6064_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6065_AwakerVoiceContent = {
    Text = "Dein Blick auf mich macht Aigis unruhig... Hast du keine Angst vor dem Fluch?"
  },
  Voice_6065_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6065_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6066_AwakerVoiceContent = {
    Text = "B-bitte schau nicht in meine Augen... Aigis hat Angst, dir Weh zu tun... Schließlich bin ich wie ein Monster..."
  },
  Voice_6066_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6066_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6067_AwakerVoiceContent = {
    Text = "Der Geruchssinn des Biestes ist nur Glück, okay? Verstehe es nicht falsch, in Ordnung?"
  },
  Voice_6067_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6067_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6068_AwakerVoiceContent = {
    Text = "Ich kann noch nicht aufhören..."
  },
  Voice_6068_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6069_AwakerVoiceContent = {
    Text = "Kraft, unaufhörlich!"
  },
  Voice_6069_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6070_AwakerVoiceContent = {
    Text = "Kraft, stetig fließend."
  },
  Voice_6070_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6071_AwakerVoiceContent = {
    Text = "Magst du das Meer? Ich liebe das Meer, egal was passiert. Ich erinnere mich noch an jenen Tag vor vielen Jahren, als das Meer mir sanft den lange erwarteten Tod brachte."
  },
  Voice_6071_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6073_AwakerVoiceContent = {
    Text = "Aus irgendeinem Grund entstand ein beispielloses Gefühl der Freude..."
  },
  Voice_6073_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6074_AwakerVoiceContent = {
    Text = "Dieser Unterstrom wird die Feinde auseinanderreißen."
  },
  Voice_6074_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6075_AwakerVoiceContent = {
    Text = "Dieser Unterstrom wird die Feinde auseinanderreißen."
  },
  Voice_6075_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6076_AwakerVoiceContent = {
    Text = "Ich habe darauf gewartet, dass mich jemand die wahre Liebe, den Schmerz und das Verlangen lehrt. Kannst du meinen Wunsch erfüllen? Kannst du mich aus diesem dunklen Gefängnis erlösen?"
  },
  Voice_6076_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6076_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6077_AwakerVoiceContent = {
    Text = "Willst du die Wahrheit wissen? Ich hasse das Gefängnis, hasse die Dunkelheit und hasse es so sehr, dass ich sterben könnte. Ich möchte bemerkt werden und möchte entzündet werden..."
  },
  Voice_6077_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6077_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6078_AwakerVoiceContent = {
    Text = "Alles dient dem ewigen Wohl der Zukunft."
  },
  Voice_6078_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6079_AwakerVoiceContent = {
    Text = "Willst du mich genießen? Dann werd mein Sklave. Ich lasse dich vor Hitze schmelzen~"
  },
  Voice_6079_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6079_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6080_AwakerVoiceContent = {
    Text = "Betrachte es als bescheidenes Geschenk von deinem Diener."
  },
  Voice_6080_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6081_AwakerVoiceContent = {
    Text = "Mir ist so langweilig, so langweilig. Im Vergleich zu diesen zitternden großen Gefangenen ist das wie ein Puppenhausspiel. Warum hältst du mich nicht Gesellschaft~"
  },
  Voice_6081_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6081_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6082_AwakerVoiceContent = {
    Text = "Ich sehne mich nach mehr Sklaven, um ihre Stöhnen und Bitten zu hören—\nBring mir mehr Sklaven~ Bitte~"
  },
  Voice_6082_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6082_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6083_AwakerVoiceContent = {
    Text = "Entschuldigung, ich habe mich wieder in Erinnerungen verloren. Bitte schaue nicht traurig. Du bist dran, deine Geschichte zu erzählen. Hast du Lust, ein Gedicht zu schreiben? Deine Abenteuer, deine Erfahrungen, deine Freuden, deine Sorgen, werden sie wie ein fließender Strom von deinem Geist zu deinen Fingerspitzen strömen?"
  },
  Voice_6083_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6083_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6084_AwakerVoiceContent = {
    Text = "Ich war nur ein flüchtiger Wasserzeichen auf Pergament, doch unsere Begegnung hat mich zum Verweilen gebracht. Vielleicht ist das ein Wunder. Ich werde dieses Wunder schätzen und zeitlose Gedichte für dich verfassen."
  },
  Voice_6084_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6084_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6085_AwakerVoiceContent = {
    Text = "Jemand hat mir einmal gesagt, dass Poesie geschrieben wird, um geschätzt zu werden... Kann ich deine Gedanken dazu hören?"
  },
  Voice_6085_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6085_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6086_AwakerVoiceContent = {
    Text = "Hast du das schon mal erlebt? Den Beleidigungen anderer mit einem vergebenden Herzen zu begegnen, nur um das gewünschte Ergebnis nicht zu erzielen. Du schenkst eine Rose, aber deine Hände hinterlassen keinen bleibenden Duft, nur die blutigen Spuren scharfer Dornen."
  },
  Voice_6086_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6086_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6087_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6088_AwakerVoiceContent = {
    Text = "Mein Stift und meine Tinte..."
  },
  Voice_6088_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6089_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6089_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6090_AwakerVoiceContent = {Text = "Falsch..."},
  Voice_6090_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6091_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6091_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6092_AwakerVoiceContent = {
    Text = "Das ist eine Segnung vom Großen!"
  },
  Voice_6092_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6093_AwakerVoiceContent = {
    Text = "Segnung des Großen Blassen"
  },
  Voice_6093_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6094_AwakerVoiceContent = {
    Text = "Ich habe keine Zeit zu ruhen. Das D-Phänomen hat zwei meiner Körper zerstört. Bevor das Ende mich einholt, gibt es viel, das ich verstehen muss... Hilf mir, beginnend mit der Vorbereitung des Experimentmaterials. Ich vertraue darauf, dass du die Balance nicht falsch berechnest."
  },
  Voice_6094_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6094_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6095_AwakerVoiceContent = {
    Text = "Ich liebe die Buntglasfenster in Fontainebleau. Sie werfen unterschiedliche Farbtöne auf die Gesichter der Menschen: verzweifeltes Purpur, schmeichelndes Blau und natürlich mein Favorit—ehrgeiziges Rot..."
  },
  Voice_6095_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6096_AwakerVoiceContent = {
    Text = "Hier spüre ich oft die Gegenwart meines Herrn, doch vielleicht bin ich noch nicht bereit, Ihm gegenüberzutreten... Wie dem auch sei, ich danke Euch, dass Ihr mir Zuflucht gewährt."
  },
  Voice_6096_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6097_AwakerVoiceContent = {
    Text = "Verrat verwandelt Menschen in Monster, egal auf welcher Seite sie stehen. Deshalb verachte ich Verräter."
  },
  Voice_6097_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_60985_AwakerVoiceContent = {
    Text = "Hameln, zu Ihren Diensten."
  },
  Voice_60985_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_60986_AwakerVoiceContent = {
    Text = "Ich traf einmal jemanden, der ein nahezu instinktives Verständnis für Musik hatte. Die von dieser Person geschaffenen Konzerte und Symphonien waren unvergesslich.\nEin wahres Genie."
  },
  Voice_60986_AwakerVoiceTitle = {
    Text = "Casual Talk: Über alte Bekannte"
  },
  Voice_60987_AwakerVoiceContent = {
    Text = "Ich verbringe nicht gerne Zeit mit Strategien. Im Vergleich zur Musik hat die Kunst der Strategie wenig Wert. Dennoch ist sie als Werkzeug zum Überwinden von Hindernissen notwendig. Um den Gipfel der Musik zu erreichen, scheue ich mich nicht, sie zu verwenden."
  },
  Voice_60987_AwakerVoiceTitle = {
    Text = "Casual Talk: Über Strategie"
  },
  Voice_60988_AwakerVoiceContent = {Text = "Rüpel."},
  Voice_60988_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_60989_AwakerVoiceContent = {
    Text = "Hier ist es wieder. Was ist diese Melodie? Seit ich sie zum letzten Mal gehört habe, schwirrt sie in meinem Kopf herum und weigert sich zu gehen oder zu ruhen."
  },
  Voice_60989_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_60989_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6098_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6098_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_60990_AwakerVoiceContent = {
    Text = "In Bezug auf Technik sind strategische Planung und musikalische Leitung nicht anders. Menschlichkeit, Emotion, Verlangen... sie sind so klar und sanft wie Noten auf einem Notensystem, vor meinen Augen ausgestellt, die dem Weg des Taktstocks folgen. Musik zu verstehen bedeutet, alles zu verstehen."
  },
  Voice_60990_AwakerVoiceTitle = {
    Text = "Casual Talk: Über Gemeinsamkeiten"
  },
  Voice_60991_AwakerVoiceContent = {
    Text = "Fast da, nur noch ein kleines bisschen. Ich muss es beenden; ich muss es hören!"
  },
  Voice_60991_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_60991_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_60992_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60992_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_60993_AwakerVoiceContent = {Text = "Rüpel."},
  Voice_60993_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_60994_AwakerVoiceContent = {Text = "Hmm."},
  Voice_60994_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_60995_AwakerVoiceContent = {
    Text = "Musik überwindet Sprache, Schrift und alles. Wenn das nicht Perfektion ist, weiß ich nicht, was das dann ist."
  },
  Voice_60995_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_60995_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_60996_AwakerVoiceContent = {
    Text = "Achte auf den Rhythmus."
  },
  Voice_60996_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_60997_AwakerVoiceContent = {
    Text = "Tuning abgeschlossen."
  },
  Voice_60997_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_60998_AwakerVoiceContent = {
    Text = "Ich bin froh, dass Sie die Bedeutung des Trainings verstehen."
  },
  Voice_60998_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_60999_AwakerVoiceContent = {
    Text = "Ich werde eine perfekte Leistung erbringen."
  },
  Voice_60999_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6099_AwakerVoiceContent = {
    Text = "Eifersüchtig? Diese harten Schuppen sind ein Beweis für ein edles Erbe."
  },
  Voice_6099_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_61000_AwakerVoiceContent = {
    Text = "Ich wurde einst gelobt, aber... das war kein wahres Talent.\nMeine Werke waren lediglich Nachahmungen meiner Vorgänger."
  },
  Voice_61000_AwakerVoiceTitle = {
    Text = "Alltägliches Gespräch: Über die Arbeit"
  },
  Voice_61001_AwakerVoiceContent = {
    Text = "Holzblasinstrumente und Saiten... verweben sich auf- und abwärts, das Motiv tritt wieder auf... Jetzt erinnere ich mich, es ist das Requiem, das ich für das früh verstorbene Genie, den gefallenen Stern, komponiert habe."
  },
  Voice_61001_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_61001_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_61002_AwakerVoiceContent = {
    Text = "Hmm? Hast du ein neues Teil, das du mir zeigen kannst?"
  },
  Voice_61002_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_61003_AwakerVoiceContent = {
    Text = "Diese Melodie ist den Seelen der Verstorbenen gewidmet."
  },
  Voice_61003_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_61004_AwakerVoiceContent = {
    Text = "Der grüne Tänzer hatte eine Eleganz, die würdig war, die Hauptrolle einer Hoftruppe zu übernehmen.\nWenn sich die Gelegenheit bietet, hoffe ich wirklich, dass wir zusammenarbeiten könnten."
  },
  Voice_61004_AwakerVoiceTitle = {
    Text = "Kleine Gespräche: Über Liz"
  },
  Voice_61004_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Liz“"
  },
  Voice_61005_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_61006_AwakerVoiceContent = {
    Text = "Es gibt einen Konzertmeister im Orchester, aber ein Konzertmeister allein kann kein vollständiges Orchester bilden. Mein Orchester hat keinen Platz für diejenigen, die nur zeigen wollen, was sie können."
  },
  Voice_61006_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_61007_AwakerVoiceContent = {
    Text = "Ich glaube, ich habe eine Melodie gehört. Übt hier jemand in der Nähe?"
  },
  Voice_61007_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_61007_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_61008_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_61009_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6100_AwakerVoiceContent = {
    Text = "Bereite dich darauf vor, dein Ende zu treffen!"
  },
  Voice_6100_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_61010_AwakerVoiceContent = {
    Text = "Ja, ja, das ist es - die letzte Messe, ein Requiem für die Musik selbst!"
  },
  Voice_61010_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_61010_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_61011_AwakerVoiceContent = {
    Text = "Ah, Hüter, du bist gerade rechtzeitig angekommen. Sag mir, was hältst du von dieser Bewegung?"
  },
  Voice_61011_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_61012_AwakerVoiceContent = {
    Text = "Streicher, beginnt."
  },
  Voice_61012_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_61013_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_61014_AwakerVoiceContent = {
    Text = "Es wurde klar, diese schlingende Melodie, wie das Wailing einer Seele... Ich bin mir sicher, ich habe sie schon einmal gehört."
  },
  Voice_61014_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_61014_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_61015_AwakerVoiceContent = {
    Text = "Rationalität und Ordnung bahnten den Weg. Ich ging nach oben und öffnete die Tore des Saales. Jenseits davon blieb nichts – wahrhaft ewige Musik transcended die Vernunft."
  },
  Voice_61015_AwakerVoiceTitle = {
    Text = "Casual Talk: Über Grund und Ordnung"
  },
  Voice_61016_AwakerVoiceContent = {
    Text = "Achte auf meine Hände, eins, zwei, drei."
  },
  Voice_61016_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_61017_AwakerVoiceContent = {
    Text = "Ich habe die Darbietung deines sogenannten Orchesters gehört, voller Fehler. Aber keine Sorge, ich habe einen detaillierten Plan, um eine perfekte Show vor dem Silberfrostfest zu inszenieren."
  },
  Voice_61017_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_61018_AwakerVoiceContent = {
    Text = "Ich kann niemals die erste Erfahrung vergessen, als ich die Musik tief in meinem Bewusstsein hörte. In diesen Tönen und Akkorden verschwand die reale Welt; nur pure und erhabene Musik blieb."
  },
  Voice_61018_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_61019_AwakerVoiceContent = {
    Text = "Es ist schade. Es scheint, als wären mehr Proben nötig."
  },
  Voice_61019_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6101_AwakerVoiceContent = {
    Text = "Dies ist ein Befehl."
  },
  Voice_6101_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_61020_AwakerVoiceContent = {
    Text = "Normalerweise spreche ich solche Einladungen nicht aus, aber... möchten Sie es versuchen? Halten Sie das Dirigentenstäbchen und hauchen Sie der Musik neues Leben ein?"
  },
  Voice_61020_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_61020_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_61021_AwakerVoiceContent = {
    Text = "Ich ziehe es vor, mich durch Musik auszudrücken, anstatt durch Worte. Aber mit dir zu kommunizieren, fühlt sich an wie das Dirigieren eines Orchesters, das unzählige Male geprobt wurde - reibungslos und oft angenehm überraschend.\nDu nimmst einen besonderen Platz sowohl für die Musik als auch für mich ein."
  },
  Voice_61021_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_61021_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_61022_AwakerVoiceContent = {
    Text = [[
In einer Symphonie ist die Koordination zwischen den Instrumenten entscheidend; wie jede Sektion eintritt und austritt, bringt eine andere Erfahrung zur Musik.
Was ich meine ist, wenn das Kommandieren von Erwachenden eine Darbietung ist, machst du es gut.]]
  },
  Voice_61022_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_61022_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_61023_AwakerVoiceContent = {
    Text = "Magst du dieses Stück? Es präsentiert das Motiv in nur vier Takten vollständig, während die Holzblasinstrumente die Melodie nach oben treiben, bis das Thema erreicht ist. Ein solches Design hat unzählige Nachfolger beeinflusst... Entschuldige, rede ich zu viel?"
  },
  Voice_61023_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_61023_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_61024_AwakerVoiceContent = {
    Text = "Perfekte Aufführung."
  },
  Voice_61024_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_61025_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_61026_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_61027_AwakerVoiceContent = {
    Text = "Jeder von uns verbirgt eine Melodie in seinem Herzen, gefangen von Vernunft und Körper, die nur in der Verrücktheit vollständig ausgedrückt werden kann."
  },
  Voice_61027_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_61028_AwakerVoiceContent = {
    Text = "Nur Musik verdient Lob."
  },
  Voice_61028_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_61029_AwakerVoiceContent = {
    Text = "Nur Musik verdient Lob."
  },
  Voice_61029_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6102_AwakerVoiceContent = {Text = "Gehe."},
  Voice_6102_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_61030_AwakerVoiceContent = {
    Text = "Hör zu, dies ist das letzte Requiem!"
  },
  Voice_61030_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_6103_AwakerVoiceContent = {
    Text = "Bette um Gnade!"
  },
  Voice_6103_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_61049_AwakerVoiceContent = {
    Text = "Hör zu, dies ist das letzte Requiem!"
  },
  Voice_61049_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_6104_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6104_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6105_AwakerVoiceContent = {
    Text = "Wünscht du dir auch, von den grünen Flammen verzehrt zu werden?"
  },
  Voice_6105_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6107_AwakerVoiceContent = {
    Text = "Wagst du es, den Fokus zu verlieren?"
  },
  Voice_6107_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6108_AwakerVoiceContent = {
    Text = "Konzentriere dich!"
  },
  Voice_6108_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6109_AwakerVoiceContent = {
    Text = "Wie kann es solche adorablen Studenten an der Universität geben~ Ich habe ihn gerade gefragt: „Möchtest du mein Diener sein?“ und er ist rot geworden, stammelte etwas darüber, wie „ich bereits ein Ritter des Hüters bin“... \nOffensichtlich gibt es absolut keinen Konflikt~"
  },
  Voice_6109_AwakerVoiceTitle = {
    Text = "Alltägliches Gespräch · Über Ogier"
  },
  Voice_6109_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Ogier“"
  },
  Voice_6110_AwakerVoiceContent = {
    Text = "Denk nicht einmal daran, dich der Prinzessin zu nähern."
  },
  Voice_6110_AwakerVoiceTitle = {
    Text = "Fähigkeit·eins·Tobende Wellen"
  },
  Voice_6111_AwakerVoiceContent = {
    Text = "Akzeptiere dein Schicksal."
  },
  Voice_6111_AwakerVoiceTitle = {
    Text = "Fähigkeit·eins·Steigende Fluten"
  },
  Voice_6112_AwakerVoiceContent = {
    Text = "Die Tore meines Heimatlandes treiben davon... Nein... Nicht schon wieder..."
  },
  Voice_6112_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6113_AwakerVoiceContent = {
    Text = "Aus dem Weg!"
  },
  Voice_6113_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6114_AwakerVoiceContent = {
    Text = "Aus dem Weg!"
  },
  Voice_6114_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6115_AwakerVoiceContent = {
    Text = "Zahle den Preis für deine Taten."
  },
  Voice_6115_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6116_AwakerVoiceContent = {
    Text = "Willst du sterben?"
  },
  Voice_6116_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6117_AwakerVoiceContent = {
    Text = "Ich glaube, ich habe wieder an Auflösung gelitten... Mein Herz löst sich auf! Nur ein paar Aspirin, eine Peitsche und ein bisschen Schmerz sollten ausreichen, um mich zu heilen..."
  },
  Voice_6117_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6118_AwakerVoiceContent = {
    Text = "Selbst du kannst diese gespenstische Krankheit nicht heilen? Warum also die Auflösung verfolgen, dein Leben riskieren?"
  },
  Voice_6118_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6119_AwakerVoiceContent = {
    Text = "Ich bin der letzte römische Krieger—Uvhash!"
  },
  Voice_6119_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6120_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6120_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6121_AwakerVoiceContent = {
    Text = "Ich bin der letzte römische Krieger—Uvhash!"
  },
  Voice_6121_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6122_AwakerVoiceContent = {
    Text = "Auflösung...? Natürlich weiß ich das. Es bedeutet einfach, dass die Meister-Diener-Bindung gebrochen ist, richtig? Was ist daran so schwer?"
  },
  Voice_6122_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6123_AwakerVoiceContent = {
    Text = "Ich wurde beschworen; die Grenze zwischen Göttern und Narren hat sich verwischt."
  },
  Voice_6123_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6123_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6124_AwakerVoiceContent = {
    Text = "Hmm... Der Druck ist gut ausbalanciert, und die Massagetechnik ist ziemlich gut~"
  },
  Voice_6124_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6125_AwakerVoiceContent = {
    Text = "Ist die Dekoration hier nicht zu veraltet? Es ist unheimlich, als ob es spukt."
  },
  Voice_6125_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6126_AwakerVoiceContent = {
    Text = "Hier sind üppige Pflanzen, eine ruhige Luft und ein Heilmittel für die Krankheit meiner Schwester. Für uns beide ist es das wundervollste neue Zuhause."
  },
  Voice_6126_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6127_AwakerVoiceContent = {
    Text = "Hätte nie gedacht hier zu treffen... Ich frage mich, wie es meiner Schwester seitdem ergangen ist. Egal wie ich frage, sie sagt nur, es ginge ihr gut... Es tut mir leid und danke, dass du uns wiedervereint hast."
  },
  Voice_6127_AwakerVoiceTitle = {
    Text = "Chat·Über Ohnmacht"
  },
  Voice_6127_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Ohnmacht“ wird freigeschaltet"
  },
  Voice_6128_AwakerVoiceContent = {
    Text = "Ein Angebot an meinen Herrn."
  },
  Voice_6128_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6129_AwakerVoiceContent = {
    Text = "Ein Angebot an meinen Herrn."
  },
  Voice_6129_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6130_AwakerVoiceContent = {
    Text = "Beruhige dich, beruhige dich, beruhige dich..."
  },
  Voice_6130_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6131_AwakerVoiceContent = {
    Text = "Es gibt viele „mich“ darin. Glücklich, traurig, wütend... Sie lieben Biskuitkuchen, hassen die regnerischen Tage in Londinium. Sie alle nennen sich „24“ und sie alle verehren dich."
  },
  Voice_6131_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6131_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6132_AwakerVoiceContent = {
    Text = "Früher arbeitete ich jeden Tag bis Mitternacht – spinnen, waschen, putzen, babysitten, sogar sammeln... Ich würde alles tun, um Geld zu verdienen. Damals war das Leben lediglich Überleben.\nJetzt haben wir frisches Essen, warme Betten und freundliche Meister wie Sie... Es ist jenseits meiner kühnsten Träume."
  },
  Voice_6132_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6132_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6133_AwakerVoiceContent = {
    Text = "Egal was, wir werden ein Steak und ein Bett teilen und dir niemals Unannehmlichkeiten bereiten."
  },
  Voice_6133_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6133_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6134_AwakerVoiceContent = {
    Text = "Heh, diese Frau hat solche Angst, dass ich herauskomme, dass sie sich nicht einmal nachts traut zu schlafen. Entspann dich, ich würde dich nicht töten — nicht wenn du mir Geschenke machst.\nWer bin ich? Natürlich bin ich \"24\", hahaha!"
  },
  Voice_6134_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6134_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6135_AwakerVoiceContent = {
    Text = "Ich fühle mich gerade fantastisch. Was? Du sagst, mein Verstand sei von etwas anderem übernommen worden? N-nein... äh..."
  },
  Voice_6135_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6135_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6136_AwakerVoiceContent = {
    Text = "Als Subjekt bist du ziemlich scharfsinnig. Bevor ich meinen nächsten langen Schlummer halte, werde ich diesen Moment mit meiner Präsenz erhellen."
  },
  Voice_6136_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6137_AwakerVoiceContent = {
    Text = "Hmm, das Meer ist heute Nacht ganz warm..."
  },
  Voice_6137_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6138_AwakerVoiceContent = {
    Text = "Der weiße Vogel, der im Traum kreiste, ist angekommen."
  },
  Voice_6138_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6139_AwakerVoiceContent = {
    Text = "Wie du wünschst, ist meine Präsenz greifbarer geworden."
  },
  Voice_6139_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6140_AwakerVoiceContent = {
    Text = "So befriedigend, so befriedigend!"
  },
  Voice_6140_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6141_AwakerVoiceContent = {Text = "Süß!"},
  Voice_6141_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6142_AwakerVoiceContent = {
    Text = "Überlass es mir!"
  },
  Voice_6142_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6143_AwakerVoiceContent = {
    Text = "Überlass es mir!"
  },
  Voice_6143_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6144_AwakerVoiceContent = {
    Text = "Willkommen zu — unserem Festmahl!"
  },
  Voice_6144_AwakerVoiceTitle = {
    Text = "Exalt · Manie"
  },
  Voice_6145_AwakerVoiceContent = {
    Text = "Dieses Mädchen trägt zweifellos das Blut von Yu in sich... Nein, Yu ist nicht alt genug, um Nachkommen zu haben. Ihre Kraft ist jedoch tatsächlich Yu ähnlich."
  },
  Voice_6145_AwakerVoiceTitle = {
    Text = "Idle-Gespräch·Über die Göttliche Blutlinie"
  },
  Voice_6145_UnlockDesc = {
    Text = "Nach dem Erwerb entweder des Erweckers \"Aigis\" oder \"Murphy\" freigeschaltet"
  },
  Voice_6146_AwakerVoiceContent = {
    Text = "Die Güte des Meisters, Karen wagt es nicht, auch nur einen Moment zu vergessen!"
  },
  Voice_6146_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6147_AwakerVoiceContent = {
    Text = "—So süß und köstlich!"
  },
  Voice_6147_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6148_AwakerVoiceContent = {
    Text = "Karen macht eine Diät und kann nicht zu viel essen~"
  },
  Voice_6148_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6149_AwakerVoiceContent = {
    Text = "Diese Typen sind es nicht wert, meine Gegner zu sein."
  },
  Voice_6149_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6150_AwakerVoiceContent = {
    Text = "Kunst zu erklären ist so lächerlich wie Eisenbahnaktien zu erklären – bitte mach das Leben den armen Künstlern nicht schwerer."
  },
  Voice_6150_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6151_AwakerVoiceContent = {
    Text = "Aigis... Habe ich etwas Falsches getan?"
  },
  Voice_6151_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6152_AwakerVoiceContent = {
    Text = "Deine Gebete wurden gehört."
  },
  Voice_6152_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6153_AwakerVoiceContent = {
    Text = "Deine Gebete wurden gehört."
  },
  Voice_6153_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6154_AwakerVoiceContent = {
    Text = "Hmph, respektlos."
  },
  Voice_6154_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6155_AwakerVoiceContent = {
    Text = "Ah, war das gerade der Meister? Nein, egal. Das letzte Mal, als ich ihn grüßte, erkannte er mich nicht... Ich wartete auf ihn im Gefängnis und hoffte, er würde mich mitnehmen, aber er kam nie, nicht einmal während des Aufstands."
  },
  Voice_6155_AwakerVoiceTitle = {
    Text = "Plaudern · Über \"N\""
  },
  Voice_6155_UnlockDesc = {
    Text = "Freigeschaltet nach Abschluss von Kapitel 7 der \"Ermittlungsoperation\""
  },
  Voice_6156_AwakerVoiceContent = {
    Text = "Auf das Erwachen der Menschheit reagieren und Allianzen bilden, um meine unerledigte Pflicht zu erfüllen – wenn du stark genug werden kannst, um mich herauszufordern, wäre das ideal."
  },
  Voice_6156_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6157_AwakerVoiceContent = {
    Text = "Schwester, Braun, der Feigling aus dem Waisenhaus, ich bin zufrieden, sie einfach nur als Freunde zu haben. Äh... nun, ich nehme an, du zählst auch. Braun, teile ein Stück Candy mit dem Hüter.  \n\"Cheep?!\""
  },
  Voice_6157_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6157_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6158_AwakerVoiceContent = {
    Text = "Das Ostslum ist kein Ort für Kinder. Listige Vorarbeiter finden Wege, den Lohn der Zeitungsausträger zu kürzen und kritisieren die Milchlieferanten für ihre Geschwindigkeit... lächerliches Nörgeln! Um auf den Straßen zu überleben, kann man sich nur auf sich selbst verlassen. Niemand sonst ist vertrauenswürdig."
  },
  Voice_6158_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6158_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6159_AwakerVoiceContent = {
    Text = "Meine \"schlechten Gewohnheiten\" können nicht über Nacht geändert werden, verstehst du, oder? Unter Brücken und in Sturmdrainagen zu schlafen und von Müll zu überleben - am Leben zu bleiben war schon hart genug... Du kannst nicht erwarten, dass ich sofort anfange, mein Bett zu machen! Es wird mindestens einen halben Monat dauern, um mich daran zu gewöhnen!"
  },
  Voice_6159_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6159_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6160_AwakerVoiceContent = {
    Text = "Es fühlt sich nicht gut an, im Raum verloren zu gehen. Da du mich dort herausgezogen hast, kannst du gerne fragen, aber ich kann nicht garantieren, dass ich helfen kann.\nAngesichts meines Alters würdest du dich nicht mit einem Kind beschäftigen, oder?~"
  },
  Voice_6160_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6160_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6161_AwakerVoiceContent = {
    Text = "Hey, Westsider! Hast du Brown gesehen? Dieser Vielfraß muss wieder etwas erschnüffelt haben."
  },
  Voice_6161_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6161_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6162_AwakerVoiceContent = {
    Text = "\"Die Starken dürfen ihre Macht nicht einsetzen, um andere zu unterdrücken, denn ihr alle teilt mein Blut.\" — Ich erinnere mich an die Lehren des Gottes des Mitgefühls und werde diese Stärke nutzen, um die Menschen um mich herum zu beschützen."
  },
  Voice_6162_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6162_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6163_AwakerVoiceContent = {
    Text = "Neugierig auf das, was ich zu Beginn des Universums gesehen habe? Ich kann dir sagen, es war nichts dort."
  },
  Voice_6163_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6163_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6164_AwakerVoiceContent = {
    Text = "Es ist jetzt heller."
  },
  Voice_6164_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6165_AwakerVoiceContent = {
    Text = "Die immerwährende Lampe..."
  },
  Voice_6165_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6166_AwakerVoiceContent = {
    Text = "Die Verbindung zur Heimat ist stärker geworden."
  },
  Voice_6166_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6167_AwakerVoiceContent = {
    Text = "Wenn ich die Welt von ihrem Leid befreien kann, werde ich zufrieden sein."
  },
  Voice_6167_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6168_AwakerVoiceContent = {
    Text = "Gib mir mehr Befehle, Blasser Bote. Möge deine Flamme meinen Weg erleuchten."
  },
  Voice_6168_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6169_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6169_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6170_AwakerVoiceContent = {
    Text = "Die Bildung einer Person umfasst nicht nur den Körper, sondern auch das Herz."
  },
  Voice_6170_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6171_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6171_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6172_AwakerVoiceContent = {Text = "Aua!"},
  Voice_6172_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6173_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6173_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6174_AwakerVoiceContent = {
    Text = "Hmm! Deine Temperatur ist ein wenig zu hoch für Korallen. Aber... es ist warm und intensiv. Ich mag es."
  },
  Voice_6174_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6175_AwakerVoiceContent = {
    Text = "Ah... Brauchst du etwas? Wenn möglich, lass uns hinter den Kulissen sprechen..."
  },
  Voice_6175_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6176_AwakerVoiceContent = {
    Text = "Verwelkend vor dem Blühen, wie eine wassergesättigte Lotusblume... Frieden zu suchen in den kalten, wütenden Gezeiten, zu schüchtern, um mein eigenes Glück zu verfolgen... Das bin ich, der Hüter."
  },
  Voice_6176_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6176_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6177_AwakerVoiceContent = {
    Text = "Ich kämpfte einst mit diesem Dilemma: Ist Schmerz länger als das Leben selbst? Wenn ja, ist ein friedlicher Schlaf glücklicher als gequältes Wachsein? Nachdem ich erwachte, war ich ebenfalls gefangen, bis du mir dieses sichere Heiligtum gebracht hast..."
  },
  Voice_6177_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6177_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6178_AwakerVoiceContent = {
    Text = "Während meiner Zeit im Sanatorium versuchte ich, Freundschaften zu schließen, aber die Menschen waren zögerlich, mir näherzukommen... Liegt es an diesem knochenzerfallenden \"Gift\"? Wie auch immer, sei vorsichtig, wenn du mir näher kommst."
  },
  Voice_6178_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6178_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6179_AwakerVoiceContent = {
    Text = "Das Geräusch der von der Nachtluft getragenen Glocke bringt Frieden. Möchtest du auf dem Steinstuhl sitzen und eine Weile zuhören? Ich werde dir mit einem Schal einen Platz bereiten."
  },
  Voice_6179_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6179_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6180_AwakerVoiceContent = {
    Text = "Hast du von der \"Seebestattung\" gehört? In der Stadt, in der ich früher lebte, gab es den Brauch, die Verstorbenen im Meer zu versenken, sodass der Ozean der letzte Ruheplatz für alle wurde. Was mich betrifft, ich bin früh in die Umarmung des Meeres zurückgekehrt..."
  },
  Voice_6180_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6180_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6181_AwakerVoiceContent = {Text = "Hmph!"},
  Voice_6181_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6182_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6182_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6183_AwakerVoiceContent = {Text = "Ja!"},
  Voice_6183_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6184_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6184_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6185_AwakerVoiceContent = {
    Text = "Das Kampfprotokoll wurde archiviert. Danke für deine harte Arbeit, Hüter."
  },
  Voice_6185_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6186_AwakerVoiceContent = {
    Text = "(Stöhnen vor Schmerz)"
  },
  Voice_6186_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6187_AwakerVoiceContent = {
    Text = "(Stöhnen vor Schmerz)"
  },
  Voice_6187_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6188_AwakerVoiceContent = {
    Text = "(Stöhnen vor Schmerz)"
  },
  Voice_6188_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6189_AwakerVoiceContent = {
    Text = "Du kannst weitermachen."
  },
  Voice_6189_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6190_AwakerVoiceContent = {
    Text = "Besucher im Salon erhalten die beste Gastfreundschaft... Als Eintrittskarte, haben die Gäste Geheimnisse vorbereitet, die diesen großen Festmahl würdig sind?"
  },
  Voice_6190_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6191_AwakerVoiceContent = {
    Text = "Ich liebe neue Dinge. Während meiner Jahrtausende langen Reisen habe ich viele faszinierende Innovationen und Erfindungen gesehen, wie poetische Formen und filmische Szenen. Menschen sind wirklich faszinierende Wesen."
  },
  Voice_6191_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6192_AwakerVoiceContent = {
    Text = "Hmm, Lily erkennt sie. Wenn ihre Mutter nicht da ist, bleibt Lily bei ihr zu Hause."
  },
  Voice_6192_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Narzisse"
  },
  Voice_6192_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Daffodil“"
  },
  Voice_6195_AwakerVoiceContent = {
    Text = "Bist du derjenige, der meinen langen Schlaf stört?"
  },
  Voice_6195_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6196_AwakerVoiceContent = {
    Text = "Götter? Nur Narren würden ihr Leben solchen immateriellen Wesen anvertrauen. Anstatt sich auf die sogenannten Götter zu verlassen, denke mehr darüber nach, wie du stärker werden kannst."
  },
  Voice_6196_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6197_AwakerVoiceContent = {
    Text = "Was für ein Meister der Gladiatoren, nur ein wertloses Insekt."
  },
  Voice_6197_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Agrippa"
  },
  Voice_6197_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Agrippa“"
  },
  Voice_6198_AwakerVoiceContent = {
    Text = "Nach dem Sieg, bitte erlaube mir, die für die Reproduktion benötigten Materialien zu nehmen."
  },
  Voice_6198_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6199_AwakerVoiceContent = {
    Text = "Großer Freund! Partner! Hoo-hoo, lass uns für immer beste Freunde mit Aurita sein!"
  },
  Voice_6199_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6200_AwakerVoiceContent = {
    Text = "Ich freue mich gerade so sehr... Wenn du nicht sterben willst, halte besser Abstand von mir."
  },
  Voice_6200_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6201_AwakerVoiceContent = {
    Text = "Ist es wirklich in Ordnung, dass diese Person andere so behandelt? Frau Sarah sagte, dass Kinder keine Wutausbrüche haben sollten..."
  },
  Voice_6201_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Murphy"
  },
  Voice_6201_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_6202_AwakerVoiceContent = {
    Text = "Der Ruhm des Sieges gehört dir"
  },
  Voice_6202_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6203_AwakerVoiceContent = {
    Text = "Kann ich nicht mehr essen, ich bin voll~"
  },
  Voice_6203_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6204_AwakerVoiceContent = {
    Text = "Der leere Raum wurde gefüllt~"
  },
  Voice_6204_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6205_AwakerVoiceContent = {
    Text = "Ein wenig mehr Hitze~"
  },
  Voice_6205_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6206_AwakerVoiceContent = {
    Text = "Ich kenne dieses Kind. Manchmal steht sie weit weg und beobachtet die Darbietung. Es ist besser, wenn sie nicht näher kommt, sonst werden diese kleinen Zuschauer \"geistig und körperlich erschöpft\" sein!"
  },
  Voice_6206_AwakerVoiceTitle = {
    Text = "Chat·Über Ohnmacht"
  },
  Voice_6206_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Ohnmacht“ wird freigeschaltet"
  },
  Voice_6207_AwakerVoiceContent = {
    Text = "Tinktur sagte: „Güte zurückzahlen.“ So werde ich, solange es in meiner Macht steht zu helfen, eine Hand reichen..."
  },
  Voice_6207_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6208_AwakerVoiceContent = {
    Text = "Hallo, Hüter. Wie kann ich dir helfen?"
  },
  Voice_6208_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6209_AwakerVoiceContent = {
    Text = "Eines Tages werde ich als Anführer an der Spitze des Schlachtfeldes zurückkehren."
  },
  Voice_6209_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6209_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6210_AwakerVoiceContent = {
    Text = "Kannst du es glauben? Ich kann fühlen, wie mein gebrochenes Bein heilt."
  },
  Voice_6210_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6210_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6211_AwakerVoiceContent = {
    Text = "Ich danke dir aufrichtig für dein Vertrauen, mich auf dieses Niveau auszubilden. Du musst auch jemand sein, der nach Gerechtigkeit strebt, daher werde ich weiterhin Ruhm für unser Militär hier bringen."
  },
  Voice_6211_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6211_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6212_AwakerVoiceContent = {
    Text = "Der Tag der Reise rückt näher, und mein Blut kocht vor Leidenschaft."
  },
  Voice_6212_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6212_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6213_AwakerVoiceContent = {
    Text = "Die Ehre, ein Krieger zu sein, wird wiederhergestellt."
  },
  Voice_6213_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6213_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6214_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6214_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6215_AwakerVoiceContent = {Text = "Aua!"},
  Voice_6215_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6216_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6216_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6217_AwakerVoiceContent = {Text = "Betrüger!"},
  Voice_6217_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6218_AwakerVoiceContent = {
    Text = "Ups, Entschuldigung! Ich werde es beim nächsten Mal schaffen!"
  },
  Voice_6218_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6219_AwakerVoiceContent = {
    Text = "Ich höre jemanden meinen Namen rufen, Agrippa, Agrippa, Agrippina..."
  },
  Voice_6219_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6219_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6220_AwakerVoiceContent = {
    Text = "Ich habe es gesehen... Es kroch aus der Dunkelheit des Brunnens empor, unzählige Augen erschienen auf seinem Fleisch-Ei. Sie starrten mich an, riefen mich... Gott des Labyrinths."
  },
  Voice_6220_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6220_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6221_AwakerVoiceContent = {
    Text = "Ich habe ein sehr starkes Verlangen, einen Zweikampf zu sehen... Es wäre noch besser, wenn er in einem Labyrinth stattfindet."
  },
  Voice_6221_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6221_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6222_AwakerVoiceContent = {
    Text = "Vertrag... Ja, ich möchte einen Vertrag mit dir unterzeichnen, einen ewigen Meister-Diener-Vertrag..."
  },
  Voice_6222_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6222_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6223_AwakerVoiceContent = {
    Text = "Hmph... Nicht schlecht. Gib mir mehr. Ich muss diese Spinnenlarven füttern."
  },
  Voice_6223_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6223_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6224_AwakerVoiceContent = {
    Text = "Was für ein Schmutz, was für eine Abscheulichkeit! Ah—hör auf! Bitte! Lass mich es nicht sehen, und sprich nicht in meiner Nähe darüber..."
  },
  Voice_6224_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6225_AwakerVoiceContent = {
    Text = "Meine Vergangenheit war routiniert und ruhig, wie die Meere in der Nähe des Äquators, nichts Nennenswertes."
  },
  Voice_6225_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6225_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6226_AwakerVoiceContent = {
    Text = "Hmm...? Mutter, umarm mich... Mm, so warm..."
  },
  Voice_6226_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6227_AwakerVoiceContent = {
    Text = "Sternenstaub..."
  },
  Voice_6227_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6228_AwakerVoiceContent = {
    Text = "Oh nein, bist du verloren?"
  },
  Voice_6228_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6229_AwakerVoiceContent = {Text = "Nutzlos."},
  Voice_6229_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6230_AwakerVoiceContent = {
    Text = "Wann immer ich an diese Verräter denke, die auf Knien um Gnade flehen, verspüre ich eine Welle der Zufriedenheit, und die Flammen in meinem Herzen scheinen zu erlöschen."
  },
  Voice_6230_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6231_AwakerVoiceContent = {
    Text = "Der Schiffsmeister nahm mich von meinem Zuhause und betraute mich mit der Mission der Jungfernfahrt des Schiffs. Seitdem liegt die Bedeutung meines Lebens außerhalb meiner Kontrolle. Jemand sagte mir, dass ich, zumindest in diesem zweiten Leben als Erwachter, für meine eigenen Wünsche leben sollte... Wirst du mir helfen? Hilf mir egoistisch zu sein, hilf mir, meinen Wunsch zu finden."
  },
  Voice_6231_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6231_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6232_AwakerVoiceContent = {
    Text = "Agrippa. Ich habe nichts mit dir zu besprechen – es sei denn, du wagst es, dich freiwillig als mein Gladiator zu melden."
  },
  Voice_6232_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6233_AwakerVoiceContent = {
    Text = "Tawil... weit gefährlicher als wir uns vorgestellt haben. Wenn ich nicht da bin, musst du extrem vorsichtig mit ihr sein."
  },
  Voice_6233_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Tawil"
  },
  Voice_6235_AwakerVoiceContent = {
    Text = "Mit diesem Argument... interpretiere die Welt!"
  },
  Voice_6235_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6236_AwakerVoiceContent = {
    Text = "Mit diesem Argument... interpretiere die Welt!"
  },
  Voice_6236_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6237_AwakerVoiceContent = {
    Text = "Strahle hell!"
  },
  Voice_6237_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6238_AwakerVoiceContent = {
    Text = "Nach bestem Wissen und Gewissen."
  },
  Voice_6238_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6239_AwakerVoiceContent = {
    Text = "Nach bestem Wissen und Gewissen."
  },
  Voice_6239_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6240_AwakerVoiceContent = {
    Text = "Lass es verfallen."
  },
  Voice_6240_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6241_AwakerVoiceContent = {
    Text = "Lass es verfallen."
  },
  Voice_6241_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6242_AwakerVoiceContent = {
    Text = "Lächeln und Etikette dienen als eine Art Rüstung, die mir hilft, Abstand zu anderen zu wahren und langweilige Störungen zu vermeiden. Was mein wahres Ich angeht... ich habe nichts dagegen, es dir zu zeigen."
  },
  Voice_6242_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6242_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6243_AwakerVoiceContent = {
    Text = "Gedanken sammeln sich wie weißer Kalkstein und werden in wunderschönen Korallen gewaschen. Sie vereinen sich mit mir, pulsierend mit meinem Herzschlag... Wirst du zuhören?"
  },
  Voice_6243_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6243_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6244_AwakerVoiceContent = {
    Text = "Inspiration ist wie Blasen, die im Meer aufsteigen: eine sanfte Berührung, und sie verschwinden. Bist du das auch?"
  },
  Voice_6244_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6244_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6245_AwakerVoiceContent = {
    Text = "Krieg, Raub und Ruhm sind alles menschliche Begierden. Der bescheidene Bildhauer hat kein Interesse daran, was die Menschen verfolgen; sie wünscht sich nur, Sklavin der Schönheit zu sein."
  },
  Voice_6245_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6245_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6246_AwakerVoiceContent = {
    Text = "Ein wunderbares Leben liegt im Genuss. Manchmal sollte man sich selbst nicht zu sehr verurteilen."
  },
  Voice_6246_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6246_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6247_AwakerVoiceContent = {
    Text = "So nur kleine Wunden..."
  },
  Voice_6247_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6249_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6249_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6250_AwakerVoiceContent = {
    Text = "Verdammtes Ding!"
  },
  Voice_6250_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6251_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6251_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6252_AwakerVoiceContent = {
    Text = "D-Phänomen bringt Chaos und Katastrophen. Vielleicht ist mein Land aufgrund dessen ins Aequor gesunken..."
  },
  Voice_6252_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6253_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6253_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6254_AwakerVoiceContent = {Text = "Ah~!"},
  Voice_6254_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_6255_AwakerVoiceContent = {
    Text = "Riesen-Majestät"
  },
  Voice_6255_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_6256_AwakerVoiceContent = {
    Text = "Versuche das hier!"
  },
  Voice_6256_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6257_AwakerVoiceContent = {
    Text = "Unvermeidliches Opfer"
  },
  Voice_6257_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6258_AwakerVoiceContent = {
    Text = "Überhaupt nicht schlecht, das ist der Ruhm des Kriegers."
  },
  Voice_6258_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6259_AwakerVoiceContent = {
    Text = "Du! Wie konntest du diese Frau hier reinlassen? Richte mir einen eingeschränkten Bereich ein! Lass sie nicht näher als 50 Schritte an mich herankommen!"
  },
  Voice_6259_AwakerVoiceTitle = {
    Text = "Chat·Über Miryam"
  },
  Voice_6259_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Miryam“ wird freigeschaltet"
  },
  Voice_6260_AwakerVoiceContent = {
    Text = "Warum will ich stärker werden? In meinem Stamm werden die Schwachen ihrer Kleider beraubt, die Köpfe rasiert und den schmutzigsten Demütigungen ausgesetzt - die Kosten der Schwäche sind nichts, was jeder ertragen kann."
  },
  Voice_6260_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6260_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6261_AwakerVoiceContent = {
    Text = "Göttin des Glücks, schenk mir deinen Segen!"
  },
  Voice_6261_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6262_AwakerVoiceContent = {
    Text = "Wie erwartet... Hat menschliche Stärke ihre Grenzen...?"
  },
  Voice_6262_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6263_AwakerVoiceContent = {
    Text = "Die Muskeln und Knochen entspannten sich leicht."
  },
  Voice_6263_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6263_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6264_AwakerVoiceContent = {
    Text = "Ist das die Manifestation deines Wunsches, meine Zuneigung zu vertiefen?"
  },
  Voice_6264_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6264_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6265_AwakerVoiceContent = {Text = "Gehe wild!"},
  Voice_6265_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6266_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6266_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6267_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6267_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6268_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6268_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6269_AwakerVoiceContent = {
    Text = "Ah, unvergesslich..."
  },
  Voice_6269_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6270_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6271_AwakerVoiceContent = {
    Text = "Rücksichtsloser Ort!"
  },
  Voice_6271_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6272_AwakerVoiceContent = {Text = "Biu—"},
  Voice_6272_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6273_AwakerVoiceContent = {
    Text = "Mach weiter! Deine Endnoten sind vielversprechend."
  },
  Voice_6273_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6274_AwakerVoiceContent = {
    Text = "Ich habe gehört, dass ein Dieb aus den Slums aufgetaucht ist und eine fette Ratte mitgebracht hat? Hehehe... Sieh zu, wie ich diese Bedrohung für meinen Meister beseitige!"
  },
  Voice_6274_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_6274_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_6275_AwakerVoiceContent = {
    Text = "Komm schon, atme tief durch—"
  },
  Voice_6275_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6276_AwakerVoiceContent = {
    Text = "Interessant, dein Wachstum im Kampf übertrifft bei weitem meine Erwartungen. Mit etwas Zeit könntest du der Nächste werden... Seltsam... Durch die Zeit finde ich immer noch Hoffnung in einem schwachen Wesen wie dir."
  },
  Voice_6276_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6276_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6277_AwakerVoiceContent = {
    Text = "Vielleicht ist jetzt der Zeitpunkt, dies zu sagen. Hör genau zu.\nLotan, das Sternenwesen, fordert dich formell heraus... Aber keine Sorge, ich werde für deine Sicherheit sorgen, bis du deinen Höhepunkt erreichst. Ich werde nicht zulassen, dass mein gewählter Gegner erneut das gleiche Schicksal trifft."
  },
  Voice_6277_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6277_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6278_AwakerVoiceContent = {
    Text = "Hmph... Ich kann nicht nachvollziehen, warum Ramona dich als Partner genehmigen würde. Ich gebe zu, du trägst den Duft der Stärke, aber du bist noch weit davon entfernt, mein Rivale zu sein."
  },
  Voice_6278_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6278_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6279_AwakerVoiceContent = {
    Text = "Ja, schau zu mir auf mit Ehrfurcht. Ich bin das älteste Relikt des Planeten und verdiene Respekt von den Unbedeutsamen – ich habe diesen Planeten seit Äonen bewacht. Es ist nicht zu viel verlangt, als Belohnung um einen spannenden Kampf zu bitten, oder?"
  },
  Voice_6279_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6279_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6280_AwakerVoiceContent = {
    Text = "Hah, ich habe keine Energie, um mit Kindern zu spielen. Wenn du weißt, was gut für dich ist, suche dir einfach eine Ecke und bleib still."
  },
  Voice_6280_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6280_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6281_AwakerVoiceContent = {
    Text = "Seelen ohne Schutz, ich werde euch den ewigen Frieden gewähren"
  },
  Voice_6281_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6282_AwakerVoiceContent = {Text = "Alarm."},
  Voice_6282_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6283_AwakerVoiceContent = {Text = "Alarm."},
  Voice_6283_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6284_AwakerVoiceContent = {
    Text = "Etwas weint... in meinem Kopf."
  },
  Voice_6284_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6284_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6285_AwakerVoiceContent = {
    Text = "Es fühlt sich an, als ob ein Schleier aus weißem Nebel meine Gedanken trübt."
  },
  Voice_6285_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6285_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6286_AwakerVoiceContent = {
    Text = "Der Klang wurde lauter, und der weiße Nebel verdichtete sich."
  },
  Voice_6286_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6286_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6287_AwakerVoiceContent = {
    Text = "Ist das das Geräusch der sich bewegenden Uhrzeiger?"
  },
  Voice_6287_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6287_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6288_AwakerVoiceContent = {
    Text = "Wenn die Glocke läutet, werde ich dann noch hier sein?"
  },
  Voice_6288_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6288_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6289_AwakerVoiceContent = {
    Text = "So ein tollpatschiger Trick... Hmph, du naiver Narr. Wie könntest du nur denken, dass du mich so leicht binden könntest?"
  },
  Voice_6289_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6290_AwakerVoiceContent = {
    Text = "Entschuldigen Sie... Haben Sie meine Schwester, Jenkin, gesehen? Sie ist ein Mädchen, das eine Maus trägt und ziemlich zornig sein kann... Ich könnte sie unmöglich verwechseln."
  },
  Voice_6290_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_6290_UnlockDesc = {
    Text = "Nach dem Abschluss der \"Ermittlungsoperation\" Kapitel 2 freigeschaltet"
  },
  Voice_6292_AwakerVoiceContent = {
    Text = "Danke für Ihre Freundlichkeit."
  },
  Voice_6292_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6293_AwakerVoiceContent = {Text = "Bereit."},
  Voice_6293_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6294_AwakerVoiceContent = {
    Text = "Bitte freu dich darauf."
  },
  Voice_6294_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6295_AwakerVoiceContent = {
    Text = "Singe für dich."
  },
  Voice_6295_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6296_AwakerVoiceContent = {
    Text = "New Keeper? Gib dein Bestes und zeig mir, ob du es wert bist, mein Gegner zu sein."
  },
  Voice_6296_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6297_AwakerVoiceContent = {
    Text = "Obwohl ich ein Pazifist bin, denken \"sie\" eindeutig anders..."
  },
  Voice_6297_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6298_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6298_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6299_AwakerVoiceContent = {
    Text = "Tretet zurück!"
  },
  Voice_6299_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6300_AwakerVoiceContent = {
    Text = "Wie wagst du es, mich so zu erniedrigen..."
  },
  Voice_6300_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6301_AwakerVoiceContent = {
    Text = "Bist du bereit? Casiahs Zaubershow steht kurz bevor! Sieh nicht weg, verpass nicht die Höhepunkte. Es ist Showzeit!"
  },
  Voice_6301_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6302_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6303_AwakerVoiceContent = {Text = "Ha!"},
  Voice_6303_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6304_AwakerVoiceContent = {
    Text = "Ich habe deinen Zeitplan von Sylvia erhalten, das ist zu hart für die Neulinge. Ich verstehe, dass ihr das Richtige tut, aber die neuen Rekruten mit einer schweren Last zu belasten, könnte unnötige Probleme für das Team verursachen. \n Du sagst, du bist kein Neuling? Nein, ich sehe es in deinen Augen, es gibt viele Dinge, die du noch nicht erlebt hast."
  },
  Voice_6304_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6304_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6305_AwakerVoiceContent = {
    Text = "Ich verachte meine eigenen Misserfolge... Ah! Es ist nicht nötig, mich zu trösten! Diese vergangenen Erfahrungen sind die treibende Kraft hinter meinem Wachstum geworden. Bin ich nicht schon deine Unterstützung geworden?"
  },
  Voice_6305_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6306_AwakerVoiceContent = {
    Text = "Ich kann mich mit diesem Mann einfach nicht verstehen. Das Leben besteht doch nicht nur aus Sünde und Strafe, oder? Ist es nicht wichtiger, den Moment zu nutzen?"
  },
  Voice_6306_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Salvador"
  },
  Voice_6306_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Salvador“"
  },
  Voice_6307_AwakerVoiceContent = {
    Text = "Die Zeit läuft ab, lass uns aufbrechen."
  },
  Voice_6307_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6308_AwakerVoiceContent = {
    Text = "Ich hasse Kerzen, die leicht ausgehen, Schwarzbrot und lose Fäden an Röcken... Kein Grund, ich hasse sie einfach. Ist das nicht natürlich?"
  },
  Voice_6308_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6309_AwakerVoiceContent = {
    Text = "Seit du mich zur heiligen Jungfrau gekrönt hast, musst du dich fügen!"
  },
  Voice_6309_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6310_AwakerVoiceContent = {
    Text = "Seit du mich zur heiligen Jungfrau gekrönt hast, musst du dich fügen!"
  },
  Voice_6310_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6311_AwakerVoiceContent = {Text = "Singe."},
  Voice_6311_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6312_AwakerVoiceContent = {
    Text = "„Der Kleiderschrank der Dame“ und „Der Leitfaden für die berufstätige Frau“ sind beide hervorragende Lektüren... Selbst wenn du sie dir nicht leisten kannst, ist es schon ziemlich angenehm, die schönen Kleider einfach nur zu bewundern."
  },
  Voice_6312_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6313_AwakerVoiceContent = {
    Text = "Es ist seltsam. Ich habe normalerweise Schwierigkeiten, mich an Dinge zu erinnern, aber ich habe dich in nur wenigen Tagen auswendig gelernt... Was? Sind es schon drei Monate? Es tut mir leid, ich habe schon wieder vergessen."
  },
  Voice_6313_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6314_AwakerVoiceContent = {
    Text = "Genieße es."
  },
  Voice_6314_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6316_AwakerVoiceContent = {
    Text = "Verbessere deine Gelassenheit weiter."
  },
  Voice_6316_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6317_AwakerVoiceContent = {
    Text = "Übe den Peitschenwirbel zwanzig weitere Male."
  },
  Voice_6317_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6318_AwakerVoiceContent = {
    Text = "Sind meine Bewegungen genau genug?"
  },
  Voice_6318_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6319_AwakerVoiceContent = {
    Text = "Bitte mach weiter!"
  },
  Voice_6319_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6320_AwakerVoiceContent = {
    Text = "Beeil dich, nimm Brown und geh!"
  },
  Voice_6320_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6321_AwakerVoiceContent = {
    Text = "Knien Sie vor dem Thron."
  },
  Voice_6321_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6322_AwakerVoiceContent = {
    Text = "Knien Sie vor dem Thron."
  },
  Voice_6322_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6323_AwakerVoiceContent = {
    Text = "Die verschiedenen Ausdrucksformen der Menschen im Angesicht des Verlangens hören niemals auf, mich zu erstaunen. Leider sind Menschen immer noch zu zerbrechlich, zu unbedeutend... Allein das lässt mich fühlen, als würde eine Katze an meinem Herzen kratzen."
  },
  Voice_6323_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6324_AwakerVoiceContent = {
    Text = "Aus ihren Erinnerungen sah ich viele vergangene Ereignisse, die mit \"Auflösung\" zusammenhängen... Aber jedes Mal, wenn ich dir davon erzählen wollte, brach mein Bewusstsein ab. Ich fürchte, das ist auch ihr Werk."
  },
  Voice_6324_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6325_AwakerVoiceContent = {
    Text = "Wäre es nicht schön, einfach ins Nichts zu verschwinden?"
  },
  Voice_6325_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6326_AwakerVoiceContent = {
    Text = "Ein qualifizierter Diener muss schwach und plump sein – ich mag gehorsame Lämmer."
  },
  Voice_6326_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6327_AwakerVoiceContent = {
    Text = "Unser Treffen muss ein Versprechen der Götter an die Leidenden sein – du bist die blasse Flamme, die das Unheil vertreibt, und ich werde dein Arm sein, der an deiner Seite steht."
  },
  Voice_6327_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6328_AwakerVoiceContent = {
    Text = "Das ist genug!"
  },
  Voice_6328_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6329_AwakerVoiceContent = {
    Text = "Hast du schon versucht, D-Slime direkt in deinen Körper zu injizieren? Der schwarze Schleim wickelt sich wie eine Viper um dein Herz, und dann... Boom! Dein Körper explodiert in einem warmen Pool aus Schleim. Eklig, aber effektiv."
  },
  Voice_6329_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6330_AwakerVoiceContent = {
    Text = "Hmph, ein Zufluchtsort für die Schwachen, um sich zusammenzuhocken."
  },
  Voice_6330_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6331_AwakerVoiceContent = {
    Text = "Ab und zu hilft mir das Mädchen auf dem Motorrad, mein Prothesenbein instand zu halten. Aber hat die Häufigkeit der Wartungschecks in letzter Zeit nicht ein wenig zu hoch gewesen?"
  },
  Voice_6331_AwakerVoiceTitle = {
    Text = "Chat·Über Nautila"
  },
  Voice_6331_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Nautila“ wird freigeschaltet"
  },
  Voice_6332_AwakerVoiceContent = {
    Text = "Unsere Beziehung? Musst du überhaupt fragen? Es ist genau das, was du dir vorstellst!"
  },
  Voice_6332_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6333_AwakerVoiceContent = {
    Text = "Nicht mein bevorzugtes Genre, aber wenn du bestehst."
  },
  Voice_6333_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6334_AwakerVoiceContent = {
    Text = "Deine Dunkelringen werden immer schlimmer... Warum so hart arbeiten? Du solltest mehr wie ich sein und lernen, deine Freizeit zu genießen."
  },
  Voice_6334_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6334_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6335_AwakerVoiceContent = {
    Text = "Warte, ohne meine Erlaubnis..."
  },
  Voice_6335_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6335_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6336_AwakerVoiceContent = {
    Text = "Gut... Es kommt seiner ursprünglichen Form näher."
  },
  Voice_6336_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6336_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6337_AwakerVoiceContent = {
    Text = "Das ist die Kraft, um „Grüne Verderbnis“ abzulehnen... Du hast etwas Berührt, was du nicht hättest berühren sollen. Was mich betrifft, ich werde dich nie wieder loslassen."
  },
  Voice_6337_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6337_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6338_AwakerVoiceContent = {
    Text = "Shh... Der Morgenstrahl im Tal – das muss dein erstes Mal sein, dass du ihn siehst, oder? Dies ist deine Belohnung für Loyalität."
  },
  Voice_6338_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6338_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6339_AwakerVoiceContent = {
    Text = "Dieses Buch, \"Die @1@2 Offenbarung,\" wird dir übergeben. Es hilft, den Geist zu erleuchten oder schnell einzuschlafen"
  },
  Voice_6339_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6339_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6340_AwakerVoiceContent = {
    Text = "Die Sterblichenwelt ist immer noch zu laut. Wenn du mir in der Akademie eine ruhige Ecke finden könntest, wäre das perfekt... Nein, ich brauche keinen Kamin. Nur durch asketische Praktiken können die Götter meine Gebete hören..."
  },
  Voice_6340_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6341_AwakerVoiceContent = {
    Text = "Ist das Wachs oder Honig, der von meinem Körper tropft? Warum leckst du nicht einmal und siehst selbst?"
  },
  Voice_6341_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6341_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6342_AwakerVoiceContent = {
    Text = "Hallo... Schön, Sie kennenzulernen. Mein Name ist Aigis... Bitte tun Sie so, als ob ich nicht existiere!"
  },
  Voice_6342_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6343_AwakerVoiceContent = {
    Text = "Solange ich noch \"Ramona\" bin, sind wir immer noch Partner, oder?"
  },
  Voice_6343_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6344_AwakerVoiceContent = {
    Text = "Diese Dame mit den schweren Augenringen hat mich einmal über das „ewige Leben in der Sonne\" befragt... Sie müsste lediglich zwischen zwei Dimensionen wandern. Dennoch weigert sie sich, den Dimensionstunnel zu betreten. Das war wirklich zum Verzweifeln."
  },
  Voice_6344_AwakerVoiceTitle = {
    Text = "Chat·Über Zwinkern"
  },
  Voice_6344_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Zwinkern“ wird freigeschaltet"
  },
  Voice_6345_AwakerVoiceContent = {
    Text = "Willkommen in meinem Paradies! Bist du bereit, der Peitsche gegenüberzutreten?"
  },
  Voice_6345_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6346_AwakerVoiceContent = {
    Text = "Da Er dich anerkannt hat, werde ich dich nicht als Feind betrachten."
  },
  Voice_6346_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6347_AwakerVoiceContent = {
    Text = "Was meinst du, \"ich habe es genommen\"? Beschuldige mich nicht zu Unrecht! Als ihre Schrauben verschwanden, war ich—Braun, stopp! ... Hehe, tu einfach so, als hättest du nichts gesehen, okay?"
  },
  Voice_6347_AwakerVoiceTitle = {
    Text = "Chat·Über Nautila"
  },
  Voice_6347_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Nautila“ wird freigeschaltet"
  },
  Voice_6348_AwakerVoiceContent = {
    Text = "Das Abenteuer ist ebenso aufregend wie in den Geschichten! Was war das für eine Geschichte...?"
  },
  Voice_6348_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6349_AwakerVoiceContent = {
    Text = "...Hic. Ah, tut mir leid, ich habe wieder zu viel Energie absorbiert."
  },
  Voice_6349_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6350_AwakerVoiceContent = {
    Text = "Einmal in einem menschlichen Körper, verlor ich den gesamten Kontakt zu meinen Verwandten. Ich habe Angst, dass die anderen den Dämonen nicht entkommen sind und dass ich der letzte meines Volkes sein könnte... Bitte, Hüter, rette mich. Lass mich an deiner Seite bleiben, lass mich nicht in der Dunkelheit zurück."
  },
  Voice_6350_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6350_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6351_AwakerVoiceContent = {
    Text = "Als der Planet zerstört wurde, ließ ich meinen Körper hinter mir und übertrug mein Bewusstsein auf einen menschlichen Körper... Doch der schwarze Dämon verfolgte mich unerbittlich, band meinen Geist und verhinderte meine Flucht! Er will die Welt in einen Abgrund der Dunkelheit ziehen!"
  },
  Voice_6351_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6351_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6352_AwakerVoiceContent = {
    Text = "Bitte, Hüter... Solange du mich auf dem Locator bleiben lässt und nicht gehst, werde ich alles tun, außer in die Dunkelheit einzutreten und diesem... diesem schwarzen Ding gegenüberzutreten! Ich kann den Locator nicht verlassen. Nur noch ein wenig, und ich werde die Überreste des Heimatplans finden! Nur noch 1,2 Milliarden Berechnungen übrig!"
  },
  Voice_6352_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6352_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6353_AwakerVoiceContent = {
    Text = "Könntest du deinen Vorratsanteil nutzen, um mir zwei Taschen Koffein-Nahrungsergänzungsmittel zu besorgen? ... Ich kann nicht schlafen. Warum sollte ich schlafen? Nie schlafen! Sobald du die Augen schließt, wird alles zur Dunkelheit... Dunkelheit..."
  },
  Voice_6353_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6353_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6354_AwakerVoiceContent = {
    Text = "Wow! Halte dich von mir fern! Zuerst, beweis, dass du kein Diener der Dunkelheit bist! Ja, Diener. Zieh einfach deine Kleidung aus und zeig mir, dass du nicht diesen ekelhaften schwarzen Schleim auf deinem Körper hast, dann weiß ich, dass du nicht böse bist..."
  },
  Voice_6354_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6354_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6355_AwakerVoiceContent = {
    Text = "Frag nicht, frag nicht...! Du weißt genau, was ich am meisten fürchte und hasse! Dunkelheit, endlose Dunkelheit!"
  },
  Voice_6355_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6356_AwakerVoiceContent = {
    Text = "Eine Methode zur Heilung der Auflösung? So etwas existiert nirgendwo.\nDu fragst, wie ich uninfiziert bleibe? Hehe... solange du \"nicht gesehen wirst\", das ist alles, was nötig ist."
  },
  Voice_6356_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6357_AwakerVoiceContent = {
    Text = "Vielen Dank, Meister."
  },
  Voice_6357_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6358_AwakerVoiceContent = {
    Text = "Sie sind auch glücklich."
  },
  Voice_6358_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6359_AwakerVoiceContent = {
    Text = "Lily ist erwachsen geworden."
  },
  Voice_6359_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6360_AwakerVoiceContent = {
    Text = "Zerdrücken?"
  },
  Voice_6360_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6361_AwakerVoiceContent = {
    Text = "Wie konntest du ihn beschwören! Den nutzlosen Schlafkopf! Faul und ohne Ambitionen... Er war einmal jemand, auf den ich große Hoffnungen hatte! Lass uns gehen! Ich will diesen Kerl nicht sehen!"
  },
  Voice_6361_AwakerVoiceTitle = {
    Text = "Plauderei · Über Tulu"
  },
  Voice_6361_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_6362_AwakerVoiceContent = {Text = "Ekelhaft!"},
  Voice_6362_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6363_AwakerVoiceContent = {
    Text = "Also nervig!"
  },
  Voice_6363_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6364_AwakerVoiceContent = {
    Text = "Next time, let's go see the sea together. Febvre ist in Ordnung, ich kann dein Führer sein; oder irgendwo anders, sogar bis ans Ende der Erde, ich will mit dir gehen."
  },
  Voice_6364_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6364_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6365_AwakerVoiceContent = {
    Text = "Das Meer hat seine eigene Sprache.\n...So kann ich gelegentlich mit den kleinen Fischen im Teich über unsere Heimat plaudern. Wenn du neugierig bist, kann ich dir beim Übersetzen helfen."
  },
  Voice_6365_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6365_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6366_AwakerVoiceContent = {
    Text = "Für die Rettung durch dich fühle ich mich oft so glücklich, dass es mir Angst macht... Bitte sag mir, das ist kein Traum, und du wirst nicht spurlos im Meer verschwinden, oder?"
  },
  Voice_6366_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6366_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6367_AwakerVoiceContent = {
    Text = "Kann dieses Gefühl \"Glück\" genannt werden? Ich... habe nie zuvor gewagt, darauf zu hoffen."
  },
  Voice_6367_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6367_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6368_AwakerVoiceContent = {
    Text = "Mein Körper fühlt sich warm an, als wäre er sanft vom Meer umhüllt. Es ist wirklich unglaublich."
  },
  Voice_6368_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6368_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6369_AwakerVoiceContent = {
    Text = "Ist das ein Fragment von Ihm? Beeindruckend, es besitzt wirklich eine königliche Aura."
  },
  Voice_6369_AwakerVoiceTitle = {
    Text = "Plauderei · Über Tulu"
  },
  Voice_6369_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_6370_AwakerVoiceContent = {
    Text = "Tu das nicht, tu das nicht weiter... Es wird mich finden, es wird mich finden!"
  },
  Voice_6370_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6371_AwakerVoiceContent = {
    Text = "Das sollte mich wach halten."
  },
  Voice_6371_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6372_AwakerVoiceContent = {
    Text = "Es ist vorbei, es ist vorbei, es ist vorbei... Sie werden es definitiv herausfinden..."
  },
  Voice_6372_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6373_AwakerVoiceContent = {
    Text = "Wir haben gewonnen. Bist du glücklich? Wie fühlt sich \"glücklich\" an?"
  },
  Voice_6373_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6374_AwakerVoiceContent = {
    Text = "Dinge, die ich mag? Ich mag Tincts Wiegenlieder... Natürlich ist dein Gesang auch wunderbar!"
  },
  Voice_6374_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6375_AwakerVoiceContent = {
    Text = "Er ist ein verlässlicher Krieger. Ich hielt ihn einst für einen „Gefährten“... Was? Glaubst du, meine Definition von „Gefährte“ ist falsch? Bitte, erleuchte mich."
  },
  Voice_6375_AwakerVoiceTitle = {
    Text = "Chat·Über Goliath"
  },
  Voice_6375_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Goliath“ wird freigeschaltet"
  },
  Voice_6378_AwakerVoiceContent = {Text = "Meteor..."},
  Voice_6378_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6379_AwakerVoiceContent = {Text = "Ah—"},
  Voice_6379_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6380_AwakerVoiceContent = {
    Text = "Ein kontinuierlicher Kraftanstieg, der den ganzen Körper füllt..."
  },
  Voice_6380_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6381_AwakerVoiceContent = {Text = "Flieg!"},
  Voice_6381_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6382_AwakerVoiceContent = {
    Text = "Überhaupt nicht schlecht, du bist nützlicher, als du erscheinst."
  },
  Voice_6382_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6383_AwakerVoiceContent = {
    Text = "Zwanzig, einundzwanzig, vierundzwanzig... Warte, bei welcher Zahl war ich? Eins, zwei, drei..."
  },
  Voice_6383_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6383_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6384_AwakerVoiceContent = {
    Text = "Ich habe endlich herausgefunden, wie viele Materialien ich vorher hatte, damit ich die Reparaturen schneller abschließen kann - Warte, woher kommen die?"
  },
  Voice_6384_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6384_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6385_AwakerVoiceContent = {
    Text = "Dank deiner Hilfe hat sich die Effizienz der aktuellen Reparaturen verbessert. Bald können wir uns auf ein Abenteuer machen!"
  },
  Voice_6385_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6385_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6386_AwakerVoiceContent = {
    Text = "Ich denke, ich fange an, mich an Dinge zu erinnern... Hast du mir gestern einen Schraubenschlüssel Nummer 7 gereicht?"
  },
  Voice_6386_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6386_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6387_AwakerVoiceContent = {
    Text = "Repariere, patchen, vervollständigen! Ein unbekanntes Abenteuer, eine mysteriöse Welt, hier komme ich!"
  },
  Voice_6387_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6387_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6388_AwakerVoiceContent = {Text = "Boom—"},
  Voice_6388_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6389_AwakerVoiceContent = {
    Text = "Täusche dich nicht selbst. Mentale Fesseln sind immer noch Fesseln und können nicht als fair bezeichnet werden."
  },
  Voice_6389_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6390_AwakerVoiceContent = {
    Text = "Jetzt ist die Grenze zwischen mir und dem Erwachten noch verschwommener. Du solltest ein Auge auf mich haben."
  },
  Voice_6390_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6390_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6391_AwakerVoiceContent = {
    Text = "Lass uns gehen und die Welt retten."
  },
  Voice_6391_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6391_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6392_AwakerVoiceContent = {
    Text = "Es fühlt sich erfrischend an, \"Über den Ursprung der Arten\" am Stück zu lesen"
  },
  Voice_6392_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6392_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6393_AwakerVoiceContent = {
    Text = "Ich bin stärker geworden. Lass mich die nächste Mission alleine durchführen, einverstanden?"
  },
  Voice_6393_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6393_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6394_AwakerVoiceContent = {
    Text = "Neben der Kampf Fähigkeit haben sich mein Gedächtnis und logisches Denken nicht viel verbessert. Ich muss immer noch auf meine eigenen Gedanken angewiesen sein."
  },
  Voice_6394_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6394_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6395_AwakerVoiceContent = {
    Text = "Ich möchte, dass sie erleben, wie es sich anfühlt, auf den Kopf gestellt zu werden, alles zu verlieren und von allen getreten zu werden."
  },
  Voice_6395_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6395_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6396_AwakerVoiceContent = {
    Text = "Die Demütigungen, die ich erdulden musste, alles, was ich verloren habe... Ich werde sie zur Rechenschaft ziehen. Ich werde sie alle zur Rechenschaft ziehen."
  },
  Voice_6396_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6396_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6397_AwakerVoiceContent = {
    Text = "So süßer Hass, gewürzt mit dem Blut der Feinde, ist sicher das exquisite Gericht der Welt."
  },
  Voice_6397_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6397_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6398_AwakerVoiceContent = {
    Text = "Ah! Schleich dich nicht von hinten an mich heran!"
  },
  Voice_6398_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6399_AwakerVoiceContent = {
    Text = "Die brennenden Flammen lodern in meiner Brust... Ja, ich habe nie vergessen, noch kann ich jemals vergessen."
  },
  Voice_6399_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6399_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6400_AwakerVoiceContent = {
    Text = "Brenne, o Seele der Poesie."
  },
  Voice_6400_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6401_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6401_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6402_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6402_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6403_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6403_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6404_AwakerVoiceContent = {Text = "(Hmph)"},
  Voice_6404_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6405_AwakerVoiceContent = {
    Text = "Es kitzelt! Genau wie wenn die Dienstmagd mit einer Feder die Sohlen meiner Füße kitzelt. Du *piep* hast es doch nicht absichtlich gemacht, oder?"
  },
  Voice_6405_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6405_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6406_AwakerVoiceContent = {
    Text = "Mögest du süße Träume haben."
  },
  Voice_6406_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6407_AwakerVoiceContent = {
    Text = "Mögest du süße Träume haben."
  },
  Voice_6407_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6408_AwakerVoiceContent = {
    Text = "Gewähre Ruhe...!"
  },
  Voice_6408_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6409_AwakerVoiceContent = {
    Text = "Bewege dich mit Anmut."
  },
  Voice_6409_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6410_AwakerVoiceContent = {
    Text = "Kannst du mich hören? Meine Stimme."
  },
  Voice_6410_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6411_AwakerVoiceContent = {
    Text = "Kannst du mich hören? Meine Stimme."
  },
  Voice_6411_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6412_AwakerVoiceContent = {
    Text = "Es regnet. Der Regen wäscht alles weg: verdorbenes Essen, hartnäckigen Schmutz und Leute wie mich... die Entbehrlichen."
  },
  Voice_6412_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6413_AwakerVoiceContent = {
    Text = "Die rasende Flut der Rache hört niemals auf."
  },
  Voice_6413_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6414_AwakerVoiceContent = {
    Text = "Blut, bade meinen ganzen Körper!"
  },
  Voice_6414_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6415_AwakerVoiceContent = {Text = "Ja!"},
  Voice_6415_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6416_AwakerVoiceContent = {
    Text = "Sieh hierher!"
  },
  Voice_6416_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6417_AwakerVoiceContent = {
    Text = "Ich habe keine Angst."
  },
  Voice_6417_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6418_AwakerVoiceContent = {Text = "Vorsicht!"},
  Voice_6418_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6419_AwakerVoiceContent = {
    Text = "Eine Welt, unberührt von Trauer, unbefleckt von Kummer, frei von Schmerz und unversehrt von dunklem Leiden — vielleicht eine unerreichbare Illusion, aber es ist das Ideal, das ich mein ganzes Leben lang verfolgt habe."
  },
  Voice_6419_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6420_AwakerVoiceContent = {
    Text = "Sieh die Pracht des Ewigen Königreichs!"
  },
  Voice_6420_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6421_AwakerVoiceContent = {
    Text = "Sieh die Pracht des Ewigen Königreichs!"
  },
  Voice_6421_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6422_AwakerVoiceContent = {
    Text = "Opfer brav wieder Tribute? Braver Junge."
  },
  Voice_6422_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6422_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6423_AwakerVoiceContent = {
    Text = "Tut es weh?"
  },
  Voice_6423_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6424_AwakerVoiceContent = {
    Text = "Bleib konzentriert."
  },
  Voice_6424_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6425_AwakerVoiceContent = {
    Text = "Der Verlauf von Jahrtausenden hat mich etwas nachlässig gemacht."
  },
  Voice_6425_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6426_AwakerVoiceContent = {
    Text = "An diesem Tag verbreiteten sich die Flammen der Eifersucht wie ein Meer aus blutroten Rosen in voller Blüte... Alle Gedichte verwandelten sich in zerbröckelte Asche zwischen den scharlachroten Zungen des Feuers."
  },
  Voice_6426_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6426_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6427_AwakerVoiceContent = {
    Text = "Eine neue Technik gelernt!"
  },
  Voice_6427_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6428_AwakerVoiceContent = {
    Text = "Sei vorsichtig."
  },
  Voice_6428_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6429_AwakerVoiceContent = {
    Text = "Der Stab will tanzen!"
  },
  Voice_6429_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6430_AwakerVoiceContent = {
    Text = "Ah, dieses vertraute Gefühl der Leere!"
  },
  Voice_6430_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6431_AwakerVoiceContent = {
    Text = "Die Bewegung der Gelenke ist geschmeidiger geworden."
  },
  Voice_6431_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6432_AwakerVoiceContent = {
    Text = "Dieses unheilige Schwarz ähnelt meinem amorphen Schwertschild... Ah! Sei unbesorgt, mein Herr, mein Wächter-Schwert wird dir niemals schaden!"
  },
  Voice_6432_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6433_AwakerVoiceContent = {
    Text = "Komm schon."
  },
  Voice_6433_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6434_AwakerVoiceContent = {
    Text = "Kaum geschafft."
  },
  Voice_6434_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6435_AwakerVoiceContent = {
    Text = "Ich werde mein Bestes geben."
  },
  Voice_6435_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6436_AwakerVoiceContent = {
    Text = "Hier heute spielen?"
  },
  Voice_6436_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6437_AwakerVoiceContent = {
    Text = "Der Keller ist mit Wasser gefüllt, weich und kalt. So ist mein Körper immer in Feuchtigkeit gehüllt... Als ob ich das einzige physische Wesen zwischen Himmel und Erde bin. Manchmal wünsche ich mir wirklich, in das Wasser zu verschwinden.  \nAber dann würde ich aufhören zu existieren und würde dich niemals treffen."
  },
  Voice_6437_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6437_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6438_AwakerVoiceContent = {
    Text = [[
Hier ist ein Geheimnis... Ich hasse eigentlich Blut. Ich hasse seine Farbe, seinen Geschmack. Aber ich kann nicht ohne es leben.
...Ich schlucke das Blut und erbreche es dann wieder... Ich verachte mich selbst.]]
  },
  Voice_6438_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6438_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6439_AwakerVoiceContent = {
    Text = "Hmm! Dein Blut... schmeckt wie Met. Ich nehme an, ich bin die einzige, die dieses Geheimnis kennt, oder?"
  },
  Voice_6439_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6439_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6440_AwakerVoiceContent = {
    Text = "In meinen Fantasien zieht mich ein tapferer Ritter aus der Dunkelheit und fesselt mich dann mit Ketten. Er kann mich schlagen, verfluchen, alles mit mir tun—Schmerz ist mein Beweis für das Leben.\nWärst du bereit, mein Ritter zu sein?"
  },
  Voice_6440_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6440_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6441_AwakerVoiceContent = {
    Text = "Blut fließt wie ein Fluss. Ich gehöre dir – nie habe ich so stark gefühlt."
  },
  Voice_6441_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6441_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6442_AwakerVoiceContent = {
    Text = "Dies ist der Wille der Drei Göttinnen der Rache!"
  },
  Voice_6442_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6443_AwakerVoiceContent = {
    Text = "Klingen gezoge"
  },
  Voice_6443_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6444_AwakerVoiceContent = {Text = "Nein!"},
  Voice_6444_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6445_AwakerVoiceContent = {
    Text = "So schmutzig! So schmutzig!"
  },
  Voice_6445_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6446_AwakerVoiceContent = {
    Text = "...Aigis, ich sehe es!"
  },
  Voice_6446_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6447_AwakerVoiceContent = {
    Text = "...Aigis, ich sehe es!"
  },
  Voice_6447_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6448_AwakerVoiceContent = {
    Text = "Tipps, natürlich, Tipps. Schau dir diese ahnungslosen Kellner in der Schulkantine an! Sie bereiten nicht einmal die Liegen im Voraus vor und erwarten trotzdem ein zusätzliches Trinkgeld? Träum weiter!"
  },
  Voice_6448_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6449_AwakerVoiceContent = {Text = "Schwarz."},
  Voice_6449_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6450_AwakerVoiceContent = {
    Text = "Lass mich raus!"
  },
  Voice_6450_AwakerVoiceTitle = {
    Text = "Fähigkeit·I·Manie"
  },
  Voice_6451_AwakerVoiceContent = {
    Text = "Tu das nicht..."
  },
  Voice_6451_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins·Depression"
  },
  Voice_6452_AwakerVoiceContent = {
    Text = "Kein Bedarf für Höflichkeit, Blasser Bote. Es sollte keine Barrieren zwischen uns geben, da wir alle Gottes Relikte sind, die zusammen auf diesem schlammigen und prüfenden Weg gehen."
  },
  Voice_6452_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6452_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6453_AwakerVoiceContent = {
    Text = "Natürlich fürchte ich sie nicht, jene armen Seelen, die von dem Schmelzfluch gequält werden. Ich fühle nur Mitgefühl für sie. Ich weiß, dass ich ihr Leiden nicht ertragen kann, aber ich kann ihnen alles geben, was ich habe, wenn es ihnen ein wenig Trost bringt."
  },
  Voice_6453_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6453_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6454_AwakerVoiceContent = {
    Text = "Wirst du mit mir beten, Das Blasse Feuer? Bete für die, die heute in unserer Schlacht gestorben sind. Obwohl verflucht mit Auflösung und Wahnsinn, sind sie immer noch Relikte des Gottes der Güte, unsere Brüder und Schwestern. Mögen sie ihren verdienten Frieden finden."
  },
  Voice_6454_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6454_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6455_AwakerVoiceContent = {
    Text = "Auch wenn die rote Flamme mich unruhig macht, würde ich erneut auf die brennende Plattform für dich treten. Verschwende keinen Gedanken daran, meine blasse Flamme. Mein Opfer ist unbedeutend im Vergleich zu den Segnungen, die du bringst."
  },
  Voice_6455_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6455_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6456_AwakerVoiceContent = {
    Text = "Regret? Nein, natürlich nicht. Mein Tod erleichterte ihr Leiden und kaufte mehr Zeit – das ist genug. Aber... du warst ehrlich mit mir, also werde ich es nicht verbergen: das Scheiterhaufen an diesem Tag hinterließ Narben in meinem Herzen."
  },
  Voice_6456_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6456_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6457_AwakerVoiceContent = {
    Text = "Kannst du mir ein Versprechen geben? Hmm... Lass uns versprechen, dass du, egal was passiert, immer an \"Ramona\" denken wirst, okay?"
  },
  Voice_6457_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6457_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6458_AwakerVoiceContent = {
    Text = "Ich bereue die Entscheidung, das zu werden, was ich bin, nicht; wenn ich die Chance noch einmal hätte, würde ich es immer noch tun. Aber, Hüter, ich habe große Angst... Angst, dass \"Ramona\" keine Spur in dieser Welt hinterlassen wird."
  },
  Voice_6458_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6458_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6459_AwakerVoiceContent = {
    Text = "Keine Sorge, die Augenklappe beeinträchtigt mein Sehvermögen nicht. Wenn überhaupt, hilft sie mir, alles nicht zu sehen."
  },
  Voice_6459_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6459_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6460_AwakerVoiceContent = {
    Text = "Sieht mein Gesichtsausdruck unbekannt aus? Ich habe versucht, ihn zu kontrollieren... Es scheint, als würde ihre Präsenz stärker werden."
  },
  Voice_6460_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6460_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6461_AwakerVoiceContent = {
    Text = "Zu viele Geheimnisse zu lösen, zu viele Menschen zu retten. Ich weiß nicht, wie lange ich noch weitermachen kann, und ich kann nicht jeden schützen... Es ist wirklich hart."
  },
  Voice_6461_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6461_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6462_AwakerVoiceContent = {
    Text = "Willst du immer noch auf mich setzen? Es scheint, dass es nicht so einfach ist, nach eigenem Gutdünken zu leben. Keine Sorge, ich werde mich entspannen, während ich deine Probleme löse."
  },
  Voice_6462_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6462_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6463_AwakerVoiceContent = {
    Text = "In diesem Moment haben wir keine andere Wahl, als unsere wahren Fähigkeiten unter Beweis zu stellen, oder? Wo ist der Tatort? Selbst wenn ich mein ganzes Glück vergeuden muss, werde ich den Verdächtigen auf jeden Fall vor der Frist zurückbringen!"
  },
  Voice_6463_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6463_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6464_AwakerVoiceContent = {
    Text = "Seufz, ich habe so viele Gefallen von dir genommen, ich kann dieses Geheimnis nicht mehr behalten: Tatsächlich könnte ich die unglücklichste Person auf dieser Welt sein"
  },
  Voice_6464_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6464_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6465_AwakerVoiceContent = {
    Text = "Es scheint, dass du meine Worte nicht zu Herzen genommen hast... Egal, ich werde dir trotzdem helfen, durch Feinde zu brechen. Schließlich wurden diese Krallen und Fangzähne, oder?"
  },
  Voice_6465_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6465_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6466_AwakerVoiceContent = {
    Text = "Mein Glück könnte sich nicht auf meine Gefährten übertragen. Du musst das Sprichwort gehört haben, oder? „Ein Kaninchenfuß ist für das Kaninchen nicht glücklich.“"
  },
  Voice_6466_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6466_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6467_AwakerVoiceContent = {
    Text = "Möchtest du das Zeichen von Yu auf deiner Seele einprägen?"
  },
  Voice_6467_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6468_AwakerVoiceContent = {
    Text = "Wünscht du dir meine Macht so sehr?"
  },
  Voice_6468_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6469_AwakerVoiceContent = {
    Text = "Lass dich nicht von meinem Aussehen täuschen; ich war einmal eine Dame... Ich konnte sticken, Tennyson lesen... Oh, und ich konnte singen: Sie fließt wie ein endloser Fluss durch meine Adern~"
  },
  Voice_6469_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6470_AwakerVoiceContent = {
    Text = "Pikman und ich arbeiten an faszinierender Installationskunst und erkunden die Rekonstruktion des abstrakten Repräsentationalismus durch Dekonstruktion des visuellen Primitivismus... Huh, warum ist Aurita ohnmächtig geworden?"
  },
  Voice_6470_AwakerVoiceTitle = {
    Text = "Chat·Über Aurita"
  },
  Voice_6470_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Aurita“ wird freigeschaltet"
  },
  Voice_6471_AwakerVoiceContent = {
    Text = "Willst du, dass ich lächle?\nLily, lächle ich?"
  },
  Voice_6471_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Lächeln"
  },
  Voice_6472_AwakerVoiceContent = {
    Text = "Was für eine Überraschung, ich habe eine gleichwertige Freundschaft gewonnen.\nDoch... ich bitte darum, das Recht zu behalten, dich zu kommandieren, als ein wenig Spaß zwischen uns. Komm heute Nacht in mein Schlafzimmer; ich habe noch viel über menschliche Emotionen zu lernen..."
  },
  Voice_6472_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6472_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6473_AwakerVoiceContent = {
    Text = "Weißt du, was dich am niedlichsten macht? Wenn du \"nein\" zu mir sagst. Deine Nase runzelt sich, deine Augenbrauen heben sich leicht... Ja, genau wie jetzt."
  },
  Voice_6473_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6473_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6474_AwakerVoiceContent = {
    Text = "Ich liebe meine Minions. Diese schönen kleinen Kerlchen, die vor der Auflösung zittern und sich hinter mir verstecken, sind so liebenswert. Die Tränen einer Schönheit sind immer faszinierend. Und du? Hast du Angst vor der Auflösung?"
  },
  Voice_6474_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6474_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6475_AwakerVoiceContent = {
    Text = "Hüter, hast du jemanden, den du nicht magst? Als Gefallen kann ich ihm eine Lehre erteilen. Innerhalb einer Woche wird er eine andere Person sein, die dir gehorsam an den Füßen leckt."
  },
  Voice_6475_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6475_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6476_AwakerVoiceContent = {
    Text = [[
Hmm... Obwohl du langweilig bist, bist du nicht ganz unangenehm. Ab morgen wirst du mir dienen.
Willst du nicht...? Das ist keine Bitte; das ist ein Befehl.]]
  },
  Voice_6476_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6476_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6477_AwakerVoiceContent = {
    Text = "Es ist lange her, dass ich mich so gefühlt habe. Ich werde die Bühne in perfekter Form betreten und eine das Universum umfassende Welle des Klangs nur für dich auslösen."
  },
  Voice_6477_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6477_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6478_AwakerVoiceContent = {
    Text = "Du musst wissen, das ist bedeutungslos."
  },
  Voice_6478_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6478_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6479_AwakerVoiceContent = {
    Text = "Nach dem Pflücken der Siegblume möchte ich eine kleine Belohnung einfordern..."
  },
  Voice_6479_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6480_AwakerVoiceContent = {Text = "Ah!"},
  Voice_6480_AwakerVoiceTitle = {
    Text = "Treffer·Depression·III"
  },
  Voice_6481_AwakerVoiceContent = {
    Text = "Das Luftschiff war eng und klaustrophobisch, wie ein metallener Sarg, der im Raum schwebt. Ich wartete auf meinen Morgenstern, bis du erschienst."
  },
  Voice_6481_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6481_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6482_AwakerVoiceContent = {
    Text = "Wie könnte das sein?!"
  },
  Voice_6482_AwakerVoiceTitle = {
    Text = "Schlag·Raserei·Ich"
  },
  Voice_6483_AwakerVoiceContent = {Text = "Ugh..."},
  Voice_6483_AwakerVoiceTitle = {
    Text = "Treffer·Depression·I"
  },
  Voice_6484_AwakerVoiceContent = {Text = "Autsch..."},
  Voice_6484_AwakerVoiceTitle = {
    Text = "Treffer·Depression·II"
  },
  Voice_6485_AwakerVoiceContent = {
    Text = "Göttliche Strafe!"
  },
  Voice_6485_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6486_AwakerVoiceContent = {
    Text = "Göttliche Strafe!"
  },
  Voice_6486_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6487_AwakerVoiceContent = {
    Text = "Langweilig."
  },
  Voice_6487_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6488_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6488_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6489_AwakerVoiceContent = {
    Text = "Halt immer noch durch."
  },
  Voice_6489_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6490_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6490_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6491_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6491_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6492_AwakerVoiceContent = {
    Text = "Möge der Unerhörte in der brennenden Stille aufgelöst werden."
  },
  Voice_6492_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6493_AwakerVoiceContent = {
    Text = "Sei vorsichtig! Wenn du in einen anderen dimensionalen Raum greifst, bekommst du vielleicht deine Hand nicht zurück!"
  },
  Voice_6493_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6494_AwakerVoiceContent = {
    Text = "Eine Gruppe von Verlierern. Wenn du nicht als Hackfleisch enden willst, solltest du das nächste Mal besser aufpassen."
  },
  Voice_6494_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6495_AwakerVoiceContent = {
    Text = "Oh je, bist du so zärtlich zu mir?\nDas ist problematisch. Wenn das so weitergeht, kann ich nicht mehr warten, bis der Hüter voll ausgewachsen ist..."
  },
  Voice_6495_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6496_AwakerVoiceContent = {
    Text = "Tauche in die Tiefen des freien Willens ein!"
  },
  Voice_6496_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6497_AwakerVoiceContent = {
    Text = "Hass... Es sind definitiv diejenigen, die auf halbem Wege aufgeben. Nur der Gedanke an sie lässt mich letzten Abendessen erbrechen."
  },
  Voice_6497_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6498_AwakerVoiceContent = {
    Text = "Sieh dein Antlitz, o endloser Schädel!"
  },
  Voice_6498_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6499_AwakerVoiceContent = {
    Text = "Sieh dein Antlitz, o endloser Schädel!"
  },
  Voice_6499_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6500_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6500_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6501_AwakerVoiceContent = {Text = "Hah!"},
  Voice_6501_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6502_AwakerVoiceContent = {
    Text = "Vertraust du mir so sehr?"
  },
  Voice_6502_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6502_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6503_AwakerVoiceContent = {
    Text = "Komm zurück."
  },
  Voice_6503_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6504_AwakerVoiceContent = {Text = "Gut!"},
  Voice_6504_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6505_AwakerVoiceContent = {
    Text = "Natürlich weiß ich das, das ist ein weiterer Aspekt von mir. Aber warum wehrt sie sich? Ist es nicht möglich, das Schicksal des Auserwählten zu akzeptieren und das zu erhalten, wofür gebetet wird?"
  },
  Voice_6505_AwakerVoiceTitle = {
    Text = "Idle Talk: Über \"Murphy\""
  },
  Voice_6505_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_6506_AwakerVoiceContent = {
    Text = "Hallo, mein Name ist Daffodil. Ich habe einst einen Austausch mit einem Gast gemacht, der darum bat, dass ich dir unterstütze. Also lass mich hören, was du brauchst.\nOh weh... was du wünschst, hat seinen Preis, nicht wahr?"
  },
  Voice_6506_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6507_AwakerVoiceContent = {
    Text = "*Stille* Was machst du da! Glaub es oder nicht, ich werde dir die Hand abtrennen!"
  },
  Voice_6507_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6508_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6508_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6509_AwakerVoiceContent = {Text = "Hahaha!"},
  Voice_6509_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6510_AwakerVoiceContent = {
    Text = "Rosenstacheln stechen in die Finger und fließen in die Poesie."
  },
  Voice_6510_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6511_AwakerVoiceContent = {
    Text = "Verbeugt euch unter dieser tiefen Tinte des Kummers, werdet ein Klagelied..."
  },
  Voice_6511_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6512_AwakerVoiceContent = {
    Text = "Schau dir das an...!"
  },
  Voice_6512_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6513_AwakerVoiceContent = {Text = "Hmm...!"},
  Voice_6513_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6514_AwakerVoiceContent = {
    Text = "Ankunft der Katastrophen!"
  },
  Voice_6514_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6515_AwakerVoiceContent = {
    Text = "Gib es mir."
  },
  Voice_6515_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6516_AwakerVoiceContent = {
    Text = "...Mein Name, äh, ich kann mich nicht erinnern.\nOh, richtig, \"24\", so nennen sie mich... Nein! Komm nicht raus! Du kannst nicht, nicht jetzt."
  },
  Voice_6516_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6517_AwakerVoiceContent = {
    Text = "Der Fluss der Tintenflecken..."
  },
  Voice_6517_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6518_AwakerVoiceContent = {
    Text = "Erscheinen..."
  },
  Voice_6518_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6519_AwakerVoiceContent = {
    Text = "Ich verdiene den Titel \"Himmlische Stimme\" nicht... Solange du mein Singen genießt, ist das alles, was zählt."
  },
  Voice_6519_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über das Singen"
  },
  Voice_6520_AwakerVoiceContent = {
    Text = "Schmutzige Kleidung muss vor dem nächsten Salon gewechselt werden."
  },
  Voice_6520_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6521_AwakerVoiceContent = {
    Text = "Es holt mich ein, die ewige Dunkelheit... Niemand kann entkommen."
  },
  Voice_6521_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6522_AwakerVoiceContent = {
    Text = "Jedes Mal, wenn ich dich sehe, denke ich an die unsichtbaren Fesseln, die du mir auferlegt hast. Dich leben zu lassen ist mein größter Akt der Toleranz."
  },
  Voice_6522_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6523_AwakerVoiceContent = {
    Text = "Egal wie oft wir neu anfangen, ich werde neben dir gehen."
  },
  Voice_6523_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6524_AwakerVoiceContent = {
    Text = "Möge die Liebe Gottes deine Seele wärmen."
  },
  Voice_6524_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6525_AwakerVoiceContent = {
    Text = "Ich genieße es, ziellos umherzuwandern. Sümpfe, Friedhöfe, Krankenhäuser, verlassene Burgen... An diesen Orten finde ich immer unerwartete Freuden."
  },
  Voice_6525_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6526_AwakerVoiceContent = {
    Text = "Fühlen Sie sich geehrt, denn die Tore des Ewigen Königreichs sind hier."
  },
  Voice_6526_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6527_AwakerVoiceContent = {
    Text = "Hehe—so kitzelig! Aurita will zurückkratzen!"
  },
  Voice_6527_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6528_AwakerVoiceContent = {
    Text = "„Der Tod des Schwans,“ eine Darbietung, in der der Tänzer Körpersprache verwendet, um das Verlangen und den Kampf des Lebens auszudrücken. Ist nicht die verdrehte Gestalt in den Flammen dasselbe?"
  },
  Voice_6528_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6529_AwakerVoiceContent = {
    Text = "Scheibe, scheibe, zerreiße. So wie sie es in der Vergangenheit mit mir gemacht haben... hehe... hehehe!!"
  },
  Voice_6529_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6530_AwakerVoiceContent = {
    Text = "Du solltest dich besser nicht zu nahe an Miss Thais bringen... Nein, ich bin nicht eifersüchtig. Ich habe nur Angst, dass jemand auf die Tricks einer Frau hereinfallen könnte."
  },
  Voice_6530_AwakerVoiceTitle = {
    Text = "Plaudern: Über Thais"
  },
  Voice_6530_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Thais“ wird freigeschaltet"
  },
  Voice_6531_AwakerVoiceContent = {
    Text = "...Vielen Dank."
  },
  Voice_6531_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6531_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6532_AwakerVoiceContent = {
    Text = "Sehr gut... du hast ein scharfes Auge für Menschen."
  },
  Voice_6532_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6532_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6533_AwakerVoiceContent = {
    Text = "Karens Heimat ist schön! Es ist eine Stadt aus Stein in einem See.\nJeden Vollmond tanzen wir still in den Flammen und verehren...\nEhrlich gesagt, als Karen das erste Mal zur Universität kam, vermisste sie jede Nacht ihr Zuhause und weinte im Bett. Aber jetzt hat Karen ein neues Zuhause und Familie. Alles ist besser!"
  },
  Voice_6533_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6533_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6534_AwakerVoiceContent = {
    Text = "Oh~ Sind Sie immer noch nicht zufrieden? Kommen Sie, lassen Sie mich Sie schnell trainieren~"
  },
  Voice_6534_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6535_AwakerVoiceContent = {
    Text = "Schwache Muskeln, abgekämpftes Gesicht – nur diese leblosen Augen haben etwas Wert. Perfekt, um Spinnen zu füttern."
  },
  Voice_6535_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6536_AwakerVoiceContent = {
    Text = "Danke... für alles, was du für Aigis getan hast. Aigis wird ihr Bestes tun... um dich nicht enttäuschen!"
  },
  Voice_6536_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6537_AwakerVoiceContent = {
    Text = "(Schrei der Angst)"
  },
  Voice_6537_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6538_AwakerVoiceContent = {Text = "Nein!"},
  Voice_6538_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6539_AwakerVoiceContent = {
    Text = "Verschone mich..."
  },
  Voice_6539_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6540_AwakerVoiceContent = {
    Text = "(Schrei der Angst)"
  },
  Voice_6540_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6541_AwakerVoiceContent = {
    Text = "Miss Ramonas Schwertkunst ist ganz anders als die Techniken, die ich erlernt habe. Wenn mein Herr es erlaubt, würde ich gerne mit ihr kämpfen... Natürlich! Es ist nur zur Selbstverbesserung!"
  },
  Voice_6541_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6541_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6542_AwakerVoiceContent = {
    Text = "Du fragst, warum ich nicht mit den anderen Kindern spiele? Es ist schwer zuzugeben... In meinem früheren Leben hatte ich wenig Gelegenheit zu spielen. Mein einziger Gefährte war die Prinzessin, der ich diente... Ah! Ein weiteres Monarch in Gegenwart meines Herrn zu erwähnen, bitte verzeih mir mein Versehen."
  },
  Voice_6542_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6542_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6543_AwakerVoiceContent = {
    Text = "Du wirst von der Mythag-Universität als Hüter anerkannt, also werde ich dir die entsprechenden Zugangsberechtigungen gewähren."
  },
  Voice_6543_AwakerVoiceTitle = {
    Text = "Idle Talk · Über \"Protagonist\""
  },
  Voice_6544_AwakerVoiceContent = {
    Text = "Bist du an den \"Sieben Ritterfähigkeiten\" interessiert, die ich gelernt habe? Das ist wunderbar! Ah... ähm... bitte verzeihe meine frühere Unhöflichkeit. Was ich sagen wollte, ist, wenn du gerne Reiterbogenschießen üben möchtest, würde ich es als Ehre empfinden, als dein Trainingspartner zu dienen!"
  },
  Voice_6544_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6544_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6545_AwakerVoiceContent = {
    Text = "Ich bin kein würdiger Ritter. Ob von der abscheulichen Plage oder den eindringenden Feinden, ich habe versagt, meinen ehemaligen Herrn zu beschützen. Jetzt ist das Vertrauen, das du jemandem wie mir schenkst, eine immense Ehre... Ich schwöre auf meine ritterliche Ehre und dieses unbedeutende Leben, dass ich deinen Weg für immer bewachen werde."
  },
  Voice_6545_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6545_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6546_AwakerVoiceContent = {
    Text = "Schädige nicht."
  },
  Voice_6546_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6547_AwakerVoiceContent = {
    Text = "Komm schon~"
  },
  Voice_6547_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6548_AwakerVoiceContent = {Text = "Tippe!"},
  Voice_6548_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6549_AwakerVoiceContent = {
    Text = "Töte nicht."
  },
  Voice_6549_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6550_AwakerVoiceContent = {
    Text = "So bequem~!"
  },
  Voice_6550_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6551_AwakerVoiceContent = {
    Text = "Jetzt sind wir wie Wasser und Öl, die sich nicht vermischen."
  },
  Voice_6551_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6552_AwakerVoiceContent = {
    Text = "Ich habe keine besonderen Favoriten. Wenn ich sagen müsste, das Gefühl, auf Missionen zu gehen, ist ganz schön."
  },
  Voice_6552_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6553_AwakerVoiceContent = {
    Text = "Warum, warum sperrst du mich hier ein? Haha... Ich werde nicht zulassen, dass du Erfolg hast. Ich werde diese Fesseln, dieses Gefängnis... in Fragmente zerreißen!"
  },
  Voice_6553_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6554_AwakerVoiceContent = {
    Text = "Schütze alle."
  },
  Voice_6554_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6555_AwakerVoiceContent = {
    Text = "Ihr Guys, werdet ihr nie müde, die Zaubershow zu beobachten? Setzt euch still, okay? Wenn ihr wieder auf die Bühne lauft, werfe ich euch in eine andere Dimension!"
  },
  Voice_6555_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über die Kinder"
  },
  Voice_6555_UnlockDesc = {
    Text = "Nach dem Erwerb eines der Erwecker \"Aigis,\" \"Jenkin,\" \"Lily,\" \"Murphy,\" \"Karen\" oder \"Aurita\" freigeschaltet"
  },
  Voice_6556_AwakerVoiceContent = {
    Text = "Ich nehme dein Geschenk dankbar an."
  },
  Voice_6556_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6557_AwakerVoiceContent = {
    Text = "Was für ein Dankeschön-Geschenk könnte deiner Hingabe entsprechen?"
  },
  Voice_6557_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6558_AwakerVoiceContent = {
    Text = "Welcher Pracht..."
  },
  Voice_6558_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6559_AwakerVoiceContent = {
    Text = "Hoher Strom erkannt, Wartung wird eingeleitet... Korrektur, warum gibt es keine Überhitzung?"
  },
  Voice_6559_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6559_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6560_AwakerVoiceContent = {
    Text = "Seit dem letzten Erleuchten-Ritual sehe ich fragmentierte Visionen im Zustand der Dämmerung. In ihnen besitze ich einen Caro-Körper wie deinen, und Tränen fallen aus meinen Augen. Ist das ein Traum?"
  },
  Voice_6560_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6560_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6561_AwakerVoiceContent = {
    Text = "Nach jedem Ritual wird im Brustbereich ein hohes Maß an Wärme festgestellt, aber es sind keine energiebasierten Komponenten vorhanden. Weißt du warum?"
  },
  Voice_6561_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6561_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6562_AwakerVoiceContent = {
    Text = "Ich habe es gesehen. Alles sollte <Del:im ewigen Strom verderben>. Entschuldigung, Entschuldigung, das Modul scheint—Warnung, Warnung. Nicht-Erica-Bewusstseinsaktivität nimmt zu. Zerstören, zerstören, des... Hallo, wie kann ich Ihnen helfen?"
  },
  Voice_6562_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6562_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6563_AwakerVoiceContent = {
    Text = "Nach sorgfältiger Analyse deduzierte ich, dass das, was ich in meinem schlafenden Zustand sah, kein Traum im herkömmlichen Sinne war, sondern vielmehr meine <Del: bedauernswerte Caro-Körper, der zerstört werden sollte> Erinnerung. Was die brennende Hitze ähnlich einer Überlast betrifft, könnte das die Emotion namens \"Unwilligkeit\" sein."
  },
  Voice_6563_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6563_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6564_AwakerVoiceContent = {
    Text = "Wenn du die Aufführung sehen möchtest, setz dich ordentlich ins Publikum!"
  },
  Voice_6564_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6564_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6565_AwakerVoiceContent = {
    Text = "Die Flammen des Hasses brennen lodernd, niemals zu löschen."
  },
  Voice_6565_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6567_AwakerVoiceContent = {
    Text = "Der Wille, mit dem ich verschmolzen bin, ist ein lauter; je höher ich aufsteige, desto klarer wird \"Seine\" Stimme... wie die Gänse im Hyde Park, ziemlich laut."
  },
  Voice_6567_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6567_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6568_AwakerVoiceContent = {
    Text = "Ich werde diese Kraft nutzen, um den Verräter zu verschlingen."
  },
  Voice_6568_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6569_AwakerVoiceContent = {
    Text = "...Vielen Dank."
  },
  Voice_6569_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6570_AwakerVoiceContent = {
    Text = "Keeper? Lächerlich. Es ist Zeit, aus diesem unrealistischen Traum aufzuwachen."
  },
  Voice_6570_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6571_AwakerVoiceContent = {
    Text = "Das Blut der Rache brodelt..."
  },
  Voice_6571_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6572_AwakerVoiceContent = {
    Text = "Bewege dich, Minions!"
  },
  Voice_6572_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6573_AwakerVoiceContent = {
    Text = "Drown nicht!"
  },
  Voice_6573_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6574_AwakerVoiceContent = {Text = "Whoosh!"},
  Voice_6574_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6575_AwakerVoiceContent = {
    Text = "Ich habe die Mausfallen am Hintereingang der Cafeteria weggeworfen. Sie sind zu gefährlich. Was ist, wenn der tollpatschige Brown darauf tritt!"
  },
  Voice_6575_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6576_AwakerVoiceContent = {
    Text = "Das fühlt sich so seltsam an... Sterbe ich? Nein, rette mich! Nein!!!"
  },
  Voice_6576_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6576_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6579_AwakerVoiceContent = {
    Text = "Ich will eine Lampe, die niemals ausgeht. Sie hat tatsächlich gesagt, ich solle sie gegen ein Exemplar einer „flügellosen fliegenden Hydra“ eintauschen. Wo kann ich eine so bizarre Art finden?"
  },
  Voice_6579_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Narzisse"
  },
  Voice_6579_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Daffodil“"
  },
  Voice_6582_AwakerVoiceContent = {Text = "Gefahr."},
  Voice_6582_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6583_AwakerVoiceContent = {Text = "Warnung."},
  Voice_6583_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6584_AwakerVoiceContent = {Text = "Treffer."},
  Voice_6584_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6585_AwakerVoiceContent = {
    Text = "Ein Schatz, der glitzert wie Bonbonverpackungen... Aigis wird ihn sehr schätzen."
  },
  Voice_6585_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6586_AwakerVoiceContent = {
    Text = "Schaden erlitten."
  },
  Voice_6586_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6587_AwakerVoiceContent = {
    Text = "Mein Geschäft existiert in jeder Dimension, an jedem Ort im Universum, und natürlich kann es auch hier sein. Außerdem mag ich diese sorglosen Kinder in Mythag."
  },
  Voice_6587_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6588_AwakerVoiceContent = {
    Text = "Hass... Grüne Paprika schmecken schrecklich."
  },
  Voice_6588_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6589_AwakerVoiceContent = {
    Text = "Unsere Beziehung ist wie die zwischen einem Segel und einem Boot. Ohne das Boot sollte das Segel nicht existieren; ohne das Segel kann das Boot nicht weit reisen. Ist das nicht richtig?"
  },
  Voice_6589_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6590_AwakerVoiceContent = {
    Text = "Die fromme Tänzerin ist tot, und der Lästerer der Kunst ist ebenfalls tot, beide verbrannt in Flammen, die nach Teer riechen. Der Tod ist nicht das Ende, sondern der Anfang, denn nur Menschen sterben; Tanz und Kunst sind ewig."
  },
  Voice_6590_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6590_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6591_AwakerVoiceContent = {
    Text = "Danke für Ihr Verständnis. Vielleicht ist jetzt die Zeit, um mich mit meinem vergangenen Selbst zu versöhnen... Ich glaube, ich tue das Richtige und habe das Erbe meiner Familie im Tanzen nicht beschämt. Ich werde auf die Bühne treten, die Sie vorbereitet haben, und glänzen, wie Sie es wünschen."
  },
  Voice_6591_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6591_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6592_AwakerVoiceContent = {
    Text = "Sei vorsichtig."
  },
  Voice_6592_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6593_AwakerVoiceContent = {
    Text = "Willst du, dass ich die Bühne betrete und strahle?\nDas ist jetzt unmöglich. Diese Augen sind von Hass verzehrt. Alles, was ich tun kann, ist, alles zu Asche zu verbrennen."
  },
  Voice_6593_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6593_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6594_AwakerVoiceContent = {
    Text = "Verstehst du dieses Gefühl? Drehen, drehen, drehen, niemals stoppen. Knie bis zum Äußersten gestreckt, Zehen bluten schwarz, durchtränken die Ballettschuhe, doch niemals innehalten. Alles nur, weil ich das Schicksal eines Spielzeugs nicht akzeptieren will..."
  },
  Voice_6594_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6594_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6595_AwakerVoiceContent = {
    Text = "Ich habe keine fähigen Hof-Tänzer, graziöse Ballettmeister oder Adelige, die Sublimität und Schönheit schätzen, verbrannt. Ich habe nutzlose Narren verbrannt, die ihren Körper verkaufen, Kriecher, die andere missachten, und widerwärtige Wesen, die im Lust verloren sind... Du verstehst mich, richtig?"
  },
  Voice_6595_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6595_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6596_AwakerVoiceContent = {
    Text = "Ich mag diese Leute mit schlüpfrigen Tentakeln nicht, und ich mag den Ozean nicht... Gib mir nicht diesen wissenden Blick! Ich bin kein Kind, das sich vor seinen Eltern fürchtet!"
  },
  Voice_6596_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6596_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6597_AwakerVoiceContent = {
    Text = "Deine Großzügigkeit wird sehr geschätzt..."
  },
  Voice_6597_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6598_AwakerVoiceContent = {
    Text = "Verschwinde!"
  },
  Voice_6598_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6599_AwakerVoiceContent = {
    Text = "Verschwinde!"
  },
  Voice_6599_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6600_AwakerVoiceContent = {
    Text = "Beeil dich, nimm Brown und geh!"
  },
  Voice_6600_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6601_AwakerVoiceContent = {
    Text = "Tu das nicht..."
  },
  Voice_6601_AwakerVoiceTitle = {
    Text = "Verteidigung·Depression"
  },
  Voice_6602_AwakerVoiceContent = {
    Text = "Verschwinde!"
  },
  Voice_6602_AwakerVoiceTitle = {
    Text = "Verteidigung·Manie"
  },
  Voice_6603_AwakerVoiceContent = {
    Text = "Wer ist Leigh? Oh, die Frau, die mich bat, sie zu schlagen. Haha, interessant... Dieser Ort ist doch nicht so langweilig."
  },
  Voice_6603_AwakerVoiceTitle = {
    Text = "Chat·Über Leigh"
  },
  Voice_6603_UnlockDesc = {
    Text = "Erwirb den Erwecker „Leigh“ und schalte frei"
  },
  Voice_6604_AwakerVoiceContent = {
    Text = "Der Sonnenuntergang auf dem kleinen Hügel erinnert mich oft an meine Tage in Cleveland... Cleveland, ich kann nicht glauben, dass ich diesen Namen immer noch erinnere, der Ort, der mir diese Wunden zugefügt hat."
  },
  Voice_6604_AwakerVoiceTitle = {
    Text = "Idle-Gespräch: Über Dämmerung"
  },
  Voice_6605_AwakerVoiceContent = {
    Text = "Ah... die Sterne... sind gefallen..."
  },
  Voice_6605_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6606_AwakerVoiceContent = {
    Text = "Zweifellos Menschen. Gibt es irgendwelche Kreaturen, die schmutziger sind als Menschen?"
  },
  Voice_6606_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6607_AwakerVoiceContent = {
    Text = "Es ist jetzt!"
  },
  Voice_6607_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6608_AwakerVoiceContent = {Text = "Hey!"},
  Voice_6608_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6609_AwakerVoiceContent = {
    Text = "Auflösung? Hmm... Ja! Eiscreme schmilzt! Aber wenn wir es teilen, können wir es essen, bevor es vollständig zu Sahne wird!"
  },
  Voice_6609_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6610_AwakerVoiceContent = {
    Text = "Ich werde diese Stärke nutzen, um dich zu beschützen."
  },
  Voice_6610_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6610_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6611_AwakerVoiceContent = {
    Text = "Oh mein Gott, keine Rückgabe von hier verkauften Gegenständen! Du benötigst wirklich ein U-Boot, um in die Aequor einzutauchen, richtig?"
  },
  Voice_6611_AwakerVoiceTitle = {
    Text = "Chat·Über Caecus"
  },
  Voice_6611_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Caecus“ wird freigeschaltet"
  },
  Voice_6612_AwakerVoiceContent = {
    Text = "Die beste Bühne! Sowohl die Lehrer als auch die Schüler der Mythag-Universität können verstehen, dass meine Aufführung wahre Magie ist! Das muss es sein, was sie einen Seelenverwandten eines Magiers nennen, oder?"
  },
  Voice_6612_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6613_AwakerVoiceContent = {
    Text = "Die Ordnung des Universums verschiebt sich hier; die Zukunft der Zerstörung ist der Glaube des Magiers!"
  },
  Voice_6613_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6613_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6614_AwakerVoiceContent = {
    Text = "Kann Aigis hier ein wenig länger bleiben? Ich werde still bleiben, keinen Ton von mir geben und mein Bestes tun, um dich nicht zu stören..."
  },
  Voice_6614_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6614_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6615_AwakerVoiceContent = {
    Text = "Entblöße das Wesen der Welt mit menschlicher Intelligenz...!"
  },
  Voice_6615_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6616_AwakerVoiceContent = {
    Text = "In meinen Träumen höre ich oft das Geräusch der Gezeiten, das immer leiser wird. Ich weiß, ich könnte hier für immer bleiben, Mensch."
  },
  Voice_6616_AwakerVoiceTitle = {
    Text = "Chat·Über Aequor"
  },
  Voice_6617_AwakerVoiceContent = {
    Text = "Mehr Erinnerungen, mehr Emotionen, mehr Träume—"
  },
  Voice_6617_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6617_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6618_AwakerVoiceContent = {
    Text = "Es fängt an sich zu ändern!"
  },
  Voice_6618_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6619_AwakerVoiceContent = {
    Text = "Blinzle nicht!"
  },
  Voice_6619_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_6620_AwakerVoiceContent = {
    Text = "Wenn Er geboren wird... muss ich diese Demütigung nicht mehr ertragen."
  },
  Voice_6620_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6621_AwakerVoiceContent = {
    Text = "Wählt mich, wählt mich! Wo eine Party ist, ist Karen!"
  },
  Voice_6621_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6622_AwakerVoiceContent = {
    Text = "Hmm? Interessierst du dich für mich? Ich nehme an... du bist bereit, den Preis zu zahlen?"
  },
  Voice_6622_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6623_AwakerVoiceContent = {
    Text = "Keine Gnade, keine Gnade...!"
  },
  Voice_6623_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6624_AwakerVoiceContent = {
    Text = "Immer noch von den Farben der Sterne singen."
  },
  Voice_6624_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6625_AwakerVoiceContent = {
    Text = "Gesang, Gesang!"
  },
  Voice_6625_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_6626_AwakerVoiceContent = {
    Text = "Liebe Mama!"
  },
  Voice_6626_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6627_AwakerVoiceContent = {
    Text = "Komm schon."
  },
  Voice_6627_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6628_AwakerVoiceContent = {
    Text = "Sei vorsichtig."
  },
  Voice_6628_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6629_AwakerVoiceContent = {
    Text = "Erwecker könnten aus Neugier essen, aber Nahrung ist für unser Dasein nicht wesentlich. Daher ist es nicht nötig, mich für jeden Nachmittagstee zu rufen. Zuckeraufnahme beschleunigt nur den Verschleiß der Gelenke dieses Körpers."
  },
  Voice_6629_AwakerVoiceTitle = {
    Text = "Plauderei: Bei Nachmittags-Tee"
  },
  Voice_6632_AwakerVoiceContent = {
    Text = "Bitte, schone meinen Meister. Karen... tu, was du willst mit Karen!"
  },
  Voice_6632_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6633_AwakerVoiceContent = {
    Text = "Sind all diese für Lily essbar?"
  },
  Voice_6633_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6633_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6634_AwakerVoiceContent = {
    Text = "Nervig? Darf ich das sagen? Aigis hasst es, sich immer machtlos zu fühlen... Aber wenn ich das sage, wird Jenkin wirklich wütend..."
  },
  Voice_6634_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6635_AwakerVoiceContent = {
    Text = "Zu Asche verwandeln."
  },
  Voice_6635_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6636_AwakerVoiceContent = {
    Text = "Zu Asche verwandeln."
  },
  Voice_6636_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6637_AwakerVoiceContent = {
    Text = "Gut gemacht, Hüter. Also, wen willst du, dass ich diesmal töte?"
  },
  Voice_6637_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6637_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6638_AwakerVoiceContent = {
    Text = "Auflösung ist der Grund, warum diese Akademie gegründet wurde und warum wir uns getroffen haben. Um den Funken der Menschheit vor der Auflösung zu retten, lass uns unser Bestes tun, Partner."
  },
  Voice_6638_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6639_AwakerVoiceContent = {
    Text = "Ich kann die Feindseligkeit der Dame spüren; es muss meine Liebe zu dir sein, die ihre Eifersucht entfacht hat... Sieh mal, selbst der Mund des großen Walfischs ist vor Neid geöffnet."
  },
  Voice_6639_AwakerVoiceTitle = {
    Text = "Chat·Über Lotan"
  },
  Voice_6639_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Lotan“ wird freigeschaltet"
  },
  Voice_6640_AwakerVoiceContent = {
    Text = "Meister, Meister! Karen sah heute bei Harold eine unglaublich schöne Camee-Brosche! Könntest du sie für Karen kaufen? Es ist mein Lebenswunsch!"
  },
  Voice_6640_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6641_AwakerVoiceContent = {
    Text = "Ich werde dein Licht in der Dunkelheit sein, aber dieser Zeitraum ist nicht ewig."
  },
  Voice_6641_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6642_AwakerVoiceContent = {
    Text = "Mutter, es tut weh... Mutter..."
  },
  Voice_6642_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6643_AwakerVoiceContent = {
    Text = "Gib auf! Der Sieg gehört mir!"
  },
  Voice_6643_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6644_AwakerVoiceContent = {
    Text = "Gib auf! Der Sieg gehört mir!"
  },
  Voice_6644_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6645_AwakerVoiceContent = {
    Text = "Auflösung... Ich muss gestehen, meine Gehirnkapazität ist begrenzt; ich kann solche komplexen Krankheiten nicht verstehen... Wenn du irgendwelche Maschinen repariert haben musst, komm zu mir!"
  },
  Voice_6645_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6646_AwakerVoiceContent = {
    Text = "Oh nein! Aurita wurde gefunden! Als Strafe für das Verlieren kannst du eine Bitte an Aurita richten—bitte lass sie nur nicht zum Unterricht gehen, bitte sehr!"
  },
  Voice_6646_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6647_AwakerVoiceContent = {
    Text = "Den Weg für Seine Rückkehr freimachen..."
  },
  Voice_6647_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6648_AwakerVoiceContent = {
    Text = "Eines Tages wird Onkel Ornn mich wieder in mein Unterwasserheim begrüßen. Bis dahin kann ich widerwillig mit dir befreundet sein."
  },
  Voice_6648_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6648_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6649_AwakerVoiceContent = {
    Text = "\"Unsere Familie trägt eine große Blutlinie; der Auserwählte wird in Aequor ewigen Frieden genießen.\"\nIch hätte nie erwartet, diesen Frieden zu empfinden, nachdem ich das Meer verlassen und zur Akademie gekommen bin. Du bist anders als die, die mich mobben, also werde ich nicht zulassen, dass andere dich auch mobben."
  },
  Voice_6649_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6649_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6650_AwakerVoiceContent = {
    Text = "Super robustes, maßgeschneidertes Material!"
  },
  Voice_6650_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6651_AwakerVoiceContent = {
    Text = "In dieser Hülle, die mit menschlichen Elementen durchzogen ist, gefangen zu sein, macht mich krank. Ich habe endlich die Vergangenheit losgelassen, und jetzt muss ich sie wieder hervorrufen..."
  },
  Voice_6651_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6651_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6652_AwakerVoiceContent = {
    Text = "Ich weiß, der Erbe des großen Blutlinien hat erneut zu einem Handlanger der Menschen geworden. Aber denk nicht, dass du mich nach Belieben herumkommandieren kannst."
  },
  Voice_6652_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6652_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6653_AwakerVoiceContent = {
    Text = "Hmph, du schwache Mensch hast tatsächlich etwas Talent im Kommando, aber dieser minderwertige Körper hindert mein volles Potenzial."
  },
  Voice_6653_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6653_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6654_AwakerVoiceContent = {
    Text = "Mein Körper wird heißer."
  },
  Voice_6654_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6655_AwakerVoiceContent = {
    Text = "Entkomme... Ich muss fliehen! Ich muss hier weg!"
  },
  Voice_6655_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6656_AwakerVoiceContent = {
    Text = "Entkomme... Ich muss fliehen! Ich muss hier weg!"
  },
  Voice_6656_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6657_AwakerVoiceContent = {
    Text = "Danke für Ihre Bemühungen. Erlauben Sie mir, Sie entsprechend zu belohnen."
  },
  Voice_6657_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6658_AwakerVoiceContent = {
    Text = "Schon in Ordnung."
  },
  Voice_6658_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6659_AwakerVoiceContent = {
    Text = "(Schmerzgrunzen)"
  },
  Voice_6659_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6660_AwakerVoiceContent = {
    Text = "Mensch, obwohl du zerbrechlich bist, hat mich dein Glauben bewegt. Ich bin bereit, deine Waffe zu werden. Lass uns zusammen Chaos stiften!"
  },
  Voice_6660_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6660_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6662_AwakerVoiceContent = {
    Text = "Das ist mein Salon."
  },
  Voice_6662_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6664_AwakerVoiceContent = {
    Text = "Die Akademie der Gleichheit... Ich frage mich, welche törichten Träume du hegst. Auch wenn du nichts Unrechtes getan hast, werden sie dich trotzdem unter ihren Fuß trampeln. Ich kenne dieses Gefühl."
  },
  Voice_6664_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6665_AwakerVoiceContent = {
    Text = "Dies ist die Quelle aller Unreinheit..."
  },
  Voice_6665_AwakerVoiceTitle = {
    Text = "Exalt · Depression"
  },
  Voice_6666_AwakerVoiceContent = {
    Text = "Ich wurde bestraft, weil ich die Besatzung nicht geschützt habe. Sie sagten, dass die vermissten Besatzungsmitglieder aufgrund meiner Nachlässigkeit niemals mit ihren Familien wieder vereinen würden... Ist das, was Auflösung ist?"
  },
  Voice_6666_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6667_AwakerVoiceContent = {
    Text = "Näher zu meinem Herrn..."
  },
  Voice_6667_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6668_AwakerVoiceContent = {
    Text = "Warum? Warum möchtest du nicht... erwachen?"
  },
  Voice_6668_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6669_AwakerVoiceContent = {
    Text = "Ich bin Horla aus Cité, Pseudonym... Ich habe versprochen, es niemandem zu verraten. Entschuldige bitte, aber nenne mich einfach Horla."
  },
  Voice_6669_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6670_AwakerVoiceContent = {
    Text = "Ich lehne alle Ungerechtigkeiten ab, wobei Verrat das Schlimmste ist. In der Armee, wenn du deinen Kameraden nicht vertrauen kannst oder es dich nicht wagt, sie deinen Rücken zu schützen, wird die gesamte Einheit auseinanderfallen."
  },
  Voice_6670_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_6671_AwakerVoiceContent = {
    Text = "Warum erscheinst du so dunkel, aber so strahlend? ... Nein, egal, ignorier einfach mein Gerede."
  },
  Voice_6671_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_6672_AwakerVoiceContent = {Text = "(Stöhnen)"},
  Voice_6672_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6673_AwakerVoiceContent = {Text = "(Grunzen)"},
  Voice_6673_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6674_AwakerVoiceContent = {Text = "Was?!"},
  Voice_6674_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6675_AwakerVoiceContent = {
    Text = "Ich liebe das Leben, und ich liebe das Licht. Ich möchte, dass Ohnmacht aus ihrer abgeschiedenen Schale hervorkommt und die Welt mit eigenen Augen und Ohren erfährt."
  },
  Voice_6675_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6676_AwakerVoiceContent = {
    Text = "Du kannst mich nicht sehen!"
  },
  Voice_6676_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6677_AwakerVoiceContent = {
    Text = "Muss die Wartungsarbeit fortgesetzt werden?"
  },
  Voice_6677_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6678_AwakerVoiceContent = {
    Text = "Teilewartung wurde abgeschlossen."
  },
  Voice_6678_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6679_AwakerVoiceContent = {
    Text = "Menschen können verraten, aber Werkzeuge werden es niemals tun. Wenn sie richtig eingesetzt werden, kann Auflösung auch ein Werkzeug für Rache werden."
  },
  Voice_6679_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_6680_AwakerVoiceContent = {
    Text = "Nach einem Jahrtausend des Wartens ist der Moment endlich gekommen... Ich bin der einzig wahre Herrscher der Perishiten!"
  },
  Voice_6680_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_6680_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_6681_AwakerVoiceContent = {
    Text = "War das ein Hybrid von Aequor, an dem wir gerade vorbeigegangen sind? Hmm... sieh dir diesen geraden Rücken an. Heute Nacht werde ich sehen, wie er um Gnade winselt."
  },
  Voice_6681_AwakerVoiceTitle = {
    Text = "Chat·Über Caecus"
  },
  Voice_6681_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Caecus“ wird freigeschaltet"
  },
  Voice_6682_AwakerVoiceContent = {
    Text = "Kraft kehrt allmählich in meine Hände zurück... Der nächste Schritt ist, die Kraft zu ergreifen, die mir rechtmäßig gehört!"
  },
  Voice_6682_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6682_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6683_AwakerVoiceContent = {
    Text = "Überhaupt nicht schlecht. Wir sind einen Schritt näher daran, den heuchlerischen Schleier dieser Frau abzureißen."
  },
  Voice_6683_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_6683_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_6684_AwakerVoiceContent = {
    Text = "Beruhige dich, beruhige dich, beruhige dich..."
  },
  Voice_6684_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6685_AwakerVoiceContent = {
    Text = "Kein Grund, dir Sorgen zu machen. Meine Schmerzgrenze könnte weit über deiner Vorstellungskraft liegen."
  },
  Voice_6685_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6685_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6686_AwakerVoiceContent = {
    Text = "Wenn du mich fragst, sind schöne Narren die besten. Leider gibt es hier zu viele clevere, aber nutzlose Köpfe."
  },
  Voice_6686_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6687_AwakerVoiceContent = {
    Text = "Angetrieben von der Kernfusion eines roten Riesen, ergänzt durch die Energie eines kollabierenden Sterns, könntest du eine perpetuelle Bewegungmaschine starten und eine ewige Lampe entzünden... Eh? Du sagst, es gibt keinen Weg, hier eine perpetuelle Bewegungmaschine zu bauen, und keinen roten Riesen? Hmm..."
  },
  Voice_6687_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6688_AwakerVoiceContent = {
    Text = "Das Blut des Feindes ist noch nicht vollständig entwichen."
  },
  Voice_6688_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6689_AwakerVoiceContent = {
    Text = "Gib sie alle... mir!"
  },
  Voice_6689_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6690_AwakerVoiceContent = {
    Text = "Gib sie alle... mir!"
  },
  Voice_6690_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6691_AwakerVoiceContent = {
    Text = "Es ist Zeit, zum Schlachtfeld zu gehen."
  },
  Voice_6691_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6692_AwakerVoiceContent = {
    Text = "Es ist Zeit!"
  },
  Voice_6692_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_6693_AwakerVoiceContent = {
    Text = "Wenn ich schlafe, verursachen überquellende Träume seelische Unruhe. Also komm nicht zu mir, während ich schlafe, und wecke mich nicht leichtfertig auf."
  },
  Voice_6693_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Schlummer"
  },
  Voice_6694_AwakerVoiceContent = {
    Text = "Es ist Zeit!"
  },
  Voice_6694_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6695_AwakerVoiceContent = {
    Text = "Obwohl Herbert eine furchterregende Person ist, sind seine Katzen sehr sanft... Nein, um genau zu sein, es gibt zwei Katzen, richtig?"
  },
  Voice_6695_AwakerVoiceTitle = {
    Text = "Gespräche ohne Eile · Über Herbert"
  },
  Voice_6695_UnlockDesc = {
    Text = "Nach dem Abschluss der \"Ermittlungsoperation\" Kapitel 2 freigeschaltet"
  },
  Voice_6696_AwakerVoiceContent = {
    Text = "Diese Frau Murphy kleidet sich zu auffällig... Auf keinen Fall, Karen kann nicht gegen sie verlieren!\nOder vielleicht, töte sie einfach..."
  },
  Voice_6696_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Murphy"
  },
  Voice_6696_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_6697_AwakerVoiceContent = {Text = "Ah~"},
  Voice_6697_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6698_AwakerVoiceContent = {
    Text = "Fühlst du dich wohl?"
  },
  Voice_6698_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6699_AwakerVoiceContent = {
    Text = "Als wir mit der Mythag-Universität zusammengearbeitet haben, wurde klar vereinbart, dass ich nicht in den Kampf geschickt werde..."
  },
  Voice_6699_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6699_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6700_AwakerVoiceContent = {
    Text = "Lass dich nicht mitreißen. Manchmal ist die Grenze zwischen edel und niederträchtig nur ein einziger Schritt entfernt."
  },
  Voice_6700_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6700_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6701_AwakerVoiceContent = {
    Text = "Faros begrüßt dich. Mich hierher zu beschwören, muss bedeuten, dass du bereit bist, die Segel zu setzen."
  },
  Voice_6701_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_6702_AwakerVoiceContent = {
    Text = "Yahoo—Ich bin so müde, darf ich jetzt spielen gehen!"
  },
  Voice_6702_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_6703_AwakerVoiceContent = {
    Text = "Ah... Seine Brillanz ist so intensiv und blendend, unmöglich zu ignorieren. Es war törichter Eifer, der meine Sinne trübte... Nein, ich kann keine Ausreden für meine Dummheit machen."
  },
  Voice_6703_AwakerVoiceTitle = {
    Text = "Plauderei · Über Tulu"
  },
  Voice_6703_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Tulu“"
  },
  Voice_6705_AwakerVoiceContent = {
    Text = "Die Sterne im Traum, auf dem Weg dorthin, wo sie hingehören, zeigen auf das Reich Gottes!"
  },
  Voice_6705_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6706_AwakerVoiceContent = {
    Text = "Denkst du nicht, es ist faszinierend, alles auf sein Ende zuzuschieben und die Gesetze der Welt zum Stillstand zu bringen?"
  },
  Voice_6706_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6707_AwakerVoiceContent = {Text = "Trink auf!"},
  Voice_6707_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6708_AwakerVoiceContent = {
    Text = "Schmerzhaft!"
  },
  Voice_6708_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_6709_AwakerVoiceContent = {
    Text = "Gib den Kampfbefehl ein."
  },
  Voice_6709_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6710_AwakerVoiceContent = {
    Text = "Während meiner Tage des Umherirrens unter den Sternen träumte ich unzählige Male von diesem Moment... Danke, dass du mich mit Tinct wiedervereint hast."
  },
  Voice_6710_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über Tinktur"
  },
  Voice_6710_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Tinktur“ wird freigeschaltet"
  },
  Voice_6711_AwakerVoiceContent = {
    Text = "Die Mythag-Universität ist ein großartiger Ort, besonders mit dem Untergrund-Casino, das jede Woche öffnet...\nHuh, wusstest du das nicht? Ups, habe ich die Katze aus dem Sack gelassen..."
  },
  Voice_6711_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6712_AwakerVoiceContent = {
    Text = "\"Widerstehe der Auflösungs-Krise,\" ha, menschliche Selbstzufriedenheit ist wahrlich lächerlich."
  },
  Voice_6712_AwakerVoiceTitle = {
    Text = "Chat·Über die Mythag-Universität"
  },
  Voice_6713_AwakerVoiceContent = {
    Text = "Schließlich sind Menschen nur oberflächliche Wesen. Ein paar Worte, ein Hinweis, und sie beginnen, gegeneinander zu kämpfen... Seufz, dieses Niveau an Konflikt reicht kaum aus, um zu inspirieren."
  },
  Voice_6713_AwakerVoiceTitle = {
    Text = "Idle Talk·Über Menschen"
  },
  Voice_6714_AwakerVoiceContent = {
    Text = "Vielleicht war ich kurzsichtig, dich als gewöhnlichen Menschen zu betrachten und zu schnell zu urteilen. Ich bin neugierig – wie hält ein Nicht-Gläubiger wie du seinen Entschluss aufrecht? Das ist keine Frage von der See-Mutter, sondern Miryams Anfrage. Kannst du... es mir beantworten?"
  },
  Voice_6714_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6714_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6715_AwakerVoiceContent = {
    Text = "So einzigartig du, wirst du nicht müde von dieser oberflächlichen und turbulenten Welt? Ich glaube wirklich, dass das ewige Reich der Ort ist, wo du hingehörst. Du wirst über das Land der Götter wandeln, im heiligen Teich baden und im fruchtbaren Boden Wurzeln schlagen... Begleite mich auf meiner heiligen Reise und transzendiere gemeinsam mit mir die sterbliche Ebene. Dann werden wir Seite an Seite neben dem Thron stehen und die Freude am Wiederaufbau des Göttlichen Reichs teilen..."
  },
  Voice_6715_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_6715_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_6716_AwakerVoiceContent = {
    Text = "Wir sind alle bloße Sterbliche, die im Staub kriechen, aber der Weise ist anders. Er ist der Gesandte, eine göttliche Inkarnation. Sein Rat hallt mit den Worten der Götter wider und leitet die Zivilisation zur Unsterblichkeit... Ich erwarte nicht, dass du jetzt deinen Glauben an ihn verstehst, aber eines Tages wirst du vor seinem Thron knien."
  },
  Voice_6716_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6716_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_6717_AwakerVoiceContent = {
    Text = "Die Auserwählten sind wirklich gesegnet, oder nicht? Ihnen wurde göttliche Macht und verlängerte Lebensdauer gewährt. Wenn das Königreich Gottes erneut herabsteigt und Sein Wille auf Erden wiederhergestellt wird, werden sie glorreiche Gläubige werden. Ist das nicht ein immenses Vermögen und ein Segen für die schwache Menschheit?"
  },
  Voice_6717_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6717_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6718_AwakerVoiceContent = {
    Text = "Die Freude, im göttlichen Licht zu baden, ist jenseits des Verständnisses von jemandem wie dir, der keinen Glauben hat... Möge mein Gott dir vergeben, dir deine Unwissenheit und Unverschämtheit vergeben."
  },
  Voice_6718_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6718_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6719_AwakerVoiceContent = {
    Text = "Lass es uns schnell machen, Hüter."
  },
  Voice_6719_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6720_AwakerVoiceContent = {Text = "Eh-heh—"},
  Voice_6720_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_6720_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_6721_AwakerVoiceContent = {
    Text = "Bereite dich darauf vor zu sterben, spartianischer Insekt."
  },
  Voice_6721_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6722_AwakerVoiceContent = {
    Text = "Miss Doll sagt, dass ich die Auflösung temporär vermeiden kann, indem ich meinen Körper wie sie aufgebe ... Kann es nicht tun, kann es nicht tun, kann es nicht tun. Ich werde während der Operation das Bewusstsein verlieren, und die Dunkelheit wird übernehmen ..."
  },
  Voice_6722_AwakerVoiceTitle = {
    Text = "Chat·Über Puppe"
  },
  Voice_6722_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Puppe“ wird freigeschaltet"
  },
  Voice_6723_AwakerVoiceContent = {
    Text = "Hmph... Was? Suchst du das Schicksal der Auslöschung?"
  },
  Voice_6723_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_6724_AwakerVoiceContent = {
    Text = "Schläfst du immer noch schlecht, Meister? Karen hat Dobies Beruhigungsmittel für dich vorbereitet~! Obwohl die Dosis ein wenig hoch ist, ist guter Schlaf die oberste Priorität!"
  },
  Voice_6724_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_6724_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_6725_AwakerVoiceContent = {
    Text = "Wir tranken und sangen, als wir plötzlich in Monster verwandelt wurden! Aber es ist in Ordnung, die grünliche Haut ist ziemlich amüsant!"
  },
  Voice_6725_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_6725_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_6726_AwakerVoiceContent = {
    Text = "Karens Traum? Hmm... Eine schöne Perlenkette zu kaufen und sie zu einem Ball zu tragen, der hellste Stern zu werden!"
  },
  Voice_6726_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_6726_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_67276_AwakerVoiceContent = {
    Text = "Verlangensexemplar, Tifhreid, suchte ihren Weg zur Existenz. Angesichts des Unbekannten kann niemand die Edeligkeit oder Niederträchtigkeit ihrer Methoden beurteilen."
  },
  Voice_67276_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über das Wesen des Verlangens"
  },
  Voice_67276_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Thais“ wird freigeschaltet"
  },
  Voice_67277_AwakerVoiceContent = {
    Text = "Durch das Silber Schlüssel Tor gehen, um Seinen Thron zu erreichen."
  },
  Voice_67277_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_67278_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_67279_AwakerVoiceContent = {
    Text = "Lass sein Wissen und seine Erinnerung nicht im Stich"
  },
  Voice_67279_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6727_AwakerVoiceContent = {
    Text = "Wische nach links, wische nach rechts, wische den Staub und die Sorgen weg—"
  },
  Voice_6727_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_6727_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_67280_AwakerVoiceContent = {
    Text = "Ich bin nicht hier."
  },
  Voice_67280_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_67281_AwakerVoiceContent = {
    Text = "Ein Fragment aus dem unendlichen Raum-Zeit-Kontinuum gelangt in mein Bewusstsein."
  },
  Voice_67281_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_67282_AwakerVoiceContent = {
    Text = "Ich habe das ganze Bild gesehen."
  },
  Voice_67282_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_67283_AwakerVoiceContent = {
    Text = "Alles existiert innerhalb der Leere."
  },
  Voice_67283_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_67284_AwakerVoiceContent = {
    Text = "Du bist tief eingedrungen, sehr tief. Bald wirst du ein außergewöhnliches Wunder erleben. Ich hoffe, du kannst so vernünftig und gelassen bleiben, wie du es jetzt bist."
  },
  Voice_67284_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_67284_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_67285_AwakerVoiceContent = {
    Text = "\"Ignoranz.\" Nein, das Streben nach dem Wesentlichen ist keine Ignoranz; wahre Ignoranz liegt darin, in einem Nebel zu leben, sich nicht bewusst zu sein, was man nicht weiß."
  },
  Voice_67285_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_67286_AwakerVoiceContent = {
    Text = "Ich werde dir meine Träume zeigen. Alles Bizarre und Chaotische, das du darin siehst, ist näher an der wahren Natur dieser Welt als die Realität, die du kennst."
  },
  Voice_67286_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_67286_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_67287_AwakerVoiceContent = {
    Text = "Hier ist mein Rat: Bleib ruhig. Wenn du müde wirst, halte sofort an und schone deine Kraft und Energie. Andernfalls wirst du für immer im Traumreich verloren sein."
  },
  Voice_67287_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_67287_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_67288_AwakerVoiceContent = {
    Text = "Das Universum zirkuliert endlos."
  },
  Voice_67288_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_67289_AwakerVoiceContent = {
    Text = "Die Synchronisation zwischen uns sollte nicht so lange Anpassung benötigen. Um jedoch deine geistige Klarheit vor den Illusionen zu schützen, werde ich allmählich vorgehen."
  },
  Voice_67289_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_67289_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_6728_AwakerVoiceContent = {
    Text = "Auflösung... Ich hatte zufällig einen verwandten Fall. Aber das Verschwinden scheint eine natürliche Sache zu sein, nicht wahr? Am Ende verschwindet jeder."
  },
  Voice_6728_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_67290_AwakerVoiceContent = {
    Text = "Das Erste Tor. Das unendliche Universum wurde aus einem Punkt geboren."
  },
  Voice_67290_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_67290_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_67291_AwakerVoiceContent = {
    Text = "Das Zweite Tor. Eine Linie erstreckt sich von einem Punkt und dehnt sich in unendliche Polaritäten aus."
  },
  Voice_67291_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_67291_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_67292_AwakerVoiceContent = {
    Text = "Das Vierte Tor. Der ewige Archetyp hat sich in einem Raum der Dimensionen verfestigt."
  },
  Voice_67292_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_67292_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_67293_AwakerVoiceContent = {
    Text = "Das dritte Tor. Ebenen sind partielle und eindimensionale Pronomen."
  },
  Voice_67293_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_67293_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_67294_AwakerVoiceContent = {
    Text = "Tor der Extreme. Die finale Leere, die unzählige Universen verbindet. Durch das Tor der Extreme zu treten, und die ultimativen Geheimnisse der Welt werden dir enthüllt."
  },
  Voice_67294_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_67294_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_67295_AwakerVoiceContent = {
    Text = "Das Fünfte Tor. Der Ablauf der Zeit ist nur eine Illusion; es gab nie einen Anfang und somit kein Ende."
  },
  Voice_67295_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_67295_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_67296_AwakerVoiceContent = {
    Text = "Ich sollte nur dein Führer sein, dich auf dieser Reise leiten, bevor ich in den illusorischen Gewässern ruhe. Jetzt bist du mein Linker, und unsere Verbindung ist so kompliziert, dass sie schwer zu trennen ist..."
  },
  Voice_67296_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_67297_AwakerVoiceContent = {
    Text = "Wünschst du, etwas zu bestätigen? Leider sind die Sinne und der Verstand dieses Körpers zu eingeschränkt. Wenn wir uns im Abgrund treffen, kann ich dir viel mehr zeigen..."
  },
  Voice_67297_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_67298_AwakerVoiceContent = {
    Text = "Sie ist eines meiner Fragmente, aus einer anderen Dimension, die ewig annihiliert wurde. Leider, während sie Zeitumkehr meisterte, fiel es ihr schwer, das Wesen des Transzendierens von Raum-Zeit zu begreifen und fiel immer wieder in die Qualen. Das ist meine Schuld."
  },
  Voice_67298_AwakerVoiceTitle = {
    Text = "Chit-Chat: Über Ramona den Wanderer"
  },
  Voice_67298_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Orbit Ramona“"
  },
  Voice_67299_AwakerVoiceContent = {Text = "Ich weiß."},
  Voice_67299_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_6729_AwakerVoiceContent = {
    Text = "Machst du dir Sorgen über das Aussehen dieses Körpers? Denk nicht zu viel darüber nach. Ich wurde mit einem menschlichen Gesicht geboren."
  },
  Voice_6729_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_67300_AwakerVoiceContent = {Text = "Ich siehe"},
  Voice_67300_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_67301_AwakerVoiceContent = {
    Text = "Wie winzig."
  },
  Voice_67301_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_67302_AwakerVoiceContent = {
    Text = "Beherrsche deine Gelassenheit."
  },
  Voice_67302_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_67303_AwakerVoiceContent = {
    Text = "Der direkte Kontakt mit dem Stoff wird deinen Verstand schädigen... Doch da du darauf bestehst, werde ich auf deinen Ruf reagieren."
  },
  Voice_67303_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_67304_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_67305_AwakerVoiceContent = {
    Text = "Dieses Kind hat viel zu viel aufgrund meines Fragments erdulden müssen. Glücklicherweise bleibt ihre Seele so klar wie fließendes Silber..."
  },
  Voice_67305_AwakerVoiceTitle = {
    Text = "Plauderei · Über Ramona"
  },
  Voice_67305_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Ramona“"
  },
  Voice_67306_AwakerVoiceContent = {
    Text = "Besuche seinen Traum und erhasche einen Blick auf die verbotenen Geheimnisse des Universums."
  },
  Voice_67306_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_67307_AwakerVoiceContent = {Text = "Hmm."},
  Voice_67307_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_67308_AwakerVoiceContent = {
    Text = "Das Tor der Extreme öffnet sich für dich. Umarm das Reich der tödlichen Stille dahinter."
  },
  Voice_67308_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_67308_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_67309_AwakerVoiceContent = {
    Text = "Mein Zweck, diese Schule mit ihnen zu gründen, ist \"Lagerung\". Du hast mehr erreicht, als ich erwartet habe."
  },
  Voice_67309_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_6730_AwakerVoiceContent = {
    Text = "Auflösung ist ein göttliches Geschenk. Der Schmerz, den sie bringt, reicht gerade aus, um unsere Nerven zu lähmen, sodass wir uns ganz dem Essen, Wein und dem Schwelgen hingeben können, um dann der Auslöschung entgegenzugehen."
  },
  Voice_6730_AwakerVoiceTitle = {
    Text = "Chat·Über Auflösung"
  },
  Voice_67310_AwakerVoiceContent = {
    Text = "Vergangenheit, Gegenwart und Zukunft – all das Glanz von Milliarden ist damit verbunden!"
  },
  Voice_67310_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_67311_AwakerVoiceContent = {
    Text = "Vergangenheit, Gegenwart und Zukunft – all das Glanz von Milliarden ist damit verbunden!"
  },
  Voice_67311_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_67312_AwakerVoiceContent = {
    Text = "Das Tor der Extreme hat sich geöffnet. Hier vereinen sich alle Dinge zu einer!"
  },
  Voice_67312_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_67313_AwakerVoiceContent = {
    Text = "Das Tor der Extreme hat sich geöffnet. Hier vereinen sich alle Dinge zu einer!"
  },
  Voice_67313_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_67314_AwakerVoiceContent = {
    Text = "Höre die Stimme der Weisheit."
  },
  Voice_67314_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_67315_AwakerVoiceContent = {
    Text = "Unendlich, grenzenlos, endlos und unbegrenzt."
  },
  Voice_67315_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Drei"
  },
  Voice_67316_AwakerVoiceContent = {
    Text = "Es ist Sein Wille... Nein, vielmehr ist es ein unbewusster Blick, der alle Dinge in Seinem Atem umfasst."
  },
  Voice_67316_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_67317_AwakerVoiceContent = {
    Text = "Nicht in der Lage, gründlich zu untersuchen... subtile Spuren..."
  },
  Voice_67317_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_67318_AwakerVoiceContent = {
    Text = "Ich werde die Wahrheit offenbaren."
  },
  Voice_67318_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_67319_AwakerVoiceContent = {
    Text = "\"Antwort\" Ich bewache diese Tür aus Liebe, und es ist auch aus Liebe, dass ich den Schlüssel in deine Hand lege."
  },
  Voice_67319_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6731_AwakerVoiceContent = {
    Text = "Muss... zurück..."
  },
  Voice_6731_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_6732_AwakerVoiceContent = {
    Text = "Himmel und Erde, der Kreislauf des Karma!"
  },
  Voice_6732_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6733_AwakerVoiceContent = {
    Text = "Himmel und Erde, der Kreislauf des Karma!"
  },
  Voice_6733_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6734_AwakerVoiceContent = {
    Text = "Die Klinge hat ihre Farbe noch nicht verloren."
  },
  Voice_6734_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6735_AwakerVoiceContent = {
    Text = "Training darf nicht vernachlässigt werden."
  },
  Voice_6735_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6736_AwakerVoiceContent = {
    Text = "Jetzt agiler."
  },
  Voice_6736_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6737_AwakerVoiceContent = {
    Text = "Unsichtbare Wesen werden unter deinem Kommando stehen."
  },
  Voice_6737_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_6737_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_6738_AwakerVoiceContent = {
    Text = "Fühle diesen sengenden Atem—"
  },
  Voice_6738_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6739_AwakerVoiceContent = {
    Text = "Wir werden alle... Teil der Grünen Flamme werden..."
  },
  Voice_6739_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_6740_AwakerVoiceContent = {
    Text = "Mein Schild wird für dich leuchten, mein Herr."
  },
  Voice_6740_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_6740_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_6741_AwakerVoiceContent = {
    Text = "Wieder einmal verbessert, sehr geschätzt!"
  },
  Voice_6741_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_6741_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_6743_AwakerVoiceContent = {Text = "Tss"},
  Voice_6743_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6744_AwakerVoiceContent = {
    Text = "(Verächtliche Ausdauer)"
  },
  Voice_6744_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6745_AwakerVoiceContent = {
    Text = "(Verächtliche Ausdauer)"
  },
  Voice_6745_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6746_AwakerVoiceContent = {
    Text = "(Verächtliche Ausdauer)"
  },
  Voice_6746_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6747_AwakerVoiceContent = {
    Text = "Die Zeit, die ich mit allen verbracht habe, fühlt sich immer so entspannend an..."
  },
  Voice_6747_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_6748_AwakerVoiceContent = {
    Text = "Der Höllenhelot, Tisiphones Bote, Klinge des Hasses... Sie haben mir diese Titel verliehen. Natürlich habe ich nichts dagegen, diese Person zu sein."
  },
  Voice_6748_AwakerVoiceTitle = {
    Text = "Plauderei · Über mich selbst"
  },
  Voice_6749_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6749_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_6750_AwakerVoiceContent = {
    Text = "Alles oder nichts!"
  },
  Voice_6750_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_6751_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6751_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_6752_AwakerVoiceContent = {Text = "(Ausruf)"},
  Voice_6752_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_6753_AwakerVoiceContent = {
    Text = "Können wir diesmal weiter gehen? Lass uns zum Strand gehen!"
  },
  Voice_6753_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_6754_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_6755_AwakerVoiceContent = {
    Text = "Wow—Danke, Kumpel~"
  },
  Voice_6755_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_6756_AwakerVoiceContent = {
    Text = "Gefährten~Mehr Gefährten~"
  },
  Voice_6756_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_6757_AwakerVoiceContent = {
    Text = "Uvhash... er ist besonders. Denkst du, der Wohlstand meiner Familie kam leicht? Es ist alles ihm zu verdanken, dass er wie ein verrückter Hund in der Arena tötet. Er ist unsere größte Geldquelle."
  },
  Voice_6757_AwakerVoiceTitle = {
    Text = "Chat·Über Uvhash"
  },
  Voice_6757_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Uvhash“ wird freigeschaltet"
  },
  Voice_6758_AwakerVoiceContent = {Text = "Torheit!"},
  Voice_6758_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_6759_AwakerVoiceContent = {Text = "Heh."},
  Voice_6759_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_6760_AwakerVoiceContent = {
    Text = "Gehe! Gib den Kampfauftrag!"
  },
  Voice_6760_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_6761_AwakerVoiceContent = {
    Text = "Im Abgrund... wird es ein Licht der Gerechtigkeit geben."
  },
  Voice_6761_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_6762_AwakerVoiceContent = {
    Text = "Das Licht der Gerechtigkeit wird hier entzündet!"
  },
  Voice_6762_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6763_AwakerVoiceContent = {
    Text = "Menschliche Emotionen sind so zerbrechlich und kostbar wie Blumen..."
  },
  Voice_6763_AwakerVoiceTitle = {
    Text = "Idle Talk: Über Colette"
  },
  Voice_6764_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6764_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_6765_AwakerVoiceContent = {
    Text = "Hit, Stand, Black·Jack!"
  },
  Voice_6765_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_67754_AwakerVoiceContent = {
    Text = "Widerstehe nicht, weine nicht, lebe nicht!"
  },
  Voice_67754_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_67756_AwakerVoiceContent = {
    Text = "Widerstehe nicht, weine nicht, lebe nicht!"
  },
  Voice_67756_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_67772_AwakerVoiceContent = {
    Text = "Tür, öffne dich!"
  },
  Voice_67772_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_79297_AwakerVoiceContent = {Text = "Oh."},
  Voice_79297_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_79298_AwakerVoiceContent = {Text = "Hmm...?"},
  Voice_79298_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_80092_AwakerVoiceContent = {
    Text = "Hydrotherapie, Elektrokrampftherapie, Haltebehandlung, das sind keine Behandlungen, sondern Folter. Daher werde ich während meiner Pro-bono-Zeit die Patienten im psychiatrischen Krankenhaus auf meine eigene Weise behandeln, und am Ende werden sie alle Genesung erreichen und wahre Freiheit finden."
  },
  Voice_80092_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_80092_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_80093_AwakerVoiceContent = {
    Text = "Der arme Weiße, weil das nahegelegene Asyl voll ist, wurde er von seiner Familie in einem Schweinestall gehalten. Ich habe ihn kostenlos behandelt, und danach hat er endlich erkannt, dass er ein Mensch und kein Vieh ist, und hat seine Würde als Mensch wiedererlangt."
  },
  Voice_80093_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_80093_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_80094_AwakerVoiceContent = {
    Text = "Webere, Anwälte, Barone... Ich werde niemals Patienten wegen Gebühren abweisen; für mich sind sie lediglich Patienten, die Heilung benötigen."
  },
  Voice_80094_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_80094_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_80095_AwakerVoiceContent = {
    Text = "Ich gebe zu, dass ich dich tatsächlich unterschätzt habe; deine Existenz ist der Schmerz selbst. Diesmal sind Nachsorgetermine nicht nötig, ich möchte an deiner Seite bleiben und das Ergebnis aus erster Hand sehen."
  },
  Voice_80095_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_80095_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_80096_AwakerVoiceContent = {
    Text = "Diese Patienten haben mir schöne Erinnerungen gegeben. Als Nächstes bist du dran, Hüter, ich habe das Ende für dich bereits gewählt. Das wird die exquisiteste Konsultation in meiner Karriere sein."
  },
  Voice_80096_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_80096_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_81138_AwakerVoiceContent = {
    Text = "Die Hilfe des Arztes abzulehnen, nützt dir nichts. Vielleicht müssen wir beim nächsten Mal tiefe Hypnose versuchen."
  },
  Voice_81138_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_81139_AwakerVoiceContent = {
    Text = "In einem dunklen Raum, ganz alleine, zusammen mit den zahllosen schmerzhaften Flüstern, die ständig in meinem Kopf widerhallen, ist dies der beste Weg, die Zeit zu genießen."
  },
  Voice_81139_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_81140_AwakerVoiceContent = {
    Text = "Obwohl es unhöflich sein mag, zu sagen, dass das Reden mit diesem Kind mich nur langweilt – man sieht nur einen Ausdruck, und das ist ein Lächeln."
  },
  Voice_81140_AwakerVoiceTitle = {
    Text = "Chat·Über Aurita"
  },
  Voice_81140_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Aurita“ wird freigeschaltet"
  },
  Voice_81141_AwakerVoiceContent = {
    Text = "Entschuldige, dass ich eindringe, ich habe nur deine niedrige psychologische Energie gespürt und bin gekommen, um nach dir zu sehen. Nun, Hüter, möchtest du eine mentale Reise antreten?"
  },
  Voice_81141_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_81143_AwakerVoiceContent = {
    Text = "Der Psychiater heilt Patienten, indem er ihre Schädel mit einer Trepanationstechnik aufbohrt—entspann dich, das ist lange her, jetzt haben wir viele Möglichkeiten, den Geist des Patienten zu messen und zu erkunden."
  },
  Voice_81143_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_81143_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_81144_AwakerVoiceContent = {
    Text = "Um einander zu verstehen, kann man nur sein Herz öffnen—berühre hier, und mein silbernes Herz wird sich für dich öffnen."
  },
  Voice_81144_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_81145_AwakerVoiceContent = {
    Text = "Wenn du meine Gedanken zu etwas hören möchtest, könntest du enttäuscht sein. Anstatt zu schimpfen, bin ich besser im Zuhören."
  },
  Voice_81145_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_81146_AwakerVoiceContent = {
    Text = "Ah, ich habe Seine Stimme gehört, diese murmeln, jede Silbe voller größter Qual!"
  },
  Voice_81146_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_81147_AwakerVoiceContent = {
    Text = "Ich werde den Schmerz dieses Moments in meinem Herzen behalten und ihn immer wieder erinnern und genießen..."
  },
  Voice_81147_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_81148_AwakerVoiceContent = {
    Text = "Als ein Fragment dieser Existenz trägst du ihren Atem, diesen Atem, der mit Schmerz gefüllt ist und jede deiner Erinnerungen unglaublich lecker macht."
  },
  Voice_81148_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_81149_AwakerVoiceContent = {
    Text = "Erinnere dich an diese Ängste, beschreibe deine Gefühle des Schmerzes; die Essenz der emotionalen Wirkungstherapie besteht darin, den Schmerz direkt zu konfrontieren und ihn zu überwinden. Komm, wische deine Tränen weg und erzähle mir langsam diese Erinnerungen im Detail..."
  },
  Voice_81149_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_81149_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_81150_AwakerVoiceContent = {
    Text = "Herzlichen Glückwunsch, du bist geheilt—ja, Halluzinationen und Illusionen sind normale Phänomene; sie sind der Beweis für deine Genesung."
  },
  Voice_81150_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_81150_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_81151_AwakerVoiceContent = {
    Text = "Dein Geist ist sicher mit seltsamen und bizarren Bildern gefüllt, was normal ist. Zieh sie heraus, und dein Unterbewusstsein und deine Instinkte werden dir alles offenbaren."
  },
  Voice_81151_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_81151_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_81152_AwakerVoiceContent = {
    Text = "Als nächstes ist die moralische Therapie von Philip Pinel. Du musst deine innigsten Wünsche und Ängste äußern, was ein notwendiges Verfahren ist, um den Geist zu befreien und die schlafende Menschlichkeit wiederherzustellen."
  },
  Voice_81152_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_81152_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_81153_AwakerVoiceContent = {
    Text = "Hüter, kannst du mir bei einem kleinen Test helfen? Es ist nur der Rorschach-Tintenfleck-Test. Wenn ich ihn bestehe, werde ich in der Lage sein, die Tiefen deines inneren Selbst zu sehen, die anderen unbekannt bleiben, und ich werde der einzige Wachende sein, der die Geheimnisse des Herzens des Hüters enthüllt."
  },
  Voice_81153_AwakerVoiceTitle = {
    Text = "Plauderei·Über psychologische Analyse"
  },
  Voice_81154_AwakerVoiceContent = {
    Text = "Zunächst hören wir ein Stück Musik. Kannst du es hören, die beruhigende und sanfte Musik? Lass nun deinen Körper und Geist mit der Musik mitschwingen und in einen Zustand der spirituellen Entspannung eintreten..."
  },
  Voice_81154_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_81154_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_81155_AwakerVoiceContent = {
    Text = "Den Pendel beobachten, mit deinen Augen, die seiner Bewegung folgen..."
  },
  Voice_81155_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_81156_AwakerVoiceContent = {
    Text = "Schhh—Sei still, geh dann auf das Ende zu, das ich dir zeige."
  },
  Voice_81156_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_81157_AwakerVoiceContent = {
    Text = "Eine betäubte Seele weckt überhaupt nicht mein Interesse. Ihre Seelen sind bereits tot, und ganz gleich, wie sehr man sie aufrüttelt, es wird keine Welle geben."
  },
  Voice_81157_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_81158_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_81159_AwakerVoiceContent = {
    Text = "Ich höre zu, bitte fahre fort."
  },
  Voice_81159_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_81160_AwakerVoiceContent = {
    Text = "Bitte bleib still."
  },
  Voice_81160_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_81161_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_81162_AwakerVoiceContent = {
    Text = "Vertraue mir ein wenig mehr."
  },
  Voice_81162_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_81163_AwakerVoiceContent = {
    Text = "Entblöße mehr von dem Schmerz!"
  },
  Voice_81163_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_81164_AwakerVoiceContent = {
    Text = "Keine Notwendigkeit zu verstecken, keine Notwendigkeit, schüchtern zu sein, ich bin dein vertrauenswürdigster und einziger Zuhörer. Komm, schütte deinen tiefsten Schmerz bei mir aus..."
  },
  Voice_81164_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_81165_AwakerVoiceContent = {
    Text = "Aigis sieht jetzt viel heller aus. Natürlich, wenn mein kleiner Gast Hilfe benötigt, biete ich sie gerne an. Ich meine, echte Hilfe."
  },
  Voice_81165_AwakerVoiceTitle = {
    Text = "Chat·Über Aigis"
  },
  Voice_81165_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Aigis“"
  },
  Voice_81166_AwakerVoiceContent = {
    Text = "Zeig mir dein wahrhaftigstes Ich."
  },
  Voice_81166_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_81168_AwakerVoiceContent = {
    Text = "Ich werde diesen süßen Schmerz genießen."
  },
  Voice_81168_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_81169_AwakerVoiceContent = {
    Text = "Keine Notwendigkeit zu verstecken, keine Notwendigkeit, schüchtern zu sein, ich bin dein vertrauenswürdigster und einziger Zuhörer. Komm, schütte deinen tiefsten Schmerz bei mir aus..."
  },
  Voice_81169_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_81170_AwakerVoiceContent = {
    Text = "Psychische Erkrankungen sind nicht nur auf diese Ära beschränkt; sie transcenden Zeit und Raum, und Auflösung ist das gleiche. Beide überschreiten die Grenzen menschlichen Wissen, nicht wahr?"
  },
  Voice_81170_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_81171_AwakerVoiceContent = {
    Text = "Schhh—Sei still, geh dann auf das Ende zu, das ich dir zeige."
  },
  Voice_81171_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_81172_AwakerVoiceContent = {
    Text = "Dieser Ort ist voller Spuren der Geschichte, und in gewissem Maße stellt Geschichte Erinnerungen dar – schmerzhafte Erinnerungen der Abgeschiedenen."
  },
  Voice_81172_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_81173_AwakerVoiceContent = {
    Text = "Tiefer Atem..."
  },
  Voice_81173_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_81174_AwakerVoiceContent = {
    Text = "Schmerz, Verzweiflung, Tod... diese Erinnerungen schmecken wie Dessert nach einer Mahlzeit."
  },
  Voice_81174_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_81175_AwakerVoiceContent = {
    Text = "Es ist nicht nötig, so nervös zu sein, dies ist nur eine reguläre psychologische Beratung."
  },
  Voice_81175_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_81176_AwakerVoiceContent = {
    Text = "Höre auf meine Anleitung."
  },
  Voice_81176_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_84185_AwakerVoiceContent = {
    Text = "Beim Ritual ist ein unbekannter Zwischenfall aufgetreten. Bitte verzeiht, dass ich Euren Arm mit der Fahne geschlagen habe – ich musste Euch wach halten."
  },
  Voice_84185_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_84185_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_84186_AwakerVoiceContent = {
    Text = "Hier kann ich verschiedene Schiffmodelle betrachten und mit fortschrittlicheren Navigationsgeräten in Berührung kommen. Das gefällt mir sehr. Am wichtigsten ist jedoch, dass ich glaube, dieses “Schiff“ verfolgt den richtigen Kurs in der menschlichen Geschichte."
  },
  Voice_84186_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_84187_AwakerVoiceContent = {
    Text = "Die Zeremonie war erfolgreich – vielen Dank für Ihre Unterstützung. Beim nächsten Mal werde ich einige eigene Flaggenzeichen entwickeln, um uns bei der sicheren und reibungslosen Durchführung der Zeremonie zu helfen."
  },
  Voice_84187_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_84187_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_84188_AwakerVoiceContent = {
    Text = "Ich weiß nicht, warum es existiert, ich kenne nur eine Sache: Ich muss erfolgreich navigieren und alle Seeleute und Passagiere sicher von der Seereise zurückbringen."
  },
  Voice_84188_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_84189_AwakerVoiceContent = {
    Text = "Bitte haben Sie Vertrauen, ich werde diese Kraft nutzen, um die sichere Navigation des Schiffes zu gewährleisten, und sie niemals missbrauchen."
  },
  Voice_84189_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_84190_AwakerVoiceContent = {
    Text = "Hör auf zu kämpfen."
  },
  Voice_84190_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_84191_AwakerVoiceContent = {
    Text = "Ich habe nur tiefsten Respekt vor Ihnen und werde bis in den Tod alle Befehle befolgen, die Sie erteilen."
  },
  Voice_84191_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_84192_AwakerVoiceContent = {
    Text = "Entschuldigung, ich verstehe keine Menschen, nur Schiffe. Bitte verzeih mir diese Metapher: Dein Kiel ist nicht aus Holz oder Eisen, sondern aus Stahl – stark und fest, bewundernswert."
  },
  Voice_84192_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_84192_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_84193_AwakerVoiceContent = {
    Text = "Ergebt euch."
  },
  Voice_84193_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_84194_AwakerVoiceContent = {
    Text = "Eher als „Liebe“ ziehe ich das Wort „Erlösung“ vor. Als ich das unaussprechliche Wesen direkt ansah, verlor ich den Verstand und versank in Ekstase. Ja, ich sollte Angst vor Ihm haben, aber ich kann mich nicht beherrschen."
  },
  Voice_84194_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_84195_AwakerVoiceContent = {
    Text = "Ich werde nicht vom Sturm umgeworfen."
  },
  Voice_84195_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_84196_AwakerVoiceContent = {
    Text = "Wenn es keine Ordnung gäbe, was bliebe dann noch von dieser Welt übrig? Nichts als Chaos und Verwirrung."
  },
  Voice_84196_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_84197_AwakerVoiceContent = {
    Text = "Beim nächsten Auslaufen möchte ich das Schiff in einer anderen Rolle als der Navigatorin betreten. Das heißt... ich bin bereit, unter Ihrer Leitung zu handeln. Sie haben mein vollstes Vertrauen verdient."
  },
  Voice_84197_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_84197_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_84198_AwakerVoiceContent = {
    Text = "Ich erfülle lediglich meine Pflicht als Navigator. Eine Anerkennung ist nicht erforderlich."
  },
  Voice_84198_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_84199_AwakerVoiceContent = {
    Text = "Das Leuchtturmsystem kann den Stress bei der Navigation erheblich reduzieren, und ihr Licht ist besonders hell. Ich würde gerne mit Falos segeln."
  },
  Voice_84199_AwakerVoiceTitle = {
    Text = "Chat·Über Faros"
  },
  Voice_84199_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Faros“, wird es freigeschaltet"
  },
  Voice_84200_AwakerVoiceContent = {
    Text = "Matrosen, folgt meiner Führung – gemeinsam erreichen wir sicher den Hafen."
  },
  Voice_84200_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_84201_AwakerVoiceContent = {
    Text = "Geistesverbindung erfolgreich, ich spüre dein Bewusstsein... Dies ist das erste Mal, dass ich im Leerraum navigiere. Falls es zu Kursabweichungen kommt, korrigiere mich bitte rechtzeitig."
  },
  Voice_84201_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_84201_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_84202_AwakerVoiceContent = {
    Text = "Bei Beobachtung von Cirruswolken und kontinuierlich fallendem Quecksilber im Barometer: Achtung, das Schiff wird bald einen Sturm erleben!"
  },
  Voice_84202_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_84203_AwakerVoiceContent = {
    Text = "Dieses Chaos ist vollständig auf meine falsche Routenplanung zurückzuführen. Ich bin bereit, gemäß den Regeln bestraft zu werden."
  },
  Voice_84203_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_84204_AwakerVoiceContent = {
    Text = "Messung des Höhenwinkels eines Himmelsobjekts."
  },
  Voice_84204_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_84205_AwakerVoiceContent = {
    Text = "Dieses Schwindelgefühl ist ähnlich wie bei einer Seekrankheit. Bitte schließe die Augen, halte meine Hand und lehne dich an mich, das wird dich etwas erleichtern."
  },
  Voice_84205_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_84205_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_84206_AwakerVoiceContent = {
    Text = "Vorstagsegel einholen, Backbord gegen die Wellen, Kurs neu berechnen und vom Steuermann entsprechend meiner Berechnung anpassen."
  },
  Voice_84206_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_84207_AwakerVoiceContent = {
    Text = "Diese Erfahrungen sind äußerst wertvoll. Ich werde sie detailliert im Logbuch festhalten und den nachfolgenden Seeleuten weitergeben."
  },
  Voice_84207_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_84208_AwakerVoiceContent = {
    Text = "Die Zeremonie zur Vertiefung der Verbindung birgt Risiken und unbekannte Folgen, aber machen Sie sich keine Sorgen – ich werde Sie sicher durch die Zeremonie führen, damit sie erfolgreich abgeschlossen wird."
  },
  Voice_84208_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_84208_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_84209_AwakerVoiceContent = {
    Text = "Gewicht neu justieren."
  },
  Voice_84209_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_84210_AwakerVoiceContent = {
    Text = "Achte darauf, das Schiff zu schützen."
  },
  Voice_84210_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_84211_AwakerVoiceContent = {
    Text = "Manche sind wie Dampfschiffe – langsam in der Reaktion, aber bei hoher Geschwindigkeit lauffähig. Andere sind wie Dieselschiffe – schnell beim Anfahren, aber mit begrenzter Leistung. Und Sie, Hüter des Geheimnisses?"
  },
  Voice_84211_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_84211_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_84212_AwakerVoiceContent = {
    Text = "Ich glaube fest an das grundlegende Prinzip, dass harte Arbeit belohnt wird, und ich werde in Zukunft noch härter arbeiten."
  },
  Voice_84212_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_84213_AwakerVoiceContent = {
    Text = "Bei mehreren Missionen haben Sie bereits Ihre Fähigkeiten bewiesen. Ich glaube, Sie sind ein ebenso guter Navigator wie ich – nein, vielleicht sogar noch viel besser."
  },
  Voice_84213_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_84213_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_84214_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_84215_AwakerVoiceContent = {
    Text = "Kupferspange steht Ihnen jederzeit zur Verfügung, sobald Sie sie benötigen."
  },
  Voice_84215_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_84215_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_84216_AwakerVoiceContent = {
    Text = "Matrosen, folgt meiner Führung, wir werden sicher den Hafen erreichen."
  },
  Voice_84216_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_84217_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_84218_AwakerVoiceContent = {
    Text = "Navigatorin Kupferspange meldet sich zum Dienst! Die Flagge ist einsatzbereit, der persönliche Status ist gut, Geheimnisträger wird der Auslauf-Befehl erteilt."
  },
  Voice_84218_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_84219_AwakerVoiceContent = {
    Text = "Ich werde das Schiff sicher in die richtige Richtung lenken."
  },
  Voice_84219_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_84220_AwakerVoiceContent = {
    Text = "Ist der Hut schief? Entschuldigung, ich verstehe nicht ganz Ihre Intention dabei. Bitte geben Sie mir einen klaren Befehl."
  },
  Voice_84220_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_84221_AwakerVoiceContent = {
    Text = "Die Flagge ist die Sprache des Piloten und zugleich seine Grabinschrift. Wenn das Schiff untergeht, werden die Bergungsteams aus den Überresten der Flagge die letzte Botschaft entschlüsseln, die ich hinterlassen habe."
  },
  Voice_84221_AwakerVoiceTitle = {
    Text = "Plauderei·Über Flaggen"
  },
  Voice_84222_AwakerVoiceContent = {
    Text = "Den Schwerpunkt des Schiffskörpers wahrnehmen."
  },
  Voice_84222_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_84223_AwakerVoiceContent = {
    Text = "Vorstagsegel einholen, Backbord gegen die Wellen, Kurs neu berechnen und vom Steuermann entsprechend meiner Berechnung anpassen."
  },
  Voice_84223_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_84224_AwakerVoiceContent = {
    Text = "E-Flagge gibt Befehl weiter."
  },
  Voice_84224_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_84225_AwakerVoiceContent = {
    Text = "In Notfällen kann ein Navigator, der Erfahrung mit Maschinenraumkooperation hat, auch als Steuermann eingesetzt werden, aber um die Sicherheit des Schiffes zu gewährleisten, hoffe ich dennoch, diese Aufgabe an jemanden übertragen zu können, der darin erfahren ist."
  },
  Voice_84225_AwakerVoiceTitle = {
    Text = "Chat·Über Celeste"
  },
  Voice_84225_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Celeste“ wird freigeschaltet"
  },
  Voice_84226_AwakerVoiceContent = {
    Text = "Ein Gefühl der Schwerelosigkeit macht sich breit, gefolgt von einem heftigen Schwanken, als würde das Schiff stark erschüttert. Folge meiner Bewegung und spüre das Gewicht deines Körpers, um das Gleichgewicht zu halten."
  },
  Voice_84226_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_84226_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_84406_AwakerVoiceContent = {
    Text = "Kartendatum korrigieren."
  },
  Voice_84406_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_84407_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Drei"
  },
  Voice_84408_AwakerVoiceContent = {
    Text = "C-Flagge reagiert auf den Befehl."
  },
  Voice_84408_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_84409_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Drei"
  },
  Voice_90333_AwakerVoiceContent = {
    Text = "Du wirst mich nicht überwinden."
  },
  Voice_90333_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_90334_AwakerVoiceContent = {
    Text = "Wie sollte man als Freund mit anderen umgehen? Pollux erteilt mir gerne viele Befehle, obwohl er selbst durchaus in der Lage wäre, diese Dinge zu tun. Und dennoch bin ich bereit, diese Dinge für ihn zu erledigen, denn das gehört zu unserer Art der Kommunikation. Wenn du möchtest, tue ich dasselbe gerne auch für dich."
  },
  Voice_90334_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_90334_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_90335_AwakerVoiceContent = {
    Text = "Mit diesem unvergänglichen Körper werde ich alle Katastrophen abwehren!"
  },
  Voice_90335_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_90336_AwakerVoiceContent = {
    Text = "Auch noch vor dem Lesen dieses Buches hatten wir nicht aufgehört, uns für die Welt jenseits der Seeinsel und der dunkelroten Mauern zu interessieren. Doch als Pollux gequält wurde, habe ich nicht den geringsten Gedanken an Widerstand verschwendet. Gegenüber Pollux bin ich wirklich viel zu feige und unbeholfen."
  },
  Voice_90336_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_90336_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_90337_AwakerVoiceContent = {
    Text = "Ich wirke wie ein Idiot? Es tut mir leid, entschuldige meine Unwissenheit. Abgesehen von dem Wissen über die Götter, das uns die Tempellicht-Kirche vermittelt hat, weiß ich über alles andere kaum etwas. Ich werde mich schneller bemühen zu lernen. Sag mir, was du magst und was du nicht magst – ich werde mir alles gut merken."
  },
  Voice_90337_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_90337_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_90338_AwakerVoiceContent = {
    Text = "Seht diesen Willen, der nach Freiheit strebt."
  },
  Voice_90338_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_90339_AwakerVoiceContent = {
    Text = "Ein Laden, der jeden Wunsch erfüllt, Waren aller Art – das ist wirklich beeindruckend... Ehrfurcht einflößend, würde ich sagen. Nein, ich zweifle nicht an der Macht dieser Dame, aber „um etwas zu besitzen, muss man den entsprechenden Preis zahlen“ – diesen Grundsatz haben wir, Castor, und auch Pollux nur allzu oft erfahren."
  },
  Voice_90339_AwakerVoiceTitle = {
    Text = "Kleine Gespräche · Über Narzisse"
  },
  Voice_90339_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Daffodil“"
  },
  Voice_90340_AwakerVoiceContent = {
    Text = "Können diese verfluchten Flügel auch hoch am Himmel schweben?"
  },
  Voice_90340_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_90341_AwakerVoiceContent = {
    Text = "Ihr könnt mich nicht zerstören!"
  },
  Voice_90341_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_90342_AwakerVoiceContent = {
    Text = "Möchten Sie die Federn streicheln? Bitte, soll ich die Flügel etwas ausbreiten?"
  },
  Voice_90342_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_90343_AwakerVoiceContent = {
    Text = "Wenn ich von anderen Hilfe erhalte, frage ich mich oft, ob all die besondere Fürsorge, die wertvollen Bücher und die prächtigen Meteoritenkristalle, die du mir geschenkt hast, wohl einen verborgenen Preis haben? Entschuldige, ich hätte nicht so von dir denken sollen."
  },
  Voice_90343_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_90343_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_90344_AwakerVoiceContent = {
    Text = "Der Vogel wird schließlich hoch am Himmel fliegen."
  },
  Voice_90344_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_90345_AwakerVoiceContent = {
    Text = "Kochmeister... Das Wissen, um Speisen herzustellen, ist tatsächlich auch sehr notwendig. Obwohl meine Ansprüche an die Nahrungsaufnahme nicht hoch sind, ist Pollux einfach zu wählerisch. Es scheint, als sollte ich mal einen Termin finden, um intensiv nachzufragen... Nicht hingehen? Warum? Aber die Speisen, die dieser Herr zubereitet, sehen doch alle sehr lecker aus!"
  },
  Voice_90345_AwakerVoiceTitle = {
    Text = "Small Talk · Über Durschein"
  },
  Voice_90345_UnlockDesc = {
    Text = "Wird entsperrt, nachdem du den Erwachten Körper “Durschein“ erhalten hast"
  },
  Voice_90346_AwakerVoiceContent = {
    Text = "Wenn ich jetzt darüber nachdenke, waren die Dienstmädchen während der Laterne tatsächlich nicht sehr verschieden von mir und Pollux. Wir alle lebten mit Ketten um uns herum, und sie akzeptierten dies stets geduldig und fügten sich hinein. Doch dieses grüne Dienstmädchen schien etwas anders zu sein. Sie war ... sehr lebendig und schien diese Dinge von Natur aus gerne zu tun. Vielleicht hatte sie bereits die kostbarste Freiheit erlangt."
  },
  Voice_90346_AwakerVoiceTitle = {
    Text = "Chat·Über Karen"
  },
  Voice_90346_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Karen“ wird freigeschaltet"
  },
  Voice_90347_AwakerVoiceContent = {
    Text = "Ihr könnt mich nicht zerstören!"
  },
  Voice_90347_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_90348_AwakerVoiceContent = {
    Text = "Immer noch nicht... fliegen können..."
  },
  Voice_90348_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_90349_AwakerVoiceContent = {
    Text = "Verschwinde mit dem Wind!"
  },
  Voice_90349_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Zwei"
  },
  Voice_90350_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_90351_AwakerVoiceContent = {
    Text = "Seid gegrüßt, es ist unser erstes Treffen. Ich bin Castor... Sollte ich noch etwas anderes sagen? Entschuldigt, ich bin nicht sehr gesprächig. Falls ihr etwas habt, das ich wissen sollte, ruft mich jederzeit."
  },
  Voice_90351_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_90352_AwakerVoiceContent = {
    Text = "Nicht der Rede wert..."
  },
  Voice_90352_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_90353_AwakerVoiceContent = {Text = "Stürz ab!"},
  Voice_90353_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_90354_AwakerVoiceContent = {
    Text = "Ich habe vieles nicht gesehen und vieles nicht getan. Die öden dunkelgrünen Seen und der ständig anhaltende Nebel werden uns nie wieder gefangen halten. Meer, Großstadt, Landwirtschaft – all die Orte, die in dem Manuskript beschrieben werden, möchte ich sehen, zusammen mit Pollux und Ihnen."
  },
  Voice_90354_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_90354_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_90355_AwakerVoiceContent = {
    Text = "Wenn du das leise Rascheln der Blätter am Baum hörst, weißt du, dass ich schon bei dir bin."
  },
  Voice_90355_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_90355_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_90356_AwakerVoiceContent = {
    Text = "Diese dunklen Federn wurden noch dunkler."
  },
  Voice_90356_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_90357_AwakerVoiceContent = {
    Text = "Eigentlich ist das, was ich am meisten bewundere, die Art und Weise, wie Sie und Ihre Gefährten einander vollkommen vertrauen und keinerlei Misstrauen kennen. Das Gefühl, vergessen und verraten zu werden... ist einfach zu schmerzhaft."
  },
  Voice_90357_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_90358_AwakerVoiceContent = {
    Text = "Der Meisterdieb sagte mir, sie könnte mir die besten Straßensurvival-Techniken beibringen, für nur fünfhundert Leos... Ich wurde betrogen? Nein, ich glaube, dieses Wissen ist es wert zu lernen, genau das ist es, was ich und Pollux bisher gefehlt haben... Liegt es am Geld? Ich verstehe. Dann werde ich gehen und mit ihr verhandeln, wie wäre es, wenn ich ihr fünfhundert Leos gebe?"
  },
  Voice_90358_AwakerVoiceTitle = {
    Text = "Gerüchte · Über Jenkin"
  },
  Voice_90358_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Jenkins“"
  },
  Voice_90359_AwakerVoiceContent = {
    Text = "Ich kann es noch aushalten..."
  },
  Voice_90359_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_90360_AwakerVoiceContent = {
    Text = "Als Kind war die Kontrolle durch die Laterne noch nicht so streng. Manchmal sagte Pollux irgendetwas, und schon zauberte er wunderbarerweise eine Handvoll Süßigkeiten herbei. Das Gefühl, diese Süßigkeiten zu kosten... war genau wie jetzt."
  },
  Voice_90360_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_90360_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_90361_AwakerVoiceContent = {
    Text = "Mit diesem unvergänglichen Körper werde ich alle Katastrophen abwehren!"
  },
  Voice_90361_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_90362_AwakerVoiceContent = {
    Text = "Können Sie mir etwas über das Wissen bezüglich des Handels mit Menschen beibringen? Wie tauscht man Gegenstände miteinander und wie verwaltet man das erhaltene Geld? Das ist wirklich eine tiefsinnige Wissenschaft. Die Freiheit zu erlangen ist erst der Anfang. Um unabhängig leben zu können, gibt es für mich und Pollux noch vieles zu lernen. Ich werde Sie also in Zukunft häufiger um Rat fragen müssen."
  },
  Voice_90362_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_90363_AwakerVoiceContent = {
    Text = "Verschwinde mit dem Wind!"
  },
  Voice_90363_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  },
  Voice_90364_AwakerVoiceContent = {
    Text = "Wind, blase ihn in den Rachen des Todes!"
  },
  Voice_90364_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_90365_AwakerVoiceContent = {
    Text = "Pollux... obwohl er von Laterne viele schlechte Ideen eingetrichtert bekam, ist sein wahrer Kern nicht schlecht. Er wollte einfach nur dringend die Anerkennung von Laterne und den Anhängern erlangen, bis zu dem Punkt, wo er übermäßig auf deren Bedürfnisse achtete. Man könnte sagen, nicht seine Überheblichkeit ist das Problem, sondern vielmehr seine ständige Angst, diese „Identität“ zu verlieren."
  },
  Voice_90365_AwakerVoiceTitle = {
    Text = "Plauderei·Über Pollux"
  },
  Voice_90365_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Pollux“, wird freigeschaltet"
  },
  Voice_90366_AwakerVoiceContent = {
    Text = "Entschuldigung, ich wollte nicht abgelenkt sein... Sie haben mich gefragt, was diese Feder ist? Das ist... das Wichtigste für ihn und auch das Wichtigste für mich. Ist sie nicht wunderschön?"
  },
  Voice_90366_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_90367_AwakerVoiceContent = {
    Text = "Damals mussten wir jeden Tag unter der Anleitung von Albino oder den Lichtwächtern Theologie lernen, und mein größter Wunsch war, dass die Texte eines Tages überarbeitet würden, um kürzer und weniger zu sein. Dann würde ich nicht mehr wegen des Auswendiglernens mit Schwindelgefühlen von den strengen Lichtwächtern kritisiert werden."
  },
  Voice_90367_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_90367_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_90368_AwakerVoiceContent = {
    Text = "Danke, dass du mir den Schlüssel zur Freiheit gegeben hast."
  },
  Voice_90368_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_90369_AwakerVoiceContent = {
    Text = "Diese Flügel sind endlich in ihrer prächtigsten Form erblüht, so kräftig und mächtig. Nun kann ich euch beide – dich und Pollux – auf einmal mitnehmen. Wenn du in den Himmel aufsteigen willst, ruf mich einfach laut."
  },
  Voice_90369_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_90369_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_90370_AwakerVoiceContent = {
    Text = "Versteck dich hinter meinen Flügeln!"
  },
  Voice_90370_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_90371_AwakerVoiceContent = {
    Text = "Endlich... ich sehe den weiten Sternenhimmel, von dem in dem Buch die Rede war."
  },
  Voice_90371_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_90372_AwakerVoiceContent = {
    Text = "Einst war die Anführerin... Juliette uns gegenüber oft von sanfter Wärme. Sie zeigte stets allen ihr warmes, freundliches Lächeln und machte einem das Gefühl, ihre Erwartungen niemals enttäuschen zu dürfen. Sobald sie lächelnd deinen Kopf berührte, brachte man einfach kein Wort des Widerstands mehr hervor. Aber jetzt ist das nicht mehr so – Sie können mich jederzeit berühren, wie Sie möchten."
  },
  Voice_90372_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_90372_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_90373_AwakerVoiceContent = {
    Text = "Ich wurde lange, sehr lange in diesem schwarzen Schleim eingetaucht, so lange, dass ich die Zeit vergaß, so lange, bis... selbst Pollux mich vergessen hatte. Es verursacht keinen körperlichen Schmerz, sondern eine seelische Angst, mit anzusehen, wie man selbst verschwindet."
  },
  Voice_90373_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_90374_AwakerVoiceContent = {
    Text = "Von klein auf war es uns nicht erlaubt, viel mit anderen Menschen zu interagieren. Das Wort „Freund“ lernte ich erst sehr viel später kennen. Pollux und ich hatten außer einander nichts – weder ich noch er. Brüder, Freunde, Gefangene desselben Gefängnisses – das waren wir, nur wir beide. Jetzt ist es an der Zeit, neue Freunde zu finden."
  },
  Voice_90374_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_90374_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_90375_AwakerVoiceContent = {Text = "Geh weg!"},
  Voice_90375_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_90376_AwakerVoiceContent = {
    Text = "Eine Schule, in der jeder frei miteinander kommunizieren und beliebig Freunde finden kann? Du sagst, hier wird keine Theologie unterrichtet, und man kann aus zahlreichen Kursen wählen... ja, sogar dem Unterricht fernbleiben? Hmm, wirklich ein wunderbarer Ort."
  },
  Voice_90376_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_90377_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_90378_AwakerVoiceContent = {
    Text = "Aus dem Weg!"
  },
  Voice_90378_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_95050_AwakerVoiceContent = {
    Text = "Unwürdige... werden bestraft..."
  },
  Voice_95050_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_95051_AwakerVoiceContent = {
    Text = "Mein Herz leuchtet hell!"
  },
  Voice_95051_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_95052_AwakerVoiceContent = {
    Text = "Unreiner Gegenstand"
  },
  Voice_95052_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_95053_AwakerVoiceContent = {
    Text = "Ein zu fanatischer Gläubiger mag in den Augen der Menschen nur ein unverständlicher Verrückter sein. Obwohl sie ebenfalls in die Irre gegangen ist, ist diese Entschlossenheit, alles für die Götter zu opfern, eine Stärke, zu der die meisten gewöhnlichen Menschen nicht fähig sind. Was sie betrifft... fühle ich nur eine gewisse Traurigkeit, wie sie zwischen Gleichgesinnten manchmal entsteht."
  },
  Voice_95053_AwakerVoiceTitle = {
    Text = "Plauderei · Über Miryam"
  },
  Voice_95053_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Miryam“ wird freigeschaltet"
  },
  Voice_95054_AwakerVoiceContent = {
    Text = "Ich werde Führung und Urteil bringen, das Glimmer der Weißen Nacht wird eure Sünden vertreiben!"
  },
  Voice_95054_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_95055_AwakerVoiceContent = {
    Text = "Haha... So viel Zeit ist vergangen, und er hat sich kein bisschen verändert. Als Kind hätte ich nie gedacht, dass ich meinen Bruder einst so sehr verletzen und ihm so viel Schuld schulden würde – mehr, als ich ertragen kann, obwohl dieses tragische Schicksal außerhalb unserer Kontrolle lag. Wir haben so viele Trennungen erlebt, aber nun, da ich zurückgekehrt bin, wird ab heute nichts und niemand uns je wieder trennen, nicht einmal der Tod."
  },
  Voice_95055_AwakerVoiceTitle = {
    Text = "Small Talk: Über Castor"
  },
  Voice_95055_UnlockDesc = {
    Text = "Wird freigeschaltet, sobald du den Erwecker „Castor“ erhältst"
  },
  Voice_95056_AwakerVoiceContent = {
    Text = "Früher hasste ich viele Dinge. Dienstmädchen, die die Etikette nicht beherrschten, Diener, die keine Achtung vor Rang und Würde zeigten, Götterlästerer, die die Götter entweihten ... Doch jetzt, Laterne, nur Laterne! Liriet und ihre Sekte haben meinem Bruder und mir unersetzliche Schmerzen zugefügt. Im Namen des Heiligen Sohnes schwöre ich, solche Schmerzen werde ich niemals wieder zulassen!"
  },
  Voice_95056_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_95057_AwakerVoiceContent = {
    Text = "Ich werde den Pfad des Lichts beschreiten, bis ans Ende meines Lebens."
  },
  Voice_95057_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_95058_AwakerVoiceContent = {
    Text = "Das Licht des Lichtträgers wird endlich die lange Nacht erhellen!"
  },
  Voice_95058_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_95059_AwakerVoiceContent = {
    Text = "Sie sind immer so großzügig und gnädig. Ich werde diese Wärme des Lichts sorgfältig erfühlen und verinnerlichen."
  },
  Voice_95059_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_95060_AwakerVoiceContent = {
    Text = "Der Apostel des Lampenträgers, der aus der Weißen Nacht Geborene, der die Dunkelheit vertreibt, der Heilige Herz und Heiliger Sohn, ich, Pollux, komme auf deinen Ruf hin, um dir meine dunkle Kraft und meine helle Seele zu schenken."
  },
  Voice_95060_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_95061_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_95062_AwakerVoiceContent = {
    Text = "Reinige deine Sünden!"
  },
  Voice_95062_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_95063_AwakerVoiceContent = {
    Text = "Einst sagten mir alle Menschen, dass diese abgründige Schwärze mein Glaube sei und dass ich den Gläubigen Segen bringen würde. Heute hat mich diese Dunkelheit bereits vollständig erfasst und ist mit mir verschmolzen... Doch das Herz, das in diesem sündigen Körper schlägt, ist ein Ort, der niemals erfasst werden kann. Vertraut mir, ich werde die Fähigkeit, die mir diese Schwärze verliehen hat, nutzen, um der Menschheit den wahren Segen zu bringen!"
  },
  Voice_95063_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_95064_AwakerVoiceContent = {
    Text = "Ich werde deinen mächtigen Namen verkünden. Alle Unreinheit und Schmutz werden letztendlich vom Licht gereinigt."
  },
  Voice_95064_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_95065_AwakerVoiceContent = {
    Text = "Die Sünden der Vergangenheit sind bereits geschehen – man sollte nicht länger versuchen, ihnen zu entkommen. Ich muss auch die Fehler der Laterne korrigieren und jene, die vom rechten Weg abgewichen sind, auf den richtigen Pfad zurückbringen. Lass mich meine Sünden tragen. Dann werde ich auf dieses Licht reagieren, deinem Ruf folgen und den wahren Weg des Sohnes gehen."
  },
  Voice_95065_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_95065_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_95066_AwakerVoiceContent = {
    Text = "Wie ein so gütiges Herz, das bereit ist, eine Person voller Sünden zu vergeben! Ich kann spüren, wie rein und heller als das Licht der Lampe der Glanz Ihrer Seele ist. Vielleicht können Sie meinen irrenden Geist führen ..."
  },
  Voice_95066_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_95066_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_95067_AwakerVoiceContent = {
    Text = "Diese Dunkelheit, die aus Yllièttes Fluch verbreitet wurde, hat stets meine Gedanken umhüllt... Doch jetzt ist in dieser Dunkelheit tatsächlich ein Licht erschienen! Will mir dieser schwache Lichtpunkt etwas mitteilen?"
  },
  Voice_95067_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_95067_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_95068_AwakerVoiceContent = {
    Text = "Ich habe gehört, dass sie früher auch eine Heilige war. Aber diese grobe Haltung, diese rüde Art... Was? Sie kann nicht einmal einen Gebetstext rezitieren? So wenig fromm zu wirken, ist wirklich peinlich für ihren Gott."
  },
  Voice_95068_AwakerVoiceTitle = {
    Text = "Plauderei · Über Murphy"
  },
  Voice_95068_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Murphy“"
  },
  Voice_95069_AwakerVoiceContent = {
    Text = "Derjenige, der die Menschen aus dem Nebel führen kann, ist der wahre Leuchterträger mit einem Körper aus reinem Silber. Das sündenfreie Paradies, von dem Liette spricht, wurde aus den Überresten der Gläubigen gebaut. Als Heiliger Sohn werde ich das neue Evangelium unter allen gläubigen Seelen verbreiten, die der Erlösung würdig sind."
  },
  Voice_95069_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_95070_AwakerVoiceContent = {
    Text = "Oh du, der mich führt und mir Licht schenkt! Einst war ich von falschen Vorstellungen umfangen, doch nun, unter deiner Führung, habe ich meinen wahren Lebenszweck wiedergefunden – jenen, die verblendeten und verdrehten Heuchler zur Umkehr zu bringen und für diese Welt eine ewige, unvergängliche Lichtgestalt zu sein. Ich kenne deine Selbstlosigkeit; weder meines Glaubens noch meiner Opfer bedarfst du. Erlaube mir daher, an deiner Seite zu gehen und jedes deiner heiligen Worte und Taten aufzuzeichnen, um sie als Leitfaden auf meinem Weg durch die dunklen Nächte zu nutzen."
  },
  Voice_95070_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_95070_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_95071_AwakerVoiceContent = {
    Text = "Mit Fesseln, in Dunkelheit getaucht, auf das Licht zugehen, fest entschlossen... Das ist es, was Sie mir sagen wollten?"
  },
  Voice_95071_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_95071_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_95072_AwakerVoiceContent = {
    Text = "Ein Diener des Lichts verlor die Flamme in seiner Hand, und dieser schmerzhafte Verlust betrübt mein Herz zutiefst. Ich flehe Sie von Herzen an, dieses verlorene Seelenheil zu retten. Bitte ergreifen Sie meine Hand und kommen Sie diesem heiligen Herzen nahe. Gewähren Sie mir, Ihren Beistand auf dem Weg ins Licht ..."
  },
  Voice_95072_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_95072_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_95073_AwakerVoiceContent = {
    Text = "Das arme Kind, doch da sie sich bereits dem Dienst an Ihrem Werk verschrieben hat, wird sie gewiss die endgültige Erlösung finden. Doch warum hat sie diesen affenähnlichen Freund bekommen, der ebenso Ihre Gnade erfahren hat? Dieses böse Kind hat sogar den heiligen Gegenstand meines Gebets gestohlen! Gewiss verbirgt sich eine Flut von Sünden in ihrer Seele. Eine Schande! Eine Schande!"
  },
  Voice_95073_AwakerVoiceTitle = {
    Text = "Plauderei: Über Aigis und Jenkins"
  },
  Voice_95073_UnlockDesc = {
    Text = "Nachdem die Awakener „Aegis“ und der Awakener „Jenkin“ erhalten wurden, freigeschaltet"
  },
  Voice_95074_AwakerVoiceContent = {
    Text = "Macht, dass ihr fortkommt."
  },
  Voice_95074_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_95075_AwakerVoiceContent = {
    Text = "Das Licht des Lichtträgers wird die lange Nacht endgültig erhellen!"
  },
  Voice_95075_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_95076_AwakerVoiceContent = {
    Text = "Ah... Ich habe es bereits gesehen – die ungeheure Macht, die Wahrheit der Welt... Ich erkenne nun, welchem Irrweg ich früher folgte. Sie sind der wahre Lichtträger! Erlauben Sie mir, Ihr treuer Apostel zu werden. Dieses Herz, das für den Lichtträger geschaffen wurde, wird von nun an für Sie erbeben und sich in Ehrfurcht verneigen..."
  },
  Voice_95076_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_95076_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_95077_AwakerVoiceContent = {
    Text = "Diese blinde Erlösung durch den Priester ist wirklich eine unüberlegte Torheit. Das Evangelium Gottes sollte doch nur den frommen Gerechten zuteilwerden. Wenn sogar der Abgesandte Gottes nicht mit scharfsinnigem Blick ausgestattet ist, um schuldvolle Übeltäter ohne Reue zu belohnen und in das reine Reich Gottes einzulassen, dann wäre das doch ein Verrat an den Göttern und all den Gerechten?"
  },
  Voice_95077_AwakerVoiceTitle = {
    Text = "Small Talk: Über El Salvador"
  },
  Voice_95077_UnlockDesc = {
    Text = "Freigeschaltet nach Erhalt von Erweckungseinheit „Salvador“"
  },
  Voice_95078_AwakerVoiceContent = {
    Text = "Mein Herz leuchtet hell!"
  },
  Voice_95078_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_95079_AwakerVoiceContent = {Text = "Hah!"},
  Voice_95079_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_95080_AwakerVoiceContent = {
    Text = "Als Kind wollte ich nur aus dem Käfig fliehen. Damals glaubte ich, dass dieser Ort, der nur Leid brachte, keinerlei Wehmut verdiente. Doch nach zwei Leben erkannte ich schließlich, dass Freiheit nicht das Einzige ist, nach dem ich mich sehne. Erst als ich die Gläubigen sah, wie sie beim Gedanken an die Erlösung voller Aufrichtigkeit, Hoffnung und Dankbarkeit waren, wurde mir bewusst, welch tiefe Bedeutung der Titel des Heiligen Sohnes wirklich hat."
  },
  Voice_95080_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_95081_AwakerVoiceContent = {
    Text = "In der Zeit, in der ich Juliette folgte, habe ich viele Fehler begangen und eigentlich dieses Vertrauen nicht mehr verdient. Doch Ihr habt mich dennoch ausgewählt... Seid unbesorgt, ich werde meinen eigenen Glauben neu finden. Der Erlöser wird seine Anhänger nicht enttäuschen, und auch Euch nicht enttäuschen."
  },
  Voice_95081_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_95081_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_95082_AwakerVoiceContent = {
    Text = "Ich werde die Gaben, die Ihr mir gewährt habt, mit Dankbarkeit nutzen."
  },
  Voice_95082_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_95083_AwakerVoiceContent = {
    Text = "Unhöflich!"
  },
  Voice_95083_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_95084_AwakerVoiceContent = {
    Text = "Verdammte Scheiße."
  },
  Voice_95084_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_95085_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_95086_AwakerVoiceContent = {
    Text = "In meinem Namen!"
  },
  Voice_95086_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_95087_AwakerVoiceContent = {
    Text = "Ich sehe es! Das Licht, das tief in meinem Bewusstsein leuchtet, wird immer heller! Es ruft mich ..."
  },
  Voice_95087_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_95087_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_95088_AwakerVoiceContent = {
    Text = "In meiner Kindheit teilte Castor mit mir das Amt des Heiligen Sohnes. Damals glaubte ich stets, er sei zu verschlossen und unbeholfen, sodass ich die Richtung seiner Zukunft lenken müsste. Doch nachdem ich nun Ihren Lebensweg kennengelernt habe, verstehe ich erst, dass die Grundpfeiler der Welt von Menschen wie Ihnen und ihm erschaffen und gestaltet wurden, die mit Festigkeit und Rechtschaffenheit handelten."
  },
  Voice_95088_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_95088_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_95089_AwakerVoiceContent = {
    Text = "Mein Leuchtturm, seitdem ich Ihre Anleitung erhalten habe, glaube ich, dass ich nun den völlig richtigen Pfad eingeschlagen habe. Doch noch immer hat Ihr törichter Anhänger eine letzte Verwirrung: Jenes legendäre, sündenfreie Paradies – liegt es ebenfalls unter Ihrer Herrschaft? Gibt es so etwas gar nicht? Wollen Sie damit sagen ... dass das sündenfreie Paradies in der Welt der Menschen liegt, in den reinen Herzen der Gerechten?"
  },
  Voice_95089_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_95090_AwakerVoiceContent = {
    Text = "Dieses Herz, das den Willen Gottes hört, ist dir nun noch näher."
  },
  Voice_95090_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_95091_AwakerVoiceContent = {
    Text = "Haben Sie... haben Sie einen Befehl für mich? Ihr Apostel ist jederzeit bereit, Ihre Lehren anzuhören."
  },
  Voice_95091_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_95092_AwakerVoiceContent = {
    Text = "Erleuchte mich, irrender Führer! Mit deinem Licht habe ich bereits alles erkannt, was ich erkennen musste ... Mit diesem verfluchten Körper werde ich die Vergangenheit reinigen und die Zukunft in diesem Licht baden lassen!"
  },
  Voice_95092_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_95092_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_95093_AwakerVoiceContent = {
    Text = "Heiliges Herz als Kern, das Licht der Lampe leuchtet ewig!"
  },
  Voice_95093_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_95391_AwakerVoiceContent = {
    Text = "Strebst du nach Rettung in dieser grausamen Welt? Dann gib dein Bestes, kleines Hoffnungslicht."
  },
  Voice_95391_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_95391_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_95392_AwakerVoiceContent = {
    Text = "Komm, nimm das mit, um damit zu spielen. Es soll angeblich aus einem verbotenen Schatz aus einer Ruine stammen. Mich interessieren diese Dinge, die nach \"ihnen\" riechen, nicht weiter. Eigentlich wollte ich sie verbrennen, aber ich dachte, sie könnten dir vielleicht nützen, also habe ich sie dir mitgebracht. \n Fragst du, wie ich sie bekommen habe? Natürlich haben sie mir diese Dinge “freiwillig“ gegeben. Mach dir keine Sorgen, der Ursprung ist “sauber“.\n\n."
  },
  Voice_95392_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_95392_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_95393_AwakerVoiceContent = {
    Text = "Die Jagd ist beendet – als Belohnung erhältst du das Lächeln des kleinen Kerls."
  },
  Voice_95393_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_95394_AwakerVoiceContent = {
    Text = "Weißt du, kleiner Kerl, dass die Kugeln, die aus diesen beiden Pistolen abgefeuert werden, keine gewöhnlichen Projektile sind, sondern die Summe aus Wunsch und Bosheit? Dieses ungeordnete Chaos bildet eine fleischähnliche Flamme, und beim siebten Schuss auf der anderen Seite wird sie alles in die Hölle ziehen und verbrennen."
  },
  Voice_95394_AwakerVoiceTitle = {
    Text = "Plauderei · Über Schusswaffen"
  },
  Voice_95395_AwakerVoiceContent = {
    Text = "Keine Notwendigkeit, dich selbst übermäßig unter Druck zu setzen, mein Geheimniswahrer. Obwohl mir bewusst ist, dass dies ein Weg voller Verzweigungen ist, auf dem jeder Fehler schwerwiegende Folgen haben kann und der keinen Aufschub duldet, wirst du eines Tages vor Erschöpfung zusammenbrechen, wenn du so weitermachst. Falls du Unterstützung benötigst, kannst du dich jederzeit an mich wenden – als Familie."
  },
  Voice_95395_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_95395_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_95396_AwakerVoiceContent = {
    Text = "Brenne, zerstöre und heule!"
  },
  Voice_95396_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_95397_AwakerVoiceContent = {
    Text = "Verschwinden."
  },
  Voice_95397_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_95398_AwakerVoiceContent = {
    Text = "Mein Blick ist klarer geworden, ich habe das gesehen, was unter dem Abgrund verborgen ist... Für euch muss ich eine noch größere Kraft erlangen..."
  },
  Voice_95398_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_95398_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_95399_AwakerVoiceContent = {
    Text = "Komm, Geheimnisträger, setz dich näher heran. So ist es jetzt zu förmlich. \nWeißt du, als ich dich zum ersten Mal sah, hätte ich nie gedacht, dass ich eines Tages die als grausam und kalt geltende Schale ablegen könnte, um dir mein wahres Ich anzuvertrauen. Es ist fast schon lächerlich, nicht wahr? Der berüchtigte Meister des Infernos sehnt sich nach einem Familienmitglied, dem er sein Herz öffnen kann. \nVersprich mir eines: Wenn du eines Tages nicht mehr weiterkannst ... dann ruf in deinem Herzen nach meinem Namen. Ich werde dich begleiten, gemeinsam gehen wir in mein Reich. Obwohl dies alles nur hinauszögern kann, so wirst du doch zumindest im letzten Moment in meinen Armen zur Ruhe kommen können."
  },
  Voice_95399_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_95399_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_95400_AwakerVoiceContent = {
    Text = "Stell dich dem Ende."
  },
  Voice_95400_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_95401_AwakerVoiceContent = {Text = "Ugh!"},
  Voice_95401_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_95402_AwakerVoiceContent = {
    Text = "In unzähligen Wünschen und Bosheiten, verbrenne!"
  },
  Voice_95402_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_95403_AwakerVoiceContent = {
    Text = "Nach einer erfolgreichen Jagd braucht man immer ein Festmahl zur Feier. Komm schon, probiere mein gebratenes Kamelfleisch und den neu besorgten Agave-Schnaps. Moment mal, du kleiner Kerl darfst ja keinen Alkohol trinken... Dann probiere doch meinen speziellen Saft!"
  },
  Voice_95403_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_95403_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_95404_AwakerVoiceContent = {
    Text = "Was ist los, kleiner Kerl? Willst du eine Umarmung? Komm schon, meine warme Brust steht dir immer offen ... Haha, sei nicht schüchtern. Es ist doch völlig normal, dass sich eine große Schwester um ihre jüngeren Kameraden kümmert, oder?"
  },
  Voice_95404_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_95406_AwakerVoiceContent = {
    Text = "Verdammter."
  },
  Voice_95406_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_95407_AwakerVoiceContent = {
    Text = "Stell dich dem bernsteinfarbenen Tod."
  },
  Voice_95407_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_95408_AwakerVoiceContent = {
    Text = "Zieht zuerst zurück, ich bleibe als Nachhut... macht euch keine Sorgen, ich komme lebend zurück."
  },
  Voice_95408_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_95409_AwakerVoiceContent = {
    Text = "Komm schon, lass uns alles zu Asche verbrennen!"
  },
  Voice_95409_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_95410_AwakerVoiceContent = {
    Text = "Explosives Feuer, entfache dich hier erneut!"
  },
  Voice_95410_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_95411_AwakerVoiceContent = {
    Text = "Die Flammen werden immer stärker. Möchtest du dir ein großes Feuerwerk ansehen, kleiner Freund?"
  },
  Voice_95411_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_95412_AwakerVoiceContent = {
    Text = "Diese Typen, die die Moral verachten, sich im Schatten verstecken und @1 als Material für ihre schmutzigen Opfer und Forschungen verwenden... eines Tages werde ich sie alle ausrotten."
  },
  Voice_95412_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_95413_AwakerVoiceContent = {Text = "Peng!"},
  Voice_95413_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_95414_AwakerVoiceContent = {
    Text = "Ich werde ihn finden, egal in welcher Ecke des Universums er sich versteckt – ich werde ihn finden. \nDiese schmutzige Ratte soll für alles bezahlen. In dem Moment, in dem ich ihn finde, werden alle Freuden und Wonnen dieser Welt in der Hölle verbrennen. \nMach dir keine Sorgen, bei seiner Beerdigung werde ich dir einen Platz in der ersten Reihe reservieren, damit wir gemeinsam seinen letzten Schmerzensschrei genießen können."
  },
  Voice_95414_AwakerVoiceTitle = {
    Text = "Plauderei · Über N"
  },
  Voice_95415_AwakerVoiceContent = {
    Text = "Höre das klägliche Wehgeschrei, das die Sterne schmelzen lässt."
  },
  Voice_95415_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_95415_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_95416_AwakerVoiceContent = {
    Text = "Stell dich dem Ende."
  },
  Voice_95416_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_95417_AwakerVoiceContent = {
    Text = "Du bist doch die Familie, auf die ich stolz bin, sei selbstbewusster, mein Geheimnisträger! Egal was passiert, ich werde immer deine stärkste Unterstützung sein."
  },
  Voice_95417_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_95418_AwakerVoiceContent = {
    Text = "Jene namenlosen Wesen greifen diese Welt an, und du wirst unweigerlich gegen sie kämpfen müssen. Doch das ist in Ordnung, denn ich werde hinter dir stehen."
  },
  Voice_95418_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_95418_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_95420_AwakerVoiceContent = {
    Text = "Brenne, zerstöre und heule!"
  },
  Voice_95420_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_95421_AwakerVoiceContent = {
    Text = "Bewahre die Ruhe."
  },
  Voice_95421_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_95422_AwakerVoiceContent = {Text = "Zurück."},
  Voice_95422_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_95423_AwakerVoiceContent = {
    Text = "Was ich von Korrosion halte? Das ist, als würde man eine kleine Ratte, die durch Abwasserkanäle schleicht, nach einem hochwohlgeborenen Herrn befragen. Meine Antwort ist eindeutig: eine instinktive Abneigung. Wenn es nach mir ginge, würde ich gerne ein köstliches Kamelmilchbier trinken und dabei das Kreischen hören, wenn sie unter meinem Feuer sterben."
  },
  Voice_95423_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_95424_AwakerVoiceContent = {
    Text = "Möchtest du die Flammen noch heißer machen?"
  },
  Voice_95424_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_95424_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_95425_AwakerVoiceContent = {
    Text = "Ich erscheine hier nur, wenn ich einen Auftrag annehme. Wenn du mich suchst, verwende diesen Zauber. Komm, wiederhole nach mir: .................. Ia! KathiguRa!"
  },
  Voice_95425_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_95426_AwakerVoiceContent = {
    Text = "Einst lebten wir noch in dieser heruntergekommenen Kleinstadt und kämpften ums Überleben mit Grausamkeit und List. Selbst nachdem wir zu einer sogenannten „großen Macht“ geworden waren, mussten wir uns gegenüber dem Herrn, der Wachtruppe und den „edlen Rittern“, die sich weigerten, die Bühne der Geschichte zu verlassen, stets äußerst wachsam verhalten. Aber jetzt ist alles anders. Alle sind nun meine „Anhänger“ und müssen nicht länger auf die Gesichter anderer Rücksicht nehmen. Nun ja, zumindest fast alle – ein kleines Mitglied unserer Gruppe ist noch irgendwo da draußen unterwegs. Doch ich bin mir sicher, dass diesem Kerl nichts passieren wird. Schließlich war es stets dieserjenige, der sich um die anderen kümmerte, während ich mich draußen um Dinge scherte."
  },
  Voice_95426_AwakerVoiceTitle = {
    Text = "Plauderei · Über Familie"
  },
  Voice_95427_AwakerVoiceContent = {
    Text = "Das ist also der Feind des kleinen Kerls? Dann - fröhliche Jagd."
  },
  Voice_95427_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_95428_AwakerVoiceContent = {
    Text = "Ich bin der unvergessliche Meister der Explosionen! Verkünde! Alles wird vergehen!"
  },
  Voice_95428_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_95429_AwakerVoiceContent = {
    Text = "Brennen und Zerstören ist alles für mich, ich liebe den Tod, den die Jagd bringt... Würdest du denken, ich würde so etwas sagen? \n Haha, nur ein Scherz. Für mich sind natürlich die Menschen um mich herum am wichtigsten. Es gibt nichts Wichtigeres als sie. Nicht einmal... ich selbst."
  },
  Voice_95429_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_95430_AwakerVoiceContent = {
    Text = "Hat das kleine Ding Probleme? Dann folge dem Ruf – Khatygula wird mit Zerstörung erscheinen und alle Probleme mit einem lauten „Peng“ zu Staub zerfallen lassen."
  },
  Voice_95430_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_95431_AwakerVoiceContent = {
    Text = "Der Geschmack der Macht – sollen wir ein paar Pechvögel finden, um sie zu testen?"
  },
  Voice_95431_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_95431_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_95432_AwakerVoiceContent = {
    Text = "Ich bin der unvergessliche Meister der Explosion! Verkünde! Alles wird vergehen!"
  },
  Voice_95432_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_95433_AwakerVoiceContent = {
    Text = "Die legendäre Königin von Aran, die mächtige Materie der Begierde, Tifreyah Sod – ich hatte sie einst kurz gesehen, als ich N verfolgte. Obwohl ich nicht gutheiße, was sie getan hat, muss ich ehrlich sagen: Wenn dies der einzige Weg wäre, um alle vor dem Tod durch „Seinen“ Blick zu retten ... dann würde ich dieselbe Wahl treffen. Aus diesem Blickwinkel betrachtet, unterscheide ich mich in nichts von ihr."
  },
  Voice_95433_AwakerVoiceTitle = {
    Text = "Plauderei: Über Thais"
  },
  Voice_95433_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Thais“ wird freigeschaltet"
  },
  Voice_95434_AwakerVoiceContent = {
    Text = "Hervorragendes Handling, die Waffe ist gut gepflegt."
  },
  Voice_95434_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_95435_AwakerVoiceContent = {
    Text = "Ich bin das Feuer, die Flamme, das ewig brennende Chaos... Ich werde euch alle... heimbringen..."
  },
  Voice_95435_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_95435_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_96361_AwakerVoiceContent = {
    Text = "Der gotische Glockenturm wirkt hier sehr klassisch. Die Erwachten haben hier ebenfalls einen einzigartigen Geruch – eine Mischung aus dem Aroma der Verstorbenen und einem Hauch lebendiger Vitalität. Es ist wirklich ... verlockend, es einmal zu probieren."
  },
  Voice_96361_AwakerVoiceTitle = {
    Text = "Plauderei·Über Misaga"
  },
  Voice_96362_AwakerVoiceContent = {
    Text = "Wer den Tod sucht, dem werde ich seinen Wunsch erfüllen."
  },
  Voice_96362_AwakerVoiceTitle = {
    Text = "Exalt · Zwei"
  },
  Voice_96363_AwakerVoiceContent = {
    Text = "Ich kann es kaum erwarten, loszulegen."
  },
  Voice_96363_AwakerVoiceTitle = {Text = "Erwecken"},
  Voice_96364_AwakerVoiceContent = {
    Text = "Du hast Herzklopfen, nicht wahr? Komm schon, mein lieber Gast, werde mein ehrenwerter Tischgast und genieße gemeinsam mit mir dieses Festmahl. Lass mich dich führen und jeden feinen Nachklang der verstorbenen Seelen zusammen mit dir kosten."
  },
  Voice_96364_AwakerVoiceTitle = {
    Text = "Erleuchten·Blühen"
  },
  Voice_96364_UnlockDesc = {
    Text = "Erleuchten Level erreicht 15 freigeschaltet"
  },
  Voice_96365_AwakerVoiceContent = {
    Text = "Pssst, sei still und höre gemeinsam mit mir den Stimmen der Toten zu."
  },
  Voice_96365_AwakerVoiceTitle = {
    Text = "Affinität·Eins"
  },
  Voice_96365_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 2 freigeschaltet"
  },
  Voice_96366_AwakerVoiceContent = {
    Text = "Die ewige Schönheit ist unser Glaube. Sie wird langsam auf Lebende angewendet und alle Spuren ihrer Existenz auslöschen... Dies ist für das Leben eine reine und grausame Folter."
  },
  Voice_96366_AwakerVoiceTitle = {
    Text = "Plauderei·Über die Krise"
  },
  Voice_96367_AwakerVoiceContent = {
    Text = "Ebenso wie ich strebt Pikmann nach der ewigen Kunst, und wir hätten bessere Freunde sein sollen. Doch er betrachtet das Essen als eine Handlung, die die Ewigkeit zerstört, eine künstlerische Vorstellung, die wirklich zu eng ist."
  },
  Voice_96367_AwakerVoiceTitle = {
    Text = "Plauderei·Über Mr. Pickman"
  },
  Voice_96367_UnlockDesc = {
    Text = "Erhältst du den Erwecker „Pickman“ wird freigeschaltet"
  },
  Voice_96368_AwakerVoiceContent = {Text = "Ha!"},
  Voice_96368_AwakerVoiceTitle = {
    Text = "Schlag·Eins"
  },
  Voice_96369_AwakerVoiceContent = {
    Text = "Kein Adjektiv vermag deinen berauschenden Duft zu beschreiben, der sowohl an den säuerlich-vollmundigen Abklang von Bordeaux-Wein als auch an die intensive, samtige Süße von Buttergebäck erinnert... Ah... Der Tag deines Todes könnte vielleicht das Wichtigste meines restlichen Lebens werden."
  },
  Voice_96369_AwakerVoiceTitle = {
    Text = "Plauderei·Über Geheimnishüter"
  },
  Voice_96370_AwakerVoiceContent = {
    Text = "Ich habe einmal einen Tatort gesehen, bei dem ein Mann langsam die Haut, die Nägel, die Hände und die Füße eines jungen Mädchens abschnitt, sie dabei aber immer wieder heilte. Er wollte sie nicht sterben lassen, noch wollte er, dass sie lebte. Ich konnte ihm natürlich keinen friedvollen Tod gewähren, sondern ließ ihn einfach immer wieder die gleichen Erfahrungen machen wie das Mädchen. Das müsste jetzt schon einige Jahre her sein... Für jemanden, der den Tod entweiht, ist das doch nur gerecht, oder?"
  },
  Voice_96370_AwakerVoiceTitle = {
    Text = "Plauderei·Über Hassdinge"
  },
  Voice_96371_AwakerVoiceContent = {
    Text = "Ich bin der Gott des Todes, doch missverstehe mich nicht – ich erzeuge den Tod nicht. Ich folge nur den Spuren des Todes und pflücke die reifen, üppigen Früchte."
  },
  Voice_96371_AwakerVoiceTitle = {
    Text = "Erleuchten·Fernblick"
  },
  Voice_96371_UnlockDesc = {
    Text = "Erleuchten Level erreicht 1 freigeschaltet"
  },
  Voice_96372_AwakerVoiceContent = {
    Text = "Hast du auch das Verlangen nach meinem Geschmack, Geheimnisträger?"
  },
  Voice_96372_AwakerVoiceTitle = {
    Text = "Plauderei·Über Berührung"
  },
  Voice_96373_AwakerVoiceContent = {
    Text = "Wer kommt heute auf den Tisch?"
  },
  Voice_96373_AwakerVoiceTitle = {
    Text = "Ermittlung gestartet"
  },
  Voice_96374_AwakerVoiceContent = {
    Text = "Ich werde euch die Ehre verleihen, heute Abend am Festmahl teilzunehmen."
  },
  Voice_96374_AwakerVoiceTitle = {
    Text = "Ermittlung erfolgreich"
  },
  Voice_96375_AwakerVoiceContent = {
    Text = "Sehr unbeholfen."
  },
  Voice_96375_AwakerVoiceTitle = {
    Text = "Treffer·III"
  },
  Voice_96376_AwakerVoiceContent = {
    Text = "Ich werde eine reine Ruhe bringen."
  },
  Voice_96376_AwakerVoiceTitle = {
    Text = "Fähigkeit·Eins"
  },
  Voice_96377_AwakerVoiceContent = {
    Text = "Bei jeder Mahlzeit unterhalte ich mich mit den Toten. Für sie ist es eine Verlängerung und der letzte Höhepunkt ihres Lebens, sorgfältig von uns verzehrt und gekostet zu werden. So wie wir nach ihnen verlangen, sehnen auch sie sich nach uns."
  },
  Voice_96377_AwakerVoiceTitle = {
    Text = "Affinität·Drei"
  },
  Voice_96377_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 6 freigeschaltet"
  },
  Voice_96378_AwakerVoiceContent = {Text = "Ruhig."},
  Voice_96378_AwakerVoiceTitle = {
    Text = "Treffer·Vier"
  },
  Voice_96379_AwakerVoiceContent = {
    Text = "Im Schatten verschwinden!"
  },
  Voice_96379_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_96380_AwakerVoiceContent = {
    Text = "Wir sollten besser Abstand halten."
  },
  Voice_96380_AwakerVoiceTitle = {
    Text = "Verteidigung · Ich"
  },
  Voice_96381_AwakerVoiceContent = {
    Text = "Im Schatten verschwinden!"
  },
  Voice_96381_AwakerVoiceTitle = {
    Text = "Fähigkeitskarte·Vier"
  },
  Voice_96382_AwakerVoiceContent = {
    Text = "Warum bist du so misstrauisch mir gegenüber? Du solltest nicht in Panik geraten und musst es auch nicht. Es widerspricht meinem ästhetischen Empfinden, von Lebenden zu trinken."
  },
  Voice_96382_AwakerVoiceTitle = {
    Text = "Plauderei·Über Essen"
  },
  Voice_96383_AwakerVoiceContent = {
    Text = "Wer den Tod sucht, dem werde ich seinen Wunsch erfüllen."
  },
  Voice_96383_AwakerVoiceTitle = {
    Text = "Verherrlichung"
  },
  Voice_96384_AwakerVoiceContent = {
    Text = "Sehr unbeholfen."
  },
  Voice_96384_AwakerVoiceTitle = {Text = "Treffer·1"},
  Voice_96385_AwakerVoiceContent = {
    Text = "Sei vorsichtig."
  },
  Voice_96385_AwakerVoiceTitle = {
    Text = "Verteidigung·II"
  },
  Voice_96386_AwakerVoiceContent = {
    Text = "Die Leidenschaft der jungen Dame ist zwar wirklich rührend, aber ihr Geruch erinnert an überreife, feuchte Fermentation. Selbst wenn sie mich unaufhörlich darum bittet, eine Kostprobe zu nehmen – das entspricht einfach nicht meinem Geschmack. Das ist wirklich eine schwierige Situation."
  },
  Voice_96386_AwakerVoiceTitle = {
    Text = "Chat·Über Leigh"
  },
  Voice_96386_UnlockDesc = {
    Text = "Erwirb den Erwecker „Leigh“ und schalte frei"
  },
  Voice_96387_AwakerVoiceContent = {
    Text = "Wusstest du? Wenn alles Leben stirbt, entsteht ein langer Widerhall. Die Tonhöhen und Klangfarben sind unterschiedlich und ab dem Moment des Todes dehnen sie sich allmählich aus, bis sie schließlich zwischen Himmel und Erde verwehen – wie ein Seufzen oder ein Ruf."
  },
  Voice_96387_AwakerVoiceTitle = {
    Text = "Affinität·Zwei"
  },
  Voice_96387_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 4 freigeschaltet"
  },
  Voice_96388_AwakerVoiceContent = {
    Text = "Seien Sie unbesorgt, edler Geheimnisträger, ich werde stets an Eurer Seite bleiben, bis der Tag kommt, an dem Euer Leben unaufhaltsam vergeht. An jenem Tag werde ich Euren Körper mit dem allerfeierlichsten Ritual nach und nach verschlingen. Eure Seele werde ich für immer in meinem Körper bewahren."
  },
  Voice_96388_AwakerVoiceTitle = {
    Text = "Affinität·Fünf"
  },
  Voice_96388_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 10 freigeschaltet"
  },
  Voice_96389_AwakerVoiceContent = {
    Text = "Du kannst deinen eigenen Geruch nicht riechen? Das ist wirklich bedauerlich. Du verpasst den süßesten, verlockendsten... Oh, warum weichst du zurück?"
  },
  Voice_96389_AwakerVoiceTitle = {
    Text = "Affinität·Vier"
  },
  Voice_96389_UnlockDesc = {
    Text = "Affinitätsstufe erreicht 8 freigeschaltet"
  },
  Voice_96390_AwakerVoiceContent = {
    Text = "Ich kann bereits mehr Tod erkennen, die Landschaft auf der anderen Seite wird immer klarer..."
  },
  Voice_96390_AwakerVoiceTitle = {
    Text = "Erhalte Boost·Drei"
  },
  Voice_96391_AwakerVoiceContent = {
    Text = "Überlass mir deinen Körper, lass mich dich sorgfältig kosten – jeden Tropfen Blut, jedes Stück Fleisch und jeden Knochen."
  },
  Voice_96391_AwakerVoiceTitle = {
    Text = "Über-Erhöhung"
  },
  Voice_96392_AwakerVoiceContent = {
    Text = "Verschiedene Zutaten erfordern unterschiedliche Zubereitungsweisen. Innereien sollten mariniert werden, Sehnen an den Beinen am besten geschmort, fette Partien eignen sich hervorragend zum Fermentieren und Reifen, besonders schmackhafte Stücke kann man braten, angrillen oder sogar zu ansprechend geformten Aspik verarbeiten – all dies erfordert eine sorgfältige Auswahl. Selbstverständlich ist es dabei stets notwendig, den ursprünglichen Geschmack der Zutaten zu bewahren und hervorzuheben, als Ausdruck der nötigen Wertschätzung."
  },
  Voice_96392_AwakerVoiceTitle = {
    Text = "Erleuchten: Einsicht"
  },
  Voice_96392_UnlockDesc = {
    Text = "Erleuchten Level erreicht 7 freigeschaltet"
  },
  Voice_96393_AwakerVoiceContent = {
    Text = "Es wird etwas kühl sein."
  },
  Voice_96393_AwakerVoiceTitle = {Text = "Schlag·II"},
  Voice_96394_AwakerVoiceContent = {
    Text = "Auch die Kombination der Gerichte bedarf großer Sensibilität: Sauer und süß, knusprig und zart, frisch und schwer, fein und grob – diese unterschiedlichen Aromen und kontrastierenden Texturen vermengen sich zu einer geschmacklichen Abfolge, die beim ersten Biss, beim Kauen und sogar im Nachklang jeweils ein anderes Gefühl vermittelt. Erst dadurch entsteht das unendliche und wunderbare Vergnügen, das eine gelungene Mahlzeit dem Genießer bereiten kann."
  },
  Voice_96394_AwakerVoiceTitle = {
    Text = "Erleuchten·Bau"
  },
  Voice_96394_UnlockDesc = {
    Text = "Erleuchten Level erreicht 11 freigeschaltet"
  },
  Voice_96395_AwakerVoiceContent = {
    Text = "Vielen Dank für deine Herzlichkeit, ich fühle mich geehrt."
  },
  Voice_96395_AwakerVoiceTitle = {
    Text = "Upgrade·II"
  },
  Voice_96396_AwakerVoiceContent = {
    Text = "Leckeres Essen ist immer eine längere Wartezeit wert."
  },
  Voice_96396_AwakerVoiceTitle = {
    Text = "Ermittlung gestoppt"
  },
  Voice_96397_AwakerVoiceContent = {
    Text = "Natürlich bin ich kein primitives Ungeheuer, das rohes Fleisch frisst und Blut trinkt. Der Prozess, den Tod zu genießen, ist würdevoll und elegant. Du musst mit Respekt kommunizieren und den einzigartigen Geschmack jedes Zutats verstehen."
  },
  Voice_96397_AwakerVoiceTitle = {
    Text = "Erleuchten: Nachdenken"
  },
  Voice_96397_UnlockDesc = {
    Text = "Erleuchten Level erreicht 2 freigeschaltet"
  },
  Voice_96398_AwakerVoiceContent = {
    Text = "Die Ruhe gefundenen Toten sind schön und duftend, nicht wegen großer Unterschiede ihres Körpers zu Lebzeiten oder nach dem Tod, sondern aufgrund ihrer Seelen – jene Seelen, die das Verständnis des Todes, die Zuneigung zum Leben und das Verlangen nach Erinnerung besitzen, sind eine köstliche Kost, nach der ich mich sehne."
  },
  Voice_96398_AwakerVoiceTitle = {
    Text = "Plauderei·Über Lieblingsdinge"
  },
  Voice_96399_AwakerVoiceContent = {
    Text = "Kein Parfüm kann den natürlichen Duft des menschlichen Körpers übertreffen. Es ist etwas Wunderbares, eine Person an ihrem Geruch zu erkennen."
  },
  Voice_96399_AwakerVoiceTitle = {
    Text = "Erleuchten·Nachdenken"
  },
  Voice_96399_UnlockDesc = {
    Text = "Erleuchten Level erreicht 3 freigeschaltet"
  },
  Voice_96400_AwakerVoiceContent = {
    Text = "Ah, welch ein unvergesslicher Duft... Ich kann es kaum erwarten, dich in meinem Heiligtum willkommen zu heißen."
  },
  Voice_96400_AwakerVoiceTitle = {Text = "Erweckung"},
  Voice_96401_AwakerVoiceContent = {
    Text = "Überlass mir deinen Körper, lass mich dich sorgfältig kosten – jeden Tropfen Blut, jedes Stück Fleisch und jeden Knochen."
  },
  Voice_96401_AwakerVoiceTitle = {
    Text = "Über-Exaltation Aliemus Burst·II"
  },
  Voice_96402_AwakerVoiceContent = {
    Text = "Ich werde eine ruhige Reinheit bringen."
  },
  Voice_96402_AwakerVoiceTitle = {
    Text = "Fähigkeit·II"
  },
  Voice_96403_AwakerVoiceContent = {Text = "Sei ruhig."},
  Voice_96403_AwakerVoiceTitle = {
    Text = "Treffer · II"
  },
  Voice_96404_AwakerVoiceContent = {
    Text = "Dein verführerisch duftender Geruch ist wirklich betörend."
  },
  Voice_96404_AwakerVoiceTitle = {
    Text = "Erhalte Boost · I"
  },
  Voice_98324_AwakerVoiceContent = {
    Text = "In Milliarden von Wünschen und Bosheit, brenne!"
  },
  Voice_98324_AwakerVoiceTitle = {
    Text = "Sonderfertigkeit · Eins"
  }
})
return Text_Voice
